return ['project-id-version'=>'WPOptimizing','pot-creation-date'=>'2026-10-22 14:54+0200','po-revision-date'=>'2026-02-19 09:32+0000','last-translator'=>'Art Project Group','language-team'=>'Arabic','language'=>'ar','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','plural-forms'=>'nplurals=6; plural=n==0?0:n==1?1:n==2?2:n%100>=3 && n%100<=10?3:n%100>=11 && n%100<=99?4:5;','messages'=>['Table'=>'جدول','Option'=>'خيار','Post meta'=>'بيانات المقال الوصفية','User meta'=>'بيانات المستخدم الوصفية','Cron event'=>'حدث cron','Plugin'=>'إضافة','Theme'=>'قالب','File'=>'الملف','The update could not be downloaded: the update token could not be obtained.'=>'تعذّر تنزيل التحديث: تعذّر الحصول على رمز التحديث.','The update could not be downloaded: a temporary file could not be created.'=>'تعذّر تنزيل التحديث: تعذّر إنشاء ملف مؤقت.','The update could not be downloaded: the repository answered with HTTP %d.'=>'تعذّر تنزيل التحديث: ردّ المستودع برمز HTTP %d.','Some kind of error occurred while trying to check the plugin license key.'=>'حدث خطأ أثناء محاولة التحقق من مفتاح ترخيص الإضافة.','Your license key has been activated!'=>'تم تفعيل مفتاح الترخيص الخاص بك!','Your license key has been deactivated!'=>'تم تعطيل مفتاح الترخيص الخاص بك!','Scan interrupted. Please try again.'=>'تمت مقاطعة الفحص. يرجى المحاولة مرة أخرى.','This scan was bounded, so this list may include media that is actually in use. Select the items you have checked yourself instead.'=>'كان هذا التحليل محدودًا، لذا قد تتضمن هذه القائمة وسائط مستخدمة فعلًا. حدّد بدلًا من ذلك العناصر التي راجعتها بنفسك.','Object cache'=>'تخزين الكائنات المؤقت','Available in WPOptimizing Pro.'=>'متاح في WPOptimizing Pro.','Pro feature — click to learn more'=>'ميزة Pro — انقر لمعرفة المزيد','feature badge' . "\4" . 'Pro'=>'Pro','Save as PDF / Print'=>'حفظ كـ PDF / طباعة','Close'=>'إغلاق','All extensions'=>'كل الإضافات','Filter by type'=>'تصفية حسب النوع','All types'=>'جميع الأنواع','Filter by extension'=>'تصفية حسب الإضافة','Items per page'=>'العناصر لكل صفحة','Filter'=>'تصفية','Protected from deletion — click to unprotect'=>'محمي من الحذف — انقر لإلغاء الحماية','Protect from deletion'=>'الحماية من الحذف','Value'=>'القيمة','Type'=>'النوع','Records'=>'السجلات','Size'=>'الحجم','Confidence'=>'الثقة','Extension'=>'إضافة','row' . "\0" . 'rows'=>'صف' . "\0" . 'صف' . "\0" . 'صفان' . "\0" . 'صفوف' . "\0" . 'صفًا' . "\0" . 'صف','Path relative to wp-content'=>'المسار النسبي إلى wp-content','Name'=>'الاسم','Slug'=>'المعرّف (Slug)','Attribution'=>'الإسناد','Crowd'=>'جماعي','Weight'=>'الوزن','Read on'=>'اقرأ المزيد على','Other sites confirm this autoloaded option belongs to an uninstalled extension — likely safe to disable.'=>'تؤكد مواقع أخرى أن خيار التحميل التلقائي هذا يخص إضافة غير مثبتة — من المرجح أنه آمن للتعطيل.','orphan · %s site' . "\0" . 'orphan · %s sites'=>'يتيم · %s موقع' . "\0" . 'يتيم · موقع واحد' . "\0" . 'يتيم · موقعان' . "\0" . 'يتيم · %s مواقع' . "\0" . 'يتيم · %s موقعًا' . "\0" . 'يتيم · %s موقع','WordPress core'=>'نواة ووردبريس','Transient'=>'مؤقت','Orphan'=>'يتيم','No installed plugin or theme, the scan or other sites claim this option. It may be left over from something uninstalled, or belong to code WPOptimizing cannot see.'=>'لا يطالب بهذا الخيار أي إضافة أو قالب مثبت، ولا الفحص ولا مواقع أخرى. قد يكون من بقايا شيء أُزيل، أو يعود إلى شيفرة لا يراها WPOptimizing.','Unattributed'=>'غير منسوبة','Likely orphan'=>'يتيم على الأرجح','Preview'=>'معاينة','File (relative to uploads)'=>'الملف (نسبةً إلى مجلد الرفع)','Suspected owner'=>'المالك المُحتمَل','Kept'=>'مُحتفَظ به','File to keep (lowest ID)'=>'الملف المُحتفَظ به (أقل معرّف)','Duplicates'=>'النسخ المكررة','Reclaimable'=>'قابل للاسترداد','edit'=>'تحرير','%s copy' . "\0" . '%s copies'=>'%s نسخة' . "\0" . '%s نسخة' . "\0" . '%s نسختان' . "\0" . '%s نسخ' . "\0" . '%s نسخة' . "\0" . '%s نسخة','ID'=>'المعرّف','No matching attachments.'=>'لا توجد مرفقات مطابقة.','Edit attachment'=>'تعديل المرفق','Image'=>'صورة','Dimensions'=>'الأبعاد','What would help'=>'ما الذي سيساعد','Est. saving'=>'التوفير التقديري','View image'=>'عرض الصورة','No images need attention.'=>'لا توجد صور تحتاج إلى معالجة.','Oversized'=>'أكبر من اللازم','No WebP'=>'بدون WebP','No AVIF'=>'بدون AVIF','Large file'=>'ملف كبير','Hook'=>'الخطّاف','Schedule'=>'الجدولة','Next run'=>'التشغيل التالي','Status'=>'الحالة','No scheduled events.'=>'لا توجد أحداث مجدولة.','Run now'=>'شغّل الآن','Resume'=>'استئناف','Pause'=>'إيقاف مؤقت','One-time'=>'مرة واحدة','in %s'=>'خلال %s','%s ago'=>'قبل %s','Paused'=>'موقوف مؤقتًا','Orphaned'=>'يتيم','Active'=>'النشطة','Engine'=>'المحرك','Rows'=>'الصفوف','Overhead'=>'العبء الزائد','No tables found.'=>'لم يتم العثور على جداول.','Manage in Orphans'=>'الإدارة في «اليتيمة»','Don\'t load'=>'عدم التحميل','Handle'=>'المعرّف','Owner'=>'المالك','Protected — cannot be disabled'=>'محمي — لا يمكن تعطيله','Not resolved on this site. %d site sharing its registry attributes this handle to this extension.' . "\0" . 'Not resolved on this site. %d sites sharing their registry attribute this handle to this extension.'=>'لم يُحدَّد في هذا الموقع. لا يوجد موقع يشارك سجله ينسب هذا المُعرِّف إلى هذه الإضافة.' . "\0" . 'لم يُحدَّد في هذا الموقع. موقع واحد (%d) يشارك سجله ينسب هذا المُعرِّف إلى هذه الإضافة.' . "\0" . 'لم يُحدَّد في هذا الموقع. موقعان (%d) يشاركان سجلهما ينسبان هذا المُعرِّف إلى هذه الإضافة.' . "\0" . 'لم يُحدَّد في هذا الموقع. %d مواقع تشارك سجلاتها تنسب هذا المُعرِّف إلى هذه الإضافة.' . "\0" . 'لم يُحدَّد في هذا الموقع. %d موقعًا تشارك سجلاتها تنسب هذا المُعرِّف إلى هذه الإضافة.' . "\0" . 'لم يُحدَّد في هذا الموقع. %d موقع تشارك سجلاتها تنسب هذا المُعرِّف إلى هذه الإضافة.','shared data'=>'بيانات مشتركة','The sites sharing their registry attribute this handle to more than one extension, so its owner cannot be established. Check what uses it before unloading it.'=>'المواقع التي تشارك سجلاتها تنسب هذا المُعرِّف إلى أكثر من إضافة، لذلك لا يمكن تحديد مالكه. تحقق مما يستخدمه قبل إلغاء تحميله.','conflicting'=>'متعارض','Style'=>'نمط','Script'=>'سكربت','Match'=>'المطابقة','exact'=>'مطابق','contains'=>'يحتوي','Remove'=>'إزالة','Empty records'=>'سجلات فارغة','In use'=>'قيد الاستخدام','Inactive'=>'غير نشط','To identify'=>'قيد التحديد','read-only'=>'للقراءة فقط','No snapshots match these filters.'=>'لا توجد لقطات تطابق هذه المرشحات.','No backups match the current filter.'=>'لا توجد نسخة احتياطية تطابق التصفية الحالية.','Undo this action? What it changed is put back as it was before.'=>'هل تريد التراجع عن هذا الإجراء؟ سيعود ما غيّره كما كان.','Undo'=>'تراجع','Improve attribution for your site — and everyone’s'=>'حسِّن إسناد موقعك — وإسناد الجميع','Data sharing is off. Turn it on and WPOptimizing contributes only attribution metadata (names, sizes and how often things are seen — never values or content) to a shared dataset, and in return your site receives it, so plugins and options are identified far more accurately. It is reciprocal: while it is off, your site does not receive the shared dataset.'=>'مشاركة البيانات مُعطَّلة. فعِّلها وسيُسهم WPOptimizing ببيانات إسناد فقط (الأسماء والأحجام وعدد مرات الظهور — وليس القيم أو المحتوى) في مجموعة بيانات مشتركة، وفي المقابل يستقبلها موقعك، فتُحدَّد الإضافات والخيارات بدقة أعلى بكثير. وهي متبادلة: ما دامت مُعطَّلة، لا يستقبل موقعك مجموعة البيانات المشتركة.','Turn on sharing'=>'تفعيل المشاركة','Not now'=>'ليس الآن','Autoload turned off for %d non-essential option (reversible).' . "\0" . 'Autoload turned off for %d non-essential options (reversible).'=>'تم إيقاف التحميل التلقائي لـ %d خيار غير ضروري (قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي لـ %d خيار غير ضروري (قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي لـ %d خيارين غير ضروريين (قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي لـ %d خيارات غير ضرورية (قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي لـ %d خيارًا غير ضروري (قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي لـ %d خيار غير ضروري (قابل للتراجع).','Not enough usage measured yet. WPOptimizing is learning which autoloaded options are actually read on your site; check back in a day or two, or after more visits.'=>'لم يُقَس استخدام كافٍ بعد. يتعلّم WPOptimizing أيّ الخيارات ذاتية التحميل تُقرأ فعليًا على موقعك؛ تحقّق مرة أخرى بعد يوم أو يومين، أو بعد مزيد من الزيارات.','Autoload turned off for %1$d never-read option (%2$s off every request, reversible).' . "\0" . 'Autoload turned off for %1$d never-read options (%2$s off every request, reversible).'=>'تم إيقاف التحميل التلقائي عن %1$d خيار لا يُقرأ أبدًا (%2$s أقل في كل طلب، قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي عن خيار واحد لا يُقرأ أبدًا (%2$s أقل في كل طلب، قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي عن خيارين لا يُقرآن أبدًا (%2$s أقل في كل طلب، قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي عن %1$d خيارات لا تُقرأ أبدًا (%2$s أقل في كل طلب، قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي عن %1$d خيارًا لا يُقرأ أبدًا (%2$s أقل في كل طلب، قابل للتراجع).' . "\0" . 'تم إيقاف التحميل التلقائي عن %1$d خيار لا يُقرأ أبدًا (%2$s أقل في كل طلب، قابل للتراجع).','Timeline retention updated.'=>'تم تحديث مدة الاحتفاظ بالمخطط الزمني.','You do not have permission to change the WP-Cron setting.'=>'ليس لديك صلاحية لتغيير إعداد WP-Cron.','wp-config.php could not be located, so WP-Cron was left unchanged.'=>'تعذّر تحديد موقع wp-config.php، لذا لم يتم تغيير WP-Cron.','wp-config.php is not writable. Add the constant manually using the snippet shown below.'=>'الملف wp-config.php غير قابل للكتابة. أضف الثابت يدويًا باستخدام المقتطف المعروض أدناه.','wp-config.php has an unexpected format, so it was left untouched. Add the constant manually.'=>'الملف wp-config.php بتنسيق غير متوقّع، لذا لم يتم تعديله. أضف الثابت يدويًا.','Could not save wp-config.php. Check file permissions and try again.'=>'تعذّر حفظ wp-config.php. تحقّق من أذونات الملف وحاول مرة أخرى.','WP-Cron disabled. Now add the system-cron line shown below so scheduled tasks keep running.'=>'تم تعطيل WP-Cron. أضف الآن سطر cron الخاص بالنظام المعروض أدناه حتى تستمر المهام المجدولة في العمل.','WP-Cron re-enabled — WordPress will run scheduled tasks on page loads again.'=>'تمت إعادة تفعيل WP-Cron — سيقوم ووردبريس بتشغيل المهام المجدولة عند تحميل الصفحات مجددًا.','WP-Cron was left unchanged.'=>'لم يتم تغيير WP-Cron.','No reclaimable overhead was found — nothing to optimize.'=>'لم يتم العثور على زيادة قابلة للاسترداد — لا شيء لتحسينه.','%d table optimized — overhead reclaimed.' . "\0" . '%d tables optimized — overhead reclaimed.'=>'تم تحسين %d جدول — تم استرداد الزيادة.' . "\0" . 'تم تحسين جدول واحد — تم استرداد الزيادة.' . "\0" . 'تم تحسين جدولين — تم استرداد الزيادة.' . "\0" . 'تم تحسين %d جداول — تم استرداد الزيادة.' . "\0" . 'تم تحسين %d جدولًا — تم استرداد الزيادة.' . "\0" . 'تم تحسين %d جدول — تم استرداد الزيادة.','Local Google Fonts removed — the site will use the original Google-hosted fonts again.'=>'تمت إزالة خطوط Google المحلية — سيعود الموقع إلى استخدام الخطوط المستضافة على Google.','Activity log cleared. Tracking continues from now.'=>'تم مسح سجل النشاط. تستمر المتابعة من الآن.','Thank you! Data sharing is now on — your attribution metadata helps everyone, and your site now receives the shared dataset too.'=>'شكرًا! أصبحت مشاركة البيانات مفعّلة الآن — تساعد بيانات الإسناد لديك الجميع، ويستقبل موقعك الآن أيضًا مجموعة البيانات المشتركة.','nothing to download'=>'لا شيء لتنزيله','all %d layers'=>'الطبقات الـ%d كلها','%1$d of %2$d layers. Did not arrive — %3$s'=>'%1$d من %2$d طبقة. لم تصل: %3$s','Data sharing is off, so nothing was uploaded.'=>'مشاركة البيانات معطّلة، لذا لم يُرفع أي شيء.','Download: %s.'=>'التنزيل: %s.','database'=>'قاعدة البيانات','files'=>'الملفات','assets'=>'الموارد','autoload'=>'التحميل التلقائي','paused after repeated failures'=>'متوقف مؤقتًا بعد إخفاقات متكررة','daily limit reached, it goes out tomorrow'=>'تم بلوغ الحد اليومي؛ سيُرسل غدًا','Shared dataset synced. Upload — %1$s. Download: %2$s.'=>'تمت مزامنة مجموعة البيانات المشتركة. الرفع — %1$s. التنزيل: %2$s.','nothing to send'=>'لا شيء لإرساله','Cleanup profile applied.'=>'تم تطبيق ملف التنظيف.','Unknown cleanup profile.'=>'ملف تنظيف غير معروف.','Actions executed. Run a rescan to refresh the lists.'=>'تم تنفيذ الإجراءات. قم بإعادة الفحص لتحديث القوائم.','You do not have sufficient permissions.'=>'ليس لديك الأذونات الكافية.','<strong>Large installation:</strong> Results are limited to %1$d rows to prevent memory exhaustion. Add <code>define( \'%2$s\', 100000 );</code> to wp-config.php to raise the limit.'=>'<strong>تثبيت كبير:</strong> النتائج محدودة بـ %1$d صف لمنع استنفاد الذاكرة. أضف <code>define( \'%2$s\', 100000 );</code> إلى wp-config.php لرفع الحد.','WPOptimizing sections'=>'أقسام WPOptimizing','Menu'=>'القائمة','Settings'=>'الإعدادات','Collapse or expand the menu'=>'طيّ القائمة أو توسيعها','Collapse menu'=>'طيّ القائمة','Database'=>'قاعدة البيانات','Files'=>'الملفات','Entries confirmed as belonging to extensions that are no longer installed. Nothing on the site uses them; delete them unless you plan to reinstall that extension and keep its settings (a backup is made first).'=>'إدخالات تأكَّد انتماؤها إلى إضافات لم تعد مثبَّتة. لا يستخدمها أي شيء في الموقع؛ احذفها ما لم تكن تنوي إعادة تثبيت تلك الإضافة والاحتفاظ بإعداداتها (تُنشأ نسخة احتياطية أولًا).','Nothing was left behind by uninstalled extensions. If you no longer use a plugin or theme, uninstall it from the Inactive tab and re-run the analysis.'=>'لم تترك الإضافات المُلغى تثبيتها أي شيء. إذا لم تعد تستخدم إضافة أو قالبًا، فألغِ تثبيته من تبويب «غير المفعّلة» وأعد تشغيل التحليل.','Files and folders confirmed as belonging to extensions that are no longer installed. Nothing on the site uses them; delete them unless you plan to reinstall that extension and keep its data (a backup is made first).'=>'ملفات ومجلدات تأكَّد انتماؤها إلى إضافات لم تعد مثبَّتة. لا يستخدمها أي شيء في الموقع؛ احذفها ما لم تكن تنوي إعادة تثبيت تلك الإضافة والاحتفاظ ببياناتها (تُنشأ نسخة احتياطية أولًا).','Plugins & Themes'=>'الإضافات والقوالب','This section lists options, tables, user roles, data types, and taxonomies that belong to installed but currently inactive plugins or themes. These items are not required for the site to run now, though they may be needed again if those extensions are reactivated.'=>'يسرد هذا القسم الخيارات والجداول وأدوار المستخدمين وأنواع البيانات والتصنيفات التي تنتمي إلى إضافات أو قوالب مثبتة لكنها غير نشطة حاليًا. هذه العناصر غير مطلوبة لتشغيل الموقع الآن، لكنها قد تكون مطلوبة مرة أخرى إذا أُعيد تفعيل تلك الإضافات.','You can select or deselect all rows from the header checkbox, or manually mark and unmark the ones you want to keep or remove. Once you have reviewed your selection, click <strong>Delete</strong> to apply the changes.'=>'يمكنك تحديد أو إلغاء تحديد جميع الصفوف من مربع الاختيار في الرأس، أو تحديد وإلغاء تحديد الصفوف التي تريد الاحتفاظ بها أو إزالتها يدويًا. بعد مراجعة اختيارك، انقر <strong>حذف</strong> لتطبيق التغييرات.','Nothing here belongs to inactive extensions. If you stopped using a plugin or theme, uninstall it from the Plugins & Themes list so WPOptimizing can flag anything it leaves behind.'=>'لا شيء هنا يخص إضافات غير نشطة. إن توقفت عن استخدام إضافة أو قالب، فأزِله من قائمة الإضافات والقوالب كي يستطيع WPOptimizing الإشارة إلى ما يخلّفه.','This section lists files and folders that belong to installed but currently inactive plugins or themes. These items are not required for the site to run now, though they may be needed again if those extensions are reactivated.'=>'يسرد هذا القسم الملفات والمجلدات التي تنتمي إلى إضافات أو قوالب مثبتة لكنها غير نشطة حاليًا. هذه العناصر غير مطلوبة لتشغيل الموقع الآن، لكنها قد تكون مطلوبة مرة أخرى إذا أُعيد تفعيل تلك الإضافات.','This section lists installed plugins and themes that are currently inactive. You can select them to uninstall directly and, if you want, check the option to also remove all associated disposable items.'=>'يسرد هذا القسم الإضافات والقوالب المثبتة غير النشطة حاليًا. يمكنك تحديدها لإزالتها مباشرة، وإذا رغبت، تفعيل خيار إزالة جميع العناصر القابلة للإزالة المرتبطة.','No inactive plugins or themes — everything installed is in use. Check Orphans for leftovers from extensions you have already removed.'=>'لا إضافات أو قوالب غير نشطة — كل المُثبَّت قيد الاستخدام. راجع "اليتيمة" بحثًا عن بقايا إضافات أزلتها سابقًا.','Review orphans'=>'مراجعة اليتيمة','Records currently associated with active plugins or themes. You cannot delete these, but if one is attributed to the wrong extension you can select it and reassign it to the correct owner below.'=>'السجلات المرتبطة حاليًا بإضافات أو قوالب مُفعّلة. لا يمكنك حذفها، ولكن إذا كان أحدها منسوبًا إلى الإضافة الخطأ، يمكنك تحديده وإعادة نسبه إلى المالك الصحيح بالأسفل.','This informational view lists database records attributed to your active extensions; it fills in after an analysis runs.'=>'يعرض هذا العرض المعلوماتي سجلات قاعدة البيانات المنسوبة إلى إضافاتك النشطة؛ ويمتلئ بعد تشغيل تحليل.','This section lists files and folders currently associated with active plugins or themes. It is informational and does not allow deletion.'=>'يسرد هذا القسم الملفات والمجلدات المرتبطة حالياً بالإضافات أو القوالب النشطة. وهو للعرض فقط ولا يسمح بالحذف.','This informational view lists files attributed to your active extensions; it fills in after an analysis runs.'=>'يعرض هذا العرض المعلوماتي الملفات المنسوبة إلى إضافاتك النشطة؛ ويمتلئ بعد تشغيل تحليل.','This section lists active plugins and themes. You can select items to deactivate.'=>'يسرد هذا القسم الإضافات والقوالب النشطة. يمكنك تحديد العناصر لتعطيلها.','Home'=>'الرئيسية','Where your site stands and what to do next. Nothing on this page changes your site: each suggestion opens the screen that does it, where you confirm it.'=>'حالة موقعك وما يجب فعله بعد ذلك. لا شيء في هذه الصفحة يغيّر موقعك: كل اقتراح يفتح الشاشة التي تنفّذه، حيث تؤكده.','What the analysis found'=>'ما وجده التحليل','Records and files the last analysis attributed, by state. Open one to review it.'=>'السجلات والملفات التي نسبها آخر تحليل، حسب الحالة. افتح أحدها لمراجعته.','Orphans'=>'يتيمة','Left behind by extensions that are no longer installed. Attributed with evidence: you can delete them (a backup is made first).'=>'بقايا إضافات لم تعد مثبتة. منسوبة بأدلة: يمكنك حذفها (تُنشأ نسخة احتياطية أولًا).','No owner could be identified. They may belong to something still in use: review them one by one before deleting anything.'=>'تعذّر تحديد مالكها. قد تعود إلى شيء لا يزال قيد الاستخدام: راجعها واحدًا تلو الآخر قبل حذف أي شيء.','They belong to plugins or themes that are installed but deactivated. Delete them only if you will not use those extensions again.'=>'تعود إلى إضافات أو قوالب مثبتة لكنها معطّلة. احذفها فقط إن لم تكن ستستخدم تلك الإضافات مجددًا.','Empty'=>'فارغة','Records with no value stored. The Status column says whose they are; those of active extensions or WordPress are read-only.'=>'سجلات لا تحتوي أي قيمة مخزّنة. يوضح عمود الحالة لمن تعود؛ سجلات الإضافات المفعّلة أو ووردبريس للقراءة فقط.','They belong to active extensions or WordPress. Read-only: fix a wrong owner or protect a record, but nothing is deleted here.'=>'تعود إلى إضافات مفعّلة أو إلى ووردبريس. للقراءة فقط: يمكنك تصحيح مالك خاطئ أو حماية سجل، لكن لا يُحذف شيء هنا.','Filter the results by state'=>'تصفية النتائج حسب الحالة','Diagnose'=>'التشخيص','Performance'=>'الأداء','History'=>'السجل','Speed'=>'السرعة','Cache'=>'التخزين المؤقت','Page & browser'=>'الصفحة والمتصفح','Smart Assets'=>'الموارد الذكية','Autoload'=>'التحميل التلقائي','Clean up'=>'التنظيف','General cleanup'=>'التنظيف العام','Tables'=>'الجداول','Cron jobs'=>'مهام cron','Media'=>'الوسائط','Review the analysis'=>'مراجعة التحليل','Analysis results'=>'نتائج التحليل','History & recovery'=>'السجل والاستعادة','Activity'=>'النشاط','Backups'=>'النسخ الاحتياطية','Help'=>'مساعدة','Documentation'=>'التوثيق','No analysis has been completed yet.'=>'لم يتم إكمال أي تحليل بعد.','Analyze now'=>'تحليل الآن','Please wait while we analyse your ecosystem.'=>'يرجى الانتظار أثناء تحليل نظامك البيئي.','Great news! There is nothing to display in this section.'=>'أخبار رائعة! لا يوجد شيء لعرضه في هذا القسم.','%1$d in the database and %2$d files, left by uninstalled plugins, can be reviewed and cleaned.'=>'%1$d في قاعدة البيانات و%2$d من الملفات، تركتها إضافات أُلغي تثبيتها، يمكن مراجعتها وتنظيفها.','%d file left by an uninstalled plugin can be reviewed and cleaned.' . "\0" . '%d files left by uninstalled plugins can be reviewed and cleaned.'=>'لا توجد ملفات متروكة لمراجعتها.' . "\0" . 'يمكن مراجعة وتنظيف ملف واحد تركته إضافة أُلغي تثبيتها.' . "\0" . 'يمكن مراجعة وتنظيف ملفين تركتهما إضافات أُلغي تثبيتها.' . "\0" . 'يمكن مراجعة وتنظيف %d ملفات تركتها إضافات أُلغي تثبيتها.' . "\0" . 'يمكن مراجعة وتنظيف %d ملفاً تركتها إضافات أُلغي تثبيتها.' . "\0" . 'يمكن مراجعة وتنظيف %d ملف تركتها إضافات أُلغي تثبيتها.','%d record left by an uninstalled plugin can be reviewed and cleaned.' . "\0" . '%d records left by uninstalled plugins can be reviewed and cleaned.'=>'يمكن مراجعة %d سجل تركتها إضافات مُزالة وتنظيفها.' . "\0" . 'يمكن مراجعة سجل واحد تركته إضافة مُزالة وتنظيفه.' . "\0" . 'يمكن مراجعة سجلَّين تركتهما إضافات مُزالة وتنظيفهما.' . "\0" . 'يمكن مراجعة %d سجلات تركتها إضافات مُزالة وتنظيفها.' . "\0" . 'يمكن مراجعة %d سجلاً تركتها إضافات مُزالة وتنظيفها.' . "\0" . 'يمكن مراجعة %d سجل تركتها إضافات مُزالة وتنظيفها.','Orphaned records found'=>'تم العثور على سجلات يتيمة','Analysis is out of date'=>'التحليل قديم','Last analysed %s ago — re-run it to refresh the findings.'=>'آخر تحليل قبل %s — أعد تشغيله لتحديث النتائج.','Autoloaded options are heavy'=>'خيارات التحميل التلقائي ثقيلة','%s of options load on every page request. Review what can be disabled.'=>'يتم تحميل %s من الخيارات في كل طلب صفحة. راجع ما يمكن تعطيله.','Review autoload'=>'مراجعة التحميل التلقائي','Reclaimable media space'=>'مساحة وسائط قابلة للاسترداد','About %s in duplicate or potentially-unused attachments.'=>'حوالي %s في المرفقات المكررة أو غير المستخدمة المحتملة.','Review media'=>'مراجعة الوسائط','Orphaned scheduled tasks'=>'مهام مجدولة يتيمة','%d scheduled event left by an uninstalled plugin.' . "\0" . '%d scheduled events left by uninstalled plugins.'=>'%d حدث مجدول تركتها إضافات مُزالة.' . "\0" . 'حدث مجدول واحد تركته إضافة مُزالة.' . "\0" . 'حدثان مجدولان تركتهما إضافات مُزالة.' . "\0" . '%d أحداث مجدولة تركتها إضافات مُزالة.' . "\0" . '%d حدثًا مجدولًا تركتها إضافات مُزالة.' . "\0" . '%d حدث مجدول تركتها إضافات مُزالة.','Review cron jobs'=>'مراجعة مهام cron','Excellent'=>'ممتاز','Good'=>'جيد','Fair'=>'مقبول','Needs work'=>'يحتاج إلى تحسين','Reduce autoload weight'=>'تقليل وزن التحميل التلقائي','Remove orphaned items'=>'إزالة العناصر اليتيمة','Reclaim media space'=>'استعادة مساحة الوسائط','Delete expired transients'=>'حذف Transients منتهية الصلاحية','Trim the options table'=>'تقليص جدول الخيارات','Optimization health score: %d out of 100'=>'درجة صحة التحسين: %d من 100','Optimization health'=>'صحة التحسين','Server TTFB (avg)'=>'زمن أول بايت من الخادم (المتوسط)','Your site is in great shape. Keep it that way with a periodic analysis.'=>'موقعك في حالة ممتازة. حافظ عليها بتحليل دوري.','Top ways to raise your score:'=>'أفضل الطرق لرفع درجتك:','Optimization health — open the dashboard for details'=>'حالة التحسين — افتح لوحة التحكم لمزيد من التفاصيل','Needs attention'=>'يتطلب الانتباه','Warning:'=>'تحذير:','Heads up:'=>'تنبيه:','More info'=>'مزيد من المعلومات','Unlock this with Pro'=>'افتحها مع Pro','The free plan analyses everything and shows up to 25 records in each list. WPOptimizing Pro lets you act on them — clean orphans, disable autoload, optimise media and more. Those deletions, like the general cleanup, are backed up first and restorable.'=>'تحلّل الخطة المجانية كل شيء وتعرض ما يصل إلى 25 سجلًّا في كل قائمة. ويتيح لك WPOptimizing Pro التصرف بناءً عليها: تنظيف اليتيم، وتعطيل التحميل التلقائي، وتحسين الوسائط وغير ذلك. تُنسخ هذه العمليات احتياطيًا قبل تنفيذها، شأنها شأن التنظيف العام، ويمكن استعادتها.','Upgrade to Pro'=>'رقِّ إلى Pro','Delete selected'=>'حذف المحدد','Process all'=>'معالجة الكل','A backup is created before deletion.'=>'يتم إنشاء نسخة احتياطية قبل الحذف.','Delete the %d selected item(s)? A backup is created first.'=>'حذف العناصر المحددة وعددها %d؟ يتم إنشاء نسخة احتياطية أولاً.','Process ALL %d filtered item(s)? A backup is created first.'=>'معالجة جميع العناصر المُصفّاة وعددها %d؟ يتم إنشاء نسخة احتياطية أولاً.','WPOptimizing — Working…'=>'WPOptimizing — جارٍ المعالجة…','Also delete the content of orphaned custom post types and the terms of orphaned taxonomies (backed up and restorable).'=>'احذف أيضاً محتوى أنواع المقالات المخصصة اليتيمة ومصطلحات التصنيفات اليتيمة (مع نسخ احتياطي وقابلية للاستعادة).','“Process all” is capped at 20,000 items per run; repeat to continue.'=>'‏«معالجة الكل» محدودة بـ 20,000 عنصر في كل تشغيل؛ كرّر العملية للمتابعة.','Select at least one item first.'=>'حدد عنصراً واحداً على الأقل أولاً.','This scan was bounded, so acting on everything is not offered. Tick the items you have checked yourself.'=>'كان هذا التحليل محدودًا، لذا لا يُتاح التنفيذ على الكل. حدّد العناصر التي راجعتها بنفسك.','Select the items to delete'=>'حدّد العناصر المراد حذفها','Processing %1$s of %2$s…'=>'جارٍ معالجة %1$s من %2$s…','Done — %s processed. Reloading…'=>'تم — تمت معالجة %s. جارٍ إعادة التحميل…','A batch failed. Stopping and reporting what was done…'=>'فشلت دفعة. جارٍ الإيقاف وتلخيص ما تم…','One or more selected items are attributed by heuristic or are unknown — they may belong to an active plugin. Continue?'=>'عنصر واحد أو أكثر من العناصر المحددة مُسند اكتشافياً أو غير معروف — قد ينتمي إلى إضافة نشطة. هل تريد المتابعة؟','%d of the items to process are attributed by heuristic or are unknown — they may belong to an active plugin. Review them, or filter by confidence first. Continue anyway?'=>'%d من العناصر المراد معالجتها منسوبة بالاستدلال أو غير معروفة — قد تعود إلى إضافة مفعّلة. راجعها أو صفِّ حسب الثقة أولًا. هل تريد المتابعة على أي حال؟','Optimizing tables'=>'جارٍ تحسين الجداول','Converting tables to InnoDB'=>'جارٍ تحويل الجداول إلى InnoDB','Deleting attachments'=>'جارٍ حذف المرفقات','Marking as known'=>'يجري التحديد كمعروف','Deleting duplicates'=>'جارٍ حذف التكرارات','Removing scheduled events'=>'جارٍ إزالة الأحداث المجدولة','Updating options'=>'جارٍ تحديث الخيارات','Deleting records'=>'جارٍ حذف السجلات','Deleting files'=>'جارٍ حذف الملفات','Search'=>'بحث','When uninstalling, also remove any unnecessary files or data associated with the selected plugins or themes.'=>'عند إلغاء التثبيت، أزل أيضًا أي ملفات أو بيانات غير ضرورية مرتبطة بالإضافات أو القوالب المحددة.','Deleted records are removed from the scan immediately. Low-confidence selections are confirmed first.'=>'تُزال السجلات المحذوفة من الفحص فوراً. يتم تأكيد التحديدات منخفضة الثقة أولاً.','A copy is saved to the Backups tab before deletion.'=>'يتم حفظ نسخة في علامة تبويب النسخ الاحتياطية قبل الحذف.','Attribute selected'=>'إسناد المحدد','Protect selected'=>'حماية المحدد','Unprotect selected'=>'إلغاء حماية المحدد','Select records to reassign a wrong attribution, or to protect them from future cleanups. Active records are never deleted here.'=>'حدّد السجلات لإعادة نسب خاطئ أو لحمايتها من عمليات التنظيف المستقبلية. لا تُحذف السجلات النشطة هنا أبدًا.','Delete'=>'حذف','Select at least one plugin or theme first.'=>'اختر إضافة أو قالبًا واحدًا على الأقل أولًا.','These plugins and themes will be uninstalled: their files are deleted from the server. This cannot be undone from WPOptimizing.'=>'سيتم إلغاء تثبيت هذه الإضافات والقوالب: تُحذف ملفاتها من الخادم. لا يمكن التراجع عن ذلك من WPOptimizing.','Their data and files found by the analysis will also be deleted (a copy is saved to Backups).'=>'ستُحذف أيضًا بياناتها وملفاتها التي وجدها التحليل (تُحفظ نسخة في النسخ الاحتياطية).','These plugins and themes will be deactivated. You can activate them again from the Plugins screen.'=>'سيتم تعطيل هذه الإضافات والقوالب. يمكنك تفعيلها مجددًا من شاشة الإضافات.','One or more selected items are attributed by heuristic or are unknown — they may belong to an active plugin. Are you sure you want to delete them?'=>'عنصر واحد أو أكثر من العناصر المحددة مُسند اكتشافياً أو غير معروف — قد ينتمي إلى إضافة نشطة. هل أنت متأكد من رغبتك في حذفها؟','Confidence:'=>'الثقة:','View its content in the database'=>'عرض محتواه في قاعدة البيانات','Full content'=>'المحتوى الكامل','Query failed.'=>'فشل الاستعلام.','No rows found.'=>'لم يتم العثور على صفوف.','Click to view the full content'=>'انقر لعرض المحتوى الكامل','Showing first 50 rows.'=>'عرض أول 50 صفاً.','Request failed.'=>'فشل الطلب.','Test mode: apply only for logged-in administrators'=>'وضع الاختبار: التطبيق على المسؤولين المسجّلين فقط','While test mode is on, only you (a logged-in user who can manage WPOptimizing) get the change; visitors get the page as before. Check your key pages, then switch test mode off to apply it to everyone.'=>'طالما وضع الاختبار مفعّل، تظهر التغييرات لك وحدك (مستخدم مسجّل يمكنه إدارة WPOptimizing)؛ ويرى الزوار الصفحة كما كانت. راجع صفحاتك الأساسية، ثم أوقف وضع الاختبار لتطبيقها على الجميع.','Unsaved changes'=>'تغييرات غير محفوظة','No related inactive extensions.'=>'لا توجد إضافات غير نشطة ذات صلة.','Uninstall selected'=>'إلغاء تثبيت المحدد','No related active extensions.'=>'لا توجد امتدادات نشطة مرتبطة.','Deactivate selected'=>'تعطيل المحدد','%d attachment marked as known; it will no longer appear as unused.' . "\0" . '%d attachments marked as known; they will no longer appear as unused.'=>'تم تحديد %d مرفق كمعروفة؛ لن تظهر بعد الآن كغير مستخدمة.' . "\0" . 'تم تحديد مرفق واحد كمعروف؛ لن يظهر بعد الآن كغير مستخدم.' . "\0" . 'تم تحديد مرفقين كمعروفين؛ لن يظهرا بعد الآن كغير مستخدمين.' . "\0" . 'تم تحديد %d مرفقات كمعروفة؛ لن تظهر بعد الآن كغير مستخدمة.' . "\0" . 'تم تحديد %d مرفقًا كمعروفة؛ لن تظهر بعد الآن كغير مستخدمة.' . "\0" . 'تم تحديد %d مرفق كمعروفة؛ لن تظهر بعد الآن كغير مستخدمة.','%d orphaned scheduled event unscheduled.' . "\0" . '%d orphaned scheduled events unscheduled.'=>'تم إلغاء جدولة %d حدث مجدول يتيم.' . "\0" . 'تم إلغاء جدولة حدث مجدول يتيم واحد.' . "\0" . 'تم إلغاء جدولة حدثَين مجدولَين يتيمَين.' . "\0" . 'تم إلغاء جدولة %d أحداث مجدولة يتيمة.' . "\0" . 'تم إلغاء جدولة %d حدثاً مجدولاً يتيماً.' . "\0" . 'تم إلغاء جدولة %d حدث مجدول يتيم.','%d table optimized.' . "\0" . '%d tables optimized.'=>'تم تحسين %d جدول.' . "\0" . 'تم تحسين جدول واحد.' . "\0" . 'تم تحسين جدولَين.' . "\0" . 'تم تحسين %d جداول.' . "\0" . 'تم تحسين %d جدولاً.' . "\0" . 'تم تحسين %d جدول.','%d table converted to InnoDB.' . "\0" . '%d tables converted to InnoDB.'=>'تم تحويل %d جدول إلى InnoDB.' . "\0" . 'تم تحويل جدول واحد إلى InnoDB.' . "\0" . 'تم تحويل جدولَين إلى InnoDB.' . "\0" . 'تم تحويل %d جداول إلى InnoDB.' . "\0" . 'تم تحويل %d جدولاً إلى InnoDB.' . "\0" . 'تم تحويل %d جدول إلى InnoDB.','Images optimized: %1$d recompressed/resized, %2$d WebP and %3$d AVIF copies created.'=>'تم تحسين الصور: %1$d أُعيد ضغطها/تحجيمها، وأُنشئت %2$d نسخة WebP و%3$d نسخة AVIF.','The action stopped before changing anything. Please try again.'=>'توقف الإجراء قبل أن يغيّر أي شيء. حاول مرة أخرى.','The action stopped part-way because a batch failed. Part of it may have been applied: check the list, and run it again for the rest.'=>'توقف الإجراء في منتصفه لأن دفعة فشلت. ربما طُبّق جزء منه: راجع القائمة وشغّله مجددًا للباقي.','Autoload turned off for %s option.' . "\0" . 'Autoload turned off for %s options.'=>'أُوقف التحميل التلقائي لـ %s خيار.' . "\0" . 'أُوقف التحميل التلقائي لخيار واحد.' . "\0" . 'أُوقف التحميل التلقائي لخيارين.' . "\0" . 'أُوقف التحميل التلقائي لـ %s خيارات.' . "\0" . 'أُوقف التحميل التلقائي لـ %s خيارًا.' . "\0" . 'أُوقف التحميل التلقائي لـ %s خيار.','%s record deleted.' . "\0" . '%s records deleted.'=>'حُذف %s سجل.' . "\0" . 'حُذف سجل واحد.' . "\0" . 'حُذف سجلان.' . "\0" . 'حُذفت %s سجلات.' . "\0" . 'حُذف %s سجلًا.' . "\0" . 'حُذف %s سجل.','%s could not be removed and stays in the list.' . "\0" . '%s could not be removed and stay in the list.'=>'تعذّر حذف %s سجل، وتبقى في القائمة.' . "\0" . 'تعذّر حذف سجل واحد، ويبقى في القائمة.' . "\0" . 'تعذّر حذف سجلين، ويبقيان في القائمة.' . "\0" . 'تعذّر حذف %s سجلات، وتبقى في القائمة.' . "\0" . 'تعذّر حذف %s سجلًا، وتبقى في القائمة.' . "\0" . 'تعذّر حذف %s سجل، وتبقى في القائمة.','%s item processed.' . "\0" . '%s items processed.'=>'عولج %s عنصر.' . "\0" . 'عولج عنصر واحد.' . "\0" . 'عولج عنصران.' . "\0" . 'عولجت %s عناصر.' . "\0" . 'عولج %s عنصرًا.' . "\0" . 'عولج %s عنصر.','The action stopped part-way because a batch failed.'=>'توقف الإجراء في منتصفه لأن دفعة فشلت.','The rest was not touched; you can run it again.'=>'لم يُمسّ الباقي؛ يمكنك تشغيله مجددًا.','You can undo it below, or from the Autoload tab at any time.'=>'يمكنك التراجع عنه أدناه، أو من تبويب Autoload في أي وقت.','A backup was made first: you can undo it below, or from Backups at any time.'=>'أُنشئت نسخة احتياطية أولًا: يمكنك التراجع أدناه، أو من النسخ الاحتياطية في أي وقت.','That action can no longer be undone from here. Its backup, if any, is still in Backups.'=>'لم يعد بالإمكان التراجع عن هذا الإجراء من هنا. نسخته الاحتياطية، إن وجدت، لا تزال في النسخ الاحتياطية.','Undone: autoload turned back on for %s option.' . "\0" . 'Undone: autoload turned back on for %s options.'=>'تم التراجع: أُعيد التحميل التلقائي لـ %s خيار.' . "\0" . 'تم التراجع: أُعيد التحميل التلقائي لخيار واحد.' . "\0" . 'تم التراجع: أُعيد التحميل التلقائي لخيارين.' . "\0" . 'تم التراجع: أُعيد التحميل التلقائي لـ %s خيارات.' . "\0" . 'تم التراجع: أُعيد التحميل التلقائي لـ %s خيارًا.' . "\0" . 'تم التراجع: أُعيد التحميل التلقائي لـ %s خيار.','Undone: what that action deleted was restored from its backup. Run a new analysis to refresh the lists.'=>'تم التراجع: استُعيد ما حذفه ذلك الإجراء من نسخته الاحتياطية. شغّل تحليلًا جديدًا لتحديث القوائم.','More help'=>'مزيد من المساعدة','Support'=>'الدعم','Read the full article in the knowledge base'=>'اقرأ المقال الكامل في قاعدة المعرفة','Analysis'=>'التحليل','The analysis reads your plugins, themes, database and files and works out who owns each record and file. It runs in the background in stages, so the window can be closed, and it changes nothing on the site.'=>'يقرأ التحليل الإضافات والقوالب وقاعدة البيانات والملفات ويحدّد مالك كل سجل وكل ملف. يعمل في الخلفية على مراحل، لذا يمكن إغلاق النافذة، ولا يغيّر أي شيء في الموقع.','starts a new analysis straight away, whatever the low-traffic window says; at most five per hour.'=>'يبدأ تحليلًا جديدًا فورًا، بصرف النظر عن نافذة الحركة المنخفضة؛ خمس مرات في الساعة كحد أقصى.','View report'=>'عرض التقرير','opens a printable summary of the last analysis in a new window.'=>'يفتح ملخصًا قابلًا للطباعة لآخر تحليل في نافذة جديدة.','Below the buttons, the date of the last analysis. If the database cut some of its queries short, a notice says so and the database lists keep the results of the previous analysis.'=>'أسفل الأزرار يظهر تاريخ آخر تحليل. إذا قطعت قاعدة البيانات بعض استعلاماتها قبل اكتمالها، يُشير تنبيه إلى ذلك، وتحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق.','Where your site stands and what to do next. Nothing on this page changes your site: each suggestion opens the screen that does it.'=>'أين يقف موقعك وما الخطوة التالية. لا شيء في هذه الصفحة يغيّر موقعك: كل اقتراح يفتح الشاشة التي تنفّذه.','Site status'=>'حالة الموقع','three cards: the weight of the autoloaded options (healthy under 800 KB), the orphaned data the analysis found and the state of the object cache.'=>'ثلاث بطاقات: حجم الخيارات المحمّلة تلقائيًا (سليم إذا كان أقل من 800 KB)، والبيانات اليتيمة التي وجدها التحليل، وحالة تخزين الكائنات المؤقت.','a score out of 100 with the server response time and up to three ways to raise it.'=>'درجة من 100 مع زمن استجابة الخادم وما يصل إلى ثلاث طرق لرفعها.','orphaned records, an analysis older than 14 days, heavy autoload, reclaimable media space and orphaned scheduled tasks, each with a link to the screen that fixes it.'=>'السجلات اليتيمة، وتحليل مضى عليه أكثر من 14 يومًا، والتحميل التلقائي الثقيل، ومساحة الوسائط القابلة للاسترداد، والمهام المجدولة اليتيمة، مع رابط لكل منها إلى الشاشة التي تعالجه.','the records and files of the last analysis by state, with a link to each list.'=>'سجلات وملفات آخر تحليل حسب الحالة، مع رابط إلى كل قائمة.','Measures how long WordPress takes to start sending the page (the server share of TTFB) and lists what can make it faster.'=>'يقيس المدة التي يستغرقها WordPress ليبدأ إرسال الصفحة (حصة الخادم من TTFB) ويسرد ما يمكن أن يجعله أسرع.','Summary'=>'الملخص','the measured response time, its trend and the verdict.'=>'زمن الاستجابة المقاس واتجاهه والحكم عليه.','PageSpeed Insights'=>'PageSpeed Insights','tests a page of your site, on mobile or desktop, with the public API of Google. It sends the address of that page to Google and changes nothing on your site. With your own API key you can also load the history of real visitors (Chrome UX Report).'=>'يختبر صفحة من موقعك، على الجوال أو سطح المكتب، عبر واجهة Google البرمجية العامة. يرسل عنوان تلك الصفحة إلى Google ولا يغيّر شيئًا في موقعك. باستخدام مفتاح API خاص بك يمكنك أيضًا تحميل سجل الزوار الحقيقيين (Chrome UX Report).','Server'=>'الخادم','the levers the plugin can apply with one click (object cache, query deduplication, autoload, Heartbeat), the ones that need server access as guidance (system cron, PHP and OPcache) and a read-only check of the database and Redis.'=>'الروافع التي يمكن للإضافة تطبيقها بنقرة واحدة (تخزين الكائنات المؤقت، وإزالة تكرار الاستعلامات، والتحميل التلقائي، وHeartbeat)، والروافع التي تتطلب الوصول إلى الخادم كإرشادات (cron النظام وPHP وOPcache)، وفحص للقراءة فقط لقاعدة البيانات وRedis.','Deep analysis (optional)'=>'تحليل معمّق (اختياري)','profiles the next few front-end requests and switches itself off. The report shows the slowest hooks and queries; "Apply index" creates a database index after asking, and "Undo" drops it.'=>'يحلّل الطلبات القليلة التالية في الواجهة الأمامية ثم يتوقف من تلقاء نفسه. يعرض التقرير أبطأ الخطافات والاستعلامات؛ «تطبيق الفهرس» ينشئ فهرسًا في قاعدة البيانات بعد السؤال، و«تراجع» يحذفه.','Where you started versus where you are now. A snapshot is taken automatically before and after every analysis and after every cleanup.'=>'من أين بدأت مقارنةً بما وصلت إليه الآن. تُلتقط لقطة تلقائيًا قبل كل تحليل وبعده وبعد كل تنظيف.','Set baseline to now'=>'تعيين خط الأساس إلى الآن','takes a new starting point to compare with. Earlier snapshots are kept.'=>'يلتقط نقطة بداية جديدة للمقارنة بها. تُحفظ اللقطات السابقة.','Export CSV'=>'تصدير CSV','downloads every snapshot, to open it in a spreadsheet.'=>'ينزّل جميع اللقطات لفتحها في جدول بيانات.','Keep timeline data:'=>'الاحتفاظ ببيانات المخطط الزمني:','three months by default. Choosing a shorter period deletes the older snapshots at once; the baseline and the first snapshot are always kept.'=>'ثلاثة أشهر افتراضيًا. اختيار مدة أقصر يحذف اللقطات الأقدم فورًا؛ ويُحتفظ دائمًا بخط الأساس وأول لقطة.','Object and page cache'=>'تخزين الكائنات المؤقت وذاكرة تخزين الصفحات','Every cache is off until you turn it on, and turning it off puts back what was there. A drop-in that belongs to another plugin is never overwritten unless you choose to replace it, and the original is kept to give it back.'=>'كل ذاكرة تخزين مؤقت معطّلة حتى تفعّلها، وتعطيلها يعيد ما كان موجودًا. لا يُستبدل أبدًا ملف drop-in يخص إضافة أخرى إلا إذا اخترت استبداله، ويُحتفظ بالأصل لإعادته.','keeps the results of database queries in Redis, Memcached, APCu or a SQLite file. Enabling it writes wp-content/object-cache.php.'=>'يحفظ نتائج استعلامات قاعدة البيانات في Redis أو Memcached أو APCu أو ملف SQLite. تفعيله يكتب wp-content/object-cache.php.','Page cache'=>'ذاكرة تخزين الصفحات','serves a static copy of each page to anonymous visitors for up to 10 hours, and clears what changes. Logged-in users, carts, checkout and the admin are never cached. Enabling it writes wp-content/advanced-cache.php and adds WP_CACHE to wp-config.php. It is not available on a multisite network, and it stays off while another page cache is active.'=>'يقدّم نسخة ثابتة من كل صفحة للزوار المجهولين لمدة تصل إلى 10 ساعات، ويمسح ما يتغيّر. لا تُخزَّن أبدًا صفحات المستخدمين المسجلين وعربات التسوق وصفحة الدفع ولوحة الإدارة. تفعيله يكتب wp-content/advanced-cache.php ويضيف WP_CACHE إلى wp-config.php. غير متاح على شبكة متعددة المواقع، ويبقى معطّلًا ما دامت ذاكرة تخزين صفحات أخرى نشطة.','Preload'=>'التحميل المسبق','rebuilds the cached pages in the background after they are cleared.'=>'يعيد بناء الصفحات المخزّنة في الخلفية بعد مسحها.','Custom exclusions'=>'استثناءات مخصصة','paths, cookies and query parameters on top of the automatic rules, and a separate cache for mobile devices.'=>'مسارات وملفات تعريف ارتباط ومعاملات استعلام إضافةً إلى القواعد التلقائية، وذاكرة تخزين منفصلة للأجهزة المحمولة.','Query deduplication'=>'إزالة تكرار الاستعلامات','writes wp-content/db.php, which answers identical read queries of the same request from memory. Any write clears it.'=>'يكتب wp-content/db.php، الذي يجيب من الذاكرة عن استعلامات القراءة المتطابقة ضمن الطلب نفسه. أي عملية كتابة تمسحه.','Analytics'=>'التحليلات','hit rate, queries and the most duplicated queries of the last 30 days.'=>'معدل الإصابة والاستعلامات والاستعلامات الأكثر تكرارًا خلال آخر 30 يومًا.','the backend and its connection, Heartbeat and the cached comment counts of the dashboard. Saving flushes the object cache.'=>'الواجهة الخلفية واتصالها، وHeartbeat، وأعداد التعليقات المخزّنة في لوحة التحكم. الحفظ يفرّغ تخزين الكائنات المؤقت.','Cloudflare'=>'Cloudflare','With the zone ID and an API token with permission to purge the cache, the plugin also clears Cloudflare: everything when it flushes the other caches, and only the affected pages when content changes. Both are on once the token is saved. Saving tests it by purging the home page.'=>'بمعرّف المنطقة (zone ID) ورمز API يملك صلاحية مسح ذاكرة التخزين المؤقت، تمسح الإضافة Cloudflare أيضًا: كل شيء عند تفريغ ذاكرات التخزين الأخرى، والصفحات المتأثرة فقط عند تغيّر المحتوى. يُفعَّل الخياران بمجرد حفظ الرمز. الحفظ يختبره بمسح الصفحة الرئيسية.','Cache the pages at Cloudflare too'=>'تخزين الصفحات مؤقتًا في Cloudflare أيضًا','creates a Cache Rule in your Cloudflare zone, which needs one more permission, checks it and removes it by itself if the check fails. Turning it off deletes the rule and empties the edge.'=>'ينشئ Cache Rule في منطقة Cloudflare الخاصة بك، ويتطلب ذلك صلاحية إضافية، ثم يتحقق منها ويزيلها من تلقاء نفسه إذا فشل التحقق. تعطيله يحذف القاعدة ويفرّغ الحافة.','Browser & server'=>'المتصفح والخادم','Caches in front of your site'=>'ذاكرات التخزين المؤقت أمام موقعك','requests the home page twice as a visitor and reads the headers to see whether your host or a CDN keeps a copy. When it finds Varnish, it can purge it too, unless Proxy Cache Purge already does.'=>'يطلب الصفحة الرئيسية مرتين كزائر ويقرأ الترويسات ليعرف ما إذا كان مزوّد الاستضافة أو شبكة CDN يحتفظ بنسخة. عندما يجد Varnish يمكنه مسحه أيضًا، إلا إذا كانت Proxy Cache Purge تفعل ذلك بالفعل.','Browser cache & compression'=>'ذاكرة تخزين المتصفح والضغط','adds a block to .htaccess, after a copy of the file, so browsers keep your static files and the server compresses them. Not available on Nginx, and not added while another plugin handles it.'=>'يضيف كتلة إلى .htaccess، بعد أخذ نسخة من الملف، لكي تحتفظ المتصفحات بملفاتك الثابتة ويضغطها الخادم. غير متاح على Nginx، ولا يُضاف ما دامت إضافة أخرى تتولى ذلك.','CSS & JavaScript'=>'CSS وJavaScript','What the browser of the visitor downloads and runs. Everything is off by default, and stays off while another optimizer is active.'=>'ما ينزّله متصفح الزائر ويشغّله. كل شيء معطّل افتراضيًا، ويبقى معطّلًا ما دامت أداة تحسين أخرى نشطة.','Minification'=>'التصغير','serves minified copies of your own CSS and JavaScript; files already minified, external or excluded are left as they are. Test mode applies it only to logged-in administrators. Saving clears the minified copies.'=>'يقدّم نسخًا مصغّرة من ملفات CSS وJavaScript الخاصة بك؛ وتُترك كما هي الملفات المصغّرة مسبقًا والخارجية والمستثناة. «وضع الاختبار» يطبّقه على المسؤولين المسجلين فقط. الحفظ يمسح النسخ المصغّرة.','Delay JavaScript'=>'تأخير JavaScript','holds scripts back until the visitor moves, taps, scrolls or types, and runs them anyway after 8 seconds. By default only known third parties are delayed. Consent banners, payment providers and captchas are never delayed. Add ?wpopt_nodelay=1 to an address to load everything at once.'=>'يؤجّل السكربتات حتى يحرّك الزائر المؤشر أو ينقر أو يمرّر أو يكتب، ويشغّلها على أي حال بعد 8 ثوانٍ. افتراضيًا لا تؤجَّل إلا الجهات الخارجية المعروفة. لا تؤجَّل أبدًا لافتات الموافقة ومزودو الدفع وأدوات captcha. أضف ?wpopt_nodelay=1 إلى أي عنوان لتحميل كل شيء دفعة واحدة.','Critical CSS'=>'CSS الحرج','works out the CSS each template uses and inlines it. Generate shows the sizes and a preview without changing anything; "Apply to the site" turns it on, and "Delete and revert" removes it. Add ?wpopt_noccss=1 to an address to see the page without it.'=>'يحدّد CSS الذي يستخدمه كل قالب عرض ويضمّنه في الصفحة. «توليد» يعرض الأحجام ومعاينة دون تغيير أي شيء؛ «تطبيق على الموقع» يفعّله، و«حذف وتراجع» يزيله. أضف ?wpopt_noccss=1 إلى أي عنوان لرؤية الصفحة بدونه.','Plugins by URL'=>'الإضافات حسب الرابط','stops a plugin from loading where it does nothing, or loads it only where it is needed. Only for visitors. Every rule is tested on real pages before it is saved, and every rule switches itself off if a visit ends in a fatal error. Saving writes a must-use plugin and clears the page cache.'=>'يمنع إضافة من التحميل حيث لا تؤدي أي عمل، أو يحمّلها فقط حيث تلزم. للزوار فقط. تُختبر كل قاعدة على صفحات حقيقية قبل حفظها، وتتعطّل كل قاعدة من تلقاء نفسها إذا انتهت زيارة بخطأ فادح. الحفظ يكتب إضافة must-use ويمسح ذاكرة تخزين الصفحات.','Loading & delivery'=>'التحميل والتسليم','How the page reaches the visitor. All optional and off by default.'=>'كيف تصل الصفحة إلى الزائر. كلها اختيارية ومعطّلة افتراضيًا.','Speculative loading'=>'التحميل الاستباقي','the browser prepares the next page on click (conservative) or on hover (eager). The admin, login, cart and checkout are left out.'=>'يجهّز المتصفح الصفحة التالية عند النقر (conservative) أو عند تمرير المؤشر فوق الرابط (eager). تُستثنى لوحة الإدارة وتسجيل الدخول وعربة التسوق وصفحة الدفع.','Image loading'=>'تحميل الصور','gives priority to the first image and lazy-loads the rest.'=>'يمنح الأولوية للصورة الأولى ويحمّل البقية بشكل كسول.','Preload key resources'=>'التحميل المسبق للموارد الرئيسية','the featured image and any address you add.'=>'الصورة البارزة وأي عنوان تضيفه.','Lazy embeds'=>'التضمينات المؤجَّلة','iframes load when they are reached, and YouTube videos show a thumbnail until they are clicked.'=>'تُحمَّل إطارات iframe عند الوصول إليها، وتعرض مقاطع YouTube صورة مصغّرة حتى يُنقر عليها.','Server-Timing'=>'Server-Timing','a header with the time the server took, to read in the developer tools of the browser.'=>'ترويسة بالوقت الذي استغرقه الخادم، لقراءتها في أدوات المطوّر في المتصفح.','Resource hints'=>'تلميحات الموارد','automatic: preconnect for the Google Fonts origins and dns-prefetch for the other external origins whose scripts and styles the page loads.'=>'تلقائية: preconnect لأصول Google Fonts وdns-prefetch لبقية الأصول الخارجية للسكربتات والأنماط التي تحمّلها الصفحة.','Google Fonts'=>'Google Fonts','downloads the fonts to your server and serves them from there.'=>'ينزّل الخطوط إلى خادمك ويقدّمها من هناك.','CDN rewriting'=>'إعادة كتابة CDN','serves the files of the chosen folders from your CDN host; with no folder ticked, all three.'=>'يقدّم ملفات المجلدات المختارة من مضيف CDN الخاص بك؛ وإذا لم يُحدَّد أي مجلد، فالثلاثة كلها.','The CSS and JavaScript loaded on your public pages, with the plugin or theme each one belongs to. Every change is saved at once.'=>'ملفات CSS وJavaScript المحمّلة في صفحاتك العامة، مع الإضافة أو القالب الذي ينتمي إليه كل منها. يُحفظ كل تغيير فورًا.','Manual unloading'=>'إزالة يدوية','stops loading the ticked assets on the front end. The admin is never touched, and WordPress core and jQuery cannot be ticked.'=>'يوقف تحميل الأصول المحدّدة في الواجهة الأمامية. لا تُمسّ لوحة الإدارة أبدًا، ولا يمكن تحديد نواة WordPress وjQuery.','Automatic unloading'=>'الإزالة التلقائية','stops loading the assets of a plugin or theme on the pages where it is not used, following the knowledge base.'=>'يوقف تحميل أصول إضافة أو قالب في الصفحات التي لا يُستخدم فيها، استنادًا إلى قاعدة المعرفة.','Test mode'=>'وضع الاختبار','applies the unloading only to logged-in administrators, to check it before visitors see it.'=>'يطبّق إلغاء التحميل على المسؤولين المسجلين فقط، للتحقق منه قبل أن يراه الزوار.','URL exceptions'=>'استثناءات حسب الرابط','pages that always keep every asset.'=>'صفحات تحتفظ دائمًا بجميع الأصول.','Per-rule targeting'=>'الاستهداف لكل قاعدة','where each rule applies: everywhere, the front page, posts and pages, archives, one content type or some addresses.'=>'حيث تنطبق كل قاعدة: في كل مكان، أو الصفحة الرئيسية، أو المقالات والصفحات، أو الأرشيفات، أو نوع محتوى واحد، أو عناوين معيّنة.','Rules that are not doing anything'=>'قواعد لا تفعل شيئًا','rules of deactivated extensions, which are kept, and rules that match nothing, which can be removed.'=>'قواعد الإضافات والقوالب المعطّلة، وهي محفوظة، والقواعد التي لا تطابق شيئًا، ويمكن إزالتها.','Autoloaded options load into memory on every request; under about 800 KB in total is healthy. Disabling autoload keeps the option and stops loading it on every page, and it can be undone.'=>'تُحمَّل الخيارات ذات التحميل التلقائي في الذاكرة مع كل طلب؛ ويُعد إجمالي أقل من 800 KB تقريبًا سليمًا. تعطيل التحميل التلقائي يُبقي الخيار ويوقف تحميله في كل صفحة، ويمكن التراجع عنه.','Disable autoload for selected'=>'تعطيل التحميل التلقائي للمحدد','saves a backup first, then stops loading the selected options on every request.'=>'يحفظ نسخة احتياطية أولًا، ثم يوقف تحميل الخيارات المحدّدة مع كل طلب.','Smart Deactivation'=>'التعطيل الذكي','the same for the options confidently identified as belonging to uninstalled extensions.'=>'الأمر نفسه للخيارات التي حُدّد بثقة أنها تخص إضافات أو قوالب غير مثبّتة.','Advanced autoload cleanup'=>'تنظيف متقدّم للتحميل التلقائي','disables autoload for the options never read, or for every non-essential one, and deletes the confirmed orphans. Deleting is the only action here that removes options, and it saves a backup first.'=>'يعطّل التحميل التلقائي للخيارات التي لا تُقرأ أبدًا، أو لكل خيار غير أساسي، ويحذف اليتيمة المؤكدة. الحذف هو الإجراء الوحيد هنا الذي يزيل خيارات، ويحفظ نسخة احتياطية أولًا.','Could be autoloaded'=>'يمكن تحميله تلقائياً','options read on almost every request without being autoloaded. The plugin measures it by itself; Smart Activation autoloads those read on at least 90% of 50 or more requests, up to 20 KB each.'=>'خيارات تُقرأ في كل طلب تقريبًا دون أن تكون محمّلة تلقائيًا. تقيس الإضافة ذلك بنفسها؛ و«تفعيل ذكي» يحمّل تلقائيًا تلك التي تُقرأ في 90% على الأقل من 50 طلبًا أو أكثر، بحد أقصى 20 KB لكل منها.','A maintenance pass over revisions, drafts, trash, comments, transients and the other tasks chosen in Settings. Everything it deletes is backed up first and can be restored from Backups; if a backup cannot be written, the cleanup stops.'=>'دورة صيانة للمراجعات والمسودات وسلة المهملات والتعليقات والمؤقتات وبقية المهام المختارة في «الإعدادات». كل ما يحذفه يُنسخ احتياطيًا أولًا ويمكن استعادته من «النسخ الاحتياطية»؛ وإذا تعذّرت كتابة نسخة احتياطية يتوقف التنظيف.','Preview (dry run)'=>'معاينة (تشغيل تجريبي)','counts what the cleanup would remove with the current settings, without deleting anything.'=>'يحسب ما سيزيله التنظيف بالإعدادات الحالية، دون حذف أي شيء.','Run general cleanup now'=>'تشغيل التنظيف العام الآن','runs it straight away, after asking. Every enabled task runs, whatever its frequency.'=>'يشغّله فورًا بعد السؤال. تعمل كل مهمة مفعّلة، أيًّا كان تكرارها.','Logs'=>'السجلات','the last run and the previous reports, to view, download or print. Event lines are included only with "Generate detailed log".'=>'آخر تشغيل والتقارير السابقة، لعرضها أو تنزيلها أو طباعتها. لا تُضمَّن أسطر الأحداث إلا مع «إنشاء سجل مفصل».','By content type'=>'حسب نوع المحتوى','where the weight of your database sits by content type. Read-only.'=>'أين يتركّز حجم قاعدة بياناتك حسب نوع المحتوى. للقراءة فقط.','Active settings'=>'الإعدادات النشطة','the tasks and limits are chosen in Settings, under General cleanup options.'=>'تُختار المهام والحدود في «الإعدادات»، ضمن «خيارات التنظيف العام».','Every table of this site with its engine, rows, size, recoverable overhead and suspected owner. Optimizing and converting never delete data, so they do not make a backup. Orphaned custom tables are deleted from Analysis results.'=>'كل جدول في هذا الموقع مع محرّكه وصفوفه وحجمه والعبء الزائد القابل للاسترداد والمالك المحتمل. التحسين والتحويل لا يحذفان أي بيانات، لذا لا يأخذان نسخة احتياطية. تُحذف الجداول المخصصة اليتيمة من «نتائج التحليل».','Unusual table growth since the previous scan'=>'نمو غير معتاد للجداول منذ الفحص السابق','tables that grew at least 5 MB and 25% between two analyses.'=>'جداول نمت بمقدار 5 MB و25% على الأقل بين تحليلين.','Tables worth a look'=>'جداول تستحق النظر','tables whose owner is not active, or that are very large for the database.'=>'جداول مالكها غير نشط، أو كبيرة جدًا بالنسبة إلى قاعدة البيانات.','Optimize selected'=>'تحسين المحدد','runs OPTIMIZE TABLE. On InnoDB the reported free space may not drop, and that is normal.'=>'ينفّذ OPTIMIZE TABLE. على InnoDB قد لا تنخفض المساحة الحرة المُبلغ عنها، وهذا طبيعي.','Convert selected to InnoDB'=>'تحويل المحدد إلى InnoDB','changes only the MyISAM tables and keeps all their data.'=>'يغيّر جداول MyISAM فقط ويحتفظ بجميع بياناتها.','Tables over 256 MB are not converted from the browser, because it would take minutes and as much free disk space. When optimized, they are rebuilt in the background if that recovers space, and skipped otherwise.'=>'لا تُحوَّل الجداول التي تتجاوز 256 ميغابايت من المتصفح، لأن ذلك سيستغرق دقائق ومساحة حرة مماثلة على القرص. عند تحسينها، يُعاد بناؤها في الخلفية إذا كان ذلك يستعيد مساحة، وإلا فتُتخطّى.','The scheduled tasks of WordPress. An event whose hook has no callback and no installed owner is orphaned: it will never run.'=>'المهام المجدولة في WordPress. الحدث الذي ليس لخطافه أي دالة استدعاء ولا مالك مثبّت يكون يتيمًا: لن يعمل أبدًا.','WP-Cron trigger'=>'مُشغّل WP-Cron','"Disable WP-Cron" adds DISABLE_WP_CRON to wp-config.php, after a copy of the file listed in Backups, and gives the line to add to the crontab of the server. "Re-enable WP-Cron" removes it.'=>'«تعطيل WP-Cron» يضيف DISABLE_WP_CRON إلى wp-config.php، بعد أخذ نسخة من الملف تظهر في «النسخ الاحتياطية»، ويعطي السطر الذي يجب إضافته إلى crontab الخادم. «إعادة تفعيل WP-Cron» يزيله.','Are the tasks running?'=>'هل تعمل المهام؟','warns when an event is more than 10 minutes late, because then nothing is firing WP-Cron.'=>'ينبّه عندما يتأخر حدث أكثر من 10 دقائق، لأن ذلك يعني أن لا شيء يشغّل WP-Cron.','queues the task to run in the background in a moment, after a backup of its events.'=>'يضع المهمة في قائمة الانتظار لتعمل في الخلفية بعد لحظات، بعد نسخ أحداثها احتياطيًا.','the task stays scheduled but does nothing until you resume it. WordPress core tasks cannot be paused.'=>'تبقى المهمة مجدولة لكنها لا تفعل شيئًا حتى تستأنفها. لا يمكن إيقاف مهام نواة WordPress مؤقتًا.','Unschedule selected'=>'إلغاء جدولة المحدد','removes orphaned events only, after a backup restorable from Backups. Active and WordPress core events are protected.'=>'يزيل الأحداث اليتيمة فقط، بعد نسخة احتياطية قابلة للاستعادة من «النسخ الاحتياطية». الأحداث النشطة وأحداث نواة WordPress محمية.','The uploads folder as the last analysis found it. Every deletion here saves a copy of the files first, restorable from Trash or Backups.'=>'مجلد الرفع كما وجده آخر تحليل. كل حذف هنا يحفظ نسخة من الملفات أولًا، قابلة للاستعادة من «سلة المهملات» أو «النسخ الاحتياطية».','files with no record in the database, thumbnails whose original is missing and files in named folders, usually left by plugins. Review them before deleting.'=>'ملفات ليس لها سجل في قاعدة البيانات، وصور مصغّرة أصلها مفقود، وملفات في مجلدات مسمّاة تتركها الإضافات عادةً. راجعها قبل الحذف.','Duplicate sets'=>'مجموعات مكررة','byte-identical files. The copy with the lowest ID is kept, featured images and content are pointed to it and the other copies are deleted. A set still used somewhere the plugin cannot rewrite is left alone.'=>'ملفات متطابقة بايتًا ببايت. يُحتفظ بالنسخة ذات المعرّف الأدنى، وتُوجَّه إليها الصور البارزة والمحتوى، وتُحذف النسخ الأخرى. تُترك المجموعة كما هي إذا كانت لا تزال مستخدمة في مكان لا تستطيع الإضافة إعادة كتابته.','Unused attachments'=>'مرفقات غير مستخدمة','attachments with no reference found in content, meta, galleries or parent posts. It is a heuristic: confirm each one, or mark it as known to keep it. References are checked again before deleting, and "Delete all" is refused when the search was incomplete.'=>'مرفقات لم يُعثر على أي إشارة إليها في المحتوى أو البيانات الوصفية أو المعارض أو المقالات الأم. إنها طريقة تقديرية: أكّد كل واحد منها، أو علّمه كمعروف للاحتفاظ به. يُعاد فحص الإشارات قبل الحذف، ويُرفض «حذف الكل» إذا كان البحث غير مكتمل.','Trash'=>'سلة المهملات','the copies of the deleted media. Restore puts the files back; Delete removes the copy for good and frees its space.'=>'نسخ الوسائط المحذوفة. «استعادة» يعيد الملفات؛ و«حذف» يزيل النسخة نهائيًا ويحرّر مساحتها.','Image optimization'=>'تحسين الصور','The weight and formats of your images and what would help each one. The analysis runs with "Analyze now".'=>'حجم صورك وصيغها وما يفيد كل واحدة منها. يعمل التحليل عبر «تحليل الآن».','Optimize originals'=>'تحسين النسخ الأصلية','recompresses the JPEG and PNG originals and resizes those larger than the maximum, after a byte-verified copy of each one; "Restore originals" puts them back.'=>'يعيد ضغط أصول JPEG وPNG ويغيّر حجم ما يتجاوز الحد الأقصى، بعد نسخة من كل منها متحقَّق منها بايتًا ببايت؛ و«استعادة الأصول» يعيدها.','Generate next-gen copies'=>'إنشاء نسخ الجيل الجديد','creates WebP and AVIF copies next to each image, without changing the original. Remove deletes only the copies made by the plugin.'=>'ينشئ نسخ WebP وAVIF بجانب كل صورة، دون تغيير الأصل. «إزالة» يحذف فقط النسخ التي أنشأتها الإضافة.','quality (82 by default), maximum dimensions (2560 × 2560), folders never optimized, image sizes no longer generated for new uploads, and optimizing new uploads as they arrive. Serving WebP and AVIF as <picture> sources is on by default.'=>'الجودة (82 افتراضيًا)، والأبعاد القصوى (2560 × 2560)، والمجلدات التي لا تُحسَّن أبدًا، وأحجام الصور التي لم تعد تُنشأ للملفات المرفوعة الجديدة، وتحسين الملفات المرفوعة الجديدة فور وصولها. تقديم WebP وAVIF كمصادر <picture> مفعّل افتراضيًا.','Serve WebP/AVIF from the server'=>'تقديم WebP/AVIF من الخادم','adds a rule to the .htaccess of the uploads folder, after a copy of it, and checks that it works. On Nginx it gives the configuration instead.'=>'يضيف قاعدة إلى ملف .htaccess في مجلد الرفع، بعد أخذ نسخة منه، ويتحقق من أنها تعمل. على Nginx يعطي الإعدادات المطلوبة بدلًا من ذلك.','Library audit'=>'تدقيق مكتبة الوسائط','An examination of the uploads folder and the attachment records behind it, run only when you click "Run the audit". It says whose each file is and never moves anything.'=>'فحص لمجلد الرفع وسجلات المرفقات المرتبطة به، لا يعمل إلا عند النقر على «تشغيل التدقيق». يحدّد لمن يعود كل ملف ولا ينقل أي شيء أبدًا.','Files that should not be downloadable'=>'ملفات لا ينبغي أن تكون قابلة للتنزيل','database dumps, logs and backups left in uploads, each checked with a real request. "Protect these files" adds an .htaccess rule that blocks them; they can also be deleted, after a backup.'=>'تفريغات قواعد البيانات والسجلات والنسخ الاحتياطية المتروكة في مجلد الرفع، ويُفحص كل منها بطلب حقيقي. «حماية هذه الملفات» يضيف قاعدة .htaccess تحظرها؛ ويمكن أيضًا حذفها بعد نسخة احتياطية.','Sizes carrying an older name'=>'مقاسات تحمل اسمًا أقدم','regenerates the thumbnails, up to 10 attachments at a time, after a backup of their metadata. The old files are not deleted.'=>'يعيد توليد الصور المصغّرة، حتى 10 مرفقات في كل مرة، بعد نسخ بياناتها الوصفية احتياطيًا. لا تُحذف الملفات القديمة.','Files claimed twice'=>'ملفات مُطالَب بها مرتين','files claimed at once by the metadata of an attachment and by an address the theme rewrites, which makes moving them unsafe. Report only.'=>'ملفات تطالب بها في آنٍ واحد البيانات الوصفية لمرفق وعنوانٌ يعيد القالب كتابته، مما يجعل نقلها غير آمن. للتقرير فقط.','Sizes no registered size could produce'=>'مقاسات لا يمكن لأي مقاس مسجَّل إنتاجها','they can be deleted, after a backup.'=>'يمكن حذفها بعد نسخة احتياطية.','Files in the uploads root'=>'ملفات في جذر مجلد الرفع','Every record and file the last analysis attributed, filtered by state. Each state has a Database and a Files view.'=>'كل سجل وملف نسبه آخر تحليل، مصفّى حسب الحالة. لكل حالة عرض «قاعدة البيانات» وعرض «الملفات».','left behind by extensions that are no longer installed. Nothing on the site uses them; delete them unless you plan to reinstall that extension and keep its settings.'=>'بقايا إضافات أو قوالب لم تعد مثبّتة. لا شيء في الموقع يستخدمها؛ احذفها إلا إذا كنت تنوي إعادة تثبيت تلك الإضافة أو القالب والاحتفاظ بإعداداته.','no owner could be identified. They may belong to something still in use: review them one by one, attribute them by hand or ask the attribution assistant.'=>'تعذّر تحديد أي مالك. قد تخص شيئًا لا يزال قيد الاستخدام: راجعها واحدًا تلو الآخر، أو انسبها يدويًا، أو اسأل مساعد النسب.','they belong to installed but deactivated plugins or themes. Delete them only if you will not use those extensions again. Plugins & Themes lists them to uninstall.'=>'تخص إضافات أو قوالب مثبّتة لكنها معطّلة. لا تحذفها إلا إذا كنت لن تستخدم تلك الإضافات أو القوالب مرة أخرى. تسردها «الإضافات والقوالب» لإلغاء تثبيتها.','records with no value stored. Those of active extensions or of WordPress are read-only.'=>'سجلات لا تحتوي على أي قيمة مخزّنة. سجلات الإضافات والقوالب النشطة أو سجلات WordPress للقراءة فقط.','they belong to active extensions or WordPress. Nothing is deleted here: fix a wrong owner, protect a record or deactivate plugins and themes.'=>'تخص إضافات أو قوالب نشطة أو WordPress. لا يُحذف شيء هنا: صحّح مالكًا خاطئًا، أو احمِ سجلًا، أو عطّل إضافات وقوالب.','Confidence levels'=>'مستويات الثقة','How much is known about the owner of each record. Only Manual, Sure, Likely and Possible can be deleted; anything lower goes to To identify.'=>'مقدار ما هو معروف عن مالك كل سجل. لا يمكن حذف إلا «يدوي» و«مؤكد» و«مرجّح» و«محتمل»؛ وما دون ذلك يذهب إلى «قيد التحديد».','Manual'=>'يدوي','you attributed it yourself, and it outranks every automatic source.'=>'نسبته بنفسك، ويتقدّم على كل مصدر تلقائي.','Sure'=>'مؤكد','captured live on this site, by a plugin whose own namespace the item belongs to.'=>'رُصد مباشرةً على هذا الموقع، بواسطة إضافة ينتمي العنصر إلى مساحة الأسماء الخاصة بها.','Likely'=>'مرجّح','seen by comparing what the site registered before and after activating the extension.'=>'رُصد بمقارنة ما سجّله الموقع قبل تفعيل الإضافة أو القالب وبعده.','Possible'=>'محتمل','read from the code of the extension, or confirmed by several sites in the shared dataset.'=>'قُرئ من كود الإضافة أو القالب، أو أكّدته عدة مواقع في مجموعة البيانات المشتركة.','Doubtful'=>'مشكوك فيه','one claim only, outside the namespace of the claimant, or reported by few sites.'=>'ادعاء واحد فقط، خارج مساحة أسماء صاحب الادعاء، أو أبلغت عنه مواقع قليلة.','Estimated'=>'تقديري','inferred from a prefix or a slug.'=>'مُستنتج من بادئة أو slug.','Undetermined'=>'غير محدد','no owner found.'=>'لم يُعثر على مالك.','Deleting and uninstalling'=>'الحذف وإلغاء التثبيت','Every deletion makes a backup first, and if it cannot be made nothing is deleted. Before deleting, each record is checked again: anything now in use, part of WordPress or no longer in the last analysis is kept, and very large entries are refused with the reason, since backing them up from the browser is not possible. The content of orphaned custom post types and the terms of orphaned taxonomies are only deleted when you tick that option.'=>'كل عملية حذف تأخذ نسخة احتياطية أولًا، وإذا تعذّر ذلك لا يُحذف شيء. قبل الحذف، يُعاد فحص كل سجل: يُحتفظ بكل ما أصبح قيد الاستخدام أو جزءًا من WordPress أو لم يعد في آخر تحليل، وتُرفض الإدخالات الكبيرة جدًا مع ذكر السبب، إذ لا يمكن أخذ نسخة احتياطية منها من المتصفح. لا يُحذف محتوى أنواع المقالات المخصصة اليتيمة ومصطلحات التصنيفات اليتيمة إلا عند تحديد ذلك الخيار.','acts on every filtered record; once rows are ticked the button deletes only the selection. The notice that follows offers Undo for one day.'=>'يعمل على كل سجل مصفّى؛ وبمجرد تحديد صفوف يحذف الزر المحدّد فقط. يقدّم التنبيه الذي يلي ذلك «تراجع» لمدة يوم واحد.','protected records are never deleted by any cleanup until you unprotect them.'=>'لا يحذف أي تنظيف السجلات المحمية أبدًا حتى تلغي حمايتها.','copies the folder of each plugin or theme to Backups and then deletes it the WordPress way, which also runs its own uninstall routine; what that routine removes from the database is not in the copy. With the option ticked, the data and files the analysis found for them are deleted too, after a backup.'=>'ينسخ مجلد كل إضافة أو قالب إلى «النسخ الاحتياطية» ثم يحذفه بطريقة WordPress، التي تشغّل أيضًا روتين إلغاء التثبيت الخاص به؛ وما يزيله ذلك الروتين من قاعدة البيانات لا يكون في النسخة. مع تحديد الخيار، تُحذف أيضًا البيانات والملفات التي وجدها التحليل لها، بعد نسخة احتياطية.','without an active license every list is analysed and the first 25 records are shown; deleting and uninstalling need the license.'=>'بدون ترخيص نشط تُحلَّل كل قائمة ويُعرض أول 25 سجلًا؛ أما الحذف وإلغاء التثبيت فيتطلبان الترخيص.','Manual attribution'=>'الإسناد اليدوي','Attribute manually'=>'إسناد يدويًا','tells WPOptimizing who owns an item when the automatic attribution is wrong or missing: "Contains" for a family of items, "Exact value" for one. Your rule takes priority, and the item moves to In use, Inactive or Orphans at once, without a new analysis. An item whose owner is active can no longer be deleted.'=>'يُخبر WPOptimizing بمالك عنصر ما عندما يكون النسب التلقائي خاطئًا أو مفقودًا: «يحتوي» لعائلة من العناصر، و«قيمة مطابقة» لعنصر واحد. قاعدتك لها الأولوية، وينتقل العنصر إلى «قيد الاستخدام» أو «غير نشط» أو «يتيمة» فورًا، دون تحليل جديد. العنصر الذي مالكه نشط لا يمكن حذفه بعد ذلك.','Attribution assistant'=>'مساعد النسب','suggests owners from the shared knowledge base, for To identify, or checks the owners shown, for Orphans. It needs data sharing. After each analysis the sure owners are applied on their own; the rest change only when you click Accept, one by one or all the sure ones at once, which creates a rule.'=>'يقترح مالكين من قاعدة المعرفة المشتركة لـ«قيد التحديد»، أو يتحقق من المالكين المعروضين لـ«يتيمة». يتطلب مشاركة البيانات. بعد كل تحليل يُطبَّق المالكون المؤكدون تلقائيًا؛ أما الباقي فلا يتغيّر إلا حين تنقر على «قبول»، واحدًا تلو الآخر أو كل المؤكدة دفعة واحدة، مما ينشئ قاعدة.','What changed in WordPress since WPOptimizing was installed: tables, options, meta keys, scheduled events and plugin, theme and upload folders added or removed, with the date and the extension responsible when it is known. It is recorded when plugins or themes change and after every analysis, and keeps the latest 2,000 changes.'=>'ما تغيّر في WordPress منذ تثبيت WPOptimizing: الجداول والخيارات ومفاتيح meta والأحداث المجدولة ومجلدات الإضافات والقوالب والرفع التي أُضيفت أو أُزيلت، مع التاريخ والإضافة أو القالب المسؤول عندما يكون معروفًا. يُسجَّل عند تغيّر الإضافات أو القوالب وبعد كل تحليل، ويحتفظ بأحدث 2,000 تغيير.','Clear activity log'=>'مسح سجل النشاط','empties the list; the starting point is kept, so tracking continues from now.'=>'يفرّغ القائمة؛ تُحفظ نقطة البداية، فيستمر التتبع من الآن.','The copies made before deletions, cleanups, autoload changes, uninstalls and edits of .htaccess and wp-config.php. They are kept in wp-content/wpoptimizing/backups/, and how many and for how long is set in Settings.'=>'النسخ المأخوذة قبل عمليات الحذف والتنظيف وتغييرات التحميل التلقائي وإلغاء التثبيت وتعديلات .htaccess وwp-config.php. تُحفظ في wp-content/wpoptimizing/backups/، ويُحدَّد عددها ومدة الاحتفاظ بها في «الإعدادات».','Restore'=>'استعادة','puts back the database rows and the files of that operation. The backup is kept after restoring.'=>'يعيد صفوف قاعدة البيانات وملفات تلك العملية. تُحفظ النسخة الاحتياطية بعد الاستعادة.','removes the backup for good.'=>'يزيل النسخة الاحتياطية نهائيًا.','Create backup now'=>'أنشئ نسخة احتياطية الآن','saves every record and file of the last analysis, without deleting anything. It is not a full backup of the site.'=>'يحفظ كل سجل وملف من آخر تحليل، دون حذف أي شيء. ليس نسخة احتياطية كاملة للموقع.','A quick reference for every feature inside the plugin, in three groups: Performance, Cleanup and Tools & data. The question mark next to a section title opens the same text. The full manual, with every setting explained, is the knowledge base.'=>'مرجع سريع لكل ميزة داخل الإضافة، في ثلاث مجموعات: «الأداء» و«تنظيف» و«الأدوات والبيانات». علامة الاستفهام بجانب عنوان القسم تفتح النص نفسه. الدليل الكامل، مع شرح كل إعداد، هو قاعدة المعرفة.','License'=>'الترخيص','License key'=>'مفتاح الترخيص','enter it and click Activate. Once stored it is hidden; deactivate it to enter another one. Without an active license everything is analysed and shown, and deleting attributed records and uninstalling extensions are not available.'=>'أدخله وانقر على «تفعيل». بعد حفظه يصبح مخفيًا؛ ألغِ تفعيله لإدخال ترخيص آخر. بدون ترخيص نشط يُحلَّل كل شيء ويُعرض، ولا يتوفر حذف السجلات المنسوبة ولا إلغاء تثبيت الإضافات والقوالب.','Backups and notifications'=>'النسخ الاحتياطية والإشعارات','Max backups per type'=>'الحد الأقصى للنسخ الاحتياطية لكل نوع','25 by default; the oldest of each type are deleted automatically.'=>'25 افتراضيًا؛ تُحذف الأقدم من كل نوع تلقائيًا.','Max age (days)'=>'الحد الأقصى للعمر (بالأيام)','backups older than this are deleted automatically; 30 by default.'=>'تُحذف النسخ الاحتياطية الأقدم من ذلك تلقائيًا؛ 30 افتراضيًا.','Max backup size (MB)'=>'الحد الأقصى لحجم النسخ الاحتياطية (ميغابايت)','when the backups would grow past it (2048 MB by default), the change stops instead of filling the disk. 0 means no limit.'=>'عندما تتجاوز النسخ الاحتياطية هذا الحد (2048 MB افتراضيًا)، يتوقف التغيير بدلًا من ملء القرص. 0 يعني بلا حد.','Notification email'=>'بريد الإشعارات','where the periodic report is sent; the address of the site administrator when empty. Separate several addresses with commas.'=>'الوجهة التي يُرسل إليها التقرير الدوري؛ عنوان مسؤول الموقع عندما يكون فارغًا. افصل بين عدة عناوين بفواصل.','Maintenance report'=>'تقرير الصيانة','an email with the health score, the main figures and the activity, daily to monthly. Off by default. "Send a test now" sends one at once without changing the schedule.'=>'رسالة بريد إلكتروني بدرجة الصحة والأرقام الرئيسية والنشاط، من يومية إلى شهرية. معطّلة افتراضيًا. «أرسل اختبارًا الآن» يرسل واحدة فورًا دون تغيير الجدولة.','Background sweeper'=>'المكنسة في الخلفية','clears expired transients a few at a time on admin requests; off by default, and idle with a persistent object cache.'=>'يمسح المؤقتات منتهية الصلاحية على دفعات صغيرة مع طلبات لوحة الإدارة؛ معطّل افتراضيًا، وخامل مع تخزين كائنات مؤقت دائم.','On uninstall'=>'عند إلغاء التثبيت','on by default: deleting the plugin deletes its settings, backups and analysis data. The drop-ins, the must-use plugins and the lines added to wp-config.php are removed in any case. Optimized images are kept.'=>'مفعّل افتراضيًا: حذف الإضافة يحذف إعداداتها ونسخها الاحتياطية وبيانات التحليل. تُزال ملفات drop-in وإضافات must-use والأسطر المضافة إلى wp-config.php في كل الأحوال. يُحتفظ بالصور المحسّنة.','Quick profile'=>'الملف الشخصي السريع','Apply a preset'=>'تطبيق إعداد مسبق','Safe, Blog, WooCommerce, Membership or Agency (maximum), with the one that suits your site marked as recommended. Applying it sets the cleanup tasks, front-end performance, core tweaks and Heartbeat, and turns on the object cache and query deduplication. The cleanup schedule is not changed.'=>'«آمنة» أو «مدونة» أو «WooCommerce» أو «العضوية» أو «وكالة (أقصى حد)»، مع تمييز الملف المناسب لموقعك على أنه موصى به. تطبيقه يضبط مهام التنظيف وأداء الواجهة الأمامية وتحسينات النواة وHeartbeat، ويفعّل تخزين الكائنات المؤقت وإزالة تكرار الاستعلامات. لا تتغيّر جدولة التنظيف.','Cleanup options'=>'خيارات التنظيف','Revisions to keep per post'=>'عدد المراجعات للاحتفاظ بها لكل مقال','2 by default; the older revisions of each post are deleted on every cleanup. A post marked "Keep all revisions" keeps all of them.'=>'2 افتراضيًا؛ تُحذف المراجعات الأقدم لكل مقالة في كل تنظيف. المقالة المعلَّمة بـ«الاحتفاظ بجميع المراجعات» تحتفظ بها كلها.','Database cleanup tasks'=>'مهام تنظيف قاعدة البيانات','what the general cleanup removes. Auto-drafts, trashed posts, spam and trashed comments, expired transients and table optimization are on by default; the rest are off.'=>'ما يزيله التنظيف العام. المسودات التلقائية والمقالات المنقولة إلى سلة المهملات والتعليقات المزعجة والمحذوفة والمؤقتات منتهية الصلاحية وتحسين الجداول مفعّلة افتراضيًا؛ والبقية معطّلة.','Keep trash and spam for at least (days)'=>'احتفظ بالمهملات والرسائل المزعجة على الأقل (أيام)','leaves alone what was sent to the trash or marked as spam more recently, so a mistake can still be undone.'=>'يترك ما أُرسل إلى سلة المهملات أو عُلّم كمزعج في وقت أحدث، حتى يظل من الممكن التراجع عن الخطأ.','Automatic analysis'=>'تحليل تلقائي','daily by default, only inside the low-traffic window (02:00 to 06:00, site time). A manual analysis always runs at once.'=>'يوميًا افتراضيًا، وفقط داخل نافذة الحركة المنخفضة (02:00 إلى 06:00، بتوقيت الموقع). التحليل اليدوي يعمل دائمًا فورًا.','Automatic maintenance'=>'الصيانة التلقائية','runs the general cleanup on a schedule, from hourly to monthly. Manual only by default.'=>'يشغّل التنظيف العام وفق جدول، من كل ساعة إلى كل شهر. يدوي فقط افتراضيًا.','Per-task frequency (advanced)'=>'التكرار لكل مهمة (متقدّم)','how often each task runs on automatic runs; "Never" skips it. Manual runs always run every enabled task.'=>'عدد مرات تشغيل كل مهمة في عمليات التشغيل التلقائية؛ «أبداً» يتخطاها. عمليات التشغيل اليدوية تشغّل دائمًا كل مهمة مفعّلة.','Auto-clean on DB growth'=>'تنظيف تلقائي عند نمو قاعدة البيانات','runs the general cleanup when the database grows more than this many MB since the last one. 0 disables it.'=>'يشغّل التنظيف العام عندما تنمو قاعدة البيانات بأكثر من هذا العدد من MB منذ آخر تنظيف. 0 يعطّله.','Core tweaks'=>'تحسينات النواة','Turn off WordPress features you do not use. Every option is off by default and reversible; nothing is deleted. The safe ones only remove noise from the head; the moderate ones (jQuery Migrate, Dashicons, oEmbed, remote patterns, REST links, WooCommerce cart fragments) may affect a few setups, so review each one.'=>'عطّل ميزات WordPress التي لا تستخدمها. كل خيار معطّل افتراضيًا وقابل للتراجع؛ لا يُحذف شيء. الخيارات الآمنة تزيل الضجيج من head فقط؛ أما المتوسطة (jQuery Migrate وDashicons وoEmbed والأنماط البعيدة وروابط REST وأجزاء سلة WooCommerce) فقد تؤثر على بعض الإعدادات، لذا راجع كل واحد منها.','Front-end performance'=>'أداء الواجهة الأمامية','these settings are now in Speed › Page & browser.'=>'هذه الإعدادات موجودة الآن في «السرعة › الصفحة والمتصفح».','Webhooks'=>'Webhooks','Endpoint URL'=>'رابط نقطة النهاية','receives a JSON POST when an analysis, a cleanup, a deletion or a dataset upload finishes. Leave it empty to disable webhooks.'=>'يستقبل طلب JSON POST عند انتهاء تحليل أو تنظيف أو حذف أو رفع مجموعة بيانات. اتركه فارغًا لتعطيل Webhooks.','Signing secret'=>'سر التوقيع','optional; each request then carries an X-WPOptimizing-Signature header with the HMAC-SHA256 of the body.'=>'اختياري؛ عندها يحمل كل طلب ترويسة X-WPOptimizing-Signature تحتوي على HMAC-SHA256 للمتن.','Events'=>'الأحداث','which events are sent; with none selected, all of them.'=>'الأحداث التي تُرسل؛ وإذا لم يُحدَّد أي منها، فجميعها.','Compatibility'=>'التوافق','The optimization plugins found on the site and what each one already does. Where doing it twice would conflict, the WPOptimizing version stays off.'=>'إضافات التحسين الموجودة في الموقع وما يفعله كل منها بالفعل. حيث يؤدي تكرار الأمر إلى تعارض، تبقى نسخة WPOptimizing معطّلة.','Use WPOptimizing for this anyway'=>'استخدم WPOptimizing لهذا رغم ذلك','runs ours as well for that feature.'=>'يشغّل نسختنا أيضًا لتلك الميزة.','Shared dataset'=>'مجموعة البيانات المشتركة','Contribute & receive'=>'المساهمة والاستلام','off by default. When on, the names of options, meta keys, tables and files, their sizes and how often they are seen are sent with the domain of the site, and the shared dataset is received in return. Values and content are never sent.'=>'معطّل افتراضيًا. عند تفعيله، تُرسل أسماء الخيارات ومفاتيح meta والجداول والملفات، وأحجامها وعدد مرات رؤيتها، مع نطاق الموقع، وتُستقبل مجموعة البيانات المشتركة في المقابل. لا تُرسل القيم والمحتوى أبدًا.','Sync dataset now'=>'زامن مجموعة البيانات الآن','uploads and downloads at once instead of waiting for the daily sync.'=>'يرفع وينزّل فورًا بدلًا من انتظار المزامنة اليومية.','Import / export'=>'استيراد / تصدير','Download settings (.json)'=>'تنزيل الإعدادات (.json)','a file with the configuration, to set another site up the same way. Keys, passwords, webhooks and the data-sharing consent are never included.'=>'ملف بالإعدادات، لإعداد موقع آخر بالطريقة نفسها. لا تُضمَّن أبدًا المفاتيح وكلمات المرور وWebhooks والموافقة على مشاركة البيانات.','Import settings'=>'استيراد الإعدادات','overwrites the current settings with those of the file; unknown entries are ignored.'=>'يستبدل الإعدادات الحالية بإعدادات الملف؛ وتُتجاهل الإدخالات غير المعروفة.','Replay welcome wizard'=>'إعادة عرض معالج الترحيب','shows the welcome wizard again on the main screen.'=>'يعرض معالج الترحيب مرة أخرى في الشاشة الرئيسية.','Network'=>'الشبكة','A read-only summary of every site of the network. Each site analyses and cleans its own data; open a site to manage it.'=>'ملخص للقراءة فقط لكل مواقع الشبكة. كل موقع يحلّل بياناته وينظّفها بنفسه؛ افتح موقعًا لإدارته.','Network quick setup'=>'الإعداد السريع للشبكة','applies a quick profile to every site or to the ones chosen, and sets the alert thresholds of that profile. Nothing is deleted.'=>'يطبّق ملفًا شخصيًا سريعًا على كل المواقع أو على المواقع المختارة، ويضبط حدود التنبيه لذلك الملف. لا يُحذف شيء.','Analyze all sites'=>'تحليل جميع المواقع','schedules a new analysis on every site.'=>'يجدول تحليلًا جديدًا على كل موقع.','the table, to open it in a spreadsheet; View report opens a printable version.'=>'الجدول، لفتحه في جدول بيانات؛ «عرض التقرير» يفتح نسخة قابلة للطباعة.','Email alerts'=>'تنبيهات البريد الإلكتروني','a daily summary to the network administrator when a site has this much orphaned data, has not been analysed in this many days or has this much autoload. 0 disables each one; the same sites are not reported again for a week.'=>'ملخص يومي إلى مسؤول الشبكة عندما يحتوي موقع على هذا القدر من البيانات اليتيمة، أو لم يُحلَّل منذ هذا العدد من الأيام، أو لديه هذا القدر من التحميل التلقائي. 0 يعطّل كل واحد منها؛ ولا يُبلَّغ عن المواقع نفسها مرة أخرى لمدة أسبوع.','activates or deactivates the license of each site from its row.'=>'يفعّل ترخيص كل موقع أو يلغي تفعيله من صفّه.','Network Report'=>'تقرير الشبكة','Generated:'=>'تم الإنشاء:','Sites'=>'المواقع','Licensed'=>'مُرخّص','Pending'=>'معلق','Scanned size'=>'الحجم المفحوص','Site'=>'الموقع','Last analysis'=>'آخر تحليل','Trend'=>'الاتجاه','Free'=>'مجاني','Never'=>'أبداً','Generated by WPOptimizing %s'=>'تم الإنشاء بواسطة WPOptimizing %s','No change since baseline'=>'لا تغيير منذ خط الأساس','Autoload change since this site’s baseline (lower is better)'=>'تغيّر التحميل التلقائي منذ خط أساس هذا الموقع (الأقل أفضل)','Apply a cleanup profile to selected sites in one step. Alert thresholds are set automatically from the chosen profile; use the Email alerts form below for manual tuning. Nothing is deleted — cleanup tasks run on each site\'s own schedule.'=>'تطبيق ملف تنظيف على المواقع المحددة في خطوة واحدة. تُعَيَّن حدود التنبيه تلقائياً من الملف المختار؛ استخدم نموذج تنبيهات البريد أدناه للضبط اليدوي. لا يُحذف شيء — تعمل مهام التنظيف وفق جدول كل موقع.','Each profile sets cleanup preferences, performance options (object cache, query deduplication, heartbeat) and network alert thresholds. Nothing is deleted.'=>'يحدد كل ملف تفضيلات التنظيف وخيارات الأداء (ذاكرة الكائنات وإلغاء تكرار الاستعلامات ومعدل ضربات القلب) وحدود تنبيهات الشبكة. لا يُحذف شيء.','Profile'=>'ملف التعريف','Sites to apply'=>'المواقع للتطبيق','"All sites" is selected by default. Deselect it to pick individual sites instead.'=>'"كل المواقع" محدد افتراضيًا. ألغِ تحديده لاختيار مواقع بعينها.','All sites'=>'كل المواقع','Apply profile'=>'تطبيق الملف','Alert thresholds from this profile: %1$s MB reclaimable, %2$s days stale, %3$s KB autoload.'=>'حدود تنبيهات هذا الملف: %1$s ميغابايت قابلة للاسترداد ، %2$s يوم بدون تحليل، %3$s كيلوبايت autoload.','Please select a profile before applying.'=>'يُرجى تحديد ملف قبل التطبيق.','You are not allowed to access this page.'=>'غير مسموح لك بالوصول إلى هذه الصفحة.','Read-only summary of every site in the network. Each site scans and cleans its own data independently; open a site to manage it.'=>'ملخص للقراءة فقط لكل موقع في الشبكة. يفحص كل موقع وينظّف بياناته الخاصة بشكل مستقل؛ افتح موقعاً لإدارته.','Analysis scheduled on %s site(s). Results will appear as each scan finishes.'=>'تمت جدولة التحليل على %s موقع. ستظهر النتائج عند انتهاء كل فحص.','Alert settings saved.'=>'تم حفظ إعدادات التنبيهات.','Quick profile applied to %d site.' . "\0" . 'Quick profile applied to %d sites.'=>'تم تطبيق الملف الشخصي السريع على %d موقع.' . "\0" . 'تم تطبيق الملف الشخصي السريع على موقع واحد.' . "\0" . 'تم تطبيق الملف الشخصي السريع على موقعَين.' . "\0" . 'تم تطبيق الملف الشخصي السريع على %d مواقع.' . "\0" . 'تم تطبيق الملف الشخصي السريع على %d موقعاً.' . "\0" . 'تم تطبيق الملف الشخصي السريع على %d موقع.','No sites were updated (no profile selected or no sites matched).'=>'لم يُحدّث أي موقع (لم يُحدد ملف أو لم تتطابق أي مواقع).','License activated for the site.'=>'تم تفعيل الترخيص لهذا الموقع.','License deactivated for the site.'=>'تم إلغاء تفعيل الترخيص لهذا الموقع.','License activation failed (rejected by the license server).'=>'فشل تفعيل الترخيص (رفضه خادم التراخيص).','Enter a license key first.'=>'أدخل مفتاح ترخيص أولاً.','Could not process the license request.'=>'تعذّرت معالجة طلب الترخيص.','Schedule a fresh analysis on every site in the network?'=>'جدولة تحليل جديد على كل موقع في الشبكة؟','Network overview'=>'نظرة عامة على الشبكة','Never analysed'=>'لم يُحلَّل أبداً','Orphans (all sites)'=>'اليتامى (جميع المواقع)','To identify (all sites)'=>'قيد التحديد (جميع المواقع)','Media reclaimable'=>'وسائط قابلة للاسترداد','Improving'=>'في تحسن','Heavy autoload'=>'تحميل تلقائي ثقيل','Filter sites'=>'تصفية المواقع','Filter sites by name or URL…'=>'تصفية المواقع حسب الاسم أو الرابط…','Recoverable media: duplicate images + orphan files'=>'الوسائط القابلة للاسترداد: صور مكررة + ملفات يتيمة','Autoload change since this site\'s baseline (lower is better)'=>'تغيير التحميل التلقائي منذ خط الأساس للموقع (كلما كان أقل كان أفضل)','Total size of everything scanned (database + files)'=>'الحجم الإجمالي لكل ما تم فحصه (قاعدة البيانات + الملفات)','Actions'=>'إجراءات','Open'=>'فتح','This site has an active license.'=>'يمتلك هذا الموقع ترخيصاً نشطاً.','Deactivate license'=>'إلغاء تفعيل الترخيص','License key:'=>'مفتاح الترخيص:','Activate license'=>'تفعيل الترخيص','Alerts on'=>'التنبيهات مفعّلة','A daily summary is sent to %s.'=>'يُرسَل ملخص يومي إلى %s.','Alerts off'=>'التنبيهات معطّلة','Set a trigger below to start receiving the daily summary.'=>'اضبط محفّزاً أدناه لبدء استلام الملخص اليومي.','Cleanup opportunity'=>'فرصة تنظيف','MB'=>'ميغابايت','Alert when a site has at least this much safely-removable (orphan) data. 0 disables.'=>'نبّه عندما يحتوي موقع على هذا القدر على الأقل من البيانات القابلة للإزالة بأمان (اليتيمة). القيمة 0 تعطّل ذلك.','Falling behind'=>'متأخر','days'=>'أيام','Alert when a site has not been analysed in this many days (never-analysed sites always count). 0 disables.'=>'نبّه عندما لا يُحلَّل موقع طوال هذا العدد من الأيام (المواقع التي لم تُحلَّل أبداً تُحتسب دائماً). القيمة 0 تعطّل ذلك.','KB'=>'كيلوبايت','Alert when a site has more than this much autoloaded data (1024 KB = 1 MB is a common limit). 0 disables.'=>'نبّه عندما يحتوي موقع على أكثر من هذا القدر من بيانات التحميل التلقائي (1024 كيلوبايت = 1 ميغابايت حدّ شائع). القيمة 0 تعطّل ذلك.','Save alert settings'=>'حفظ إعدادات التنبيهات','[%s] WPOptimizing — sites need attention'=>'‏[%s] WPOptimizing — مواقع تحتاج إلى انتباه','%s orphans'=>'%s يتيم','%1$d site has at least %2$s of safely-removable data.' . "\0" . '%1$d sites have at least %2$s of safely-removable data.'=>'%1$d موقع يحتوي على %2$s على الأقل من البيانات القابلة للإزالة بأمان.' . "\0" . 'موقع واحد يحتوي على %2$s على الأقل من البيانات القابلة للإزالة بأمان.' . "\0" . 'موقعان يحتويان على %2$s على الأقل من البيانات القابلة للإزالة بأمان.' . "\0" . '%1$d مواقع تحتوي على %2$s على الأقل من البيانات القابلة للإزالة بأمان.' . "\0" . '%1$d موقعاً يحتوي على %2$s على الأقل من البيانات القابلة للإزالة بأمان.' . "\0" . '%1$d موقع يحتوي على %2$s على الأقل من البيانات القابلة للإزالة بأمان.','🧹 Cleanup opportunity'=>'🧹 فرصة تنظيف','never'=>'أبداً','%1$d site has not been analysed in over %2$d day(s).' . "\0" . '%1$d sites have not been analysed in over %2$d day(s).'=>'%1$d موقع لم يتم تحليله منذ أكثر من %2$d يوم.' . "\0" . 'موقع واحد لم يتم تحليله منذ أكثر من %2$d يوم.' . "\0" . 'موقعان لم يتم تحليلهما منذ أكثر من %2$d يوم.' . "\0" . '%1$d مواقع لم يتم تحليلها منذ أكثر من %2$d يوم.' . "\0" . '%1$d موقعاً لم يتم تحليله منذ أكثر من %2$d يوم.' . "\0" . '%1$d موقع لم يتم تحليله منذ أكثر من %2$d يوم.','⏰ Falling behind'=>'⏰ متأخر','%s options'=>'%s خيار','%1$d site loads over %2$s of autoloaded data on every request.' . "\0" . '%1$d sites load over %2$s of autoloaded data on every request.'=>'%1$d موقع يحمّل أكثر من %2$s من البيانات ذات التحميل التلقائي في كل طلب.' . "\0" . 'موقع واحد يحمّل أكثر من %2$s من البيانات ذات التحميل التلقائي في كل طلب.' . "\0" . 'موقعان يحمّلان أكثر من %2$s من البيانات ذات التحميل التلقائي في كل طلب.' . "\0" . '%1$d مواقع تحمّل أكثر من %2$s من البيانات ذات التحميل التلقائي في كل طلب.' . "\0" . '%1$d موقعاً يحمّل أكثر من %2$s من البيانات ذات التحميل التلقائي في كل طلب.' . "\0" . '%1$d موقع يحمّل أكثر من %2$s من البيانات ذات التحميل التلقائي في كل طلب.','💾 Heavy autoload'=>'💾 تحميل تلقائي ثقيل','Daily summary for %s'=>'ملخص يومي لـ %s','Network alert'=>'تنبيه الشبكة','Open network overview'=>'فتح نظرة عامة على الشبكة','Sent by %s. Adjust or disable these alerts from the network overview.'=>'أُرسل بواسطة %s. عدّل هذه التنبيهات أو عطّلها من نظرة عامة على الشبكة.','Follow us:'=>'تابعنا:','Follow us on '=>'تابعنا على ','More plugins:'=>'مزيد من الإضافات:','More plugins on '=>'مزيد من الإضافات على ','Contact us:'=>'تواصل معنا:','Contact us by '=>'تواصل معنا عبر ','Type 2 or more characters to search…'=>'اكتب حرفين أو أكثر للبحث…','Searching…'=>'جارٍ البحث…','No matches found'=>'لا توجد نتائج مطابقة','Could not load the results'=>'تعذّر تحميل النتائج','Loading more results…'=>'جارٍ تحميل المزيد من النتائج…','Connecting'=>'جارٍ الاتصال','Deactivate'=>'إلغاء التفعيل','Activate'=>'تفعيل','The license could not be verified. Pro features stay on for %d more day while the connection to the store is restored.' . "\0" . 'The license could not be verified. Pro features stay on for %d more days while the connection to the store is restored.'=>'تعذّر التحقق من الترخيص. ستظل ميزات Pro مفعّلة %d يوم إضافي ريثما يُستعاد الاتصال بالمتجر.' . "\0" . 'تعذّر التحقق من الترخيص. ستظل ميزات Pro مفعّلة يومًا إضافيًا واحدًا ريثما يُستعاد الاتصال بالمتجر.' . "\0" . 'تعذّر التحقق من الترخيص. ستظل ميزات Pro مفعّلة يومين إضافيين ريثما يُستعاد الاتصال بالمتجر.' . "\0" . 'تعذّر التحقق من الترخيص. ستظل ميزات Pro مفعّلة %d أيام إضافية ريثما يُستعاد الاتصال بالمتجر.' . "\0" . 'تعذّر التحقق من الترخيص. ستظل ميزات Pro مفعّلة %d يومًا إضافيًا ريثما يُستعاد الاتصال بالمتجر.' . "\0" . 'تعذّر التحقق من الترخيص. ستظل ميزات Pro مفعّلة %d يوم إضافي ريثما يُستعاد الاتصال بالمتجر.','Security check failed.'=>'فشل التحقق الأمني.','Welcome to WPOptimizing!'=>'مرحباً بك في WPOptimizing!','Your installation is ready. Run your first analysis to discover orphaned records, files and media, see what belongs to each plugin, and safely clean your database.'=>'التثبيت جاهز. شغّل تحليلك الأول لاكتشاف السجلات والملفات والوسائط اليتيمة، ومعرفة ما يخص كل إضافة، وتنظيف قاعدة بياناتك بأمان.','Run first analysis →'=>'تشغيل التحليل الأول ←','Dismiss'=>'تجاهل','Not analyzed'=>'لم يُحلَّل','Run an analysis first'=>'شغّل تحليلًا أولًا','Clean'=>'نظيفة','No orphaned data'=>'لا توجد بيانات يتيمة','Review'=>'مراجعة','%s recoverable'=>'%s قابلة للاسترداد','Action needed'=>'يتطلب إجراءً','Healthy'=>'سليم','Could improve'=>'قابل للتحسين','Heavy'=>'ثقيل','Managed by %s'=>'يديرها %s','Active with %s'=>'مفعّل عبر %s','Not enabled'=>'غير مُفعَّل','Object cache is off'=>'ذاكرة كائنات التخزين المؤقت معطّلة','Warming up'=>'قيد التهيئة','Hit rate'=>'نسبة الإصابة','Object cache on'=>'ذاكرة كائنات التخزين المؤقت مُفعَّلة','Autoload weight (target < 800 KB)'=>'حجم التحميل التلقائي (الهدف < 800 ك.ب)','View autoload'=>'عرض التحميل التلقائي','Open cache'=>'فتح ذاكرة التخزين المؤقت','Enable cache'=>'تفعيل ذاكرة التخزين المؤقت','Warning'=>'تحذير','Critical'=>'حرج','Known list reset. Run an analysis to re-evaluate those attachments.'=>'تمت إعادة تعيين قائمة المعروفة. شغّل تحليلًا لإعادة تقييم تلك المرفقات.','You do not have sufficient permissions to access this page.'=>'ليس لديك الأذونات الكافية للوصول إلى هذه الصفحة.','Analyses your plugins, themes, database and files to speed up your site and find what was left behind. Use the menu on the left: Diagnose, Speed, Clean up, and Analysis results to review what the analysis found.'=>'يحلّل إضافاتك وقوالبك وقاعدة بياناتك وملفاتك لتسريع موقعك والعثور على ما تُرك خلفك. استخدم القائمة على اليسار: التشخيص والسرعة والتنظيف ونتائج التحليل لمراجعة ما وجده التحليل.','Last analysis: %1$s ago (%2$s).'=>'آخر تحليل: قبل %1$s (%2$s).','The last analysis could not read part of the database: %s query did not finish (it took too long or the server returned an error). The database lists keep the results of the previous analysis; analyse again at a quieter time.' . "\0" . 'The last analysis could not read part of the database: %s queries did not finish (they took too long or the server returned an error). The database lists keep the results of the previous analysis; analyse again at a quieter time.'=>'تعذّر على التحليل الأخير قراءة جزء من قاعدة البيانات: لم يكتمل %s استعلام (استغرق وقتًا طويلًا أو أعاد الخادم خطأً). تحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق؛ أعد التحليل في وقت أهدأ.' . "\0" . 'تعذّر على التحليل الأخير قراءة جزء من قاعدة البيانات: لم يكتمل %s استعلام (استغرق وقتًا طويلًا أو أعاد الخادم خطأً). تحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق؛ أعد التحليل في وقت أهدأ.' . "\0" . 'تعذّر على التحليل الأخير قراءة جزء من قاعدة البيانات: لم يكتمل %s استعلام (استغرق وقتًا طويلًا أو أعاد الخادم خطأً). تحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق؛ أعد التحليل في وقت أهدأ.' . "\0" . 'تعذّر على التحليل الأخير قراءة جزء من قاعدة البيانات: لم يكتمل %s استعلام (استغرق وقتًا طويلًا أو أعاد الخادم خطأً). تحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق؛ أعد التحليل في وقت أهدأ.' . "\0" . 'تعذّر على التحليل الأخير قراءة جزء من قاعدة البيانات: لم يكتمل %s استعلام (استغرق وقتًا طويلًا أو أعاد الخادم خطأً). تحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق؛ أعد التحليل في وقت أهدأ.' . "\0" . 'تعذّر على التحليل الأخير قراءة جزء من قاعدة البيانات: لم يكتمل %s استعلام (استغرق وقتًا طويلًا أو أعاد الخادم خطأً). تحتفظ قوائم قاعدة البيانات بنتائج التحليل السابق؛ أعد التحليل في وقت أهدأ.','Data sharing is off.'=>'مشاركة البيانات معطّلة.','WPOptimizing is using only your local attribution — it is not receiving the shared attribution dataset that improves accuracy. Turn on sharing (opt-in and reciprocal) to give back and receive the community dataset.'=>'يستخدم WPOptimizing إسنادك المحلي فقط — وهو لا يستلم مجموعة بيانات الإسناد المشتركة التي تحسّن الدقة. فعّل المشاركة (اختيارية وتبادلية) للمساهمة واستلام مجموعة بيانات المجتمع.','Enable sharing'=>'تفعيل المشاركة','Welcome'=>'ترحيب','Cleanup'=>'تنظيف','Images'=>'الصور','Ready'=>'جاهز','Welcome to WPOptimizing'=>'مرحبًا بك في WPOptimizing','Measure and speed up'=>'قِس وسرّع','See where the time goes and fix it: object and page cache, CSS and JavaScript, WebP and AVIF images and delivery, each one switched on separately.'=>'اكتشف أين يضيع الوقت وأصلحه: التخزين المؤقت للكائنات والصفحات، وCSS وJavaScript، وصور WebP وAVIF، والتحميل والتسليم، وكل منها يُفعَّل على حدة.','Smart attribution'=>'الإسناد الذكي','Every option, post meta, cron job and file is traced back to its owning plugin or theme using backtrace analysis, callback reflection and a community dataset.'=>'يُتتبَّع كل خيار وبيانات إضافية للمقالة ومهمة cron وملف رجوعاً إلى الإضافة أو القالب المالك له باستخدام تحليل backtrace وانعكاس رد النداء ومجموعة بيانات مجتمعية.','Safe cleanup'=>'تنظيف آمن','Attributed deletions, media cleanups and the general cleanup create a backup first, restorable from the Backups tab. Orphaned records (from uninstalled plugins) are separated from inactive ones so you always know the risk.'=>'عمليات الحذف المنسوبة وتنظيف الوسائط والتنظيف العام تُنشئ نسخة احتياطية أولاً، يمكن استعادتها من تبويب النسخ الاحتياطية. تُفصل السجلات اليتيمة (من إضافات مُزالة) عن غير النشطة لتعرف المخاطر دائمًا.','7-level confidence'=>'سبعة مستويات للثقة','Each attributed record gets a confidence badge, from the Manual rules you set yourself down to Undetermined. Only Manual, Sure, Likely and Possible items are considered fully safe for automatic cleanup.'=>'يحصل كل سجل منسوب على شارة ثقة، من قواعد «يدوي» التي تضعها بنفسك وصولاً إلى «غير محدد». وحدها العناصر «يدوي» و«مؤكد» و«مرجّح» و«محتمل» تُعتبر آمنة تمامًا للتنظيف التلقائي.','Confidence levels — hover to learn more:'=>'مستويات الثقة — مرّر المؤشر لمعرفة المزيد:','Help improve attribution accuracy (recommended).'=>'ساعد في تحسين دقة الإسناد (موصى به).','Share attribution metadata with the WPOptimizing shared dataset and receive the community dataset in return. Only the names of options, meta keys, tables and files, their sizes and how often they are seen are sent, with your site’s domain — never option values, post or user content, or any record contents. It is reciprocal (off = the plugin keeps working with your local data only, but does not exchange the shared dataset) and you can change it anytime in Settings.'=>'شارك بيانات إسناد وصفية مع مجموعة بيانات WPOptimizing المشتركة واستلم مجموعة بيانات المجتمع في المقابل. تُرسَل فقط أسماء الخيارات ومفاتيح البيانات الإضافية والجداول والملفات وأحجامها وعدد مرات ظهورها، مع نطاق موقعك — ولا تُرسَل أبداً قيم الخيارات أو محتوى المقالات أو المستخدمين أو أي محتوى للسجلات. إنها تبادلية (الإيقاف = تواصل الإضافة العمل ببياناتك المحلية فقط، لكنها لا تتبادل المجموعة المشتركة) ويمكنك تغييرها في أي وقت من الإعدادات.','License active'=>'الترخيص مُفعّل','All Pro features are unlocked on this site.'=>'جميع ميزات Pro مُفعّلة على هذا الموقع.','Database cleanup'=>'تنظيف قاعدة البيانات','Choose how thorough the automatic cleanup should be. You can fine-tune everything later in Settings.'=>'اختر مدى شمولية التنظيف التلقائي. يمكنك ضبط كل شيء لاحقًا في الإعدادات.','Cleanup preset'=>'إعداد التنظيف المُسبق','%s — recommended for your site'=>'%s — مُوصى به لموقعك','Pre-selected based on the plugins we detected on your site. Applied when you start the analysis below; you can change it anytime in Settings.'=>'مُحدَّد مسبقًا بناءً على الإضافات التي اكتشفناها في موقعك. يُطبَّق عند بدء التحليل أدناه؛ ويمكنك تغييره في أي وقت من الإعدادات.','Ongoing maintenance (optional)'=>'الصيانة المستمرة (اختياري)','Clean automatically as the database grows.'=>'التنظيف تلقائيًا مع نمو قاعدة البيانات.','Runs the selected preset in the background once the database grows past a threshold since the last cleanup. Safe and backup-first.'=>'يشغّل الإعداد المسبق المحدد في الخلفية عندما تنمو قاعدة البيانات فوق حدٍّ معيّن منذ آخر تنظيف. آمن ومع نسخة احتياطية أولًا.','Growth threshold (MB)'=>'حد النمو (ميغابايت)','Email maintenance report'=>'تقرير الصيانة عبر البريد الإلكتروني','Send report to'=>'إرسال التقرير إلى','For agencies: route the report to the maintainer instead of the site owner. Separate several addresses with commas; leave empty to use the site admin email.'=>'للوكالات: أرسل التقرير إلى المسؤول عن الصيانة بدلًا من مالك الموقع. افصل بين عدة عناوين بفواصل؛ اتركه فارغًا لاستخدام بريد مدير الموقع.','Safe, reversible speed-ups. Sensible defaults are pre-selected; uncheck anything you would rather skip.'=>'تسريعات آمنة وقابلة للعكس. القيم المعقولة محددة مسبقًا؛ ألغِ تحديد ما تفضّل تخطّيه.','Enable the object cache (recommended).'=>'تفعيل تخزين الكائنات المؤقت (مُوصى به).','Speeds up the admin and the front end with a safe persistent object cache — no full-page caching, so it never serves stale pages. You can disable it anytime in Speed › Cache.'=>'يُسرّع لوحة التحكم والواجهة الأمامية عبر تخزين مؤقت آمن ودائم للكائنات — دون تخزين مؤقت للصفحة كاملة، فلا يقدّم صفحات قديمة أبدًا. يمكنك تعطيله في أي وقت من السرعة › التخزين المؤقت.','Enable query deduplication (recommended).'=>'تفعيل إزالة تكرار الاستعلامات (مُوصى به).','Stops the same database read query running twice within a request. Safe and reversible — any write clears it instantly, so results are never stale. You can disable it anytime in Speed › Cache.'=>'يمنع تنفيذ استعلام القراءة نفسه من قاعدة البيانات مرتين ضمن الطلب الواحد. آمن وقابل للتراجع — تمسحه أي عملية كتابة فورًا، لذا لا تكون النتائج قديمة أبدًا. يمكنك تعطيله في أي وقت من السرعة › التخزين المؤقت.','Self-host Google Fonts (recommended).'=>'استضافة خطوط Google ذاتيًا (موصى به).','Serves the font CSS and files from this site so the browser never contacts Google (faster first render, GDPR-friendly). We detect and download them when the analysis runs.'=>'يقدّم CSS الخطوط وملفاتها من هذا الموقع بحيث لا يتصل المتصفح بـ Google أبدًا (عرض أول أسرع، ومتوافق مع GDPR). نكتشفها وننزّلها عند تشغيل التحليل.','Heartbeat activity'=>'نشاط Heartbeat','Default (leave as-is)'=>'افتراضي (اتركه كما هو)','Slow it down (recommended)'=>'إبطاؤه (موصى به)','Turn it off outside the editor'=>'إيقافه خارج المحرر','Heartbeat is the WordPress admin auto-save/notification ping. Slowing it down cuts admin CPU with no visible downside; you can change it in Diagnose › Performance › Server.'=>'Heartbeat هو نبضة الحفظ التلقائي/الإشعارات في لوحة تحكم ووردبريس. إبطاؤه يقلّل استهلاك المعالج في اللوحة دون عيب ظاهر؛ يمكنك تغييره من التشخيص › الأداء › الخادم.','Enable Smart Assets manual unloading.'=>'تفعيل الإلغاء اليدوي للموارد الذكية.','Turns on the engine so you can stop specific CSS/JS from loading; you then choose which in the Smart Assets tab. WordPress core and jQuery are always protected, and it is fully reversible.'=>'يشغّل المحرّك حتى تتمكّن من منع تحميل ملفات CSS/JS محدّدة؛ ثم تختار أيّها من تبويب الموارد الذكية. نواة ووردبريس وjQuery محميّتان دائمًا، وهو قابل للتراجع تمامًا.','Enable automatic asset unloading.'=>'تفعيل الإلغاء التلقائي للموارد.','Pro'=>'Pro','Automatically stops loading a known plugin or theme\'s CSS/JS on pages where it is not used (e.g. WooCommerce off the shop, Contact Form 7 with no form). Conservative, core/jQuery protected, reversible. Test your key pages afterwards.'=>'يتوقّف تلقائيًا عن تحميل CSS/JS لإضافة أو قالب معروف في الصفحات التي لا يُستخدم فيها (مثلًا WooCommerce خارج المتجر، وContact Form 7 بلا نموذج). محافِظ، النواة/jQuery محميّة، قابل للتراجع. اختبر بعدها صفحاتك الرئيسية.','Advanced (optional)'=>'متقدّم (اختياري)','Not part of any preset because they change how the site behaves. Off by default — enable only if they apply to you.'=>'ليست جزءًا من أي إعداد مسبق لأنها تغيّر سلوك الموقع. معطَّلة افتراضيًا — فعّلها فقط إذا كانت تنطبق عليك.','Shrink images and serve modern formats. These feed the optimizer in the Media tab and can be changed anytime.'=>'يقلّل حجم الصور ويقدّم الصيغ الحديثة. يغذّي ذلك المُحسِّن في علامة تبويب الوسائط ويمكن تغييره في أي وقت.','Delivers lighter next-gen images, for every image that has a WebP or AVIF copy, with an automatic fallback to the original.'=>'يقدّم صور الجيل الجديد الأخفّ لكل صورة لها نسخة WebP أو AVIF، مع الرجوع التلقائي إلى الأصل.','Delivers lighter next-gen images with an automatic fallback to the original. Generate the copies later from the Image optimization sub-section.'=>'يقدّم صور الجيل الجديد الأخفّ مع الرجوع التلقائي إلى الأصل. ولّد النسخ لاحقًا من القسم الفرعي «تحسين الصور».','Serve WebP/AVIF on the front-end (recommended).'=>'تقديم WebP/AVIF في الواجهة الأمامية (مُستحسَن).','Optimize new uploads automatically.'=>'تحسين المرفوعات الجديدة تلقائيًا.','Resizes uploads above the max size, recompresses them and strips their metadata; the full-size original is preserved.'=>'يصغّر المرفوعات التي تتجاوز الحجم الأقصى ، ويعيد ضغطها ويزيل بياناتها الوصفية؛ مع الحفاظ على الأصل بالحجم الكامل.','Lossless mode.'=>'وضع بلا فقدان.','Do not reduce image quality (smaller savings, no visible change).'=>'لا يخفّض جودة الصورة (توفير أقل، دون تغيير مرئي).','Quality and max size'=>'الجودة والحجم الأقصى','Conversion quality'=>'جودة التحويل','Max width in pixels'=>'أقصى عرض بالبكسل','Max height in pixels'=>'أقصى ارتفاع بالبكسل','Quality 40–100 (82 is a good balance). 0 on an axis disables resizing.'=>'الجودة 40–100 (82 توازن جيّد). القيمة 0 على أحد المحورين تعطّل تغيير الحجم.','All set'=>'كل شيء جاهز','Start your first analysis. Your choices are saved when it begins, and everything stays adjustable in Settings.'=>'ابدأ تحليلك الأول. تُحفَظ اختياراتك عند البدء ويبقى كل شيء قابلًا للضبط في الإعدادات.','Apply these settings and analyze'=>'تطبيق هذه الإعدادات وبدء التحليل','Set up later'=>'الإعداد لاحقًا','Your selection is saved and the options you ticked (persistent object cache, query deduplication) are switched on when the analysis starts. You can switch them off again in Speed › Cache.'=>'يُحفظ اختيارك، وتُفعَّل الخيارات التي حدّدتها (التخزين المؤقت الدائم للكائنات، إزالة تكرار الاستعلامات) عند بدء التحليل. يمكنك إيقافها مجددًا من السرعة › التخزين المؤقت.','Back'=>'السابق','Next'=>'التالي','WPOptimizing — Analysis in progress'=>'WPOptimizing — التحليل قيد التنفيذ','Starting…'=>'جارٍ البدء…','Cancel analysis'=>'إلغاء التحليل','s remaining'=>'ث متبقية','min remaining'=>'دقيقة متبقية','h remaining'=>'ساعة متبقية','Post revisions'=>'مراجعات المقالات','Activity log'=>'سجل النشاط','Everything that changed in WordPress since WPOptimizing was installed: database tables, options, post/user meta keys, scheduled events and top-level plugin/theme/upload files that other plugins add or remove — each with the date and, when the change came from a plugin or theme action, the responsible extension.'=>'كل ما تغيّر في ووردبريس منذ تثبيت WPOptimizing: جداول قاعدة البيانات، والخيارات، ومفاتيح البيانات الوصفية للمقالات/المستخدمين، والأحداث المجدولة، وملفات المستوى الأعلى ضمن plugins/themes/uploads التي تضيفها أو تزيلها إضافات أخرى — كل منها بتاريخه، وعند صدور التغيير عن إجراء إضافة أو قالب، الإضافة المسؤولة.','No changes recorded yet. WPOptimizing captured a baseline of your site when it was installed; from now on, changes made by plugins and themes (new tables, options, files, scheduled events…) show up here with their date and, when known, who made them.'=>'لم يتم تسجيل أي تغييرات بعد. التقط WPOptimizing خط أساس لموقعك عند تثبيته؛ من الآن فصاعدًا، تظهر هنا التغييرات التي تجريها الإضافات والقوالب (جداول جديدة، خيارات، ملفات، أحداث مجدولة…) بتاريخها، ومَن أجراها عند معرفته.','Added'=>'أُضيف','Removed'=>'أُزيل','Unknown'=>'غير معروف','Date'=>'التاريخ','Change'=>'تغيير','Responsible'=>'المسؤول','All changes'=>'كل التغييرات','Clear the whole activity log? The baseline is kept, so tracking continues from now.'=>'مسح سجل النشاط بالكامل؟ يتم الاحتفاظ بخط الأساس، لذا تستمر المتابعة من الآن.','Suggestion accepted: "%1$s" attributed to %2$s. The record was re-evaluated.'=>'تم قبول الاقتراح: نُسِب «%1$s» إلى %2$s. أُعيد تقييم السجل.','The suggestion could not be saved (it may already exist).'=>'تعذّر حفظ الاقتراح (ربما يكون موجودًا بالفعل).','The attribution assistant needs data sharing turned on (it sends only identifier names).'=>'يحتاج مساعد النسب إلى تفعيل مشاركة البيانات (يُرسل أسماء المعرّفات فقط).','The assistant returned no suggestions (the service may be unreachable). Nothing was changed.'=>'لم يُرجع المساعد أي اقتراحات (قد تكون الخدمة غير متاحة). لم يتغيّر شيء.','Check the owner shown for these records against the shared knowledge base before you delete anything. A record whose owner does not match is flagged, and you decide: accepting a suggestion creates a manual attribution rule. Nothing is deleted here.'=>'قارن المالك المعروض لهذه السجلات بمجموعة البيانات المشتركة قبل حذف أي شيء. تُعلَّم السجلات التي لا يتطابق مالكها، والقرار لك: قبول الاقتراح يُنشئ قاعدة إسناد يدوية. لا يُحذف هنا شيء.','After each analysis, the owners the shared knowledge base gives with certainty are applied on their own. Ask here about the rest: confirm a suggestion with Accept, or all the sure ones at once, and it becomes a manual attribution rule. Nothing is deleted.'=>'بعد كل تحليل، يُطبَّق تلقائيًا المالكون الذين تحددهم قاعدة المعرفة المشتركة بيقين. اسأل هنا عن الباقي: أكّد اقتراحًا بزر «قبول»، أو كل الاقتراحات المؤكدة دفعة واحدة، فيصبح قاعدة نسب يدوية. لا يُحذف أي شيء.','Turn on data sharing to use the assistant (only identifier names are sent).'=>'فعّل مشاركة البيانات لاستخدام المساعد (تُرسَل أسماء المعرّفات فقط).','Check these owners'=>'تحقق من هؤلاء المالكين','Suggest owners'=>'اقترح المالكين','It belongs to the shared library "%s", which several plugins carry inside: there is no single owner.'=>'ينتمي إلى المكتبة المشتركة «%s» التي تحملها عدة إضافات بداخلها: لا يوجد مالك واحد.','Exact match with a single owner in the shared knowledge base.'=>'تطابق تام مع مالك واحد في مجموعة البيانات المشتركة.','Exact match: the record is in the namespace of "%s", and the others only read it.'=>'تطابق تام: السجل ضمن نطاق أسماء «%s»، والبقية تقرؤه فقط.','%d plugins use it and none is clearly its owner, so no owner is proposed. Using a record is not owning it.'=>'تستخدمه %d إضافة ولا واحدة منها مالكه بوضوح، لذا لا يُقترح مالك. استخدام السجل ليس امتلاكًا له.','No exact match, but the prefix belongs to a single owner.'=>'لا يوجد تطابق تام، لكن السابقة تخص مالكًا واحدًا.','A specific prefix of a single owner. A hint to confirm, not a certainty.'=>'سابقة خاصة بمالك واحد. قرينة للتأكيد، لا يقين.','Only prefixes shared by several owners: too weak to propose anyone.'=>'سوابق يتشاركها عدة مالكين فقط: أضعف من أن تُقترح بها جهة.','Ambiguous'=>'غامض','No data'=>'لا توجد بيانات','Record'=>'السجل','Verdict'=>'الحكم','Shown now'=>'المعروض الآن','Suggested owner'=>'المالك المقترح','Why'=>'السبب','Action'=>'إجراء','— does not match'=>'— غير مطابق','Accept'=>'قبول','review manually'=>'المراجعة يدويًا','Autoload analyzer unavailable.'=>'مُحلّل التحميل التلقائي غير متاح.','Acceptable'=>'مقبول','Autoloaded options'=>'الخيارات المُحمَّلة تلقائيًا','Autoloaded options load into memory on every request. Keeping their total weight low keeps the site fast — under ~800 KB is healthy.'=>'تُحمَّل خيارات التحميل التلقائي إلى الذاكرة في كل طلب. إبقاء وزنها الإجمالي منخفضاً يحافظ على سرعة الموقع — أقل من ~800 كيلوبايت يُعد سليماً.','Total weight'=>'الوزن الإجمالي','Crowd-confirmed'=>'مؤكد جماعياً','Health'=>'الصحة','No autoloaded options found.'=>'لم يتم العثور على خيارات تحميل تلقائي.','Autoloaded'=>'محمّل تلقائياً','Disabling autoload keeps the option but stops loading it on every page (reversible). Smart Deactivation does this automatically for options confidently identified as belonging to uninstalled extensions.'=>'تعطيل التحميل التلقائي يُبقي الخيار لكنه يوقف تحميله في كل صفحة (قابل للعكس). يقوم التعطيل الذكي بذلك تلقائياً للخيارات التي تم تحديدها بثقة على أنها تخص إضافات غير مثبتة.','Core'=>'النواة','Attributed'=>'منسوبة','Search options'=>'خيارات البحث','Smart Deactivation will turn off autoload for every option confidently identified as belonging to an uninstalled extension. This is reversible. Continue?'=>'سيقوم التعطيل الذكي بإيقاف التحميل التلقائي لكل خيار تم تحديده بثقة على أنه يخص إضافة غير مثبتة. هذا الإجراء قابل للعكس. هل تريد المتابعة؟','Aggressive Deactivation turns off autoload for EVERY option that is not core and not from an installed extension — including the unidentified ones. Options the community reads on most requests are kept. Nothing is deleted and it is fully reversible. Continue?'=>'يقوم الإيقاف العنيف بإيقاف التحميل التلقائي لكل خيار لا ينتمي إلى النواة ولا إلى إضافة مثبَّتة، بما في ذلك غير المعروفة. تُحفظ الخيارات التي يقرؤها المجتمع في معظم الطلبات. لا يُحذف أي شيء وهو قابل للتراجع تمامًا. هل تريد المتابعة؟','Disable all non-essential'=>'إيقاف كل ما هو غير ضروري','Surgical Deactivation turns off autoload only for options that load on every request but are (almost) never read — measured on your own site and confirmed across the network. Nothing is deleted and it is fully reversible. Continue?'=>'يقوم التعطيل الدقيق بإلغاء التحميل التلقائي فقط للخيارات التي تُحمَّل في كل طلب لكنها (تقريبًا) لا تُقرأ أبدًا — مقيسًا على موقعك ومؤكَّدًا عبر الشبكة. لا يُحذف أي شيء وهو قابل للتراجع تمامًا. هل تريد المتابعة؟','De-autoload never-read (%d)'=>'إلغاء التحميل التلقائي لما لا يُقرأ أبدًا (%d)','De-autoload never-read'=>'إلغاء التحميل التلقائي لما لا يُقرأ أبدًا','Delete the autoloaded options confidently identified as belonging to uninstalled extensions? Nothing installed uses them any more, but they keep that extension\'s settings if you reinstall it. A backup is created first. Continue?'=>'حذف الخيارات ذات التحميل التلقائي المُحددة بثقة كتابعة لإضافات أُلغي تثبيتها؟ لم يعد أي شيء مثبَّت يستخدمها، لكنها تحتفظ بإعدادات تلك الإضافة إن أعدت تثبيتها. تُنشأ نسخة احتياطية أولًا. هل تريد المتابعة؟','Delete confirmed orphans (backup first)'=>'حذف اليتيمة المؤكدة (مع نسخة احتياطية)','Disable all'=>'تعطيل الكل','Disabling autoload keeps the option but stops loading it on every page (reversible). Open “Advanced autoload cleanup” for the smart, never-read, non-essential and delete-orphans helpers.'=>'إلغاء التحميل التلقائي يُبقي الخيار لكنه يتوقف عن تحميله في كل صفحة (قابل للتراجع). افتح «التنظيف المتقدّم للتحميل التلقائي» للحصول على الأدوات: الذكي، وما لا يُقرأ أبدًا، وغير الضروري، وحذف اليتيمة.','Disable autoload for the %d selected option(s)? This is reversible.'=>'تعطيل التحميل التلقائي للخيارات المحددة وعددها %d؟ هذا الإجراء قابل للعكس.','Disable autoload for ALL %d filtered option(s)? This is reversible.'=>'تعطيل التحميل التلقائي لجميع الخيارات المُصفّاة وعددها %d؟ هذا الإجراء قابل للعكس.','WPOptimizing measures how often each non-autoloaded option is actually read on each request. Options read on most requests but not autoloaded are real candidates for autoloading — no guessing.'=>'يقيس WPOptimizing عدد المرات التي يُقرأ فيها فعلياً كل خيار غير محمّل تلقائياً في كل طلب. الخيارات التي تُقرأ في معظم الطلبات ولكنها غير محمّلة تلقائياً هي مرشحات حقيقية للتحميل التلقائي — بلا تخمين.','Measuring automatically'=>'القياس تلقائياً','%1$s requests sampled over %2$s.'=>'تم أخذ عينة من %1$s طلب خلال %2$s.','Warming up — let normal traffic flow for a little while.'=>'جارٍ الإحماء — اترك حركة المرور الاعتيادية تتدفق لبعض الوقت.','Measurement is continuous and refreshes itself roughly once a month. This data also helps improve autoload recommendations across the WPOptimizing network.'=>'القياس مستمر ويُحدّث نفسه تقريباً مرة في الشهر. تساعد هذه البيانات أيضاً في تحسين توصيات التحميل التلقائي عبر شبكة WPOptimizing.','Clear the measured data and start a fresh measurement window?'=>'مسح البيانات المقاسة وبدء نافذة قياس جديدة؟','Reset measurement'=>'إعادة تعيين القياس','Measuring automatically — candidates appear once enough requests have been sampled.'=>'القياس تلقائياً — تظهر المرشحات بمجرد أخذ عينة كافية من الطلبات.','No options qualify: every option read on most requests is already autoloaded. Nothing to do — that is good news.'=>'لا توجد خيارات مؤهلة: كل خيار يُقرأ في معظم الطلبات محمّل تلقائياً بالفعل. لا شيء للقيام به — وهذا خبر جيد.','Smart Activation will enable autoload for every option read on almost every request and small enough to be safe. This is reversible. Continue?'=>'سيُفعِّل التفعيل الذكي التحميل التلقائي لكل خيار يُقرأ في كل طلب تقريبًا وصغير بما يكفي ليكون آمنًا. هذا الإجراء قابل للتراجع. هل تريد المتابعة؟','Enable autoload for selected'=>'تفعيل التحميل التلقائي للمحدد','Smart Activation'=>'تفعيل ذكي','Manage backups created before cleanups. You can create a manual backup, restore one, or delete old backups.'=>'إدارة النسخ الاحتياطية التي تم إنشاؤها قبل عمليات التنظيف. يمكنك إنشاء نسخة احتياطية يدوية أو استعادة واحدة أو حذف النسخ القديمة.','No backups available.'=>'لا توجد نسخ احتياطية متاحة.','item' . "\0" . 'items'=>'عنصر' . "\0" . 'عنصر' . "\0" . 'عنصران' . "\0" . 'عناصر' . "\0" . 'عنصراً' . "\0" . 'عنصر','Restore this backup? It replaces the current data with the saved copy.'=>'استعادة هذه النسخة الاحتياطية؟ ستستبدل البيانات الحالية بالنسخة المحفوظة.','Delete this backup permanently?'=>'حذف هذه النسخة الاحتياطية نهائيًا؟','Last updated %s'=>'آخر تحديث %s','Operation'=>'العملية','Contents'=>'المحتويات','All operations'=>'كل العمليات','Cleanup (deletion)'=>'تنظيف (حذف)','Manual backup'=>'نسخة احتياطية يدوية','Scheduled cleanup'=>'تنظيف مجدول','Duplicate media removal'=>'إزالة الوسائط المكررة','Unused media removal'=>'إزالة الوسائط غير المستخدمة','Autoload change'=>'تغيير التحميل التلقائي','Background transient sweep'=>'مسح البيانات المؤقتة في الخلفية','Scheduled task run now'=>'تشغيل فوري لمهمة مجدولة','Plugin or theme uninstall'=>'إلغاء تثبيت إضافة أو قالب','.htaccess change'=>'تغيير .htaccess','wp-config.php change'=>'تغيير wp-config.php','Thumbnail regeneration'=>'إعادة توليد الصور المصغّرة','Backup'=>'نسخة احتياطية','Details'=>'التفاصيل','Includes:'=>'يتضمن:','(+%d more)'=>'(+%d أخرى)','Front-end settings saved.'=>'تم حفظ إعدادات الواجهة الأمامية.','The restore finished, but %d item could not be written back. Check the permissions of the backup folder and of wp-content, then restore again.' . "\0" . 'The restore finished, but %d items could not be written back. Check the permissions of the backup folder and of wp-content, then restore again.'=>'اكتملت الاستعادة، لكن تعذّرت إعادة كتابة %d عنصر. تحقّق من أذونات مجلد النسخ الاحتياطية و wp-content ثم أعد الاستعادة.' . "\0" . 'اكتملت الاستعادة، لكن تعذّرت إعادة كتابة عنصر واحد. تحقّق من أذونات مجلد النسخ الاحتياطية و wp-content ثم أعد الاستعادة.' . "\0" . 'اكتملت الاستعادة، لكن تعذّرت إعادة كتابة عنصرين. تحقّق من أذونات مجلد النسخ الاحتياطية و wp-content ثم أعد الاستعادة.' . "\0" . 'اكتملت الاستعادة، لكن تعذّرت إعادة كتابة %d عناصر. تحقّق من أذونات مجلد النسخ الاحتياطية و wp-content ثم أعد الاستعادة.' . "\0" . 'اكتملت الاستعادة، لكن تعذّرت إعادة كتابة %d عنصرًا. تحقّق من أذونات مجلد النسخ الاحتياطية و wp-content ثم أعد الاستعادة.' . "\0" . 'اكتملت الاستعادة، لكن تعذّرت إعادة كتابة %d عنصر. تحقّق من أذونات مجلد النسخ الاحتياطية و wp-content ثم أعد الاستعادة.','Backup created.'=>'تم إنشاء النسخة الاحتياطية.','Test report sent to the notification address.'=>'أُرسل تقرير الاختبار إلى عنوان الإشعارات.','Could not send the test report — check the notification email and that a scan has run.'=>'تعذّر إرسال تقرير الاختبار — تحقّق من بريد الإشعارات ومن أنه قد جرى فحص.','Settings saved.'=>'تم حفظ الإعدادات.','another plugin'=>'إضافة أخرى','wp-content/%1$s belongs to %2$s. WPOptimizing will not overwrite it unless you choose to replace it.'=>'wp-content/%1$s يتبع %2$s. لن يستبدله WPOptimizing إلا إذا اخترت ذلك.','wp-content/%s could not be copied aside, so it was left in place.'=>'تعذّر حفظ نسخة من wp-content/%s، لذا تُرك كما هو.','%s is active and serves its own page cache. Use its cache, or deactivate it first: two page caches on the same pages fight each other.'=>'%s نشط ويقدّم ذاكرة صفحات خاصة به. استخدم ذاكرته أو عطّله أولًا: ذاكرتا صفحات على الصفحات نفسها تتعارضان.','%s is active and provides the object cache. Use it, or deactivate it first if you prefer WPOptimizing’s.'=>'%s نشط ويوفّر ذاكرة الكائنات. استخدمها، أو عطّله أولًا إن كنت تفضّل ذاكرة WPOptimizing.','The db.php of %s routes the connection to the database itself; replacing it could leave the site without a database. WPOptimizing will not touch it.'=>'ملف db.php الخاص بـ %s يوجّه الاتصال بقاعدة البيانات نفسه؛ واستبداله قد يترك الموقع بلا قاعدة بيانات. لن يلمسه WPOptimizing.','%1$s The drop-in of %2$s that it had replaced is back in place.'=>'%1$s عاد ملف drop-in الخاص بـ %2$s الذي كان قد استُبدل إلى مكانه.','Managed by another plugin'=>'مُدار بواسطة إضافة أخرى','wp-content/%s belongs to another plugin, which could not be identified.'=>'wp-content/%s يتبع إضافة أخرى تعذّر التعرّف عليها.','wp-content/%1$s belongs to %2$s, which is active.'=>'wp-content/%1$s يتبع %2$s، وهي نشطة.','wp-content/%1$s belongs to %2$s, which is no longer active: it is a leftover.'=>'wp-content/%1$s يتبع %2$s، وهي لم تعد نشطة: إنه بقايا.','wp-content/%1$s belongs to %2$s.'=>'wp-content/%1$s يتبع %2$s.','WPOptimizing can take its place: the current %1$s is kept and put back when you disable this. Meanwhile, whatever %2$s does with that file stops.'=>'يمكن لـ WPOptimizing أن يحلّ محله: يُحفظ %1$s الحالي ويُعاد عند تعطيل هذه الميزة. وفي هذه الأثناء يتوقف ما تفعله %2$s بهذا الملف.','the other plugin'=>'الإضافة الأخرى','Replace with WPOptimizing’s'=>'الاستبدال بملف WPOptimizing','You do not have permission to manage the object cache.'=>'ليست لديك صلاحية لإدارة تخزين الكائنات المؤقت.','The object cache template is missing from the plugin.'=>'قالب تخزين الكائنات المؤقت مفقود من الإضافة.','Could not write wp-content/object-cache.php. Check filesystem permissions.'=>'تعذّرت كتابة wp-content/object-cache.php. تحقّق من أذونات نظام الملفات.','Persistent object cache enabled.'=>'تم تفعيل التخزين المؤقت الدائم للكائنات.','The active object cache drop-in is not managed by WPOptimizing; it was left untouched.'=>'ملف drop-in تخزين الكائنات المؤقت النشط ليس مُدارًا بواسطة WPOptimizing؛ وقد تُرِك دون تغيير.','Persistent object cache disabled.'=>'تم تعطيل التخزين المؤقت الدائم للكائنات.','The query-deduplication template is missing from the plugin.'=>'قالب إزالة تكرار الاستعلامات مفقود من الإضافة.','Could not write wp-content/db.php. Check filesystem permissions.'=>'تعذّرت كتابة wp-content/db.php. تحقّق من أذونات نظام الملفات.','Query deduplication enabled.'=>'تم تفعيل إزالة تكرار الاستعلامات.','The active database drop-in is not managed by WPOptimizing; it was left untouched.'=>'drop-in قاعدة البيانات النشط ليس مُدارًا بواسطة WPOptimizing؛ وقد تُرِك دون تغيير.','Query deduplication disabled.'=>'تم تعطيل إزالة تكرار الاستعلامات.','Only a network administrator can flush the object cache: on a network it is shared by every site.'=>'يمكن لمدير الشبكة وحده إفراغ ذاكرة تخزين الكائنات: فهي مشتركة بين جميع المواقع في الشبكة.','Object cache flushed.'=>'تم إفراغ تخزين الكائنات المؤقت.','Could not flush the object cache.'=>'تعذّر إفراغ تخزين الكائنات المؤقت.','Cache settings saved.'=>'تم حفظ إعدادات التخزين المؤقت.','The Cloudflare token has been removed. Cloudflare is no longer purged.'=>'تمت إزالة رمز Cloudflare. لم يعد يتم مسح ذاكرة Cloudflare.','That is the Global API Key, not an API token. It opens your whole Cloudflare account, so it is not saved: create a token with only the Zone › Cache Purge › Purge permission (see “How to get them”).'=>'هذا هو Global API Key وليس رمز API. إنه يفتح حساب Cloudflare بالكامل، لذلك لا يُحفظ: أنشئ رمزًا بصلاحية المنطقة › مسح ذاكرة التخزين المؤقت › مسح فقط (انظر «كيفية الحصول عليهما»).','That is not a Cloudflare zone ID: it is a 32-character code shown on the zone\'s Overview page.'=>'هذا ليس معرّف منطقة Cloudflare: إنه رمز من 32 حرفًا يظهر في صفحة النظرة العامة للمنطقة.','Cloudflare settings saved. Add the zone ID and an API token to start purging.'=>'تم حفظ إعدادات Cloudflare. أضف معرّف المنطقة ورمز API لبدء المسح.','Cloudflare connected: the home page was purged as a test.'=>'تم الاتصال بـ Cloudflare: تم مسح الصفحة الرئيسية كاختبار.','Settings saved, but Cloudflare refused the test purge: %s'=>'تم حفظ الإعدادات، لكن Cloudflare رفض المسح التجريبي: %s','How to get them'=>'كيفية الحصول عليهما','Cloudflare: zone ID and API token'=>'Cloudflare: معرّف المنطقة ورمز API','Zone ID'=>'معرّف المنطقة','In Cloudflare, open your domain. On the Overview page, the “API” box on the right shows the Zone ID: copy it into the first field.'=>'في Cloudflare افتح نطاقك. في صفحة النظرة العامة، يعرض مربع «API» على اليمين معرّف المنطقة: انسخه في الحقل الأول.','API token'=>'رمز API','Go to My Profile › API Tokens › Create token, and choose “Create custom token”.'=>'انتقل إلى ملفي الشخصي › رموز API › إنشاء رمز، واختر «إنشاء رمز مخصص».','Under Permissions, one line:'=>'في الأذونات، سطر واحد:','Zone'=>'المنطقة','Cache Purge'=>'مسح ذاكرة التخزين المؤقت','Purge'=>'مسح','To also cache the pages at Cloudflare, a second line:'=>'لتخزين الصفحات مؤقتًا في Cloudflare أيضًا، سطر ثانٍ:','Cache Rules'=>'Cache Rules','Edit'=>'تحرير','Under Zone Resources:'=>'في موارد المنطقة:','Include'=>'تضمين','Specific zone'=>'منطقة محددة','Or “All zones” to use the same token on every site of the account: it can then purge any of them, and nothing else.'=>'أو «كل المناطق» لاستخدام الرمز نفسه في كل مواقع الحساب: سيتمكن حينها من مسح أي منها، ولا شيء غير ذلك.','Continue to summary › Create token. Cloudflare shows the token only once: paste it into the second field and save.'=>'المتابعة إلى الملخص › إنشاء الرمز. يعرض Cloudflare الرمز مرة واحدة فقط: الصقه في الحقل الثاني واحفظ.','Do not use the Global API Key: it opens your whole account, and WPOptimizing refuses it.'=>'لا تستخدم Global API Key: فهو يفتح حسابك بالكامل، وWPOptimizing يرفضه.','This site is served through Cloudflare and it is not being purged yet.'=>'يُقدَّم هذا الموقع عبر Cloudflare ولا يتم تفريغ ذاكرته المؤقتة بعد.','If your site is behind Cloudflare, WPOptimizing purges its cache too: everything when it flushes the other caches, and only the affected pages when content changes. It needs the zone ID and an API token.'=>'إذا كان موقعك خلف Cloudflare، يمسح WPOptimizing ذاكرته المؤقتة أيضًا: كلها عند تفريغ الذاكرات المؤقتة الأخرى، والصفحات المتأثرة فقط عند تغيّر المحتوى. يحتاج إلى معرّف المنطقة ورمز API.','Your domain’s Overview page, under “API” on the right.'=>'صفحة النظرة العامة لنطاقك، ضمن «API» على اليمين.','Saved — leave empty to keep it'=>'محفوظ — اتركه فارغًا للإبقاء عليه','An API token with the Zone › Cache Purge › Purge permission, not the Global API Key. Stored encrypted and never shown again.'=>'رمز API بصلاحية المنطقة › مسح ذاكرة التخزين المؤقت › مسح، وليس Global API Key. يُحفظ مشفرًا ولا يُعرض مجددًا.','When to purge'=>'متى يتم المسح','Purge everything when WPOptimizing flushes caches (after a cleanup and from “Flush all caches”)'=>'مسح كل شيء عندما يفرّغ WPOptimizing الذواكر (بعد التنظيف ومن «تفريغ كل الذواكر»)','Purge the affected pages when a post, page or comment changes'=>'مسح الصفحات المتأثرة عند تغيّر مقالة أو صفحة أو تعليق','everything'=>'كل شيء','Last purge'=>'آخر مسح','%1$s — %2$s, confirmed by Cloudflare'=>'%1$s — %2$s، أكّده Cloudflare','%1$s — failed: %2$s'=>'%1$s — فشل: %2$s','Cloudflare did not accept the credential. It must be an API token with the Zone › Cache Purge › Purge permission; the Global API Key does not work here.'=>'لم يقبل Cloudflare بيانات الاعتماد. يجب أن تكون رمز API بصلاحية المنطقة › مسح ذاكرة التخزين المؤقت › مسح؛ Global API Key لا يعمل هنا.','Save and test Cloudflare'=>'حفظ واختبار Cloudflare','Remove token'=>'إزالة الرمز','Cloudflare does not keep HTML by default. This adds a Cache Rule to your zone so it does, for anonymous visitors only, and each page tells the edge whether it may be kept: the pages the page cache would store, for as long as it would keep them. Logged-in users, carts, searches, 404s and any page that sets a cookie always reach your server. Your own cache rules are not touched. The token needs one more permission: Zone › Cache Rules › Edit.'=>'لا يحتفظ Cloudflare بـ HTML افتراضيًا. يضيف هذا إلى منطقتك قاعدة تخزين مؤقت ليفعل ذلك، للزوار المجهولين فقط، وكل صفحة تخبر الحافة إن كان يمكن الاحتفاظ بها: الصفحات التي كانت ذاكرة الصفحات المؤقتة ستخزنها، طوال المدة التي كانت ستحتفظ بها. المستخدمون المسجّلون وعربات التسوق وعمليات البحث وصفحات 404 وأي صفحة تضع ملف تعريف ارتباط تصل دائمًا إلى خادمك. لا تُمسّ قواعد التخزين المؤقت الخاصة بك. يحتاج الرمز إلى صلاحية إضافية: المنطقة › Cache Rules › تحرير.','Check now'=>'افحص الآن','Turn off and empty the edge'=>'إيقاف وتفريغ الحافة','Turn on and check it'=>'تشغيل والتحقق','The rule was removed and the edge emptied: %s'=>'أُزيلت القاعدة وأُفرغ التخزين على الحافة: %s','The check could not reach the site through Cloudflare from this server, so the rule was not left on: an untested rule is not worth the risk.'=>'لم يتمكن التحقق من الوصول إلى الموقع عبر Cloudflare من هذا الخادم، لذا لم تُترك القاعدة مفعّلة: قاعدة غير مختبرة لا تستحق المخاطرة.','Cloudflare served a cached page to a request with a session cookie or to the login page, so the rule was removed and the edge emptied. Nothing else was changed.'=>'قدّم Cloudflare صفحة مخزنة لطلب يحمل ملف تعريف ارتباط جلسة أو لصفحة الدخول، لذا أُزيلت القاعدة وفُرّغت الحافة. لم يُغيَّر شيء آخر.','Checked: the home page is served from Cloudflare\'s edge, and requests with a session cookie and the login page reach your server.'=>'تم التحقق: تُقدَّم الصفحة الرئيسية من حافة Cloudflare، والطلبات التي تحمل ملف تعريف ارتباط جلسة وصفحة الدخول تصل إلى خادمك.','Checked: requests with a session cookie and the login page reach your server, but the home page was not served from the edge yet. That is normal while it fills, and also when the page cache would not store the home page.'=>'تم التحقق: الطلبات التي تحمل ملف تعريف ارتباط جلسة وصفحة الدخول تصل إلى خادمك، لكن الصفحة الرئيسية لم تُقدَّم من الحافة بعد. هذا طبيعي أثناء امتلائها، وأيضًا عندما لا تخزن ذاكرة الصفحات المؤقتة الصفحة الرئيسية.','Turned off here, but Cloudflare refused to delete the rule: %s. Delete the WPOptimizing rule in Caching › Cache Rules.'=>'أُوقف هنا، لكن Cloudflare رفض حذف القاعدة: %s. احذف قاعدة WPOptimizing من التخزين المؤقت › Cache Rules.','Pages are no longer cached at Cloudflare: the rule was removed and the edge emptied.'=>'لم تعد الصفحات تُخزَّن مؤقتًا في Cloudflare: أُزيلت القاعدة وفُرّغت الحافة.','Cloudflare refused to create the rule: %s. The token needs the Zone › Cache Rules › Edit permission.'=>'رفض Cloudflare إنشاء القاعدة: %s. يحتاج الرمز إلى صلاحية المنطقة › Cache Rules › تحرير.','You do not have permission to manage the page cache.'=>'ليست لديك صلاحية إدارة ذاكرة تخزين الصفحات.','Page cache enabled.'=>'تم تفعيل ذاكرة تخزين الصفحات.','The page cache is not available on a multisite network: it cannot yet purge each site\'s pages separately.'=>'التخزين المؤقت للصفحات غير متاح في شبكة متعددة المواقع: لا يمكنه بعد مسح صفحات كل موقع على حدة.','An advanced-cache.php from another plugin is already active. WPOptimizing will not overwrite it.'=>'يوجد بالفعل advanced-cache.php من إضافة أخرى نشط. لن يستبدله WPOptimizing.','The other advanced-cache.php could not be copied aside, so it was left in place.'=>'تعذّر حفظ نسخة من ملف advanced-cache.php الآخر، لذا تُرك كما هو.','Another page cache is active (%s). Disable it before enabling ours.'=>'توجد ذاكرة تخزين صفحات أخرى نشطة (%s). عطّلها قبل تفعيل ذاكرتنا.','Could not edit wp-config.php to define WP_CACHE. Check file permissions.'=>'تعذّر تعديل wp-config.php لتعريف WP_CACHE. تحقق من صلاحيات الملف.','Could not install advanced-cache.php. Check wp-content permissions.'=>'تعذّر تثبيت advanced-cache.php. تحقق من صلاحيات wp-content.','Page cache disabled.'=>'تم تعطيل ذاكرة تخزين الصفحات.','Page cache cleared.'=>'تم إفراغ ذاكرة تخزين الصفحات.','You do not have permission to manage the browser cache.'=>'ليست لديك صلاحية إدارة ذاكرة تخزين المتصفح.','Browser cache and compression enabled.'=>'تم تفعيل ذاكرة تخزين المتصفح والضغط.','Browser cache and compression disabled.'=>'تم تعطيل ذاكرة تخزين المتصفح والضغط.','Could not write .htaccess. Check file permissions.'=>'تعذّرت الكتابة في .htaccess. تحقق من صلاحيات الملف.','Could not update .htaccess.'=>'تعذّر تحديث .htaccess.','No cache found in front of the site.'=>'لم يُعثر على أي ذاكرة تخزين مؤقت أمام الموقع.','Found in front of the site: %s.'=>'أمام الموقع: %s.','Page cache settings saved.'=>'حُفظت إعدادات ذاكرة التخزين المؤقت للصفحات.','%s page queued for preloading.' . "\0" . '%s pages queued for preloading.'=>'لا توجد صفحات (%s) في قائمة التحميل المسبق.' . "\0" . 'أُضيفت صفحة واحدة إلى قائمة التحميل المسبق.' . "\0" . 'أُضيفت صفحتان إلى قائمة التحميل المسبق.' . "\0" . 'أُضيفت %s صفحات إلى قائمة التحميل المسبق.' . "\0" . 'أُضيفت %s صفحة إلى قائمة التحميل المسبق.' . "\0" . 'أُضيفت %s صفحة إلى قائمة التحميل المسبق.','Speed up the admin and the front end with a persistent object cache and per-request query deduplication — safe, reversible and free. Full-page HTML caching is available too, but it is opt-in and off by default, so nothing ever serves a stale page unless you turn it on.'=>'سرّع لوحة التحكم والواجهة الأمامية بذاكرة كائنات دائمة وإزالة تكرار الاستعلامات لكل طلب — آمن وقابل للتراجع ومجاني. يتوفّر أيضاً تخزين HTML للصفحة كاملة، لكنه اختياري ومعطّل افتراضياً، فلا تُقدَّم صفحة قديمة أبداً ما لم تفعّله.','This site is served through Cloudflare, which keeps its own copy of your pages and files. Connect it so WPOptimizing purges it along with the other caches.'=>'يُقدَّم هذا الموقع عبر Cloudflare الذي يحتفظ بنسخته الخاصة من صفحاتك وملفاتك. اربطه ليقوم WPOptimizing بتفريغها مع ذاكرات التخزين المؤقت الأخرى.','Set up Cloudflare'=>'إعداد Cloudflare','A persistent object cache stores the results of expensive database queries in memory (or on disk). It uses your server cache (Redis or Memcached) when available, APCu if you choose it, and a self-contained SQLite store otherwise.'=>'يخزّن التخزين المؤقت الدائم للكائنات نتائج استعلامات قاعدة البيانات المكلفة في الذاكرة (أو على القرص). يستخدم تخزين خادومك المؤقت (Redis أو Memcached) عند توفّره، وAPCu إذا اخترته، وإلا فمخزن SQLite مستقل.','Not active'=>'غير نشط','Active backend'=>'الواجهة الخلفية النشطة','Available backends'=>'الواجهات الخلفية المتاحة','Hits / misses (this request)'=>'إصابات / إخفاقات (هذا الطلب)','%1$s hits · %2$s misses · %3$d%% hit rate'=>'%1$s إصابة · %2$s إخفاق · %3$d %% نسبة الإصابة','Detected page caches'=>'ذاكرات تخزين الصفحات المكتشفة','WPOptimizing detects your host or plugin page cache and purges it automatically after a cleanup (and from the toolbar “Flush all caches”), so visitors never see stale content. Its own page cache, in this tab, is optional and does not run alongside another one.'=>'يكتشف WPOptimizing ذاكرة تخزين الصفحات الخاصة باستضافتك أو إضافتك ويُفرّغها تلقائيًا بعد التنظيف (ومن زر «إفراغ كل ذاكرات التخزين المؤقت» في شريط الأدوات)، حتى لا يرى الزوار محتوى قديمًا أبدًا. أما ذاكرة تخزين الصفحات الخاصة به، في هذا التبويب، فهي اختيارية ولا تعمل مع ذاكرة أخرى في الوقت نفسه.','Integration'=>'التكامل','Auto-purges on changes'=>'تُفرَّغ تلقائيًا عند التغييرات','Purged after cleanup and from the toolbar'=>'تُفرَّغ بعد التنظيف ومن شريط الأدوات','A newer version of the object cache drop-in is available. Update to get the latest fixes and backends.'=>'تتوفّر نسخة أحدث من drop-in تخزين الكائنات المؤقت. حدّث للحصول على أحدث الإصلاحات والواجهات الخلفية.','Only a network administrator can enable or disable the object cache on this multisite network.'=>'يمكن لمدير الشبكة وحده تفعيل أو تعطيل تخزين الكائنات المؤقت على شبكة المواقع المتعددة هذه.','Update drop-in'=>'تحديث الـ drop-in','Disable object cache'=>'تعطيل تخزين الكائنات المؤقت','Flush cache now'=>'إفراغ التخزين المؤقت الآن','Enable object cache'=>'تفعيل تخزين الكائنات المؤقت','Serves a static HTML copy of each page to anonymous visitors, so most requests never boot WordPress — the single biggest speed win. Opt-in and off by default: logged-in users, carts, checkout, admin, feeds and any dynamic request are never cached, and the cache is purged automatically whenever content changes.'=>'يقدّم نسخة HTML ثابتة من كل صفحة للزوّار المجهولين، فلا تُشغّل معظم الطلبات ووردبريس إطلاقاً — وهو أكبر مكسب في السرعة. اختياري ومعطّل افتراضياً: لا تُخزَّن مطلقاً صفحات المستخدمين المسجَّلين ولا السلّة ولا الدفع ولا لوحة التحكم ولا الخلاصات ولا أي طلب ديناميكي، وتُفرَّغ الذاكرة تلقائياً عند تغيّر المحتوى.','WP_CACHE constant'=>'ثابت WP_CACHE','Defined'=>'مُعرَّف','Not defined'=>'غير مُعرَّف','Another page cache is active: %s. Disable it before enabling ours to avoid two caches fighting over the same page.'=>'توجد ذاكرة تخزين صفحات أخرى نشطة: %s. عطّلها قبل تفعيل ذاكرتنا لتجنّب تنازع ذاكرتين على الصفحة نفسها.','Only a network administrator can manage the page cache on this multisite network.'=>'يمكن لمدير الشبكة فقط إدارة ذاكرة تخزين الصفحات في هذه الشبكة متعددة المواقع.','Disable page cache'=>'تعطيل ذاكرة تخزين الصفحات','Clear page cache now'=>'إفراغ ذاكرة تخزين الصفحات الآن','Enable page cache'=>'تفعيل ذاكرة تخزين الصفحات','Rebuilds the cached pages in the background after they are cleared, so the next visitor gets the fast copy instead of waiting for WordPress. It visits a few pages at a time and waits while the server is busy.'=>'يعيد بناء الصفحات المخزنة مؤقتًا في الخلفية بعد مسحها، ليحصل الزائر التالي على النسخة السريعة بدل انتظار ووردبريس. يزور بضع صفحات في كل مرة وينتظر ما دام الخادم مشغولًا.','Pages waiting'=>'صفحات في الانتظار','Last run'=>'آخر تشغيل','%1$s (%2$s page)' . "\0" . '%1$s (%2$s pages)'=>'%1$s (%2$s صفحة)' . "\0" . '%1$s (صفحة واحدة)' . "\0" . '%1$s (صفحتان)' . "\0" . '%1$s (%2$s صفحات)' . "\0" . '%1$s (%2$s صفحة)' . "\0" . '%1$s (%2$s صفحة)','Rebuild pages automatically after they are cleared'=>'أعد بناء الصفحات تلقائيًا بعد مسحها','Preload now'=>'حمّل مسبقًا الآن','Extra rules on top of the automatic ones (which can never be removed). One entry per line.'=>'قواعد إضافية فوق التلقائية (التي لا يمكن إزالتها أبداً). إدخال واحد لكل سطر.','Never cache these URL paths'=>'لا تُخزّن هذه مسارات الروابط أبداً','e.g. /my-dynamic-page/'=>'مثال: /my-dynamic-page/','Never cache when these cookies are present'=>'لا تُخزّن أبداً عند وجود هذه الكوكيز','cookie name fragment, e.g. my_membership_'=>'جزء من اسم الكوكي، مثال: my_membership_','Still cache with these query parameters'=>'خزّن رغم وجود معاملات الاستعلام هذه','parameter name, e.g. currency'=>'اسم المعامل، مثال: currency','Mobile devices'=>'الأجهزة المحمولة','Turn this on only if your theme shows phones a different page, for example another menu or fewer sections. Pages are then cached twice, once for phones and once for computers.'=>'فعّل هذا فقط إذا كان قالبك يعرض على الهواتف صفحة مختلفة، مثل قائمة أخرى أو أقسام أقل. عندها تُخزَّن الصفحات مرتين: مرة للهواتف ومرة للحواسيب.','Separate cache for mobile devices'=>'ذاكرة تخزين مؤقت منفصلة للأجهزة المحمولة','Save settings'=>'حفظ الإعدادات','Custom page-cache exclusions (URLs, cookies and query strings) and a separate cache for mobile devices are not included in this plugin.'=>'استثناءات ذاكرة التخزين المؤقت للصفحات المخصصة (عناوين URL وملفات تعريف الارتباط ومعاملات الاستعلام) وذاكرة تخزين مؤقت منفصلة للأجهزة المحمولة غير مضمّنة في هذه الإضافة.','Pro adds custom exclusions (URLs, cookies and query strings) and a separate cache for mobile devices.'=>'تضيف النسخة Pro استثناءات مخصصة (عناوين URL وملفات تعريف الارتباط ومعاملات الاستعلام) وذاكرة تخزين مؤقت منفصلة للأجهزة المحمولة.','The caches outside WordPress: the ones your host or CDN keeps in front of the site, and the copies of your files that visitors’ browsers keep.'=>'ذاكرات التخزين خارج ووردبريس: التي يحتفظ بها مستضيفك أو شبكة CDN أمام الموقع، ونسخ ملفاتك التي تحتفظ بها متصفحات الزوار.','Your host or CDN may keep its own copy of each page, which a WordPress plugin cannot see from the inside. This asks for your home page as a visitor and reads what each layer says about itself.'=>'قد تحتفظ الاستضافة أو شبكة CDN بنسختها الخاصة من كل صفحة، ولا يراها إضافة ووردبريس من الداخل. يطلب هذا الفحص صفحتك الرئيسية كزائر ويقرأ ما تقوله كل طبقة عن نفسها.','No cache in front of the site: every visit reaches your server.'=>'لا توجد ذاكرة تخزين مؤقت أمام الموقع: كل زيارة تصل إلى خادمك.','Present'=>'موجودة','Serving from its cache'=>'تقدّم من ذاكرتها المؤقتة','Present, not serving this page from cache'=>'موجودة، لكنها لا تقدّم هذه الصفحة من الذاكرة المؤقتة','Checked %s ago.'=>'فُحص منذ %s.','Varnish is purged by Proxy Cache Purge, so WPOptimizing leaves it to it.'=>'يتولى Proxy Cache Purge مسح Varnish، لذا يتركه WPOptimizing له.','Purge Varnish when content changes and when all caches are flushed'=>'امسح Varnish عند تغيّر المحتوى وعند مسح كل ذاكرات التخزين المؤقت','Sends PURGE requests for the pages a change makes stale. Varnish only accepts them when its configuration allows PURGE from this server, which hosts that run Varnish usually set up.'=>'يرسل طلبات PURGE للصفحات التي يجعلها التغيير قديمة. لا يقبلها Varnish إلا إذا سمحت إعداداته بـ PURGE من هذا الخادم، وهو ما تجهّزه عادةً الاستضافات التي تستخدم Varnish.','Check again'=>'افحص مجددًا','Tells returning visitors’ browsers to reuse your CSS, JS, images and fonts instead of re-downloading them, and serves everything GZIP/Brotli-compressed. Adds a managed, reversible block to .htaccess (Apache/LiteSpeed).'=>'يوجّه متصفحات الزوّار العائدين لإعادة استخدام ملفات CSS وJS والصور والخطوط بدل تنزيلها من جديد، ويقدّم كل شيء مضغوطاً بصيغة GZIP/Brotli. يضيف إلى .htaccess كتلة مُدارة وقابلة للتراجع (Apache/LiteSpeed).','Your server does not use .htaccess (e.g. Nginx). Add equivalent expires and gzip rules to your server config instead.'=>'لا يستخدم خادمك .htaccess (مثل Nginx). أضِف بدلاً من ذلك قواعد expires وgzip مكافئة في إعدادات الخادم.','Disable browser cache'=>'تعطيل ذاكرة تخزين المتصفح','Enable browser cache & compression'=>'تفعيل ذاكرة تخزين المتصفح والضغط','Cache analytics'=>'تحليلات التخزين المؤقت','Hit/miss ratio, query metrics and the most-duplicated queries, aggregated per day over the last 30 days.'=>'نسبة الإصابة/الإخفاق، ومقاييس الاستعلامات، وأكثر الاستعلامات تكرارًا، مجمّعة يوميًا خلال آخر 30 يومًا.','No analytics yet — figures appear after some traffic flows through the cache.'=>'لا توجد تحليلات بعد — تظهر الأرقام بعد مرور بعض الزيارات عبر التخزين المؤقت.','Overall hit rate'=>'نسبة الإصابة الإجمالية','Improvable'=>'قابل للتحسين','High'=>'مرتفع','Time WordPress takes to start sending the page — the server share of TTFB (not the visitor network).'=>'الوقت الذي يستغرقه ووردبريس لبدء إرسال الصفحة — حصة الخادم من زمن أول بايت (دون شبكة الزائر).','Open the Performance report'=>'فتح تقرير الأداء','Requests sampled'=>'الطلبات المأخوذة كعيّنة','Total hits / misses'=>'إجمالي الإصابات / الإخفاقات','Duplicate queries avoided'=>'الاستعلامات المكرّرة المتجنَّبة','%1$s of %2$s read queries'=>'%1$s من %2$s استعلامات قراءة','Read queries by type'=>'استعلامات القراءة حسب النوع','Slow queries (>50 ms)'=>'استعلامات بطيئة (>50 مللي ثانية)','Total query time'=>'إجمالي وقت الاستعلامات','%s s'=>'%s ث','Duplicate queries by source'=>'الاستعلامات المكرّرة حسب المصدر','Source'=>'المصدر','Per-day trend'=>'الاتجاه اليومي','Requests'=>'الطلبات','Installs a db.php drop-in that returns the cached result of identical read queries within the same request (admin and front end), so the same query never hits MySQL twice. Any write clears it immediately, so results are never stale.'=>'يُثبّت drop-in من نوع db.php يعيد النتيجة المخزّنة مؤقتًا لاستعلامات القراءة المتطابقة ضمن الطلب نفسه (لوحة التحكم والواجهة الأمامية)، فلا يصل الاستعلام نفسه إلى MySQL مرتين. تمسحه أي عملية كتابة فورًا، لذا لا تكون النتائج قديمة أبدًا.','Only a network administrator can manage this on a multisite network.'=>'يمكن لمدير الشبكة وحده إدارة هذا على شبكة مواقع متعددة.','Query deduplication is active.'=>'إزالة تكرار الاستعلامات نشطة.','Disable query deduplication'=>'تعطيل إزالة تكرار الاستعلامات','Enable query deduplication'=>'تفعيل إزالة تكرار الاستعلامات','Most duplicated queries'=>'أكثر الاستعلامات تكرارًا','“Times” is the highest number of times a single page load repeated the exact same read (deduplication collapses them to one hit on MySQL). It is a rolling peak recorded over time, not a fixed window. “Source” is the plugin, theme or WordPress core that fired the query.'=>'«مرات» هو أعلى عدد كرّرت فيه صفحة واحدة القراءة نفسها (تدمج إزالة التكرار هذه في وصول واحد إلى MySQL). إنه ذروة متراكمة عبر الزمن، وليست نافذة زمنية ثابتة. «المصدر» هو الإضافة أو القالب أو نواة ووردبريس التي أطلقت الاستعلام.','Times'=>'مرّات','Query'=>'استعلام','Cache settings'=>'إعدادات التخزين المؤقت','Choose the cache backend (and the Redis/Memcached connection), plus safe admin-side optimizations.'=>'اختر الواجهة الخلفية للتخزين المؤقت (واتصال Redis/Memcached)، إضافةً إلى تحسينات آمنة للوحة التحكم.','Backend'=>'الواجهة الخلفية','Auto picks the fastest available backend: Redis, then Memcached, then SQLite. APCu is only used when chosen here, and never from WP-CLI or a system cron, which cannot see its memory.'=>'يختار «تلقائي» أسرع واجهة خلفية متاحة: Redis، ثم Memcached، ثم SQLite. لا يُستخدم APCu إلا إذا اخترته هنا، ولا يُستخدم أبدًا من WP-CLI أو من cron النظام، لأنهما لا يريان ذاكرته.','Auto (recommended)'=>'تلقائي (مُوصى به)','not available'=>'غير متاح','Redis host / port'=>'مضيف / منفذ Redis','Redis password'=>'كلمة مرور Redis','Redis database'=>'قاعدة بيانات Redis','Numeric index (0–255). Leave 0 unless your Redis uses a dedicated database.'=>'فهرس رقمي (0–255). اترك 0 ما لم يكن Redis لديك يستخدم قاعدة بيانات مخصّصة.','Memcached host / port'=>'مضيف / منفذ Memcached','Admin optimizations'=>'تحسينات لوحة التحكم','Safe admin-side speedups. These never cache full admin pages (which would break security tokens).'=>'تسريعات آمنة للوحة التحكم. لا تخزّن أبدًا صفحات لوحة التحكم كاملة (سيكسر ذلك رموز الأمان).','Cache dashboard comment counts (At a Glance / menu bubble). Refreshed instantly when comments change.'=>'تخزين عدّادات التعليقات في لوحة التحكم مؤقتًا (لمحة سريعة / فقاعة القائمة). تُحدَّث فورًا عند تغيّر التعليقات.','Heartbeat (admin background polling):'=>'Heartbeat (الاستطلاع في خلفية لوحة التحكم):','Default'=>'افتراضي','Slow (every 60 s)'=>'بطيء (كل 60 ث)','Off outside the editor'=>'إيقاف خارج المحرر','Heartbeat powers autosave and edit locks via admin-ajax.php. Slowing it reduces server load; turning it off stops it everywhere except the editor, where autosave and edit locks keep working.'=>'يتولى Heartbeat الحفظ التلقائي وأقفال التحرير عبر admin-ajax.php. يقلّل إبطاؤه حمل الخادم؛ أما إيقافه فيوقفه في كل مكان باستثناء المحرر، حيث يستمر الحفظ التلقائي وأقفال التحرير في العمل.','Save cache settings'=>'حفظ إعدادات التخزين المؤقت','Must-use plugin'=>'إضافة must-use','Plugin: %s'=>'إضافة: %s','Theme: %s'=>'قالب: %s','None (per-request only)'=>'لا شيء (لكل طلب فقط)','installed'=>'مثبّت','Use “%s” as a plugin slug'=>'استخدم «%s» كـ slug للإضافة','Use “%s” as a theme slug'=>'استخدم «%s» كـ slug للقالب','Tell WPOptimizing who really owns an item when the automatic attribution is wrong or missing. Use “contains” for a family of items (e.g. wysija → MailPoet) or “exact” for one specific value, and pick one or more owners (e.g. MailPoet and MailPoet Premium). Your rule takes priority and the item moves to In use, Inactive or Orphans by whether the owner is installed.'=>'أخبر WPOptimizing بالمالك الحقيقي لعنصر ما عندما تكون النسبة التلقائية خاطئة أو مفقودة. استخدم «يحتوي» لمجموعة من العناصر (مثل wysija ← MailPoet) أو «مطابق تمامًا» لقيمة محددة، واختر مالكًا واحدًا أو أكثر (مثل MailPoet وMailPoet Premium). قاعدتك لها الأولوية وينتقل العنصر إلى قيد الاستخدام أو غير النشطة أو اليتيمة حسب ما إذا كان المالك مثبتًا.','Selected rows'=>'الصفوف المحددة','Clear'=>'مسح','These rows will be attributed (exact) to the owner(s) you pick below.'=>'ستُسنَد هذه الصفوف (بدقّة) إلى المالك/المالكين الذي تختاره أدناه.','Match type'=>'نوع المطابقة','Contains'=>'يحتوي','Exact value'=>'قيمة مطابقة','Text to match'=>'النص المطلوب مطابقته','text to match (e.g. wysija)'=>'النص المراد مطابقته (مثل wysija)','Owner(s): search installed, wp.org or KB — or type a slug'=>'المالك/المالكون: ابحث في المثبَّتة أو wp.org أو قاعدة المعرفة — أو اكتب slug','Owners'=>'المالكون','Type for a typed owner'=>'نوع المالك المُدخَل يدويًا','Add rule'=>'إضافة قاعدة','All owners'=>'كل المالكين','Select at least one row first.'=>'حدد صفًا واحدًا على الأقل أولًا.','Pick at least one row or type a value to match first.'=>'اختر صفًا واحدًا على الأقل أو اكتب قيمة للمطابقة أولًا.','Choose at least one owner for the rule.'=>'اختر مالكًا واحدًا على الأقل للقاعدة.','Attribution rule removed; the affected items were re-evaluated.'=>'حُذفت قاعدة الإسناد؛ أُعيد تقييم العناصر المتأثرة.','That attribution rule no longer exists; nothing was removed.'=>'قاعدة الإسناد هذه لم تعد موجودة؛ لم يُحذف أي شيء.','%s manual attribution saved; the affected items were re-attributed.' . "\0" . '%s manual attributions saved; the affected items were re-attributed.'=>'%s إسناد يدوي محفوظ؛ أُعيد إسناد العناصر المتأثرة.' . "\0" . 'إسناد يدوي واحد محفوظ؛ أُعيد إسناد العناصر المتأثرة.' . "\0" . 'إسنادان يدويان محفوظان؛ أُعيد إسناد العناصر المتأثرة.' . "\0" . '%s إسنادات يدوية محفوظة؛ أُعيد إسناد العناصر المتأثرة.' . "\0" . '%s إسنادًا يدويًا محفوظًا؛ أُعيد إسناد العناصر المتأثرة.' . "\0" . '%s إسناد يدوي محفوظ؛ أُعيد إسناد العناصر المتأثرة.','Sharing is off, so this hint stays on your site. Turn on data sharing to improve automatic attribution for everyone — and receive the shared dataset in return.'=>'المشاركة مُعطَّلة، لذا تبقى هذه الملاحظة على موقعك. فعِّل مشاركة البيانات لتحسين الإسناد التلقائي للجميع — وتستقبل في المقابل مجموعة البيانات المشتركة.','No rules were added. Provide a value to match and at least one owner, and check the rule does not already exist.'=>'لم تُضَف أي قواعد. حدّد قيمة للمطابقة ومالكًا واحدًا على الأقل، وتأكد من أن القاعدة غير موجودة بالفعل.','These database entries could not be attributed to any installed or known extension. They may belong to a plugin not yet in the manifest database. Review them manually before taking any action.'=>'لم يتمكن النظام من نسب هذه الإدخالات في قاعدة البيانات إلى أي إضافة مثبتة أو معروفة. قد تنتمي إلى إضافة غير موجودة بعد في قاعدة بيانات المانيفست. راجعها يدوياً قبل اتخاذ أي إجراء.','No unattributed records — everything WPOptimizing found is confidently attributed to an extension or to WordPress core.'=>'لا سجلات غير منسوبة — كل ما وجده WPOptimizing منسوب بثقة إلى إضافة أو إلى نواة ووردبريس.','These files could not be attributed to any installed or known extension. They may belong to a plugin not yet in the manifest database. Review them manually before taking any action.'=>'لم يتمكن النظام من نسب هذه الملفات إلى أي إضافة مثبتة أو معروفة. قد تنتمي إلى إضافة غير موجودة بعد في قاعدة بيانات المانيفست. راجعها يدوياً قبل اتخاذ أي إجراء.','Database entries whose stored value is empty (NULL, an empty string, or an empty serialized/JSON structure). A grouped meta key is listed only when EVERY one of its records is empty, never when only some are. The Status column shows whether each one is To identify, Orphan, Inactive or In use. Records owned by an active extension or by WordPress core are read-only: they may be empty on purpose.'=>'إدخالات قاعدة البيانات التي تكون قيمتها المخزَّنة فارغة (NULL أو سلسلة فارغة أو بنية متسلسلة/JSON فارغة). لا يظهر مفتاح البيانات المجمَّع إلا عندما تكون كل سجلاته فارغة، ولا يظهر أبدًا عندما يكون بعضها فقط فارغًا. يوضّح عمود الحالة ما إذا كان كل سجل قيد التحديد أو يتيمًا أو غير نشط أو قيد الاستخدام. سجلات إضافة نشطة أو نواة ووردبريس للقراءة فقط: قد تكون فارغة عن قصد.','No empty records were found. Re-run the analysis after making changes to refresh this list.'=>'لم يُعثر على سجلات فارغة. أعد تشغيل التحليل بعد إجراء تغييرات لتحديث هذه القائمة.','Auto-drafts & trashed posts'=>'المسودات التلقائية والمقالات في سلة المهملات','Spam/trashed/other comments'=>'تعليقات السبام/المهملات/أخرى','Transients'=>'المؤقتات','oEmbed caches'=>'ذاكرات oEmbed المؤقتة','Unused tags'=>'الوسوم غير المستخدمة','Orphaned elements'=>'عناصر يتيمة','Duplicate metadata'=>'بيانات وصفية مكرّرة','Action Scheduler logs'=>'سجلات Action Scheduler','Some of these counts did not finish (they took too long or the database returned an error), so the estimate is incomplete and the real figures may be higher. Preview the cleanup again later.'=>'لم يكتمل بعض هذه الإحصاءات (استغرقت وقتًا طويلًا أو أعادت قاعدة البيانات خطأً)، لذا فالتقدير غير مكتمل وقد تكون الأرقام الفعلية أعلى. اطلب المعاينة مرة أخرى لاحقًا.','Run a quick database maintenance pass: revisions, drafts/trash, comment cleanup, transients, and optional table optimization.'=>'قم بتشغيل مرور صيانة سريع لقاعدة البيانات: المراجعات، المسودات/المحذوفات، تنظيف التعليقات، المؤقتات، وتحسين الجداول اختيارياً.','Run cleanup'=>'تشغيل التنظيف','Last run: %s'=>'آخر تشغيل: %s','Run the cleanup now with your current settings. The cards below show the cumulative totals across all runs and your active configuration.'=>'شغّل التنظيف الآن بإعداداتك الحالية. تعرض البطاقات أدناه الإجماليات التراكمية لكل عمليات التشغيل وتكوينك النشط.','Yes'=>'نعم','No'=>'لا','Cleanup totals (all runs)'=>'إجماليات التنظيف (جميع الأعمال)','Times run'=>'مرات التشغيل','Revisions removed'=>'المراجعات المحذوفة','Posts removed'=>'المقالات المحذوفة','Comments removed'=>'التعليقات المحذوفة','Transients removed'=>'المؤقتات المحذوفة','oEmbed cache rows removed'=>'صفوف ذاكرة oEmbed المحذوفة','Unused tags removed'=>'الوسوم غير المستخدمة المحذوفة','Orphan rows removed'=>'الصفوف المعزولة المحذوفة','Tables optimized'=>'الجداول المحسّنة','DB size (before)'=>'حجم قاعدة البيانات (قبل)','DB size (after)'=>'حجم قاعدة البيانات (بعد)','Estimated freed'=>'المساحة المقدّرة المحررة','Configure in %s.'=>'قم بالإعداد في %s.','Max revision age (days)'=>'أقصى عمر للمراجعة (أيام)','Auto-drafts to keep'=>'المسودات التلقائية للاحتفاظ بها','Max auto-draft age (days)'=>'الحد الأقصى لعمر المسودات التلقائية (أيام)','Remove auto-drafts'=>'إزالة المسودات التلقائية','Remove trashed posts'=>'إزالة المقالات في سلة المهملات','Remove spam comments'=>'إزالة التعليقات المزعجة','Remove trashed comments'=>'إزالة التعليقات في سلة المهملات','Remove unapproved comments'=>'إزالة التعليقات غير المعتمدة','Delete pingbacks'=>'حذف التنبيهات الآلية','Delete trackbacks'=>'حذف التتبع الخلفي','Delete all transients, including those that have not expired yet'=>'حذف جميع Transients، بما فيها التي لم تنتهِ صلاحيتها بعد','Delete oEmbed cache'=>'حذف ذاكرة تخزين oEmbed المؤقتة','Delete unused tags'=>'حذف الوسوم غير المستخدمة','Delete orphan elements'=>'حذف العناصر اليتيمة','Delete duplicate metadata'=>'حذف البيانات الوصفية المكرّرة','Delete finished Action Scheduler logs'=>'حذف سجلات Action Scheduler المنتهية','Expired WooCommerce sessions'=>'جلسات WooCommerce المنتهية','Orphaned product variations'=>'تنويعات المنتج اليتيمة','Optimize database tables'=>'تحسين جداول قاعدة البيانات','Preview — nothing has been deleted.'=>'معاينة — لم يُحذف أي شيء.','About %s records would be removed with the current settings (estimate).'=>'ستتم إزالة نحو %s سجل بالإعدادات الحالية (تقدير).','With your current settings, a cleanup would remove about:'=>'بإعداداتك الحالية، سيزيل التنظيف نحو:','About %s records in total (estimate). Nothing is deleted until you run the cleanup, and everything it deletes is backed up first and can be restored from Backups.'=>'نحو %s سجل إجمالًا (تقدير). لا يُحذف شيء حتى تُشغّل التنظيف، وكل ما يحذفه يُنسخ احتياطيًا أولًا ويمكن استعادته من النسخ الاحتياطية.','Nothing to remove with the current settings.'=>'لا شيء لإزالته بالإعدادات الحالية.','Tip: use Preview (dry run) first to see exactly what would be removed. Like every other deletion, the general cleanup backs up what it removes first (listed under Backups).'=>'نصيحة: استخدم «معاينة (تشغيل تجريبي)» أولًا لترى بالضبط ما سيُزال. وكأي عملية حذف أخرى، ينسخ التنظيف العام ما يزيله احتياطيًا أولًا (يظهر في النسخ الاحتياطية).','Run the general cleanup now? About %s records will be removed. They are backed up first and can be restored from Backups.'=>'هل تريد تشغيل التنظيف العام الآن؟ سيُحذف نحو %s سجل. تُنسخ احتياطيًا أولًا ويمكن استعادتها من النسخ الاحتياطية.','Run the general cleanup now? What it removes is backed up first and can be restored from Backups.'=>'هل تريد تشغيل التنظيف العام الآن؟ ما يزيله يُنسخ احتياطيًا أولًا ويمكن استعادته من النسخ الاحتياطية.','Review the last cleanup run and the history of saved reports — view them on screen or download them.'=>'راجع آخر عملية تنظيف وسجل التقارير المحفوظة — اعرضها على الشاشة أو نزّلها.','No cleanup logs yet. Run a general cleanup to generate your first report.'=>'لا توجد سجلات تنظيف بعد. شغّل تنظيفًا عامًا لإنشاء تقريرك الأول.','Last run summary'=>'ملخص آخر تشغيل','oEmbed cache rows'=>'صفوف ذاكرة oEmbed','Cleanup report'=>'تقرير التنظيف','Detailed event lines are included only when "Generate detailed log" is enabled.'=>'يتم تضمين سطور الأحداث التفصيلية فقط عند تفعيل "إنشاء سجل تفصيلي".','Status: %s'=>'الحالة: %s','Started: %s'=>'بدأ: %s','Finished: %s'=>'انتهى: %s','Duration: %d ms'=>'المدة: %d مللي ثانية','Detailed log (%d events)'=>'سجل مفصّل (%d أحداث)','Download report'=>'تنزيل التقرير','Cleanup logs'=>'سجلات التنظيف','Select a previous report to view it on screen or download it.'=>'اختر تقريرًا سابقًا لعرضه على الشاشة أو تنزيله.','View log'=>'عرض السجل','Download log'=>'تنزيل السجل','Report (PDF)'=>'تقرير (PDF)','Content by type'=>'المحتوى حسب النوع','Where your database weight sits, grouped by post type: live entries, revisions, auto-drafts and attached metadata rows. Read-only — nothing is deleted here.'=>'أين يتركّز حجم قاعدة بياناتك، مُجمّعًا حسب نوع المحتوى: العناصر النشطة والمراجعات والمسودات التلقائية وصفوف البيانات الوصفية المرتبطة. للقراءة فقط — لا يُحذف أي شيء هنا.','No content found.'=>'لم يتم العثور على محتوى.','Content type'=>'نوع المحتوى','Entries'=>'العناصر','Revisions'=>'المراجعات','Auto-drafts'=>'المسودات التلقائية','Metadata rows'=>'صفوف البيانات الوصفية','Revisions and auto-drafts are attributed to their real content type. Use the per-post “Keep all revisions” option in the editor to protect specific entries.'=>'تُنسب المراجعات والمسودات التلقائية إلى نوع المحتوى الفعلي الخاص بها. استخدم خيار «الاحتفاظ بجميع المراجعات» لكل مقالة في المحرر لحماية عناصر محددة.','Metadata totals are omitted on very large databases to keep this page fast.'=>'تُحذف إجماليات البيانات الوصفية في قواعد البيانات الكبيرة جدًا للحفاظ على سرعة هذه الصفحة.','Completed'=>'مكتمل','Partial'=>'جزئي','Failed'=>'فشل','Running'=>'قيد التشغيل','Locked'=>'مقفل','Retry scheduled'=>'إعادة المحاولة مجدولة','Stopped: backup failed'=>'متوقف: فشل النسخ الاحتياطي','Nothing was deleted: a backup could not be created (check disk space and folder permissions). Please try again.'=>'لم يُحذف أي شيء: تعذّر إنشاء نسخة احتياطية (تحقّق من مساحة القرص وأذونات المجلدات). يُرجى المحاولة مرة أخرى.','WordPress scheduled tasks. An event whose hook has no registered callback is likely orphaned (left by an uninstalled plugin) and will never run — safe to remove. Active and WordPress-core events are protected.'=>'المهام المجدولة في ووردبريس. الحدث الذي لا يملك خطّافه أي ردّ نداء مُسجَّل يُرجَّح أنه يتيم (تركه إضافة أُلغي تثبيتها) ولن يُنفَّذ أبدًا — وإزالته آمنة. الأحداث النشطة وأحداث نواة ووردبريس محمية.','%d scheduled event looks orphaned (its hook has no callback).' . "\0" . '%d scheduled events look orphaned (their hooks have no callback).'=>'%d حدث مجدول تبدو يتيمة (خطافاتها لا تحتوي على استدعاء راجع).' . "\0" . 'حدث مجدول واحد يبدو يتيماً (خطافه لا يحتوي على استدعاء راجع).' . "\0" . 'حدثان مجدولان يبدوان يتيمَين (خطافاهما لا يحتويان على استدعاء راجع).' . "\0" . '%d أحداث مجدولة تبدو يتيمة (خطافاتها لا تحتوي على استدعاء راجع).' . "\0" . '%d حدثاً مجدولاً تبدو يتيمة (خطافاتها لا تحتوي على استدعاء راجع).' . "\0" . '%d حدث مجدول تبدو يتيمة (خطافاتها لا تحتوي على استدعاء راجع).','Search hooks'=>'البحث في الخطّافات','Unschedule all'=>'إلغاء جدولة الكل','Only orphaned events (a hook with no callback) can be removed; active and WordPress-core events are protected.'=>'يمكن إزالة الأحداث اليتيمة فقط (خطّاف بلا ردّ نداء)؛ أما الأحداث النشطة وأحداث نواة ووردبريس فمحمية.','Unschedule the %d selected orphaned event(s)?'=>'إلغاء جدولة الأحداث اليتيمة المحددة البالغ عددها %d؟','Unschedule ALL %d filtered orphaned event(s)?'=>'إلغاء جدولة كل الأحداث اليتيمة المُرشَّحة البالغ عددها %d؟','An event that is long overdue means nothing is firing WP-Cron, and every task behind it — updates, emails, cleanups, scheduled posts — is silently not happening.'=>'الحدث المتأخر كثيرًا يعني أن لا شيء يشغّل WP-Cron، وأن كل المهام المعتمدة عليه — التحديثات والرسائل والتنظيف والمقالات المجدولة — لا تُنفَّذ دون أن يلاحظ أحد.','Running on time'=>'في الموعد','No scheduled event is more than 10 minutes late.'=>'لا يوجد حدث مجدول متأخر أكثر من 10 دقائق.','Tasks overdue'=>'مهام متأخرة','%1$d event is overdue; the oldest by %2$s.' . "\0" . '%1$d events are overdue; the oldest by %2$s.'=>'%1$d حدث متأخر؛ الأقدم متأخر %2$s.' . "\0" . 'حدث واحد متأخر؛ متأخر %2$s.' . "\0" . 'حدثان متأخران؛ الأقدم متأخر %2$s.' . "\0" . '%1$d أحداث متأخرة؛ الأقدم متأخر %2$s.' . "\0" . '%1$d حدثًا متأخرًا؛ الأقدم متأخر %2$s.' . "\0" . '%1$d حدث متأخر؛ الأقدم متأخر %2$s.','WP-Cron is disabled, so a server cron has to call wp-cron.php: check that the crontab line above is in place and running.'=>'WP-Cron معطّل، لذا يجب أن يستدعي cron الخادم الملف wp-cron.php: تحقق من أن سطر crontab أعلاه مضاف ويعمل.','WP-Cron only runs when someone visits the site, and some hosts block the request it makes to itself. On a quiet site, switch to a server cron with the panel above.'=>'لا يعمل WP-Cron إلا عندما يزور أحدٌ الموقع، وبعض الاستضافات تحجب الطلب الذي يرسله إلى نفسه. في موقع قليل الزيارات، انتقل إلى cron الخادم من اللوحة أعلاه.','That scheduled event no longer exists or has no callback.'=>'ذلك الحدث المجدول لم يعد موجودًا أو ليس له رد نداء.','%s will run in a moment, in the background.'=>'سيُشغَّل %s بعد لحظات في الخلفية.','%s could not be queued (it may be paused).'=>'تعذّر وضع %s في الطابور (ربما هو موقوف مؤقتًا).','WordPress core tasks cannot be paused.'=>'لا يمكن إيقاف مهام نواة ووردبريس مؤقتًا.','%s is paused: it stays scheduled but does nothing until you resume it.'=>'%s موقوف مؤقتًا: يبقى مجدولًا لكنه لا يفعل شيئًا حتى تستأنفه.','%s resumed.'=>'استُؤنف %s.','By default WordPress runs scheduled tasks on visitor page loads: this adds latency to random requests and misses tasks on low-traffic sites. Disable WP-Cron and drive it from a real server cron instead for faster page loads and dependable scheduling.'=>'بشكل افتراضي، يقوم ووردبريس بتشغيل المهام المجدولة عند تحميل الصفحات من قِبل الزوّار: وهذا يضيف زمن استجابة إلى طلبات عشوائية ويُفوّت مهامًا على المواقع منخفضة الزيارات. عطّل WP-Cron وشغّله بدلًا من ذلك عبر cron حقيقي على الخادوم للحصول على تحميل أسرع للصفحات وجدولة موثوقة.','WP-Cron disabled'=>'تم تعطيل WP-Cron','WordPress no longer fires cron on page loads.'=>'لم يعد ووردبريس يشغّل cron عند تحميل الصفحات.','Runs on page loads'=>'يعمل عند تحميل الصفحات','WP-Cron fires on visitor requests (the WordPress default).'=>'يعمل WP-Cron عند طلبات الزوّار (السلوك الافتراضي لووردبريس).','Add this line to your server crontab so scheduled tasks keep running every 5 minutes:'=>'أضف هذا السطر إلى crontab الخادوم حتى تستمر المهام المجدولة في العمل كل 5 دقائق:','Re-enable WP-Cron'=>'إعادة تفعيل WP-Cron','DISABLE_WP_CRON is already defined elsewhere (wp-config.php or a must-use plugin), so there is nothing to change here.'=>'الثابت DISABLE_WP_CRON مُعرّف بالفعل في مكان آخر (wp-config.php أو إضافة must-use)، لذا لا يوجد ما يمكن تغييره هنا.','Disable WP-Cron'=>'تعطيل WP-Cron','This edits wp-config.php and keeps a protected backup copy of it in the plugin\'s data folder. After disabling, add the crontab line below.'=>'يؤدي هذا إلى تعديل wp-config.php ويحتفظ بنسخة احتياطية محمية في مجلد بيانات الإضافة. بعد التعطيل، أضف سطر crontab أدناه.','wp-config.php is not writable. Add this line by hand, just after its opening <?php tag:'=>'الملف wp-config.php غير قابل للكتابة. أضف هذا السطر يدويًا، مباشرةً بعد وسم الفتح <?php الخاص به:','The table %1$s was not deleted: it takes %2$s, too much to back up and drop from here. Your hosting provider can back it up and drop it.'=>'لم يُحذف الجدول %1$s: يشغل %2$s، وهذا أكبر من أن يُنسخ احتياطيًا ويُحذف من هنا. يمكن لمزوّد الاستضافة نسخه احتياطيًا وحذفه.','%1$s was not deleted: it has %2$s rows, too many to back up and delete from here. Your hosting provider can back them up and delete them.'=>'لم يُحذف %1$s: يحتوي على %2$s صف، وهذا أكثر من أن يُنسخ احتياطيًا ويُحذف من هنا. يمكن لمزوّد الاستضافة نسخها احتياطيًا وحذفها.','%d selected entries were still there after deleting them, so they stay in the list. The backup taken before the delete is kept.'=>'%d من الإدخالات المحددة كانت لا تزال موجودة بعد حذفها، لذا تبقى في القائمة. يتم الاحتفاظ بالنسخة الاحتياطية التي أُنشئت قبل الحذف.','Some selected entries were not removed: deleting orphaned post-type content or taxonomy terms needs the "also delete content" checkbox. Other entries (such as REST namespaces) are inventory only and have nothing to remove from the database.'=>'لم تُحذف بعض الإدخالات المحددة: حذف محتوى أنواع المحتوى اليتيمة أو مصطلحات التصنيفات يتطلب خانة «حذف المحتوى أيضاً». أما الإدخالات الأخرى (مثل مساحات أسماء REST) فهي للجرد فقط ولا شيء فيها لحذفه من قاعدة البيانات.','Some selected entries are inventory only (such as REST namespaces) and have nothing to remove from the database, so they were left in place.'=>'بعض الإدخالات المحددة للجرد فقط (مثل مساحات أسماء REST) ولا شيء فيها لحذفه من قاعدة البيانات، لذلك تُركت كما هي.','Some selected entries were kept because they are protected here: in use by an active plugin or theme, part of WordPress or of WPOptimizing, reserved to the network administrator, or no longer in the latest analysis.'=>'تم الاحتفاظ ببعض الإدخالات المحددة لأنها محمية هنا: تستخدمها إضافة أو قالب نشط، أو هي جزء من WordPress أو WPOptimizing، أو مخصصة لمسؤول الشبكة، أو لم تعد موجودة في آخر تحليل.','Some selected rows were kept: empty records owned by an active extension or by WordPress core are read-only here, as they may be empty on purpose.'=>'احتُفِظ ببعض الصفوف المحددة: السجلات الفارغة التابعة لإضافة نشطة أو لنواة ووردبريس للقراءة فقط هنا، إذ قد تكون فارغة عن قصد.','Deletion aborted: the backup could not be created, so nothing was deleted. Check filesystem permissions.'=>'تم إلغاء الحذف: تعذّر إنشاء النسخة الاحتياطية، لذا لم يُحذف شيء. تحقق من أذونات نظام الملفات.','%d item(s) were still there after deleting them, usually because of file permissions, so they stay in the list. The backup taken before the delete is kept.'=>'%d من العناصر كانت لا تزال موجودة بعد حذفها، غالبًا بسبب أذونات الملفات، لذا تبقى في القائمة. يتم الاحتفاظ بالنسخة الاحتياطية التي أُنشئت قبل الحذف.','Kept %d item(s) because their backup could not be verified — they were not deleted. Check filesystem permissions and retry.'=>'تم الإبقاء على %d عنصر لأنه تعذّر التحقق من نسختها الاحتياطية، فلم تُحذف. تحقّق من أذونات نظام الملفات وأعد المحاولة.','These plugins are still active: %s. A plugin active across the network can only be deactivated by a network administrator, from the network admin.'=>'هذه الإضافات لا تزال مفعّلة: %s. الإضافة المفعّلة على مستوى الشبكة لا يمكن تعطيلها إلا من قِبل مدير الشبكة من لوحة إدارة الشبكة.','Quick reference for every feature. Other tabs link directly to the relevant section.'=>'مرجع سريع لكل ميزة. توفر علامات التبويب الأخرى روابط مباشرة للقسم المقابل.','Tools & data'=>'الأدوات والبيانات','In this section'=>'في هذا القسم','Analyzes your uploads and optimizes new ones as they arrive: it resizes oversized uploads and recompresses them, and serves the next-gen copies they already have on the front-end with a fallback to the original.'=>'يحلّل ملفاتك المرفوعة ويحسّن الجديدة منها فور وصولها: يغيّر حجم المرفوعات الكبيرة ويعيد ضغطها، ويقدّم في الواجهة الأمامية نسخ الجيل الجديد الموجودة لديها مع الرجوع إلى الأصل.','The "Heaviest images" view of Image optimization turns the aggregate numbers into a concrete, per-image to-do list: a table with a thumbnail, dimensions, weight, a plain-language tag of what would help each image (Oversized, No WebP, No AVIF — only ever suggesting formats your server can actually create) and an estimated saving, with search, a format filter and pagination. On very large libraries the scan is time-bounded, so the list shows the worst offenders it reached.'=>'يحوّل عرض «أثقل الصور» في تحسين الصور الأرقام الإجمالية إلى قائمة مهام ملموسة لكل صورة: جدول يضم صورة مصغّرة والأبعاد والوزن ووسمًا بلغة واضحة لما سيساعد كل صورة (أكبر من اللازم، بدون WebP، بدون AVIF — مع اقتراح الصيغ التي يستطيع خادومك إنشاءها فقط) وتوفيرًا تقديريًا، مع بحث وتصفية حسب الصيغة وترقيم صفحات. في المكتبات الكبيرة جدًا يكون الفحص محدودًا زمنيًا، لذا تعرض القائمة أسوأ الحالات التي بلغها.','Compatibility with other optimizers: WPOptimizing recognizes WebP/AVIF copies created by plugins such as Imagify, LiteSpeed Cache, EWWW or ShortPixel (both the photo.jpg.webp and photo.webp naming conventions), so it never regenerates a copy that already exists and can serve theirs too. If one of those plugins is active and already serving next-gen images, WPOptimizing automatically steps back from serving to avoid a double <picture>.'=>'التوافق مع المُحسِّنات الأخرى: يتعرّف WPOptimizing على نسخ WebP/AVIF التي تنشئها إضافات مثل Imagify وLiteSpeed Cache وEWWW وShortPixel (وفق اصطلاحَي photo.jpg.webp وphoto.webp)، فلا يعيد توليد نسخة موجودة بالفعل ويمكنه تقديم نسخها أيضًا. وإذا كانت إحدى تلك الإضافات مُفعّلة وتقدّم صور الجيل الجديد بالفعل، يتوقّف WPOptimizing تلقائيًا عن التقديم لتفادي <picture> مزدوج.','Shows the CSS and JavaScript actually loaded on your public pages, sampled in the background, and lets you stop specific assets from loading — on the whole site or only where you choose.'=>'يعرض CSS وJavaScript المُحمَّلة فعليًا في صفحاتك العامة، مُعايَنة في الخلفية، ويتيح لك إيقاف تحميل موارد محددة — على كامل الموقع أو فقط حيث تختار.','Test mode (free): before applying your rules to everyone, turn on test mode to try them safely. While it is on, every unload rule takes effect only for logged-in administrators, so your visitors keep every asset. Browse your key pages while logged in to confirm they still look and work correctly, then turn test mode off to apply the rules to all visitors. This lets you validate an aggressive setup with zero risk to the public site.'=>'وضع الاختبار (مجاني): قبل تطبيق قواعدك على الجميع، فعّل وضع الاختبار لتجربتها بأمان. أثناء تفعيله، لا تسري أي قاعدة لإلغاء التحميل إلا على المسؤولين المسجّلين، فيحتفظ زوارك بجميع الموارد. تصفّح صفحاتك الرئيسية وأنت مسجّل الدخول للتأكد من أنها تظهر وتعمل بشكل صحيح، ثم أوقف وضع الاختبار لتطبيق القواعد على جميع الزوار. يتيح لك ذلك التحقق من إعداد صارم دون أي مخاطرة على الموقع العام.','URL exceptions (free): list the pages that must always load every asset — the checkout, a booking form, a landing page — and no unloading of any kind (site-wide or per page) will run there. Enter one URL pattern per line, matched against the path, and use * as a wildcard: /checkout protects any URL containing that path, */thank-you/* protects every order-received page. The "Quick add" buttons fill in this site\'s own pages — the WooCommerce cart, checkout and account, the Easy Digital Downloads pages, the course and lesson addresses, the pages with a contact or booking form — and only appear for what is installed here. This is the surgical companion to broad unloading: strip assets site-wide, but never on the pages that need them.'=>'استثناءات حسب الرابط (مجاني): أدرج الصفحات التي يجب أن تُحمِّل دائمًا جميع الموارد — صفحة الدفع، نموذج حجز، صفحة هبوط — ولن يُجرى فيها أي إلغاء تحميل (على مستوى الموقع أو لكل صفحة). أدخل نمط رابط واحدًا لكل سطر، تتم مطابقته مع المسار، واستخدم * كحرف بدل: /checkout يحمي أي رابط يحتوي على ذلك المسار، و*/thank-you/* يحمي كل صفحة تأكيد طلب. تملأ أزرار «إضافة سريعة» الصفحات الفعلية لهذا الموقع — سلة WooCommerce وصفحة الدفع والحساب، وصفحات Easy Digital Downloads، وعناوين الدورات والدروس، والصفحات التي تحتوي نموذج اتصال أو حجز — ولا تظهر إلا لما هو مثبّت هنا. إنه المكمِّل الدقيق لإلغاء التحميل الواسع: أزل الموارد في كامل الموقع، لكن ليس أبدًا في الصفحات التي تحتاجها.','Quick Profiles apply a full recommended configuration (cleanup tasks plus object cache, query deduplication and heartbeat) with a single click. Individual cleanup options and backup retention are configured here.'=>'تُطبّق الملفات الشخصية السريعة إعداداً موصى به كاملاً (مهام التنظيف بالإضافة إلى ذاكرة التخزين المؤقت للكائنات وإزالة تكرار الاستعلامات والـ Heartbeat) بنقرة واحدة. يتم تكوين خيارات التنظيف الفردية والاحتفاظ بالنسخ الاحتياطية هنا.','Notification email and maintenance report: the notification address is where WPOptimizing sends the periodic report; for agencies, point it at the maintainer instead of the site owner. Network alerts go to the network administrator instead. The maintenance report is a recurring email summary you can set to daily, weekly, fortnightly or monthly (off by default): it includes the Health Score and its trend, key database and media metrics, any unusual table growth, and the scans and cleanups done since the last report. Use "Send a test now" to check delivery without changing the schedule.'=>'بريد الإشعارات وتقرير الصيانة: عنوان الإشعارات هو حيث يرسل WPOptimizing التقرير الدوري؛ وبالنسبة للوكالات، وجّهه إلى المسؤول بدلًا من مالك الموقع. أما تنبيهات الشبكة فتُرسل إلى مدير الشبكة. تقرير الصيانة هو ملخّص بريدي دوري يمكنك ضبطه على يومي أو أسبوعي أو كل أسبوعين أو شهري (مُعطَّل افتراضيًا): يتضمّن Health Score واتجاهه، والمقاييس الرئيسية لقاعدة البيانات والوسائط، وأي نمو غير معتاد للجداول، والفحوصات وعمليات التنظيف التي جرت منذ التقرير السابق. استخدم «أرسل اختبارًا الآن» للتحقّق من التسليم دون تغيير الجدولة.','You can opt out at any time from the Settings tab. Your cleanup features keep working, but sharing is strictly reciprocal: if your site does not contribute, it does not receive the shared dataset either — the community knowledge base only flows to sites that take part. With sharing off, attribution falls back to what your own site captures locally.'=>'يمكنك إيقاف ذلك في أي وقت من علامة تبويب الإعدادات. تستمر وظائف التنظيف في العمل، لكن المشاركة متبادلة تمامًا: إذا لم يساهم موقعك، فإنه لا يتلقى مجموعة البيانات المشتركة أيضًا — فقاعدة المعرفة المجتمعية فلا تصل إلا إلى المواقع المشاركة. وعند إيقاف المشاركة، يعتمد الإسناد على ما يلتقطه موقعك محليًا.','Analyzes your uploads (free) and, with Pro, optimizes originals (backup-first), generates WebP and AVIF copies, resizes oversized uploads, and serves the next-gen copies on the front-end with a fallback to the original.'=>'يحلّل ملفاتك المرفوعة (مجانًا)، ومع Pro يحسّن النسخ الأصلية (نسخة احتياطية أولاً)، وينشئ نسخ WebP وAVIF، ويغيّر حجم المرفوعات الكبيرة، ويقدّم نسخ الجيل الجديد في الواجهة الأمامية مع الرجوع إلى الأصل.','Generate a WebP copy on upload (Pro) makes the WebP copy for a new image (and each of its sizes) the moment it is uploaded, so the front-end can serve next-gen straight away without waiting for the bulk pass. It is logged exactly like the bulk copies, so "Remove copies" still undoes it. AVIF stays a deliberate bulk action because encoding it is far too slow to run on every upload. Like the rest, it stands down when another image optimizer is active.'=>'«إنشاء نسخة WebP عند الرفع» (Pro) ينشئ نسخة WebP لصورة جديدة (ولكل مقاس من مقاساتها) لحظة رفعها، بحيث يمكن للواجهة الأمامية تقديم الجيل الجديد فورًا دون انتظار المعالجة المجمّعة. وتُسجَّل تمامًا مثل النسخ المجمّعة، لذا لا يزال «إزالة النسخ» يتراجع عنها. ويبقى AVIF إجراءً مجمّعًا مقصودًا لأن ترميزه بطيء جدًا بحيث لا يمكن تشغيله عند كل عملية رفع. ومثل البقية، يتوقف عندما يكون هناك مُحسِّن صور آخر نشطًا.','Compatibility with other optimizers: WPOptimizing recognizes WebP/AVIF copies created by plugins such as Imagify, LiteSpeed Cache, EWWW or ShortPixel (both the photo.jpg.webp and photo.webp naming conventions), so it never regenerates a copy that already exists and can serve theirs too. If one of those plugins is active and already serving next-gen images, WPOptimizing automatically steps back from serving to avoid a double <picture>. "Remove copies" only ever deletes the copies WPOptimizing itself generated.'=>'التوافق مع المُحسِّنات الأخرى: يتعرّف WPOptimizing على نسخ WebP/AVIF التي تنشئها إضافات مثل Imagify وLiteSpeed Cache وEWWW وShortPixel (وفق اصطلاحَي photo.jpg.webp وphoto.webp)، فلا يعيد توليد نسخة موجودة بالفعل ويمكنه تقديم نسخها أيضًا. وإذا كانت إحدى تلك الإضافات مُفعّلة وتقدّم صور الجيل الجديد بالفعل، يتوقّف WPOptimizing تلقائيًا عن التقديم لتفادي <picture> مزدوج. ولا يحذف «إزالة النسخ» سوى النسخ التي ولّدها WPOptimizing نفسه.','Shows the CSS and JavaScript actually loaded on your public pages, sampled in the background. You can stop specific assets from loading site-wide (free); automatic, context-aware unloading driven by the knowledge base is a Pro feature.'=>'يعرض CSS وJavaScript المُحمَّلة فعليًا في صفحاتك العامة، مُعايَنة في الخلفية. يمكنك إيقاف تحميل موارد محددة على مستوى الموقع (مجانًا)؛ أما الإلغاء التلقائي السياقي المعتمد على قاعدة المعرفة فهو ميزة احترافية.','Test mode (free): before applying your rules to everyone, turn on test mode to try them safely. While it is on, every unload rule — manual and automatic — takes effect only for logged-in administrators, so your visitors keep every asset. Browse your key pages while logged in to confirm they still look and work correctly, then turn test mode off to apply the rules to all visitors. This lets you validate an aggressive setup with zero risk to the public site.'=>'وضع الاختبار (مجاني): قبل تطبيق قواعدك على الجميع، فعّل وضع الاختبار لتجربتها بأمان. أثناء تفعيله، لا تسري أي قاعدة لإلغاء التحميل — يدوية أو تلقائية — إلا على المسؤولين المسجّلين، فيحتفظ زوارك بجميع الموارد. تصفّح صفحاتك الرئيسية وأنت مسجّل الدخول للتأكد من أنها تظهر وتعمل بشكل صحيح، ثم أوقف وضع الاختبار لتطبيق القواعد على جميع الزوار. يتيح لك ذلك التحقق من إعداد صارم دون أي مخاطرة على الموقع العام.','URL exceptions (free): list the pages that must always load every asset — the checkout, a booking form, a landing page — and no unloading of any kind (manual, automatic or per-page) will run there. Enter one URL pattern per line, matched against the path, and use * as a wildcard: /checkout protects any URL containing that path, */thank-you/* protects every order-received page. The "Quick add" buttons fill in this site\'s own pages — the WooCommerce cart, checkout and account, the Easy Digital Downloads pages, the course and lesson addresses, the pages with a contact or booking form — and only appear for what is installed here. This is the surgical companion to broad unloading: strip assets site-wide, but never on the pages that need them.'=>'استثناءات حسب الرابط (مجاني): أدرج الصفحات التي يجب أن تُحمِّل دائمًا جميع الموارد — صفحة الدفع، نموذج حجز، صفحة هبوط — ولن يُجرى فيها أي إلغاء تحميل (يدوي أو تلقائي أو لكل صفحة). أدخل نمط رابط واحدًا لكل سطر، تتم مطابقته مع المسار، واستخدم * كحرف بدل: /checkout يحمي أي رابط يحتوي على ذلك المسار، و*/thank-you/* يحمي كل صفحة تأكيد طلب. تملأ أزرار «إضافة سريعة» الصفحات الفعلية لهذا الموقع — سلة WooCommerce وصفحة الدفع والحساب، وصفحات Easy Digital Downloads، وعناوين الدورات والدروس، والصفحات التي تحتوي نموذج اتصال أو حجز — ولا تظهر إلا لما هو مثبّت هنا. إنه المكمِّل الدقيق لإلغاء التحميل الواسع: أزل الموارد في كامل الموقع، لكن ليس أبدًا في الصفحات التي تحتاجها.','Quick Profiles apply a full recommended configuration (cleanup tasks plus object cache, query deduplication and heartbeat) with a single click. Individual cleanup options, backup retention and license management are all configured here.'=>'تُطبّق الملفات الشخصية السريعة إعداداً موصى به كاملاً (مهام التنظيف بالإضافة إلى ذاكرة التخزين المؤقت للكائنات وإزالة تكرار الاستعلامات والـ Heartbeat) بنقرة واحدة. يتم تكوين خيارات التنظيف الفردية والاحتفاظ بالنسخ الاحتياطية وإدارة الترخيص هنا.','Notification email and maintenance report: the notification address is where WPOptimizing sends license notices and the periodic report; for agencies, point it at the maintainer instead of the site owner. Network alerts go to the network administrator instead. The maintenance report is a recurring email summary you can set to daily, weekly, fortnightly or monthly (off by default): it includes the Health Score and its trend, key database and media metrics, any unusual table growth, and the scans and cleanups done since the last report. Use "Send a test now" to check delivery without changing the schedule.'=>'بريد الإشعارات وتقرير الصيانة: عنوان الإشعارات هو حيث يرسل WPOptimizing إشعارات الترخيص والتقرير الدوري؛ وبالنسبة للوكالات، وجّهه إلى المسؤول بدلًا من مالك الموقع. أما تنبيهات الشبكة فتُرسل إلى مدير الشبكة. تقرير الصيانة هو ملخّص بريدي دوري يمكنك ضبطه على يومي أو أسبوعي أو كل أسبوعين أو شهري (مُعطَّل افتراضيًا): يتضمّن Health Score واتجاهه، والمقاييس الرئيسية لقاعدة البيانات والوسائط، وأي نمو غير معتاد للجداول، والفحوصات وعمليات التنظيف التي جرت منذ التقرير السابق. استخدم «أرسل اختبارًا الآن» للتحقّق من التسليم دون تغيير الجدولة.','Import / export: download the whole configuration as a JSON file and restore it here or on another site — handy to replicate your setup across a fleet. The export covers the settings for cleanup, scheduling, cache, media and images, Smart Assets, backups and attribution. For safety it never includes keys, passwords, the license, webhooks, the data-sharing consent, branding or measured runtime state (scan results, baselines, cached sizes), so importing onto another site only carries configuration. On import, existing settings are overwritten and any unrecognized keys are ignored.'=>'استيراد / تصدير: نزّل التهيئة بالكامل كملف JSON واستعدها هنا أو في موقع آخر — مفيد لنسخ إعداداتك عبر مجموعة من المواقع. يشمل التصدير إعدادات التنظيف، والجدولة، والتخزين المؤقت، والوسائط والصور، وSmart Assets، والنسخ الاحتياطية، والإسناد. لأسباب أمنية لا يتضمن أبدًا المفاتيح أو كلمات المرور أو الترخيص أو خطافات الويب أو الموافقة على مشاركة البيانات أو العلامة التجارية أو حالة التشغيل المقاسة (نتائج الفحص، القيم المرجعية، الأحجام المخزَّنة مؤقتًا)، لذا فإن الاستيراد إلى موقع آخر ينقل التهيئة فقط. عند الاستيراد، يتم استبدال الإعدادات الحالية وتجاهل أي مفاتيح غير معروفة.','You can opt out at any time from the Settings tab. Your cleanup features keep working, but sharing is strictly reciprocal: if your site does not contribute, it does not receive the shared dataset either — not even with an active license. A license unlocks every feature of the plugin; the community knowledge base only flows to sites that take part. With sharing off, attribution falls back to what your own site captures locally.'=>'يمكنك إيقاف ذلك في أي وقت من علامة تبويب الإعدادات. تستمر وظائف التنظيف في العمل، لكن المشاركة متبادلة تمامًا: إذا لم يساهم موقعك، فإنه لا يتلقى مجموعة البيانات المشتركة أيضًا — ولا حتى مع ترخيص نشط. يفتح الترخيص جميع وظائف الإضافة؛ أما قاعدة المعرفة المجتمعية فلا تصل إلا إلى المواقع المشاركة. وعند إيقاف المشاركة، يعتمد الإسناد على ما يلتقطه موقعك محليًا.','Performance assistant'=>'مساعد الأداء','A guided view of your server response time (TTFB) with one-click fixes. It rates the server share of TTFB, scores it into the Optimization health, and walks you through the levers that lower it — applying the ones WPOptimizing can do itself and explaining the ones it cannot.'=>'عرض موجّه لزمن استجابة خادمك (TTFB) مع إصلاحات بنقرة واحدة. يقيّم حصة الخادم من TTFB، ويضمّها إلى حالة التحسين، ويرشدك عبر المفاتيح التي تخفّضه — يطبّق ما يستطيع WPOptimizing القيام به ويشرح ما لا يستطيع.','The Performance tab measures the server share of TTFB — the time WordPress takes to start sending a page, excluding the visitor network. It samples real front-end requests, averages them, and shows a level (good / improvable / high) that also feeds the Optimization health score.'=>'يقيس تبويب الأداء حصة الخادم من TTFB: الوقت الذي يستغرقه ووردبريس لبدء إرسال صفحة، دون شبكة الزائر. يأخذ عيّنات من طلبات حقيقية في الواجهة الأمامية ويحسب متوسطها ويعرض مستوى (جيد / قابل للتحسين / مرتفع) يغذّي أيضاً درجة حالة التحسين.','Below the diagnosis is a checklist of levers. For the ones WPOptimizing can act on — the persistent object cache, query deduplication, autoload weight (Smart Deactivation) and the Heartbeat — an Apply button performs the change in one click, reusing the same safe, reversible actions as their own tabs. A result notice confirms each change.'=>'أسفل التشخيص توجد قائمة بالمفاتيح. بالنسبة لما يستطيع WPOptimizing التصرّف فيه — ذاكرة الكائنات الدائمة، ودمج الاستعلامات، وحجم autoload (التعطيل الذكي)، وHeartbeat — يقوم زر «تطبيق» بالتغيير بنقرة واحدة، مع إعادة استخدام نفس الإجراءات الآمنة والقابلة للتراجع الموجودة في تبويباتها. ويؤكّد إشعار كل تغيير.','For the levers WPOptimizing cannot change it shows guidance instead of a button: moving WP-Cron to a real system cron (needs wp-config.php and server access), and the server or host itself (PHP version, OPcache, hosting resources, a light theme). This is the honest case: when the database, cache and autoload are all green and TTFB is still high, the remaining time is the server, and the assistant says so rather than suggesting cleanups that would not help.'=>'بالنسبة للمفاتيح التي لا يستطيع WPOptimizing تغييرها يعرض إرشاداً بدلاً من زر: نقل WP-Cron إلى cron حقيقي على مستوى النظام (يتطلب wp-config.php ووصولاً إلى الخادم)، والخادم أو الاستضافة نفسها (إصدار PHP، وOPcache، وموارد الاستضافة، وقالب خفيف). هذه هي الحالة الصادقة: عندما تكون قاعدة البيانات والذاكرة المؤقتة وautoload كلها خضراء ويظل TTFB مرتفعاً، فالزمن المتبقي هو الخادم، ويقول المساعد ذلك بدلاً من اقتراح عمليات تنظيف لن تفيد.','Deep analysis is an optional, consented profiler: it has zero effect on your site until you click "Run profiling test", then it profiles just the next few front-end requests and disarms itself. It breaks the server response time into phases (boot, init, routing, queries and render) and summarises the request\'s database work, so you get unequivocal information about where the time goes — which is especially useful when everything WPOptimizing controls is already optimal.'=>'التحليل المعمّق هو أداة قياس اختيارية وبموافقتك: ليس له أي تأثير على موقعك حتى تنقر على «تشغيل اختبار القياس»، ثم يقيس فقط الطلبات القليلة التالية في الواجهة الأمامية ويتعطّل تلقائياً. يقسّم زمن استجابة الخادم إلى مراحل (الإقلاع، init، التوجيه، الاستعلامات والعرض) ويلخّص عمل قاعدة البيانات للطلب، ليمنحك معلومات لا لبس فيها عن أين يُصرف الوقت — وهو مفيد بوجه خاص عندما يكون كل ما يتحكم فيه WPOptimizing مضبوطاً بالفعل على النحو الأمثل.','It also points to the concrete culprit: during the test it times each hook, and because plugins fire their own hooks inside init (woocommerce_init, elementor/loaded and so on), the "Where the time went" list names the responsible plugin instead of just the generic phase — so you know exactly what to disable or review.'=>'كما يشير إلى المتسبب المحدد: أثناء الاختبار يقيس زمن كل خطاف، ولأن الإضافات تطلق خطافاتها الخاصة داخل init (مثل woocommerce_init و elementor/loaded)، فإن قائمة «أين ذهب الوقت» تذكر اسم الإضافة المسؤولة بدلاً من المرحلة العامة فقط، حتى تعرف بالضبط ما الذي يجب تعطيله أو مراجعته.','The deep analysis also flags slow SELECT queries that scan a large table without a usable index — the classic cause of a sluggish database — attributing each to the plugin that ran it and, when the query is simple enough, showing the exact CREATE INDEX you could add. With a license, Apply index creates it for you after asking, and Undo removes it again, checking afterwards that it is really gone; without one, it only advises, so you can review it with your developer first.'=>'يشير التحليل العميق أيضاً إلى استعلامات SELECT البطيئة التي تمسح جدولاً كبيراً دون فهرس قابل للاستخدام — السبب الكلاسيكي لبطء قاعدة البيانات — وينسب كلاً منها إلى الإضافة التي نفّذته، وعندما يكون الاستعلام بسيطاً بما يكفي يعرض عبارة CREATE INDEX الدقيقة التي يمكنك إضافتها. مع الترخيص، يُنشئ زر «تطبيق الفهرس» الفهرس نيابةً عنك بعد طلب تأكيدك، ويزيله زر «تراجع» مرة أخرى ثم يتحقق من أنه أُزيل فعلاً؛ ومن دون ترخيص، يكتفي بالنصح، حتى تتمكن من مراجعته أولاً مع مطوّرك.','The full breakdown opens on its own report screen — use "View report" from the assistant (running a test lands you there directly). It is a plain URL you can bookmark, share or print.'=>'يفتح التحليل الكامل في شاشة تقرير خاصة به — استخدم "عرض التقرير" من المساعد (عند تشغيل اختبار تصل إليها مباشرة). إنه رابط عادي يمكنك حفظه أو مشاركته أو طباعته.','Fetches your Google PageSpeed score and Core Web Vitals for the home page, on demand. It sends only the public URL of your site to Google’s public API and changes nothing here. The optional free API key simply raises the request quota.'=>'يجلب عند الطلب درجة Google PageSpeed ومؤشرات Core Web Vitals للصفحة الرئيسية. لا يُرسل سوى عنوان URL العام لموقعك إلى واجهة Google العامة ولا يغيّر شيئًا هنا. مفتاح API المجاني اختياري ولا يفعل سوى رفع حصة الطلبات.','PageSpeed Insights is Google’s own measurement of how fast your site loads. WPOptimizing asks for it on demand — one outbound HTTPS request carrying only the public URL of your home page — and shows the performance score plus the Core Web Vitals (LCP, INP, CLS, FCP, TBT and Speed Index). Nothing is installed, changed or stored on your site beyond the last result.'=>'PageSpeed Insights هو قياس Google نفسه لسرعة تحميل موقعك. يطلبه WPOptimizing عند الحاجة — طلب HTTPS صادر واحد يحمل فقط عنوان URL العام لصفحتك الرئيسية — ويعرض درجة الأداء إضافةً إلى مؤشرات Core Web Vitals (LCP وINP وCLS وFCP وTBT ومؤشر السرعة). لا يُثبَّت أو يُغيَّر أو يُخزَّن أي شيء في موقعك سوى آخر نتيجة.','Lab metrics come from a simulated load and are always available. Field data (what real visitors experienced over the last 28 days) is only included when Google has enough traffic for your site, which is why it can be missing on smaller sites. Test both mobile and desktop: mobile is the stricter of the two and the one Google ranks on.'=>'تأتي مقاييس المختبر من تحميل محاكى وهي متاحة دائمًا. أما بيانات الميدان (ما اختبره زوار حقيقيون خلال آخر 28 يومًا) فتُدرَج فقط عندما يتوفر لدى Google زيارات كافية لموقعك، ولهذا قد تغيب في المواقع الصغيرة. اختبر الجوال وسطح المكتب معًا: الجوال هو الأكثر صرامة وهو ما يعتمد عليه Google في الترتيب.','The API key is optional. Without one Google applies a shared, anonymous quota that is enough for occasional tests; if you test often you will eventually see a quota error. A free key raises that limit, costs nothing and needs no payment method.'=>'مفتاح API اختياري. بدونه يطبّق Google حصة مشتركة ومجهولة تكفي للاختبارات العَرَضية؛ وإذا اختبرت كثيرًا فسترى في النهاية خطأ حصة. المفتاح المجاني يرفع ذلك الحد، ولا يكلّف شيئًا، ولا يتطلب وسيلة دفع.','Installs a persistent object cache drop-in that stores expensive database queries in memory (Redis, Memcached, APCu or built-in SQLite). Query deduplication collapses repeated identical queries within a single request. Heartbeat control reduces admin-side server load.'=>'يثبّت ملحق ذاكرة تخزين مؤقت دائمة للكائنات يخزّن استعلامات قواعد البيانات المكلفة في الذاكرة (Redis أو Memcached أو APCu أو SQLite المدمج). تضم ميزة إزالة تكرار الاستعلامات الاستعلامات المتطابقة المتكررة ضمن طلب واحد. يقلّل التحكم في Heartbeat من الحمل على الخادم في منطقة الإدارة.','WPOptimizing installs a drop-in file (wp-content/object-cache.php) that intercepts WordPress object cache calls and routes them to the fastest available backend. Redis and Memcached are used when the server offers them; APCu works well on single-server hosts; the built-in SQLite store is the automatic fallback that requires zero configuration.'=>'يثبّت WPOptimizing ملف drop-in (wp-content/object-cache.php) يعترض استدعاءات ذاكرة التخزين المؤقت للكائنات في WordPress ويوجهها إلى أسرع خادم خلفي متاح. يُستخدم Redis و Memcached عندما يوفرهما الخادم؛ يعمل APCu بشكل جيد على المضيفين ذوي الخادم الواحد؛ مخزن SQLite المدمج هو الخيار الاحتياطي التلقائي الذي لا يتطلب أي تكوين.','Query deduplication (db.php drop-in) intercepts wpdb calls and returns a cached result when the same query string is executed more than once in the same HTTP request. This is particularly effective on complex pages that call get_post(), get_terms() or get_user() for the same IDs from many different code paths.'=>'يعترض إلغاء تكرار الاستعلامات (drop-in للملف db.php) استدعاءات wpdb ويعيد نتيجة مخزنة مؤقتاً عندما يتم تنفيذ نفس سلسلة الاستعلام أكثر من مرة في نفس طلب HTTP. هذا فعّال بشكل خاص في الصفحات المعقدة التي تستدعي get_post() أو get_terms() أو get_user() لنفس المعرفات من مسارات كود مختلفة.','Login-safe by design: WordPress stores user session tokens inside the user_meta cache group, so under heavy concurrent traffic a persistent cache can occasionally overwrite a freshly issued login token and log users out. WPOptimizing keeps the user_meta group out of the persistent store by default and reads it fresh on every request, so sessions stay reliable. Sites on a low-contention backend can opt back in from the cache config file.'=>'آمن لجلسات الدخول بحكم التصميم: يخزّن ووردبريس رموز جلسات المستخدمين داخل مجموعة التخزين المؤقت user_meta، لذا قد تؤدي ذاكرة تخزين مؤقت دائمة أحيانًا، تحت حركة مرور متزامنة كثيفة، إلى الكتابة فوق رمز تسجيل دخول صدر للتو وتسجيل خروج المستخدمين. يُبقي WPOptimizing مجموعة user_meta خارج المخزن الدائم افتراضيًا ويقرؤها محدثة في كل طلب، فتظل الجلسات موثوقة. ويمكن للمواقع التي تعمل بخلفية منخفضة التنازع إعادة تفعيل ذلك من ملف إعدادات التخزين المؤقت.','Heartbeat control lets you set the WordPress admin heartbeat to Default, Slow (every 60 s) or Off outside the editor, where autosave and edit locks keep working. Slowing it or turning it off noticeably lowers PHP and database load during active admin sessions.'=>'يتيح لك التحكم في Heartbeat ضبط نبض لوحة تحكم ووردبريس على الافتراضي أو بطيء (كل 60 ث) أو إيقاف خارج المحرر، حيث يستمر الحفظ التلقائي وأقفال التحرير في العمل. يؤدي إبطاؤه أو إيقافه إلى خفض ملحوظ في حمل PHP وقاعدة البيانات أثناء جلسات لوحة التحكم.','Server TTFB and what to do about it: the Cache analytics show the server share of TTFB (the time WordPress takes to start sending the page, not the visitor network). WPOptimizing rates it (good / improvable / high), folds it into the Optimization health score, and gives prioritized actions. The advice is context-aware: if the object cache is off it suggests enabling it; if autoload is heavy it points you there; and — crucially — when the database, cache and autoload are already optimal it tells you honestly that the bottleneck is the server itself (PHP version, OPcache, hosting resources or a heavy theme/plugin), which the plugin cannot fix.'=>'زمن استجابة الخادم (TTFB) وما العمل: تعرض تحليلات الذاكرة المؤقتة حصة الخادم من TTFB (الوقت الذي يستغرقه ووردبريس لبدء إرسال الصفحة، وليس شبكة الزائر). يقيّمه WPOptimizing (جيد / قابل للتحسين / مرتفع)، ويضمّه إلى درجة حالة التحسين، ويقدّم إجراءات مرتبة حسب الأولوية. النصيحة سياقية: إذا كانت ذاكرة الكائنات معطّلة يقترح تفعيلها؛ وإذا كان autoload ثقيلاً يوجّهك إليه؛ والأهم — عندما تكون قاعدة البيانات والذاكرة المؤقتة وautoload مضبوطة بالفعل على النحو الأمثل يخبرك بصراحة أن عنق الزجاجة هو الخادم نفسه (إصدار PHP أو OPcache أو موارد الاستضافة أو قالب/إضافة ثقيلة)، وهو ما لا تستطيع الإضافة إصلاحه.','Page cache (opt-in, off by default): WPOptimizing can also serve a static HTML copy of each page to anonymous visitors, so most requests never boot WordPress — the biggest speed win. It stays disabled until you enable it in the Cache tab, and it never caches logged-in users, carts, checkout, admin, feeds, search, REST/AJAX or requests with a non-tracking query string; the cache is purged automatically whenever content changes. Leave it off and WPOptimizing only caches database queries and objects, which can never serve a stale page or break a nonce.'=>'ذاكرة تخزين الصفحات (اختيارية، معطّلة افتراضياً): يمكن لـ WPOptimizing أيضاً تقديم نسخة HTML ثابتة من كل صفحة للزوّار المجهولين، فلا تُشغّل معظم الطلبات ووردبريس — أكبر مكسب في السرعة. تبقى معطّلة حتى تفعّلها من تبويب الذاكرة، ولا تُخزّن مطلقاً المستخدمين المسجَّلين ولا السلّة ولا الدفع ولا لوحة التحكم ولا الخلاصات ولا البحث ولا REST/AJAX ولا الطلبات ذات سلسلة استعلام غير خاصة بالتتبّع؛ وتُفرَّغ الذاكرة تلقائياً عند تغيّر المحتوى. إن تركتها معطّلة، فلن يخزّن WPOptimizing سوى استعلامات قاعدة البيانات والكائنات، وهو ما لا يمكن أن يقدّم صفحة قديمة أو يُفسد nonce.','Coexistence with host and plugin caches: WPOptimizing refuses to enable its own page cache alongside a third-party one (WP Rocket, LiteSpeed, W3 Total Cache…) or a host page cache, and it never overwrites another plugin’s advanced-cache.php. It detects them and purges their page cache automatically after a cleanup, and from the toolbar “Flush all caches”, so a database cleanup never leaves stale pages. The Cache tab lists the page caches it detected; a wpoptimizing_flush_all action lets hosts without a known API hook their own purge.'=>'التعايش مع ذاكرات الاستضافة والإضافات: يرفض WPOptimizing تفعيل ذاكرة تخزين صفحاته إلى جانب ذاكرة طرف ثالث (WP Rocket، LiteSpeed، W3 Total Cache…) أو ذاكرة صفحات من الاستضافة، ولا يستبدل أبداً advanced-cache.php الخاص بإضافة أخرى. يكتشفها ويُفرّغ ذاكرة صفحاتها تلقائياً بعد التنظيف، ومن «إفراغ كل الذاكرات» في شريط الأدوات، فلا يترك تنظيفُ قاعدة البيانات صفحاتٍ قديمة. يعرض تبويب الذاكرة ذاكرات الصفحات المكتشَفة؛ ويتيح إجراء wpoptimizing_flush_all للاستضافات التي لا تملك واجهة معروفة ربط عملية الإفراغ الخاصة بها.','Browser cache and compression (Apache): from the Cache tab WPOptimizing can add a managed block to your .htaccess that sets far-future Expires/Cache-Control headers for static files (images, CSS, JS, fonts) and enables on-the-fly compression (Brotli when the server offers it, otherwise gzip). Returning visitors then reuse files from their own browser instead of re-downloading them, and every text response travels compressed. The block is written between clearly marked WPOptimizing markers, a timestamped backup of .htaccess is kept, and disabling it removes exactly that block and nothing else. It is skipped when the server is not Apache or when another plugin already manages these headers.'=>'ذاكرة تخزين المتصفح والضغط (Apache): من تبويب الذاكرة، يمكن لـWPOptimizing إضافة كتلة مُدارة إلى ملف .htaccess تضبط ترويسات Expires/Cache-Control بعيدة الأمد للملفات الثابتة (الصور وCSS وJS والخطوط) وتُفعّل الضغط الفوري (Brotli عندما يوفّره الخادم، وإلا gzip). عندئذ يعيد الزوّار العائدون استخدام الملفات من متصفحهم بدلاً من تنزيلها من جديد، وتنتقل كل استجابة نصية مضغوطة. تُكتب الكتلة بين علامات WPOptimizing واضحة، ويُحتفظ بنسخة احتياطية مؤرَّخة من ملف .htaccess، وعند تعطيلها تُزال تلك الكتلة بالضبط ولا شيء غيرها. ويُتخطّى ذلك عندما لا يكون الخادم Apache أو عندما تدير إضافة أخرى هذه الترويسات بالفعل.','CSS and JavaScript minification (opt-in, off by default): under Speed › Page & browser › Minification WPOptimizing can serve minified copies of your own local CSS and JS, stripping comments and whitespace so they download faster. It is deliberately conservative: files that are already minified, hosted on another domain, or listed in your exclusions are left untouched; the minified copies live in wp-content/uploads/wpopt-assets/ and are rebuilt automatically when the source changes or a cache is flushed. A test mode lets administrators preview the result before exposing it to visitors, and — like the page cache — it refuses to run alongside another asset optimizer (Autoptimize, WP Rocket, Perfmatters, LiteSpeed) to avoid double-processing.'=>'تصغير CSS وJavaScript (اختياري، معطّل افتراضياً): من السرعة › الصفحة والمتصفح › التصغير، يمكن لـWPOptimizing تقديم نسخ مصغّرة من ملفات CSS وJS المحلية الخاصة بك، مع إزالة التعليقات والمسافات لتنزيلها بسرعة أكبر. وهو محافظ عن قصد: تُترك الملفات المصغّرة مسبقاً أو المستضافة على نطاق آخر أو المدرجة في استثناءاتك دون تغيير؛ وتوجد النسخ المصغّرة في wp-content/uploads/wpopt-assets/ ويُعاد إنشاؤها تلقائياً عند تغيّر المصدر أو إفراغ إحدى الذاكرات. ويتيح وضع الاختبار للمسؤولين معاينة النتيجة قبل عرضها على الزوّار، وهو — مثل ذاكرة تخزين الصفحات — يرفض العمل بجانب أداة تحسين موارد أخرى (Autoptimize، WP Rocket، Perfmatters، LiteSpeed) لتجنّب المعالجة المزدوجة.','Advanced CSS/JS delivery (Pro): on top of the free minification, Speed › Page & browser can defer local JavaScript (scripts run after the page paints, while jQuery stays eager so inline snippets keep working), load CSS asynchronously (the loadCSS pattern, so stylesheets no longer block the first paint), and inline your critical above-the-fold CSS in the head to remove the brief flash the async loading would otherwise cause. Each has its own exclusion list, and all of them stand down when another optimizer is active.'=>'توصيل CSS/JS المتقدّم (مدفوع): إضافةً إلى التصغير المجاني، يمكن لقسم السرعة › الصفحة والمتصفح تأجيل JavaScript المحلي (تُنفَّذ السكربتات بعد رسم الصفحة، بينما يبقى jQuery فورياً كي تستمر المقاطع المضمّنة في العمل)، وتحميل CSS بشكل غير متزامن (نمط loadCSS، بحيث لا تعود أوراق الأنماط تحجب أول رسم)، وتضمين CSS الحرِج الظاهر أولاً في الترويسة لإزالة الوميض القصير الذي كان التحميل غير المتزامن سيسبّبه. لكل ميزة قائمة استثناءات خاصة بها، وتتوقّف جميعها عند وجود أداة تحسين أخرى نشطة.','Plugins by URL (Pro): under Speed › Page & browser › Plugins by URL you can keep a plugin from loading on the URLs you choose, or load it only on them, so its PHP, queries, CSS and JavaScript stay out of pages where it does nothing. It applies to visitors only — logged-in users, the admin, AJAX, the REST API and cron always get every plugin. Before saving, each set of rules is tried on the home page and up to four more pages, loaded with every plugin and with the rules; it is not saved if any of them breaks, nor if it would leave out a plugin another one needs. If a visit ever ends in a fatal error with plugins left out, every rule switches itself off. Deactivating WPOptimizing undoes it all.'=>'الإضافات حسب الرابط (Pro): من السرعة › الصفحة والمتصفح › الإضافات حسب الرابط يمكنك منع إضافة من التحميل في الروابط التي تختارها، أو تحميلها فيها فقط، كي يبقى PHP الخاص بها واستعلاماتها وCSS وJavaScript خارج الصفحات التي لا تفعل فيها شيئًا. ينطبق ذلك على الزوار فقط: المستخدمون المسجّلون ولوحة التحكم وAJAX وواجهة REST وcron يحصلون دائمًا على كل الإضافات. قبل الحفظ، تُجرّب كل مجموعة قواعد على الصفحة الرئيسية وحتى أربع صفحات أخرى، مرة مع كل الإضافات ومرة مع القواعد؛ ولا تُحفظ إذا تعطلت إحداها، أو إذا استبعدت إضافة تحتاجها إضافة أخرى. إذا انتهت زيارة مع استبعاد إضافات بخطأ فادح، تتوقف كل القواعد من تلقاء نفسها. تعطيل WPOptimizing يلغي كل شيء.','Cloudflare: if the site is behind Cloudflare, WPOptimizing also purges its cache — everything when it flushes the other caches, and only the affected pages when content changes. It needs the zone ID and an API token with the Zone › Cache Purge › Purge permission; “How to get them” in the Cache tab shows the steps. The Global API Key is refused, because it opens the whole account. A token for “All zones” can be reused on every site of the account, and it can only purge.'=>'Cloudflare: إذا كان الموقع خلف Cloudflare، يمسح WPOptimizing ذاكرته المؤقتة أيضًا — كلها عند تفريغ الذاكرات المؤقتة الأخرى، والصفحات المتأثرة فقط عند تغيّر المحتوى. يحتاج إلى معرّف المنطقة ورمز API بصلاحية المنطقة › مسح ذاكرة التخزين المؤقت › مسح؛ ويعرض «كيفية الحصول عليهما» في تبويب الذاكرة المؤقتة الخطوات. يُرفض Global API Key لأنه يفتح الحساب بالكامل. يمكن إعادة استخدام رمز «كل المناطق» في كل مواقع الحساب، ولا يستطيع سوى المسح.','Pages at Cloudflare\'s edge (opt-in): with the page cache on and a token that also has Zone › Cache Rules › Edit, WPOptimizing can add a Cache Rule so Cloudflare keeps the pages too, for anonymous visitors only. Each page says whether it may be kept — the pages the page cache stores, for as long as it keeps them — and logged-in users, carts, searches, 404s and pages that set a cookie always reach your server. Turning it on is checked with real requests, and if a request with a session cookie or the login page is ever served from the edge, the rule is removed by itself.'=>'الصفحات على حافة Cloudflare (اختياري): مع تفعيل ذاكرة الصفحات المؤقتة ورمز يملك أيضًا صلاحية المنطقة › Cache Rules › تحرير، يمكن لـ WPOptimizing إضافة قاعدة تخزين مؤقت ليحتفظ Cloudflare بالصفحات أيضًا، للزوار المجهولين فقط. كل صفحة تقول إن كان يمكن الاحتفاظ بها — التي تخزنها ذاكرة الصفحات المؤقتة، طوال مدة احتفاظها بها — والمستخدمون المسجّلون وعربات التسوق وعمليات البحث وصفحات 404 والصفحات التي تضع ملف تعريف ارتباط تصل دائمًا إلى خادمك. يُتحقق من التفعيل بطلبات حقيقية، وإذا قُدّم يومًا من الحافة طلب يحمل ملف تعريف ارتباط جلسة أو صفحة الدخول، تُزال القاعدة من تلقاء نفسها.','Autoloaded options are loaded from the database on every single page request. This tab lists them sorted by size so you can disable autoload for options that are not needed on every request, reducing the upfront database cost on every page.'=>'يتم تحميل الخيارات ذات التحميل التلقائي من قاعدة البيانات مع كل طلب صفحة. تسرد هذه التبويبة هذه الخيارات مرتبةً حسب الحجم حتى تتمكن من تعطيل التحميل التلقائي للخيارات غير المطلوبة في كل طلب، مما يقلل من تكلفة قاعدة البيانات المبدئية في كل صفحة.','WordPress loads all autoloaded options in a single SELECT at the start of every request. If plugins have added large blobs or configuration arrays with autoload=yes, this query can transfer hundreds of kilobytes before a single line of your template runs. The Autoload tab lists every autoloaded option with its size, so you can identify the heaviest ones at a glance.'=>'يحمّل WordPress جميع الخيارات ذات التحميل التلقائي في SELECT واحد في بداية كل طلب. إذا أضافت الإضافات كائنات كبيرة أو مصفوفات تكوين بـ autoload=yes، يمكن لهذا الاستعلام نقل مئات الكيلوبايت قبل تشغيل سطر واحد من قالبك. تسرد علامة التبويب Autoload كل خيار محمَّل تلقائياً مع حجمه، حتى تتمكن من تحديد أثقلها بنظرة واحدة.','Smart Deactivation analyses every autoloaded option against the attribution manifest and automatically disables autoload for options that are confidently attributed to plugins that are no longer installed. This is completely safe: an uninstalled plugin cannot need its options on every request.'=>'يحلّل التعطيل الذكي كل خيار محمَّل تلقائياً مقابل بيان الإسناد ويعطّل تلقائياً التحميل التلقائي للخيارات المنسوبة بثقة إلى إضافات لم تعد مثبتة. هذا آمن تماماً: لا يمكن لإضافة مُزالة أن تحتاج إلى خياراتها في كل طلب.','De-autoload never-read goes further and is the most surgical option. WPOptimizing measures which of the largest autoloaded options are actually read on each request (a sampled, near-zero-overhead measurement) and, combined with the same signal aggregated across the network, turns off autoload only for options that load on every request yet are (almost) never read. WordPress core options are always protected, nothing is deleted, and every change is reversible.'=>'«إلغاء التحميل التلقائي لما لا يُقرأ أبدًا» يذهب أبعد وهو الخيار الأكثر دقّة. يقيس WPOptimizing أيّ الخيارات ذاتية التحميل الأكبر تُقرأ فعليًا في كل طلب (قياس بالعيّنة وبتكلفة شبه معدومة)، ومع دمجه بالإشارة نفسها المجمّعة عبر الشبكة، يُلغي التحميل التلقائي فقط للخيارات التي تُحمَّل في كل طلب لكنها (تقريبًا) لا تُقرأ أبدًا. تظل خيارات نواة ووردبريس محميّة دائمًا، ولا يُحذف أي شيء، وكل تغيير قابل للتراجع.','Disable all non-essential is the broadest reversible action: it de-autoloads every option that is neither core nor owned by an installed extension (options the network reads on most requests are kept). Delete confirmed orphans removes, backup-first, the dead options of uninstalled extensions.'=>'«تعطيل كل غير الضروري» هو الإجراء القابل للتراجع الأوسع: يُلغي التحميل التلقائي لكل خيار ليس من النواة ولا يخص إضافة مثبّتة (تُحفَظ الخيارات التي تقرؤها الشبكة في معظم الطلبات). «حذف اليتيمة المؤكَّدة» يحذف، مع نسخة احتياطية مسبقة، الخيارات الميتة للإضافات المُلغى تثبيتها.','The Candidates sub-tab shows non-autoloaded options that are read on almost every request (measured by the read-frequency tracker). Enabling autoload for those options turns the per-read SELECT into a zero-cost cache hit.'=>'تعرض علامة التبويب الفرعية Candidates الخيارات غير المحمَّلة تلقائياً التي تُقرأ في كل طلب تقريباً (يُقاس ذلك بواسطة متتبع تكرار القراءة). تفعيل التحميل التلقائي لتلك الخيارات يحوّل SELECT لكل قراءة إلى إصابة ذاكرة تخزين مؤقت بتكلفة صفر.','Tip: a healthy site keeps total autoload weight below about 800 KB. Sites above 1 MB will see a measurable latency improvement after a cleanup.'=>'نصيحة: الموقع الصحي يحافظ على إجمالي وزن التحميل التلقائي أقل من نحو 800 KB. المواقع التي تتجاوز 1 MB ستلاحظ تحسناً ملموساً في زمن الاستجابة بعد التنظيف.','Lists every database table with its engine, row count, data size and recoverable overhead. Optimizing a table reclaims fragmented space. Tables still using the legacy MyISAM engine are highlighted for conversion to InnoDB.'=>'يسرد كل جدول في قاعدة البيانات مع محركه وعدد صفوفه وحجم بياناته والمساحة القابلة للاسترداد. يستعيد تحسين الجدول المساحة المجزأة. يتم تمييز الجداول التي لا تزال تستخدم محرك MyISAM القديم للتحويل إلى InnoDB.','Database tables accumulate fragmented space over time as rows are deleted or updated. The "overhead" column shows how much space can be reclaimed without touching any data: MySQL simply compacts the existing rows. For busy e-commerce or membership sites this can save tens or hundreds of megabytes.'=>'تتراكم في جداول قاعدة البيانات مساحة مجزأة بمرور الوقت كلما حُذفت صفوف أو حُدّثت. تُظهر عمود «overhead» مقدار المساحة القابلة للاسترداد دون المساس بأي بيانات: يضغط MySQL ببساطة الصفوف الموجودة. في مواقع التجارة الإلكترونية أو المواقع التي تعاني ضغطاً عالياً، قد يوفر هذا عشرات أو مئات الميغابايتات.','When there is reclaimable overhead, a "Reclaim overhead now" button appears above the list. It runs OPTIMIZE on exactly the tables that carry recoverable overhead (file-based engines such as MyISAM and Aria) in one click, so you do not have to find and select them by hand. It never touches InnoDB internal free space, which the engine reuses on its own, and it never deletes data.'=>'عندما تكون هناك زيادة قابلة للاسترداد، يظهر زر «استرداد الزيادة الآن» أعلى القائمة. يقوم بتشغيل OPTIMIZE بنقرة واحدة على الجداول التي تحمل زيادة قابلة للاسترداد بالضبط (المحركات المعتمدة على الملفات مثل MyISAM وAria)، حتى لا تضطر إلى البحث عنها وتحديدها يدويًا. لا يمسّ أبدًا المساحة الحرة الداخلية لـ InnoDB، التي يعيد المحرك استخدامها بنفسه، ولا يحذف البيانات أبدًا.','MyISAM is the older MySQL table format. It lacks transaction support, uses table-level locking (so a single slow query blocks all writes), and cannot recover safely after a crash. InnoDB offers row-level locking, crash-safe recovery via a redo log, and significantly better performance under concurrent write workloads.'=>'MyISAM هو تنسيق جداول MySQL القديم. يفتقر إلى دعم المعاملات، ويستخدم قفل مستوى الجدول (لذا يحجب استعلام بطيء واحد جميع عمليات الكتابة)، ولا يمكنه الاسترداد بأمان بعد الأعطال. يوفر InnoDB قفل مستوى الصف، والاسترداد الآمن من الأعطال عبر سجل إعادة التشغيل، وأداء أفضل بشكل ملحوظ في ظل أحمال الكتابة المتزامنة.','The conversion from MyISAM to InnoDB is an online ALTER TABLE that rebuilds the table in place. It is non-destructive: all data is preserved, all indexes are rebuilt, and WordPress continues to function normally throughout. For safety, take a database backup before converting large tables.'=>'التحويل من MyISAM إلى InnoDB هو ALTER TABLE عبر الإنترنت يعيد بناء الجدول في مكانه. إنه غير مدمر: يتم الحفاظ على جميع البيانات، وإعادة بناء جميع الفهارس، ويستمر WordPress في العمل بشكل طبيعي طوال العملية. للسلامة، خذ نسخة احتياطية من قاعدة البيانات قبل تحويل الجداول الكبيرة.','Orphaned custom tables from plugins that have been uninstalled appear in the Orphans tab rather than here, so the Tables tab only lists tables that belong to something still installed.'=>'تظهر الجداول المخصصة اليتيمة من الإضافات المُزالة في علامة التبويب Orphans بدلاً من هنا، لذا تسرد علامة التبويب Tables فقط الجداول التي تنتمي إلى شيء لا يزال مثبتاً.','After each scan WPOptimizing records the size and row count of every table and compares them with the previous scan. When a table grows abnormally between scans — both by a meaningful amount and by a large percentage — it is flagged at the top of this tab (and in the performance report). This is how you catch a runaway log table, a transient/cache table that never clears, or a stuck background job before it bloats the database. A brand-new table is reported as new, never as a warning.'=>'بعد كل فحص، يسجّل WPOptimizing حجم كل جدول وعدد صفوفه ويقارنها بالفحص السابق. وعندما ينمو جدول بشكل غير طبيعي بين الفحوصات — بمقدار ملموس وبنسبة كبيرة معًا — يُبرَز في أعلى هذا التبويب (وفي تقرير الأداء). هكذا تكتشف جدول سجلّ خارجًا عن السيطرة، أو جدول عناصر عابرة/تخزين مؤقت لا يُفرَّغ أبدًا، أو مهمة خلفية عالقة قبل أن تضخّم قاعدة البيانات. أما الجدول المُنشأ حديثًا فيُبلَّغ عنه كجديد، لا كتحذير.','Shows all WordPress scheduled events with their hook, next run time and recurrence. Orphaned events — hooks whose callback function no longer exists, usually left by uninstalled plugins — are flagged so you can remove them safely.'=>'يعرض جميع الأحداث المجدولة في WordPress مع الخطاف الخاص بها ووقت التشغيل التالي والتكرار. يتم وضع علامة على الأحداث المتروكة — الخطاطيف التي لم تعد وظيفة رد الاتصال الخاصة بها موجودة، والتي تتركها عادةً الإضافات المُلغاة — حتى تتمكن من إزالتها بأمان.','WordPress Cron (wp-cron) fires scheduled tasks on the next page load after the scheduled time. Each event is identified by its hook name. When a plugin is uninstalled without cleaning up, its scheduled hooks remain in the cron table but nothing ever runs them — they fire silently, waste a small amount of server time, and clutter the schedule.'=>'يطلق WordPress Cron (wp-cron) المهام المجدولة عند تحميل الصفحة التالية بعد الوقت المحدد. يُعرَّف كل حدث باسم خطافه. عند إزالة إضافة دون تنظيف، تبقى خطاطيفها المجدولة في جدول cron لكن لا شيء يشغّلها — تُطلَق بصمت، وتهدر قدراً ضئيلاً من وقت الخادم، وتُفوضر الجدول الزمني.','An event is flagged as orphaned only when TWO checks agree: nothing is listening for its hook, AND the hook name does not belong to any plugin still installed. The second check is not a refinement, it is what makes the first usable: plugins such as MainWP Child, Complianz or LiteSpeed register their cron callback only in the context where it runs — a REST call, the front end, their own request — so on this admin screen the hook looks unclaimed while the plugin is present and keeps re-creating the event. The bias is deliberately conservative: when in doubt, not an orphan. Removing a genuine orphan is entirely safe — no code listens for the hook, so firing it has no effect, and removing it only stops the silent wasted trigger.'=>'لا يُعلَّم الحدث بأنه يتيم إلا عند اتفاق فحصين اثنين: ألا يستمع أي شيء إلى الخطّاف الخاص به، وألا يعود اسم الخطّاف إلى أي إضافة ما زالت مثبّتة. الفحص الثاني ليس تحسينًا، بل هو ما يجعل الأول قابلًا للاستخدام: إضافات مثل MainWP Child أو Complianz أو LiteSpeed تسجّل دالة الكرون الخاصة بها في السياق الذي تعمل فيه فقط — طلب REST أو الواجهة الأمامية أو طلبها الخاص — لذلك يبدو الخطّاف في شاشة الإدارة هذه بلا مالك بينما الإضافة موجودة وتعيد إنشاء الحدث. والانحياز متحفّظ عن قصد: عند الشك، ليس يتيمًا. وحذف اليتيم الحقيقي آمن تمامًا: لا يستمع أي كود إلى الخطّاف، فإطلاقه بلا أثر، وحذفه يوقف فقط الإطلاق المهدور الصامت.','The list also shows legitimate recurring events (WordPress core, active plugins) so you have a complete picture of what is scheduled and how frequently. This helps spot events that are running too often or that you did not expect.'=>'تُظهر القائمة أيضاً الأحداث المتكررة الشرعية (نواة WordPress، الإضافات النشطة) حتى يكون لديك صورة كاملة عما هو مجدول وبأي تكرار. يساعد هذا في اكتشاف الأحداث التي تعمل بكثرة مفرطة أو التي لم تكن تتوقعها.','The WP-Cron trigger panel at the top of the tab controls how cron fires. By default WordPress runs it on visitor page loads, which adds latency to random requests and can miss tasks on low-traffic sites. Disabling WP-Cron writes the DISABLE_WP_CRON constant into wp-config.php (a protected backup copy is kept in the plugin\'s data folder) and shows the exact crontab line to add so a real server cron drives wp-cron.php on a fixed schedule. If wp-config.php is not writable, the panel shows the snippet to add by hand. The change is fully reversible from the same panel.'=>'تتحكّم لوحة مُشغّل WP-Cron في أعلى التبويب في كيفية تشغيل cron. بشكل افتراضي، يشغّله ووردبريس عند تحميل الصفحات من قِبل الزوّار، وهذا يضيف زمن استجابة إلى طلبات عشوائية وقد يُفوّت مهامًا على المواقع منخفضة الزيارات. يؤدي تعطيل WP-Cron إلى كتابة الثابت DISABLE_WP_CRON في wp-config.php (يتم الاحتفاظ بنسخة احتياطية محمية في مجلد بيانات الإضافة) وعرض سطر crontab الدقيق الذي يجب إضافته حتى يشغّل cron حقيقي على الخادوم ملف wp-cron.php وفق جدول ثابت. إذا كان wp-config.php غير قابل للكتابة، تعرض اللوحة المقتطف لإضافته يدويًا. التغيير قابل للتراجع بالكامل من اللوحة نفسها.','Optional speed features for the public site, configured in Speed › Page & browser: speculative loading (prefetch/prerender the next page), content image loading optimization, resource hints, self-hosted Google Fonts, CDN URL rewriting, and a Server-Timing diagnostic header. All opt-in and reversible; none cache full HTML pages.'=>'ميزات سرعة اختيارية للموقع العام، تُضبط في السرعة › الصفحة والمتصفح: التحميل التخميني (الجلب المسبق/العرض المسبق للصفحة التالية)، وتحسين تحميل صور المحتوى، وتلميحات الموارد، وخطوط Google المستضافة ذاتيًا، وإعادة كتابة عناوين URL إلى شبكة توصيل المحتوى (CDN)، وترويسة Server-Timing تشخيصية. جميعها اختيارية وقابلة للعكس؛ ولا تخزّن أي منها صفحات HTML كاملة في الذاكرة المؤقتة.','Speculative loading uses the browser Speculation Rules API to load the next page before the visitor clicks. In Conservative mode the next page is prefetched when a link is clicked; in Eager mode it is prerendered on hover, so navigation can feel instant. The admin, the login page, URLs with a query string, and WooCommerce cart/checkout/account pages are excluded automatically, as are links marked rel="nofollow" or with the class no-prerender / no-prefetch.'=>'يستخدم التحميل الاستباقي واجهة Speculation Rules في المتصفّح لتحميل الصفحة التالية قبل أن ينقر الزائر. في الوضع المتحفّظ تُجلب الصفحة التالية مسبقًا عند النقر على رابط؛ وفي الوضع الحثيث تُصيَّر مسبقًا عند التمرير، فيبدو التصفّح فوريًا. تُستثنى تلقائيًا لوحة الإدارة وصفحة الدخول وعناوين URL التي تحتوي على سلسلة استعلام وصفحات سلة/دفع/حساب ووكومرس، وكذلك الروابط التي تحمل rel="nofollow" أو الفئة no-prerender / no-prefetch.','Content image loading optimization marks the first image of a post as the priority (LCP) image — loaded eagerly with fetchpriority=high — while the remaining images are lazy-loaded with asynchronous decoding. It uses the WordPress HTML Tag Processor, so it works even on markup produced by page builders.'=>'يعلّم تحسين تحميل الصور أول صورة في المقالة كصورة ذات أولوية (LCP) — تُحمَّل فورًا بـ fetchpriority=high — بينما تُحمَّل بقية الصور بشكل مؤجّل مع فكّ ترميز غير متزامن. يستخدم HTML Tag Processor الخاص بـ WordPress، لذا يعمل حتى مع الترميز الناتج عن منشئي الصفحات.','The Server-Timing header is a diagnostic for developers: it reports the WordPress processing time, the number of database queries and the object-cache hit rate, visible in the browser DevTools Network panel. It is off by default and intended for troubleshooting, not for end users.'=>'ترويسة Server-Timing أداة تشخيص للمطوّرين: تُبلّغ عن زمن معالجة WordPress وعدد استعلامات قاعدة البيانات ومعدّل إصابات ذاكرة الكائنات المؤقتة، وتظهر في لوحة الشبكة بأدوات مطوّري المتصفّح. معطّلة افتراضيًا ومخصّصة لاستكشاف الأخطاء، لا للمستخدمين النهائيين.','Resource hints look at the external origins your page actually loads (web fonts, CDNs) and ask the browser to resolve DNS and open the connection early, so those assets start downloading sooner. WPOptimizing adds preconnect for the well-known font origins and dns-prefetch for the rest, automatically and only for origins the page really uses — there is nothing to configure. The hints are advisory and harmless: a redundant one only costs a cheap DNS lookup.'=>'تنظر تلميحات الموارد إلى الأصول الخارجية التي تحمّلها صفحتك فعليًا (خطوط الويب، شبكات CDN) وتطلب من المتصفح حلّ DNS وفتح الاتصال مبكرًا، حتى تبدأ تلك الموارد بالتنزيل أبكر. يضيف WPOptimizing preconnect لمصادر الخطوط المعروفة وdns-prefetch لبقيتها، تلقائيًا وفقط للمصادر التي تستخدمها الصفحة فعلًا — لا شيء لإعداده. التلميحات استرشادية وغير ضارة: التلميح الزائد لا يكلّف سوى بحث DNS رخيص.','Preloading key resources goes one step further than a hint: it tells the browser to start downloading a specific file right away, before it would normally discover it. WPOptimizing preloads the featured image of the current post or page (usually the largest above-the-fold image, so this directly improves the LCP metric) with a high priority, and any extra URLs you list — typically an above-the-fold web font or a hero image. The correct type (image, font, style, script) is inferred from the file extension and fonts get the required crossorigin attribute automatically. Preload sparingly: it is a good default for the one or two resources the page needs first, but preloading a long list forces the browser to fetch everything at once and can make the page slower, not faster.'=>'التحميل المسبق للموارد الرئيسية يتجاوز مجرد تلميح: فهو يطلب من المتصفح البدء بتنزيل ملف محدَّد فوراً، قبل أن يكتشفه عادةً. يقوم WPOptimizing بالتحميل المسبق للصورة البارزة للمقال أو الصفحة الحالية (غالباً أكبر صورة ظاهرة أولاً، فيحسّن مقياس LCP مباشرةً) بأولوية عالية، بالإضافة إلى أي روابط إضافية تدرجها — عادةً خط ويب ظاهر أولاً أو صورة رئيسية. يُستنتَج النوع الصحيح (صورة، خط، نمط، سكربت) من امتداد الملف وتحصل الخطوط تلقائياً على سمة crossorigin المطلوبة. حمّل مسبقاً باعتدال: إنه خيار جيد للمورد أو المورَدين اللذين تحتاجهما الصفحة أولاً، لكن التحميل المسبق لقائمة طويلة يُجبر المتصفح على جلب كل شيء دفعة واحدة وقد يجعل الصفحة أبطأ لا أسرع.','Self-hosting Google Fonts downloads the font stylesheet and its woff2 files into your uploads folder and serves them from your own domain, so the browser never connects to fonts.googleapis.com or fonts.gstatic.com. This removes a third-party connection (faster first render) and addresses the GDPR concern about Google Fonts leaking visitor IP addresses. Turn it on, save, then open your site once so the fonts are detected and click "Localize now": WPOptimizing fetches and rewrites them, and from then on swaps the remote stylesheet for the local copy with no per-request network calls. "Remove local fonts" reverts to the original Google-hosted fonts.'=>'تقوم الاستضافة الذاتية لخطوط Google بتنزيل ورقة أنماط الخطوط وملفات woff2 الخاصة بها إلى مجلد الرفع لديك وتقديمها من نطاقك الخاص، بحيث لا يتصل المتصفح أبدًا بـ fonts.googleapis.com أو fonts.gstatic.com. يزيل هذا اتصالًا بطرف ثالث (عرض أول أسرع) ويعالج مخاوف اللائحة العامة لحماية البيانات (GDPR) بشأن تسريب خطوط Google لعناوين IP الخاصة بالزوّار. فعّله، واحفظ، ثم افتح موقعك مرة واحدة حتى تُكتشَف الخطوط وانقر على «توطين الآن»: يقوم WPOptimizing بجلبها وإعادة كتابتها، ومن ثم يستبدل ورقة الأنماط البعيدة بالنسخة المحلية دون أي استدعاءات شبكية لكل طلب. «إزالة الخطوط المحلية» يعيد الخطوط المستضافة على Google.','CDN rewriting changes the URLs of your static files (images, CSS, JS under uploads, wp-content and wp-includes) to a CDN hostname, so visitors download them from the CDN edge closest to them instead of your server. Enter the CDN host (for example cdn.example.com), choose which folders to rewrite, and save. Only local static files are rewritten — dynamic PHP endpoints and any external URL are left untouched. First configure the CDN as a pull zone whose origin is this site, and make sure it forwards the correct CORS headers for fonts. WPOptimizing does not upload anything; it only rewrites URLs, so switching the feature off instantly returns to serving from your origin.'=>'تغيّر إعادة كتابة CDN عناوين URL لملفاتك الثابتة (الصور وCSS وJS ضمن مجلدات الرفع وwp-content وwp-includes) إلى اسم مضيف CDN، بحيث يقوم الزوّار بتنزيلها من أقرب حافة CDN إليهم بدلًا من خادومك. أدخل مضيف CDN (مثل cdn.example.com)، واختر المجلدات المراد إعادة كتابتها، ثم احفظ. تُعاد كتابة الملفات الثابتة المحلية فقط — أما نقاط النهاية الديناميكية بلغة PHP وأي عنوان URL خارجي فتبقى دون مساس. اضبط CDN أولًا كمنطقة سحب (pull zone) مصدرها هذا الموقع، وتأكّد من أنه يمرّر ترويسات CORS الصحيحة للخطوط. لا يرفع WPOptimizing أي شيء؛ فهو يعيد كتابة عناوين URL فقط، لذا فإن إيقاف الميزة يعيد فورًا التقديم من مصدرك.','Compatibility with caching, SEO and image-optimization plugins: these features are built to coexist. WPOptimizing never overwrites an object-cache.php or db.php drop-in installed by another plugin — it detects it and steps aside. Resource hints are de-duplicated against hints the theme or another plugin already added. Image loading only ADDS attributes and skips any image another lazy-loader has already deferred, so it does not fight a dedicated image plugin or WordPress core. The sitemap and feed core-tweaks simply switch off the built-in versions, which an SEO plugin normally replaces anyway, so enabling them next to one is safe.'=>'التوافق مع إضافات التخزين المؤقت وSEO وتحسين الصور: صُمِّمت هذه الميزات للتعايش. لا يستبدل WPOptimizing أبدًا ملف object-cache.php أو db.php drop-in الذي ثبّتته إضافة أخرى — بل يكتشفه ويتنحّى. وتُزال تكرارات تلميحات الموارد مقابل ما أضافه القالب أو إضافة أخرى بالفعل. ولا يفعل تحسين تحميل الصور سوى «إضافة» السمات، ويتخطّى أي صورة سبق أن أجّلها مُحمِّل كسول آخر، فلا يتعارض مع إضافة صور مخصّصة ولا مع نواة ووردبريس. أما تعديلات خريطة الموقع والخلاصات فتكتفي بإيقاف النسخ المدمجة، التي تستبدلها إضافة SEO عادةً على أي حال، لذا فتفعيلها بجانب واحدة آمن.','You do not have to configure these by hand: each cleanup profile (applied from Settings or the welcome wizard) already enables sensible front-end defaults, so choosing a profile sets them up for you. You can override any of them anytime under Speed › Page & browser › Loading & delivery.'=>'لا حاجة لضبطها يدويًا: كل ملف تعريف تنظيف (مُطبَّق من الإعدادات أو من معالج الترحيب) يفعّل بالفعل إعدادات واجهة أمامية معقولة، لذا فإن اختيار ملف تعريف يجهّزها لك. يمكنك تغيير أيٍّ منها في أي وقت من السرعة › الصفحة والمتصفح › التحميل والتسليم.','Optional toggles in Settings that disable WordPress features you may not use (emojis, the version meta, RSD/WLW links, jQuery Migrate, oEmbed extras, REST API head links and more), trimming front-end weight and head noise. All are off by default and reversible.'=>'مفاتيح اختيارية في الإعدادات تُعطِّل ميزات ووردبريس التي قد لا تستخدمها (الرموز التعبيرية، وسم الإصدار، روابط RSD/WLW، jQuery Migrate، إضافات oEmbed، روابط REST API في الترويسة والمزيد)، مما يقلّل وزن الواجهة وضجيج الترويسة. كلها معطَّلة افتراضيًا وقابلة للعكس.','WordPress loads a number of features on every page that many sites never use: the emoji script and its DNS prefetch, a generator meta tag with your version, RSD and Windows Live Writer links, a shortlink tag, the jQuery Migrate compatibility script, oEmbed discovery and the wp-embed script, REST API discovery links, and more. Each one is small, but together they add markup, requests and a little attack surface. The Core tweaks section lets you switch off the ones you do not need.'=>'يُحمّل ووردبريس في كل صفحة عددًا من الميزات التي لا تستخدمها مواقع كثيرة أبدًا: سكربت الإيموجي وجلب DNS المسبق له، ووسم generator الذي يكشف إصدارك، وروابط RSD وWindows Live Writer، ووسم shortlink، وسكربت توافق jQuery Migrate، واكتشاف oEmbed وسكربت wp-embed، وروابط اكتشاف واجهة REST، وغيرها. كل منها صغير، لكنها مجتمعةً تضيف شِفرة وطلبات وقدرًا من سطح الهجوم. يتيح لك قسم «تحسينات النواة» إيقاف ما لا تحتاجه منها.','Tweaks are grouped by risk so you can decide how far to go. Safe tweaks have no visible effect (they only remove head noise). Moderate tweaks may affect a few setups — for example removing jQuery Migrate can reveal an old theme or plugin that still relies on deprecated jQuery, and removing front-end Dashicons assumes your theme does not use that icon font for logged-out visitors.'=>'التعديلات مُجمَّعة حسب المخاطرة لتقرّر إلى أي مدى تذهب. الآمنة لا تأثير مرئي لها (تزيل ضجيج الترويسة فقط). المتوسطة قد تؤثر على بعض الإعدادات — مثلًا قد تكشف إزالة jQuery Migrate عن قالب أو إضافة قديمة لا تزال تعتمد على jQuery المهجور، وإزالة Dashicons من الواجهة تفترض أن قالبك لا يستخدم خط الأيقونات ذلك للزوار غير المسجّلين.','Everything here is fully reversible: a tweak only removes a core hook or adds a short-circuit filter while it is enabled, and unticking it restores the default behaviour on the next page load. No content or settings are deleted. Features that WPOptimizing already manages elsewhere — Heartbeat, post revisions and autosave, the oEmbed cache, the object cache, query deduplication and front-end asset unloading — are intentionally not duplicated here; configure those on their own screens. Security-oriented switches such as XML-RPC are also out of scope and belong to dedicated hardening tools.'=>'كل شيء هنا قابل للتراجع بالكامل: لا يفعل التحسين سوى إزالة خطّاف من النواة أو إضافة مرشّح قصر-دائرة أثناء تفعيله، وإلغاء تحديده يعيد السلوك الافتراضي عند التحميل التالي. لا يُحذف أي محتوى أو إعداد. أما الميزات التي يديرها WPOptimizing بالفعل في مكان آخر — Heartbeat، والمراجعات والحفظ التلقائي، وذاكرة oEmbed المؤقتة، وذاكرة الكائنات المؤقتة، وإزالة تكرار الاستعلامات، وإلغاء تحميل موارد الواجهة الأمامية — فلا تُكرَّر هنا عمدًا؛ اضبطها في شاشاتها الخاصة. كما أن المفاتيح الأمنية مثل XML-RPC خارج النطاق وتخص أدوات التقوية المخصصة.','You do not have to enable these one by one: each cleanup profile (applied from Settings or the welcome wizard) already turns on a sensible set — all the Safe tweaks for every profile, plus selected Moderate ones for the blog and aggressive presets.'=>'لا داعي لتفعيلها واحدةً تلو الأخرى: كل ملف تنظيف (يُطبَّق من الإعدادات أو معالج الترحيب) يُفعِّل مجموعة معقولة بالفعل — كل التعديلات الآمنة لكل ملف، إضافةً إلى بعض المتوسطة في إعدادات المدونة والوضع الصارم.','The analysis is free and read-only: it walks /uploads and reports the total image weight, a breakdown by format, how many images are large (≥ 300 KB), how many exceed your max dimensions, and how many lack a WebP/AVIF copy, with an estimate of the space a conversion could save. It never changes a file.'=>'التحليل مجاني وللقراءة فقط: يتصفّح /uploads ويُبلغ عن الحجم الإجمالي للصور، وتوزيعًا حسب الصيغة، وكم صورة كبيرة (≥ 300 ك.ب)، وكم تتجاوز أبعادك القصوى، وكم بلا نسخة WebP/AVIF، مع تقدير للمساحة التي قد توفّرها عملية التحويل. ولا يغيّر أي ملف أبدًا.','Optimize originals (Pro) shrinks JPEG/PNG files in place and resizes any that exceed your max width/height — without a visible loss of quality. It is strictly backup-first: each original is copied to a backup before being overwritten, the result is kept only if it is actually smaller, and each image is processed once. "Restore originals" copies the backups back, so the whole step is reversible. Run it before generating copies so the copies are made from the optimized originals.'=>'يعمل «تحسين الأصول» (Pro) على تصغير ملفات JPEG/PNG في مكانها وتغيير أبعاد ما يتجاوز الحد الأقصى للعرض والارتفاع — دون خسارة مرئية في الجودة. والنسخ الاحتياطي المسبق إلزامي: يُنسخ كل أصل إلى نسخة احتياطية قبل استبداله، ولا تُحفظ النتيجة إلا إذا كانت أصغر فعلًا، وتُعالَج كل صورة مرة واحدة. و«استعادة الأصول» تعيد نسخ النسخ الاحتياطية، فالخطوة كلها قابلة للتراجع. شغّلها قبل توليد النسخ حتى تُصنع النسخ من الأصول المحسّنة.','Generate next-gen copies (Pro) creates a .webp and/or .avif copy next to each image (for example photo.jpg.webp). The originals are never modified or deleted, and every copy we create is logged so "Remove copies" deletes only our files, never another optimizer\'s. AVIF needs a newer server (PHP 8.1+ GD with AVIF, or Imagick with libheif); where it is unavailable, WebP is still offered. Because the copies are derivatives, they do not appear in the images-by-format table — they are listed in their own "Generated copies" table.'=>'ينشئ «إنشاء نسخ الجيل الجديد» (Pro) نسخة .webp و/أو .avif بجوار كل صورة (مثل photo.jpg.webp). لا تُعدَّل النسخ الأصلية أو تُحذف أبدًا، وتُسجَّل كل نسخة ننشئها كي يحذف «إزالة النسخ» ملفاتنا فقط، لا ملفات مُحسِّن آخر. يتطلّب AVIF خادمًا أحدث (GD في PHP 8.1+ مع AVIF، أو Imagick مع libheif)؛ وحيث لا يتوفّر، يظل WebP متاحًا. وبما أنّ النسخ مشتقّة، فهي لا تظهر في جدول الصور حسب الصيغة — بل تُدرَج في جدول خاص بها «النسخ المُولَّدة».','Front-end serving wraps each image in a <picture> element with the AVIF and WebP copies as sources and the original as the fallback. The browser picks the first format it supports; browsers that support neither receive the untouched JPEG/PNG. A source is only added when its copy actually exists on disk, so serving is always safe.'=>'يغلّف التقديم في الواجهة الأمامية كل صورة بعنصر <picture> مع نسختي AVIF وWebP كمصادر والأصل كبديل. يختار المتصفح أول صيغة يدعمها؛ أما المتصفحات التي لا تدعم أيًّا منهما فتتلقى ملف JPEG/PNG الأصلي دون تغيير. لا يُضاف مصدر إلا عندما تكون نسخته موجودة فعلاً على القرص، لذا فالتقديم آمن دائمًا.','Settings: Conversion quality (40–100) is the lossy knob for WebP, AVIF and JPEG; PNG recompression is always lossless. Max dimensions set separate width and height limits (0 on an axis disables it). Lossless mode keeps PNG lossless and leaves JPEGs untouched unless they must be resized, since there is no lossless JPEG recompression. Strip metadata removes EXIF/ICC/comments for smaller files (turn it off to keep camera data; note that the GD fallback always drops metadata). Optimize on upload applies the same settings to new uploads: it resizes those above the max size (WordPress\' native handling, preserving the full-size original), recompresses them and strips their metadata.'=>'الإعدادات: جودة التحويل (40–100) هي المقبض ذو الفقدان لـ WebP وAVIF وJPEG؛ أما إعادة ضغط PNG فدائمًا بلا فقدان. تحدّد الأبعاد القصوى حدّي العرض والارتفاع بشكل منفصل (القيمة 0 على أحد المحورين تعطّله). يبقي وضع «بلا فقدان» PNG بلا فقدان ويترك JPEG دون مساس ما لم يلزم تغيير حجمها، إذ لا توجد إعادة ضغط JPEG بلا فقدان. تزيل «إزالة البيانات الوصفية» EXIF/ICC/التعليقات لتصغير الملفات (عطّلها للإبقاء على بيانات الكاميرا؛ بديل GD يزيل البيانات الوصفية دائمًا). ويطبّق «التحسين عند الرفع» الإعدادات نفسها على المرفوعات الجديدة: يصغّر ما يتجاوز الحجم الأقصى (المعالجة الأصلية في ووردبريس، مع الحفاظ على الأصل بالحجم الكامل) ، ويعيد ضغطها ويزيل بياناتها الوصفية.','Every theme and plugin can enqueue its own CSS and JavaScript, and many load their files on pages that do not use them — a slider script on your contact page, a forms stylesheet site-wide. Smart Assets records which handles are actually enqueued on real front-end page loads (it samples public visits in the background; sharing must be enabled) and lists them so you can see what each page carries.'=>'يمكن لكل قالب وإضافة إدراج CSS وJavaScript الخاصة به، ويحمّل كثيرٌ منها ملفاته في صفحات لا تستخدمها — سكربت عارض شرائح في صفحة التواصل، أو ورقة أنماط نماذج على مستوى الموقع. تسجّل «الموارد الذكية» المعرّفات التي تُدرَج فعليًا في تحميلات الصفحات الأمامية الحقيقية (تعاين الزيارات العامة في الخلفية؛ ويجب تفعيل المشاركة) وتسردها لترى ما تحمّله كل صفحة.','Manual unloading (free): tick the assets you want to stop loading and save. The selected handles are dequeued on the front-end site-wide, which removes their HTTP requests and bytes. It is fully reversible — untick to restore. Start conservatively and test the public site after each change, because some scripts are dependencies of others.'=>'الإلغاء اليدوي (مجانًا): علّم الموارد التي تريد إيقاف تحميلها واحفظ. تُزال المعرّفات المحددة من الطابور في الواجهة الأمامية على مستوى الموقع، مما يلغي طلبات HTTP والبايتات الخاصة بها. وهو قابل للعكس تمامًا: ألغِ التعليم للاستعادة. ابدأ بحذر واختبر الموقع العام بعد كل تغيير، لأن بعض السكربتات تعتمد عليها أخرى.','Automatic unloading (Pro): instead of choosing by hand, WPOptimizing uses the shared knowledge base to decide, per page type, which assets are safe to drop — context-aware and kept up to date as the dataset grows. It is opt-in and can be turned off at any time.'=>'الإلغاء التلقائي (احترافي): بدلًا من الاختيار يدويًا، يستخدم WPOptimizing قاعدة المعرفة المشتركة ليقرّر، حسب نوع الصفحة، أي الموارد يمكن إزالتها بأمان — سياقيًا ومحدَّثًا مع نمو مجموعة البيانات. وهو اختياري ويمكن إيقافه في أي وقت.','Per-rule targeting (free): by default an unloaded asset is dropped on the whole site. Under "Per-rule targeting" you can narrow any single rule to a content type (front page, posts & pages, or archives) and/or to specific URLs — the opposite of the exceptions: "unload this ONLY on /shop and */product/*". Enter one or more URL patterns (comma-separated, wildcard *) in "Only on URLs"; leave it empty to keep the rule site-wide. Scope and URL are combined, so you can say "on single posts, but only under /guides". Changes save as you edit.'=>'الاستهداف لكل قاعدة (مجاني): افتراضيًا يُزال المورد المُلغى تحميله من الموقع كله. ضمن «الاستهداف لكل قاعدة» يمكنك تضييق أي قاعدة على نوع محتوى (الصفحة الرئيسية، المقالات والصفحات، أو الأرشيف) و/أو على روابط محددة — عكس الاستثناءات: «ألغِ تحميل هذا فقط على /shop و*/product/*». أدخل نمط رابط واحدًا أو أكثر (مفصولة بفواصل، حرف بدل *) في «في روابط محددة فقط»؛ اتركه فارغًا للإبقاء على القاعدة على مستوى الموقع كله. يُدمج النطاق والرابط معًا، فيمكنك القول «على المقالات المفردة، لكن فقط ضمن /guides». تُحفظ التغييرات أثناء التحرير.','Who owns an asset (free): your site can only name the handles its own plugins print, so some rows show no owner at all — and an asset you cannot name is one you cannot safely act on. WPOptimizing asks the shared knowledge base: when the sites that contribute their registry agree on who owns a handle, its owner is shown with a "shared data" mark, so you know the name came from them and not from your own site. When they disagree — two different extensions claiming the same handle — the row is marked "conflicting" and no owner is shown. That is deliberate: we never pick the most popular answer, because unloading an asset attributed to the wrong extension breaks the page that needed it.'=>'مالك المورد (مجانًا): موقعك لا يستطيع تسمية سوى المُعرِّفات التي تطبعها إضافاته الخاصة، لذلك لا تُظهر بعض الصفوف أي مالك — والمورد الذي لا تستطيع تسميته هو مورد لا يمكنك التعامل معه بأمان. يسأل WPOptimizing قاعدة المعرفة المشتركة: عندما تتفق المواقع التي تشارك سجلاتها على مالك مُعرِّف ما، يُعرض المالك مع علامة «بيانات مشتركة»، لتعلم أن الاسم جاء منها لا من موقعك. وعندما تختلف — إضافتان مختلفتان تدّعيان المُعرِّف نفسه — يُوسم الصف بـ«متعارض» ولا يُعرض أي مالك. هذا مقصود: نحن لا نختار الإجابة الأكثر شيوعًا أبدًا، لأن إلغاء تحميل مورد نُسب إلى الإضافة الخطأ يكسر الصفحة التي كانت تحتاجه.','Safety: unloading only stops an asset from being enqueued; it never deletes files. If a page looks wrong after unloading something, re-enable it and the asset loads again on the next request.'=>'الأمان: لا يفعل الإلغاء سوى منع إدراج المورد في الطابور؛ ولا يحذف الملفات أبدًا. إذا بدت صفحة خاطئة بعد إزالة شيء، فأعد تفعيله وسيُحمَّل المورد مجددًا في الطلب التالي.','Removes database clutter: post revisions, auto-drafts, trashed posts, spam comments, and expired transients. Runs from a single button or automatically on a schedule. A detailed log is saved after every run.'=>'يزيل الفوضى من قاعدة البيانات: مراجعات المنشورات، والمسودات التلقائية، والمنشورات المحذوفة، وتعليقات السبام، والمؤقتات المنتهية الصلاحية. يعمل بنقرة واحدة أو تلقائياً وفق جدول زمني. يُحفظ سجل تفصيلي بعد كل تشغيل.','Over time WordPress accumulates records that are no longer needed for the site to function: every draft save creates a revision, every failed publish leaves an auto-draft, deleted content sits in the trash, spam fills the comments table, and transients created by plugins often expire but are never purged. General Cleanup removes all of these in one pass.'=>'بمرور الوقت يتراكم في WordPress سجلات لم تعد ضرورية لعمل الموقع: كل حفظ مسودة ينشئ مراجعة، وكل نشر فاشل يترك مسودة تلقائية، والمحتوى المحذوف يجلس في سلة المهملات، والسبام يملأ جدول التعليقات، والمؤقتات التي تنشئها الإضافات غالباً تنتهي صلاحيتها لكنها لا تُنظَّف أبداً. ينظّف General Cleanup كل هذه في مرور واحد.','Quick Profiles apply a recommended set of tasks in a single click. Every profile enables the basic tasks (auto-drafts, trash, spam, expired transients and table optimization); Safe, Blog and Membership add nothing riskier, WooCommerce adds orphaned elements, Action Scheduler, WooCommerce sessions and orphaned variations, and Agency (maximum) adds unapproved comments, duplicate metadata, orphaned elements, Action Scheduler and unused tags. No profile deletes all transients.'=>'تطبّق الملفات الشخصية السريعة مجموعة موصى بها من المهام بنقرة واحدة. يفعّل كل ملف شخصي المهام الأساسية (المسودات التلقائية، وسلة المهملات، والسبام، والمؤقتات منتهية الصلاحية، وتحسين الجداول)؛ لا تضيف آمنة ومدونة والعضوية شيئاً أكثر خطورة، ويضيف WooCommerce العناصر اليتيمة وAction Scheduler وجلسات WooCommerce والتنويعات اليتيمة، وتضيف وكالة (أقصى حد) التعليقات غير المعتمدة والبيانات الوصفية المكرّرة والعناصر اليتيمة وAction Scheduler والوسوم غير المستخدمة. لا يحذف أي ملف شخصي جميع المؤقتات.','The Dry Run option shows a count of what would be removed without deleting anything — useful for auditing before your first cleanup. After a real run, a detailed HTML log is saved and accessible from the history list so you can review exactly what was deleted.'=>'يُظهر خيار التشغيل التجريبي عدد ما سيتم إزالته دون حذف أي شيء — مفيد للتدقيق قبل أول عملية تنظيف. بعد التشغيل الفعلي، يُحفظ سجل HTML تفصيلي ويمكن الوصول إليه من قائمة التاريخ لمراجعة ما تم حذفه بالضبط.','Every batch the cleanup deletes is backed up first, into one Backups entry per run (scheduled and automatic runs included). If that backup cannot be written, the run stops with the status “Stopped: backup failed” and deletes nothing more. Table optimization changes no data and needs no backup.'=>'تُنسخ كل دفعة يحذفها التنظيف احتياطيًا أولًا، في مُدخل واحد ضمن النسخ الاحتياطية لكل تشغيل (بما في ذلك التشغيلات المجدولة والتلقائية). وإذا تعذّرت كتابة تلك النسخة، يتوقف التشغيل بالحالة «متوقف: فشل النسخ الاحتياطي» ولا يحذف شيئًا آخر. أما تحسين الجداول فلا يغيّر أي بيانات ولا يحتاج إلى نسخة احتياطية.','Tip: schedule cleanup to run nightly or weekly from the Settings tab. Keeping the database lean reduces backup sizes and speeds up queries that scan post meta or comment tables.'=>'نصيحة: جدوِل تشغيل التنظيف ليلاً أو أسبوعياً من علامة التبويب Settings. الحفاظ على قاعدة بيانات خفيفة يقلل من أحجام النسخ الاحتياطية ويسرّع الاستعلامات التي تفحص جداول بيانات المنشور أو التعليقات.','Per-post protection: open any post in the editor (block or classic) and tick "Keep all revisions" to exclude that single post from revision cleanup — useful for legal pages or contracts where the full edit history matters. WPOptimizing also honors the keep_revisions custom field used by "Optimize Database after Deleting Revisions", so you can migrate from that plugin without reconfiguring anything.'=>'الحماية لكل مقالة: افتح أي مقالة في المحرر (الكتل أو الكلاسيكي) وفعّل «الاحتفاظ بجميع المراجعات» لاستثناء تلك المقالة من تنظيف المراجعات — مفيد للصفحات القانونية أو العقود التي يهمّ فيها سجل التعديلات الكامل. كما يحترم WPOptimizing الحقل المخصّص keep_revisions الذي يستخدمه «Optimize Database after Deleting Revisions»، حتى تتمكن من الانتقال من ذلك الإضافة دون إعادة أي إعداد.','The "By content type" sub-tab is a read-only diagnostic that shows where your database weight concentrates, grouped by post type: live entries, revisions, auto-drafts and attached metadata rows. Revisions and auto-drafts are attributed to their real type (revisions through their parent post), so you can see at a glance which content types carry the most overhead before deciding what to clean.'=>'علامة التبويب الفرعية «المحتوى حسب النوع» هي أداة تشخيص للقراءة فقط تُظهر أين يتركّز حجم قاعدة بياناتك، مُجمّعًا حسب نوع المحتوى: العناصر النشطة والمراجعات والمسودات التلقائية وصفوف البيانات الوصفية المرتبطة. تُنسب المراجعات والمسودات التلقائية إلى نوعها الفعلي (المراجعات عبر مقالتها الأم)، بحيث ترى بنظرة واحدة أنواع المحتوى التي تتراكم عليها أكبر زيادة قبل أن تقرّر ما الذي ستنظّفه.','Toolbar shortcuts: the WPOptimizing menu in the top admin bar runs a general cleanup or a full analysis in one click from any screen, on desktop and mobile alike.'=>'اختصارات شريط الأدوات: قائمة WPOptimizing في الشريط العلوي تُشغّل تنظيفًا عامًا أو تحليلًا كاملًا بنقرة واحدة من أي شاشة، على سطح المكتب والجوال على حدٍّ سواء.','Very large databases: the analysis runs asynchronously in stages, so it never blocks the browser or times out a request. On installs with tens of millions of rows, WPOptimizing automatically switches the heaviest counts to fast approximate queries and caps the per-query time, so some figures (like per-type metadata totals) may be shown as approximate or omitted to protect the live site.'=>'قواعد البيانات الكبيرة جدًا: يعمل التحليل بشكل غير متزامن على مراحل، لذا لا يحجب المتصفّح أبدًا ولا يتسبب في انتهاء مهلة الطلب. في التثبيتات التي تضم عشرات الملايين من الصفوف، يحوّل WPOptimizing تلقائيًا أثقل العمليات الحسابية إلى استعلامات تقريبية سريعة ويحدّ من الوقت لكل استعلام، لذا قد تظهر بعض الأرقام (مثل إجماليات البيانات الوصفية حسب النوع) كقيم تقريبية أو تُحذف لحماية الموقع الحي.','Scans your uploads for files with no database attachment record, orphaned thumbnail sizes, and exact-content duplicates. Duplicate detection keeps the oldest copy and reassigns all post references before any deletion.'=>'يفحص ملفات التحميل الخاصة بك بحثاً عن الملفات التي لا يوجد لها سجل مرفق في قاعدة البيانات، وأحجام الصور المصغرة المتروكة، والملفات المكررة ذات المحتوى المتطابق. تحتفظ ميزة اكتشاف التكرارات بأقدم نسخة وتُعيد تعيين جميع مراجع المنشورات قبل أي حذف.','The Media tab covers three separate problem types. Potentially-unused attachments are Media Library entries that are not referenced in any post content, post meta, widget, option or theme mod — they may have been uploaded and then forgotten. Review each one carefully: a file can be "unused" in the database but still referenced by hard-coded HTML in a template.'=>'تتناول علامة التبويب Media ثلاثة أنواع منفصلة من المشكلات. المرفقات التي قد تكون غير مستخدمة هي إدخالات في مكتبة الوسائط غير مرجَعة في أي محتوى منشور أو بيانات meta أو أداة أو خيار أو تعديل للقالب — ربما تم رفعها ثم نُسيت. راجع كل واحدة بعناية: يمكن أن يكون الملف «غير مستخدم» في قاعدة البيانات لكنه لا يزال مرجَعاً من خلال HTML مكتوب بصلابة في قالب.','Duplicate detection computes a hash of the actual file content (not the filename). When two or more files share the same hash, WPOptimizing keeps the attachment with the oldest ID (the original) and reassigns every post_content, post_meta and thumbnail reference that pointed to a duplicate before deleting the duplicate file and its attachment record.'=>'يحسب كشف التكرار بصمة محتوى الملف الفعلي (ليس اسم الملف). عندما يتشارك ملفان أو أكثر نفس البصمة، يحتفظ WPOptimizing بالمرفق الأقدم معرفاً (الأصلي) ويُعيد تعيين كل مرجع post_content و post_meta وصورة مصغرة كان يشير إلى نسخة مكررة قبل حذف الملف المكرر وسجل مرفقه.','Orphaned thumbnail files are physical image files in wp-content/uploads that correspond to intermediate sizes no longer registered by any active theme or plugin. They consume disk space but are never served. They are safe to remove once you have confirmed the size is no longer needed.'=>'ملفات الصور المصغرة اليتيمة هي ملفات صور فعلية في wp-content/uploads تتوافق مع أحجام وسيطة لم تعد مسجّلة من قبل أي قالب أو إضافة نشطة. تستهلك مساحة قرص لكنها لا تُعرض أبداً. يمكن إزالتها بأمان بمجرد التأكد من أن الحجم لم يعد مطلوباً.','Every media deletion is backed up first, so it is reversible: WPOptimizing copies each file (and reassigns duplicate references) before removing anything. If you ever need to undo a deletion, the Media tab shows how many file backups are available and links straight to the Backups tab, where you restore a whole operation in one click. Nothing is deleted that was not fully backed up.'=>'يُنسَخ كل حذف للوسائط احتياطيًا أولًا، لذا فهو قابل للتراجع: ينسخ WPOptimizing كل ملف (ويعيد إسناد مراجع النسخ المكررة) قبل إزالة أي شيء. وإذا احتجت يومًا إلى التراجع عن حذف، يعرض تبويب «الوسائط» عدد النسخ الاحتياطية للملفات المتاحة ويربط مباشرةً بتبويب «النسخ الاحتياطية»، حيث تستعيد عملية كاملة بنقرة واحدة. ولا يُحذف أي شيء لم يُنسَخ احتياطيًا بالكامل.','Image optimization (recompression, WebP/AVIF generation, resizing and front-end serving) has its own sub-section, documented separately under Image optimization.'=>'لتحسين الصور (إعادة الضغط، وتوليد WebP/AVIF، وتغيير الحجم، والتقديم في الواجهة الأمامية) قسم فرعي خاص به، موثَّق على حدة ضمن «تحسين الصور».','In the Library audit, the Renamed-original backups group lists a specific kind of leftover: the *-mfrh-original* copies that rename plugins such as Media File Renamer keep as a backup of the pre-rename original and register as the attachment original_image. The renamed file is what the site serves, so these copies are redundant and do not appear under Orphan files (they are still referenced). Deleting one is backup-first and also clears the leftover original_image reference so nothing is left dangling.'=>'في فحص المكتبة، تعرض مجموعة «نسخ احتياطية لأصول مُعاد تسميتها» نوعًا محددًا من المتبقيات: نسخ *-mfrh-original* التي تحتفظ بها إضافات إعادة التسمية مثل Media File Renamer كنسخة احتياطية من الأصل قبل إعادة التسمية وتسجّلها بوصفها original_image للمرفق. الملف المُعاد تسميته هو ما يقدّمه الموقع، لذا فهذه النسخ زائدة ولا تظهر ضمن «الملفات اليتيمة» (لا تزال مُشار إليها). عند حذف واحدة، يتم أولًا حفظ نسخة احتياطية، كما تُنظَّف إشارة original_image المتبقية حتى لا يبقى شيء معلّقًا.','Media has six entries: Orphans (with a filter for orphan files, orphan thumbnails and other files), Duplicate sets, Unused attachments, Image optimization (Summary and Heaviest images), Trash and Library audit. The audit examines the uploads folder and offers a fix for each finding it can stand behind: protect or delete files that should not be downloadable, delete unused orphan sizes and loose files (backup first), regenerate thumbnails that carry an older name, and a direct link when another Media section already lists the file. It never moves files.'=>'تحتوي الوسائط على ستة إدخالات: اليتيمة (مع عامل تصفية للملفات اليتيمة والصور المصغّرة اليتيمة والملفات الأخرى)، ومجموعات المكررات، والمرفقات غير المستخدمة، وتحسين الصور (الملخص وأثقل الصور)، وسلة المهملات، وفحص المكتبة. يفحص الفحص مجلد الرفع ويعرض إصلاحًا لكل نتيجة يمكنه ضمانها: حماية الملفات التي لا ينبغي تنزيلها أو حذفها، وحذف الأحجام اليتيمة والملفات المتفرقة غير المستخدمة (مع نسخة احتياطية مسبقة)، وإعادة توليد الصور المصغّرة ذات الاسم القديم، ورابط مباشر عندما يدرج قسم آخر من الوسائط الملف. لا ينقل الملفات أبدًا.','Records and files that could not be attributed to any known plugin or theme. They may belong to a custom plugin not yet in the manifest, or to bespoke code. Review them manually before taking any action.'=>'السجلات والملفات التي لا يمكن نسبها إلى أي إضافة أو قالب معروف. قد تنتمي إلى إضافة مخصصة لم تُدرج في القائمة بعد، أو إلى كود مخصص. راجعها يدوياً قبل اتخاذ أي إجراء.','Attribution uses a shared community dataset built from scan results contributed by thousands of WordPress installations. When WPOptimizing finds a database record or file that does not match any entry in the dataset and cannot be inferred from the slug or prefix of an installed extension, it is listed under “To identify” instead of being classified as Orphan or Inactive.'=>'يستخدم الإسناد مجموعة بيانات مشتركة من المجتمع مبنية من نتائج الفحص التي ساهمت بها آلاف من تثبيتات WordPress. عندما يجد WPOptimizing سجل قاعدة بيانات أو ملفاً لا يطابق أي إدخال في مجموعة البيانات ولا يمكن استنتاجه من slug أو بادئة امتداد مثبَّت، يُدرَج ضمن «قيد التحديد» بدلاً من تصنيفه كيتيم أو غير نشط.','Every attributed item carries a confidence level, from most to least reliable: Manual (you attributed it yourself), Sure, Likely, Possible, Doubtful and Estimated; hover over a badge to see what it means. Only Manual, Sure, Likely and Possible allow bulk deletion. Items to identify that have no owner at all show Undetermined.'=>'يحمل كل عنصر منسوب مستوى ثقة، من الأكثر موثوقية إلى الأقل: يدوي (نسبته أنت بنفسك)، ومؤكد، ومرجّح، ومحتمل، ومشكوك فيه، وتقديري؛ مرّر المؤشر فوق الشارة لترى معناها. لا تسمح بالحذف الجماعي إلا المستويات يدوي ومؤكد ومرجّح ومحتمل. وتظهر العناصر قيد التحديد التي ليس لها أي مالك على أنها «غير محدد».','What to do with items to identify: first, check whether the record or file belongs to a custom plugin or active feature of your site. If it does, no action is needed. If you are confident it is orphaned clutter from something you removed, you can delete it via the standard checkbox interface — a backup is created first as with all deletions.'=>'ماذا تفعل مع العناصر قيد التحديد: أولاً، تحقق مما إذا كان السجل أو الملف ينتمي إلى إضافة مخصصة أو ميزة نشطة في موقعك. إذا كان كذلك، فلا حاجة لأي إجراء. إذا كنت متأكداً من أنه فوضى يتيمة من شيء أزلته، يمكنك حذفه عبر واجهة خانات الاختيار القياسية — يُنشأ نسخ احتياطي أولاً كما هو الحال مع جميع عمليات الحذف.','Attribute manually: when you know who owns an item to identify, the "Attribute manually" panel above the list lets you teach WPOptimizing so the item leaves “To identify”. Open its own help — the ? next to the panel title — for the full guide.'=>'الإسناد اليدوي: عندما تعرف مالك عنصر «قيد التحديد»، تتيح لك لوحة «إسناد يدوي» أعلى القائمة تعليم ذلك لـ WPOptimizing كي يغادر العنصر «قيد التحديد». افتح مساعدتها الخاصة — علامة ؟ بجوار عنوان اللوحة — للدليل الكامل.','The dataset grows with each contribution. Items still to identify today may be automatically attributed after the next dataset update.'=>'تنمو مجموعة البيانات مع كل مساهمة. العناصر التي لا تزال قيد التحديد اليوم قد تُنسب تلقائياً بعد التحديث التالي لمجموعة البيانات.','Every database record whose stored value is empty, with a Status column telling you whether each one is To identify, Orphan, Inactive or In use. A convenient way to clear leftover keys that hold nothing.'=>'كل سجل في قاعدة البيانات قيمته فارغة، مع عمود حالة يوضّح ما إذا كان قيد التحديد أو يتيمًا أو غير نشط أو قيد الاستخدام. طريقة مريحة لتنظيف المفاتيح المتبقية التي لا تخزّن شيئًا.','This section lists options and post/user/term meta whose value is empty: NULL, an empty string, or an empty serialized/JSON structure (a:0:{}, [], {}). It deliberately ignores values like 0 or false, which carry meaning. A meta key appears only when EVERY record under it is empty, never when only some are; the “Empty records” column then shows the total — all of them empty.'=>'يسرد هذا القسم الخيارات وبيانات تعريف المنشور/المستخدم/المصطلح التي تكون قيمتها فارغة: NULL أو سلسلة فارغة أو بنية متسلسلة/JSON فارغة (a:0:{}، []، {}). ويتجاهل عمدًا قيمًا مثل 0 أو false لأن لها معنى. لا يظهر مفتاح البيانات إلا عندما تكون كل سجلاته فارغة، ولا يظهر أبدًا عندما يكون بعضها فقط فارغًا؛ عندئذٍ يعرض عمود «السجلات الفارغة» الإجمالي — كلها فارغة.','The Status column reuses the same attribution engine as the rest of the plugin, so each row is marked To identify (no known owner), Orphan (owner not installed), Inactive (owner installed but off) or In use (owner running now). This lets you clean with judgement instead of blindly.'=>'يعيد عمود الحالة استخدام محرّك الإسناد نفسه المستخدم في بقية الإضافة، لذا يُوسَم كل صف بأنه قيد التحديد (لا مالك معروف) أو يتيم (المالك غير مثبَّت) أو غير نشط (المالك مثبَّت لكنه متوقف) أو قيد الاستخدام (المالك يعمل). يتيح لك ذلك التنظيف بحكمة بدلًا من العشوائية.','Safety: records owned by an active extension or by WordPress core are shown read-only — they have no checkbox and cannot be deleted here, because a key may be empty on purpose and removing it could break the owner. Only empties marked To identify, Orphan or Inactive can be selected.'=>'الأمان: تُعرض سجلات إضافة نشطة أو نواة ووردبريس للقراءة فقط — فلا توجد لها خانة اختيار ولا يمكن حذفها هنا، لأن المفتاح قد يكون فارغًا عن قصد وقد تؤدي إزالته إلى تعطيل المالك. لا يمكن تحديد سوى الفارغة الموسومة بقيد التحديد أو يتيمة أو غير نشطة.','Empty-row deletion is backup-first and removes only the empty rows for a key, never the non-empty ones that share the same name — so it is fully restorable from the Backups tab.'=>'يتم حذف الصفوف الفارغة مع نسخة احتياطية مسبقة، ولا يزيل سوى الصفوف الفارغة لمفتاح ما، ولا يمس أبدًا غير الفارغة التي تحمل الاسم نفسه — لذا يمكن استعادته بالكامل من تبويب النسخ الاحتياطية.','Manually tell WPOptimizing who owns items it could not attribute. Matched items leave “To identify” and move to Orphan or Inactive depending on whether the owner is installed.'=>'أخبر WPOptimizing يدويًا بمالك العناصر التي تعذّر إسنادها. تغادر العناصر المطابِقة قائمة «قيد التحديد» وتنتقل إلى «يتيمة» أو «غير نشطة» بحسب ما إذا كان المالك مثبَّتًا.','Use this panel when you know who owns an item to identify but the shared dataset does not. Add a rule that matches either by “contains” — a family of items that share a fragment, e.g. wysija → MailPoet — or by “exact”, a single specific value. Rules are applied at display time, so matched items leave “To identify” on the next load without re-scanning, and are re-classified as Orphan (owner not installed) or Inactive (owner installed but currently off).'=>'استخدم هذه اللوحة عندما تعرف مالك عنصر «قيد التحديد» بينما لا تعرفه مجموعة البيانات المشتركة. أضف قاعدة تطابق إمّا بـ«يحتوي» — مجموعة من العناصر تشترك في جزء، مثل wysija → MailPoet — أو بـ«تطابق تام»، أي قيمة واحدة محددة. تُطبَّق القواعد وقت العرض، لذا تغادر العناصر المطابِقة «قيد التحديد» في التحميل التالي دون إعادة فحص، ويُعاد تصنيفها إلى «يتيمة» (المالك غير مثبَّت) أو «غير نشطة» (المالك مثبَّت لكنه معطَّل حاليًا).','Pick one or more owners per rule. The owner box searches as you type across three sources: your installed plugins and themes, the public wordpress.org repository, and the shared knowledge base — so you can pin the exact extension even if it is no longer installed, or type a slug for one that is not listed. Choosing several owners at once (e.g. MailPoet and MailPoet Premium) creates one rule per owner, which is useful when a value belongs to a plugin and its add-ons.'=>'اختر مالكًا واحدًا أو أكثر لكل قاعدة. يبحث حقل المالك أثناء الكتابة في ثلاثة مصادر: إضافاتك وقوالبك المثبَّتة، ومستودع wordpress.org العام، وقاعدة المعرفة المشتركة — بحيث يمكنك تحديد الإضافة الدقيقة حتى وإن لم تعد مثبَّتة، أو كتابة slug لإضافة غير مدرجة. اختيار عدة مالكين دفعة واحدة (مثل MailPoet و MailPoet Premium) ينشئ قاعدة لكل مالك، وهو مفيد عندما تنتمي قيمة ما إلى إضافة وملحقاتها.','Faster still: tick the rows you recognise in the “To identify” list, click “Attribute selected”, and choose the owner(s) once — WPOptimizing creates one exact rule per selected row and owner and opens this panel with them prefilled.'=>'أسرع من ذلك: ضع علامة على الصفوف التي تعرفها في قائمة «قيد التحديد»، وانقر «إسناد المحدد»، واختر المالك (أو المالكين) مرة واحدة — يُنشئ WPOptimizing قاعدة تطابق تام لكل صف محدَّد ومالك، ويفتح هذه اللوحة مع تعبئتها مسبقًا.','If the owner you pick is currently active, WPOptimizing also refuses to delete the matched items — including items already ticked in a list that was loaded before you added the rule. An owner that is switched off or no longer installed does not protect anything: attributing an orphan is how you get to delete it knowingly.'=>'إذا كان المالك الذي تختاره مُفعَّلًا، فسيرفض WPOptimizing أيضًا حذف العناصر المطابقة — بما فيها العناصر المحدَّدة مسبقًا في قائمة حُمِّلت قبل إضافة القاعدة. أما المالك المعطَّل أو غير المثبَّت فلا يحمي شيئًا: فإسناد عنصر يتيم هو بالضبط ما يتيح لك حذفه عن معرفة.','The rules you have added are listed under the form with their own search, owner filter and pagination; click “Remove” to delete a rule. Removing a rule sends its matched items back to “To identify” on the next load.'=>'تُدرَج القواعد التي أضفتها أسفل النموذج مع بحث خاص بها وعامل تصفية حسب المالك وترقيم صفحات؛ انقر «إزالة» لحذف قاعدة. إزالة قاعدة تعيد عناصرها المطابِقة إلى «قيد التحديد» في التحميل التالي.','With your consent (the shared-dataset setting), each rule is also sent — batched and off-request, never blocking the page — to the shared knowledge base, where it is verified before being promoted. Your manual hints improve automatic attribution for everyone over time.'=>'بموافقتك (إعداد مجموعة البيانات المشتركة)، تُرسَل كل قاعدة أيضًا — على دفعات وخارج الطلب، دون أن تحجب الصفحة أبدًا — إلى قاعدة المعرفة المشتركة، حيث يتم التحقق منها قبل اعتمادها. تحسّن إرشاداتك اليدوية الإسناد التلقائي للجميع مع مرور الوقت.','Ask the shared knowledge base to suggest the owner of database records still to identify. After each analysis the sure ones are applied on their own; you confirm the rest, and nothing is ever deleted automatically.'=>'اطلب من قاعدة المعرفة المشتركة أن تقترح مالك سجلات قاعدة البيانات التي لا تزال «قيد التحديد». بعد كل تحليل تُطبَّق الاقتراحات المؤكدة تلقائيًا؛ وتؤكّد أنت الباقي، ولا يُحذف أي شيء تلقائيًا أبدًا.','The assistant appears under Analysis results › To identify › Database and under Orphans › Database. It sends only the identifier NAMES of the records shown (option, meta, cron and table names — never their values or any content) to the shared knowledge base, which returns the most likely owning plugin or theme for each one. On Orphans it also compares the answer with the owner already on screen and flags the records where the two disagree, which is what you want to see before deleting anything.'=>'يظهر المساعد في «نتائج التحليل › قيد التحديد › قاعدة البيانات» وفي «يتيمة › قاعدة البيانات». يرسل أسماء المعرّفات المعروضة فقط (أسماء الخيارات والبيانات الوصفية والمهام المجدولة والجداول — ولا يرسل أبدًا قيمها ولا أي محتوى) إلى مجموعة البيانات المشتركة، التي تعيد لكل منها الإضافة أو القالب الأرجح أنه مالكها. وفي «يتيمة» يقارن الإجابة أيضًا بالمالك المعروض على الشاشة ويُعلّم السجلات التي يختلفان فيها، وهو بالضبط ما تريد رؤيته قبل حذف أي شيء.','Each result carries a verdict: Sure or Likely (a confident, namespace-backed match), Possible (a single-owner hint to confirm), or Ambiguous / No data (shown for review only, with no owner). Confident results offer an Accept button that creates an exact manual attribution rule — exactly as if you had typed it yourself — so the record leaves “To identify” on the next load and your choice also feeds the knowledge base. The assistant is retrieval over the shared knowledge base, not a language model: it can only answer with owners that are already recorded there, and it abstains instead of guessing. When there are several Sure results, “Accept all sure suggestions” accepts them in one go.'=>'يحمل كل نتيجة حكمًا: مؤكد أو مرجّح (تطابق موثوق يسنده نطاق الأسماء)، أو محتمل (قرينة على مالك واحد، للتأكيد)، أو غامض / لا بيانات (للمراجعة فقط، دون مالك). تتيح النتائج الموثوقة زر «قبول» الذي يُنشئ قاعدة إسناد يدوية دقيقة — تمامًا كما لو كتبتها بنفسك — فيخرج السجل من «قيد التحديد» عند التحميل التالي، ويغذّي اختيارك قاعدة المعرفة أيضًا. المساعد استرجاعٌ من مجموعة البيانات المشتركة لا نموذج لغوي: لا يستطيع الإجابة إلا بمالكين مسجّلين فيها، ويمتنع بدل أن يخمّن. وعندما تكون هناك عدة نتائج «مؤكد»، يقبلها زر «قبول كل الاقتراحات المؤكدة» دفعة واحدة.','Only the Sure verdicts are applied on their own: after each analysis, in the background, the records still to identify are asked about, and the Sure answers become Likely attributions — below anything this site saw itself, never manual rules, and they never delete anything. Everything else waits for you. A record attributed to a plugin that is not installed becomes an orphan like any other, deleted only when you choose to and with a backup first. The assistant is opt-in: it requires the shared-dataset setting to be on, since it relies on the same anonymous knowledge base you contribute to.'=>'لا تُطبَّق تلقائيًا إلا الأحكام «مؤكد»: بعد كل تحليل، وفي الخلفية، يُسأل المساعد عن السجلات التي لا تزال قيد التحديد، وتصبح الإجابات «مؤكد» نسبًا بدرجة «مرجّح» — أدنى من كل ما رآه هذا الموقع بنفسه، ولا تصبح أبدًا قواعد يدوية، ولا تحذف أي شيء أبدًا. أما كل ما عدا ذلك فينتظر قرارك. والسجل المنسوب إلى إضافة غير مثبَّتة يصبح يتيمًا مثل أي سجل آخر، ولا يُحذف إلا حين تقرر ذلك وبعد نسخة احتياطية مسبقة. المساعد اختياري: يتطلّب تفعيل إعداد مجموعة البيانات المشتركة، لأنه يعتمد على قاعدة المعرفة المجهولة نفسها التي تسهم فيها.','Records and files confirmed as belonging to plugins or themes that are no longer installed. The manifest attributes them with high certainty, so nothing on the site uses them. Delete them unless you plan to reinstall that extension and want to keep its settings; orphan deletions are backed up automatically beforehand.'=>'سجلات وملفات تأكَّد انتماؤها إلى إضافات أو قوالب لم تعد مثبَّتة. يُسندها البيان بدرجة عالية من اليقين، لذا لا يستخدمها أي شيء في الموقع. احذفها ما لم تكن تنوي إعادة تثبيت تلك الإضافة وتريد الاحتفاظ بإعداداتها؛ تُنسخ عمليات حذف العناصر اليتيمة احتياطيًا تلقائيًا قبل تنفيذها.','Items are listed as Orphans when the dataset can attribute them to a specific extension slug AND that slug is not present in the list of installed plugins or themes. Its confidence must be Possible or higher (Manual, Sure, Likely or Possible) for the item to be classified as an Orphan; with Doubtful or Estimated it stays in “To identify”.'=>'تُدرَج العناصر كيتيمة عندما تستطيع مجموعة البيانات إسنادها إلى slug امتداد محدد وذلك الـ slug غير موجود في قائمة الإضافات أو القوالب المثبتة. يجب أن تكون ثقته «محتمل» أو أعلى (يدوي أو مؤكد أو مرجّح أو محتمل) كي يُصنَّف العنصر كيتيم؛ وإذا كانت «مشكوك فيه» أو «تقديري» يبقى في «قيد التحديد».','Database orphans include options (rows in wp_options), custom tables, user roles, post meta keys, taxonomies, and custom post type records left by plugins that were deleted without running their uninstall routines. File orphans are files and directories inside wp-content that belonged to a plugin or theme folder that is now gone.'=>'تشمل أيتام قاعدة البيانات الخيارات (صفوف في wp_options)، والجداول المخصصة، وأدوار المستخدمين، ومفاتيح post meta، والتصنيفات، وسجلات أنواع المنشور المخصصة التي تركتها إضافات محذوفة دون تشغيل روتين إلغاء التثبيت. أيتام الملفات هي ملفات ومجلدات داخل wp-content كانت تنتمي إلى مجلد إضافة أو قالب لم يعد موجوداً.','Orphan deletion is backup-first: WPOptimizing exports the affected rows (for database items) or records the file paths (for filesystem items) into a restorable backup entry before removing anything. If you delete something by mistake, go to the Backups tab and restore the relevant operation.'=>'يتم حذف اليتيم مع نسخة احتياطية مسبقة: يُصدّر WPOptimizing الصفوف المتأثرة (لعناصر قاعدة البيانات) أو يسجّل مسارات الملفات (لعناصر نظام الملفات) في مُدخل نسخ احتياطي قابل للاستعادة قبل إزالة أي شيء. وإذا حذفت شيئًا بالخطأ، افتح تبويب النسخ الاحتياطية واستعد العملية المعنية.','Tip: use the extension filter above the table to delete all orphans from a single plugin at once, rather than selecting rows one by one.'=>'نصيحة: استخدم فلتر الامتداد أعلى الجدول لحذف جميع أيتام إضافة واحدة دفعة واحدة، بدلاً من تحديد الصفوف واحداً تلو الآخر.','Protected items: you can mark any database element as protected so it is never deleted, even by a "delete all" action, regardless of how the attribution heuristics classify it. Click the shield icon next to an item in the To identify, Orphans, Inactive or Empty lists to protect it (the shield turns green) or click it again to unprotect. The shield is not shown under In use: those records belong to currently-active extensions and are never a deletion target, so there is nothing to protect them from. To protect (or unprotect) many at once, tick the rows and use the single "Protect selected" button: it unprotects when every ticked row is already protected, and protects otherwise (leaving any already-protected rows untouched). This is a hard safety net for the rare case where an item is misattributed. Developers can protect items programmatically by returning false from the wpoptimizing_can_delete_item filter.'=>'العناصر المحمية: يمكنك تعليم أي عنصر في قاعدة البيانات كمحمي بحيث لا يُحذف أبدًا، حتى عبر إجراء «حذف الكل»، بغض النظر عن كيفية تصنيف خوارزميات الإسناد له. انقر على أيقونة الدرع بجوار عنصر في قوائم قيد التحديد أو يتيمة أو غير نشط أو فارغة لحمايته (يتحول الدرع إلى الأخضر) أو انقر مرة أخرى لإلغاء الحماية. لا يظهر الدرع في قيد الاستخدام: تلك السجلات تخص إضافات نشطة حاليًا ولا تكون أبدًا هدفًا للحذف، لذا لا يوجد ما يستدعي حمايتها منه. لحماية (أو إلغاء حماية) عدة عناصر دفعة واحدة، حدّد الصفوف واستخدم الزر الوحيد «حماية المحدد»: يلغي الحماية عندما تكون كل الصفوف المحددة محمية بالفعل، ويحمي في الحالات الأخرى (دون المساس بالصفوف المحمية بالفعل). هذه شبكة أمان للحالة النادرة التي يُسنَد فيها عنصر بشكل خاطئ. يمكن للمطورين حماية العناصر برمجيًا بإرجاع false من المرشّح wpoptimizing_can_delete_item.','Database records and files belonging to plugins or themes that are installed but currently inactive. These items are not needed while the extension is off, but may be required again if it is reactivated. The Plugins & Themes sub-tab lets you uninstall inactive extensions directly.'=>'سجلات قاعدة البيانات والملفات التابعة لإضافات أو قوالب مثبتة لكنها غير نشطة حالياً. لا حاجة لهذه العناصر طالما الإضافة معطّلة، غير أنها قد تكون مطلوبة مجدداً عند تفعيلها. تتيح لك علامة تبويب الإضافات والقوالب الفرعية إلغاء تثبيت الإضافات غير النشطة مباشرةً.','Inactive items are a middle ground: the plugin is still installed (its files are present), but it is not active, so its database entries and any files it manages outside its own plugin folder are serving no purpose right now. Whether to delete them depends on your intent: if the plugin is being kept around for occasional use, leave its data alone; if you know you will never reactivate it, uninstall it properly.'=>'العناصر غير النشطة هي وسط بين الأمرين: الإضافة لا تزال مثبتة (ملفاتها موجودة)، لكنها غير نشطة، لذا إدخالاتها في قاعدة البيانات وأي ملفات تديرها خارج مجلدها لا تؤدي أي غرض حالياً. ما إذا كان يجب حذفها يعتمد على نيتك: إذا كانت الإضافة محتفظاً بها للاستخدام العرضي، اترك بياناتها وشأنها؛ وإذا كنت تعلم أنك لن تُعيد تفعيلها أبداً، فقم بإلغاء تثبيتها بشكل صحيح.','The Plugins & Themes sub-tab lists every inactive plugin and theme with a checkbox for selection. Clicking Delete runs the plugin\'s own uninstall hook (if it has one) and removes its files. The "Also remove associated data" checkbox cascade-deletes the database and filesystem items associated with those slugs from the Inactive lists at the same time.'=>'تسرد علامة التبويب الفرعية Plugins & Themes كل إضافة وقالب غير نشط مع خانة اختيار للتحديد. يؤدي النقر على Delete إلى تشغيل hook إلغاء التثبيت الخاص بالإضافة (إن وُجد) وإزالة ملفاتها. تُنفّذ خانة الاختيار «إزالة البيانات المرتبطة أيضاً» حذفاً متتالياً لعناصر قاعدة البيانات ونظام الملفات المرتبطة بتلك الـ slugs من قوائم Inactive في آنٍ واحد.','Caution: deactivating a plugin does not remove its data. Uninstalling it may, depending on whether the plugin\'s author implemented an uninstall routine. WPOptimizing\'s cascade-delete fills that gap for items it can attribute, but it cannot know about data a plugin stores in non-standard locations.'=>'تنبيه: تعطيل إضافة لا يزيل بياناتها. إلغاء تثبيتها قد يفعل ذلك، وهذا يعتمد على ما إذا كان مطوّر الإضافة قد نفّذ روتين إلغاء التثبيت. يملأ حذف الشلال في WPOptimizing هذه الفجوة للعناصر التي يمكنه إسنادها، لكنه لا يستطيع معرفة البيانات التي تخزّنها الإضافة في مواقع غير قياسية.','Read-only view of records and files attributed to currently active plugins or themes. No deletion is allowed here. It is an audit view so you can see what active extensions are storing and how much space they use.'=>'عرض للقراءة فقط للسجلات والملفات المنسوبة إلى الإضافات أو القوالب النشطة حالياً. لا يُسمح بأي حذف هنا. إنه عرض تدقيق لرؤية ما تخزنه الإضافات النشطة ومقدار المساحة التي تستخدمها.','The In use list (Analysis results › In use) gives you a complete picture of what each running plugin or theme is storing in your database and filesystem. Because the extension is active, deleting these items would break functionality — the tab is intentionally read-only. Its purpose is transparency and accountability.'=>'توفر قائمة قيد الاستخدام (نتائج التحليل › قيد الاستخدام) صورة كاملة لما تخزّنه كل إضافة أو قالب نشط في قاعدة البيانات ونظام الملفات. نظراً لأن الامتداد نشط، فإن حذف هذه العناصر سيكسر الوظائف — علامة التبويب للقراءة فقط بشكل مقصود. هدفها الشفافية والمساءلة.','Use the extension filter to drill down into a single plugin and see every option, post meta key, custom table or file it owns. This is useful when auditing a new plugin before committing to it, or when investigating unexpected database growth.'=>'استخدم فلتر الامتداد للتعمق في إضافة واحدة ورؤية كل خيار ومفتاح post meta وجدول مخصص أو ملف تمتلكه. هذا مفيد عند تدقيق إضافة جديدة قبل الالتزام بها، أو عند التحقيق في نمو غير متوقع لقاعدة البيانات.','Each item carries its confidence level (Manual, Sure, Likely, Possible, Doubtful, Estimated or Undetermined), which says how its owner was established: from your own rule, captured live, read from the code or the shared dataset, or guessed from a prefix. Here it matters only for correcting a wrong owner or protecting a record, since nothing in this list is deleted.'=>'يحمل كل عنصر مستوى الثقة الخاص به (يدوي، مؤكد، مرجّح، محتمل، مشكوك فيه، تقديري أو غير محدد)، الذي يوضح كيف حُدِّد مالكه: من قاعدتك الخاصة، أو التُقط مباشرةً أثناء التشغيل، أو قُرئ من الشيفرة أو من مجموعة البيانات المشتركة، أو خُمِّن من بادئة. وهنا لا يهم إلا لتصحيح مالك خاطئ أو لحماية سجل، إذ لا يُحذف أي شيء من هذه القائمة.','Tracks your site\'s database size, autoload weight, table overhead and other metrics over time. A snapshot is recorded automatically after every scan and cleanup so you can measure the impact of each action.'=>'يتتبع حجم قاعدة بيانات موقعك ووزن التحميل التلقائي والحِمل الزائد للجداول ومقاييس أخرى عبر الزمن. يتم تسجيل لقطة تلقائياً بعد كل فحص وتنظيف حتى تتمكن من قياس تأثير كل إجراء.','Every time a scan completes or a cleanup runs, WPOptimizing captures a snapshot of key metrics: total database size, autoloaded options weight, total table overhead, number of orphaned records, and more. These snapshots build a timeline you can browse to see whether your site is getting leaner over time.'=>'في كل مرة تكتمل فيها عملية فحص أو يتم تشغيل تنظيف، يلتقط WPOptimizing لقطة من المقاييس الرئيسية: إجمالي حجم قاعدة البيانات، ووزن الخيارات المحمَّلة تلقائياً، وإجمالي حمل الجداول، وعدد السجلات اليتيمة، وغير ذلك. تبني هذه اللقطات جدولاً زمنياً يمكنك تصفحه لمعرفة ما إذا كان موقعك يصبح أخف مع مرور الوقت.','The headline cards at the top summarise the metrics that matter most — including a Server TTFB card with a trend sparkline — each showing the current value, the change since the baseline, and a mini chart of its evolution. A card always shows the latest recorded value of its metric, even if the most recent snapshot happened to be a database-only scan that did not capture it, so the same set of cards appears consistently.'=>'تلخّص البطاقات البارزة في الأعلى أهم المقاييس — بما في ذلك بطاقة زمن أول بايت (TTFB) للخادم مع خطها البياني المصغّر للاتجاه — وتعرض كلٌّ منها القيمة الحالية والتغيّر منذ خط الأساس ورسمًا بيانيًا مصغّرًا لتطوّرها. تعرض البطاقة دائمًا آخر قيمة مسجّلة لمقياسها، حتى لو كانت أحدث لقطة فحصًا لقاعدة البيانات فقط لم يلتقطها، بحيث تظهر مجموعة البطاقات نفسها باتساق.','The baseline is the very first snapshot recorded. All subsequent values are shown relative to it so you can see absolute improvements at a glance. You can reset the baseline at any time — for example, after a major cleanup — to start measuring from a new reference point.'=>'الخط الأساسي هو أول لقطة مسجّلة. جميع القيم اللاحقة تُعرض نسبةً إليه حتى تتمكن من رؤية التحسينات المطلقة بنظرة واحدة. يمكنك إعادة تعيين الخط الأساسي في أي وقت — مثلاً، بعد تنظيف رئيسي — للبدء في القياس من نقطة مرجعية جديدة.','The Export button streams the full timeline as a CSV file. Import it into a spreadsheet to build your own charts, share it with a client, or keep it as an audit record.'=>'يُدفق زر Export الجدول الزمني الكامل كملف CSV. استورده في جدول بيانات لبناء مخططاتك الخاصة، أو مشاركته مع عميل، أو الاحتفاظ به كسجل تدقيق.','Browse the timeline with the event and date filters, per-page and search — the same controls as the other tables. You decide how long snapshots are kept with the "Keep timeline data" control below the timeline (Forever, 3 months by default, 6 months or 1 year); older ones are pruned automatically each day, while the pinned baseline is always kept.'=>'تصفّح المخطط الزمني بمرشّحات الحدث والتاريخ، وعدد العناصر في الصفحة، والبحث — نفس عناصر التحكم في الجداول الأخرى. أنت تقرّر مدة الاحتفاظ باللقطات عبر عنصر "الاحتفاظ ببيانات المخطط الزمني" أسفل المخطط (دائمًا، 3 أشهر افتراضيًا، 6 أشهر أو سنة واحدة)؛ وتُزال الأقدم تلقائيًا كل يوم، بينما يُحتفظ دائمًا بخط الأساس المثبّت.','A change journal for the whole site: what other plugins and themes add or remove over time — tables, options, post/user meta keys, scheduled events and top-level files — each dated and attributed when possible.'=>'سجل تغييرات للموقع بأكمله: ما تضيفه أو تزيله الإضافات والقوالب الأخرى بمرور الوقت — الجداول، والخيارات، ومفاتيح البيانات الوصفية للمقالات/المستخدمين، والأحداث المجدولة، وملفات المستوى الأعلى — كل منها مؤرَّخ ومنسوب عند الإمكان.','When WPOptimizing is installed it captures a baseline signature of your site: the set of database tables, option names, post and user meta keys, scheduled cron hooks, and the top-level entries under plugins, themes, mu-plugins and uploads. From then on it compares the current state against that baseline at meaningful moments and records what changed.'=>'عند التثبيت، يلتقط WPOptimizing توقيع خط أساس لموقعك: مجموعة جداول قاعدة البيانات، وأسماء الخيارات، ومفاتيح البيانات الوصفية للمقالات والمستخدمين، وخطافات cron المجدولة، وإدخالات المستوى الأعلى ضمن plugins وthemes وmu-plugins وuploads. ومنذ ذلك الحين يقارن الحالة الحالية بذلك الأساس في اللحظات المهمة ويسجّل ما تغيّر.','A change is captured whenever a plugin or theme is installed, activated, deactivated, deleted or updated, and after each analysis. This has no per-page-load cost — nothing is measured on normal requests. When the change rides a plugin or theme action, that extension is recorded as responsible, so you can see exactly what a newly installed plugin added to your database and filesystem.'=>'يُلتقط التغيير في كل مرة يتم فيها تثبيت إضافة أو قالب أو تفعيله أو تعطيله أو حذفه أو تحديثه، وبعد كل تحليل. لا يترتب على ذلك أي تكلفة لكل تحميل صفحة — لا يُقاس أي شيء في الطلبات العادية. وعندما يصدر التغيير عن إجراء إضافة أو قالب، تُسجَّل تلك الإضافة كمسؤولة، فترى بالضبط ما الذي أضافته إضافة مثبَّتة حديثًا إلى قاعدة بياناتك ونظام ملفاتك.','Each entry shows the date, whether the item was added or removed, its type, its name, and the responsible extension (or Unknown for background changes). Filter by type or change and search by name, with the same controls as the other tables. The journal is capped and kept out of autoload, so it never weighs on the site; you can clear it at any time and tracking continues from the current baseline.'=>'يعرض كل سجل التاريخ، وما إذا كان العنصر قد أُضيف أو أُزيل، ونوعه، واسمه، والإضافة المسؤولة (أو «غير معروف» للتغييرات في الخلفية). صفِّ حسب النوع أو التغيير وابحث بالاسم، بنفس عناصر التحكم في الجداول الأخرى. السجل محدود وخارج التحميل التلقائي، لذا لا يثقل الموقع أبدًا؛ يمكنك مسحه في أي وقت وتستمر المتابعة من خط الأساس الحالي.','Every change WPOptimizing makes to your data is backed up first: deletions (orphans, empty rows, media, the general cleanup and its scheduled and automatic runs) and changes (autoload flags, scheduled tasks, .htaccess and wp-config.php edits). Backups are grouped by operation so you can find and restore exactly what a specific action changed. Manual backups can also be created at any time.'=>'كل تغيير يجريه WPOptimizing على بياناتك يُنسخ احتياطيًا أولًا: عمليات الحذف (اليتيم، والصفوف الفارغة، والوسائط، والتنظيف العام وتشغيلاته المجدولة والتلقائية) والتعديلات (علامات التحميل التلقائي، والمهام المجدولة، وتعديلات .htaccess وwp-config.php). وتُجمَّع النسخ حسب العملية، فتجد وتستعيد بالضبط ما غيّره إجراء بعينه. ويمكن أيضًا إنشاء نسخ يدوية في أي وقت.','Before WPOptimizing removes or changes database rows, it serialises them into a backup file under wp-content/wpoptimizing/backups/ (not in the database). For filesystem deletions it writes a manifest and copies each file alongside it; an edited file (.htaccess, wp-config.php) is copied whole. Each entry is tagged with the operation that created it (orphan deletion, database cleanup, autoload change, media deletion, etc.) and a timestamp, so you can quickly find the one you need. If the backup cannot be written — disk full, permissions, or the size limit set in Settings — the action does not run.'=>'قبل أن يزيل WPOptimizing صفوفًا من قاعدة البيانات أو يغيّرها، يحوّلها إلى ملف نسخ احتياطي داخل wp-content/wpoptimizing/backups/ (لا داخل قاعدة البيانات). وفي حذف نظام الملفات يكتب بيانًا وينسخ كل ملف بجواره؛ أما الملف المعدَّل (.htaccess وwp-config.php) فيُنسخ كاملًا. ويحمل كل مُدخل وسم العملية التي أنشأته (حذف اليتيم، وتنظيف قاعدة البيانات، وتغيير التحميل التلقائي، وحذف الوسائط وغيرها) وطابعًا زمنيًا، لتجد بسرعة ما تحتاجه. وإذا تعذّرت كتابة النسخة الاحتياطية — لامتلاء القرص أو بسبب الأذونات أو حد الحجم المضبوط في الإعدادات — فلا يُنفَّذ الإجراء.','To restore a backup, open the Backups tab, find the entry, and click Restore. For database backups this re-inserts the rows keeping their original IDs; for file backups it copies the files back to their original paths and reports any it could not restore.'=>'لاستعادة نسخة، افتح تبويب النسخ الاحتياطية، وابحث عن المُدخل، ثم انقر «استعادة». في نسخ قاعدة البيانات تُعاد الصفوف مع الحفاظ على معرّفاتها الأصلية؛ وفي نسخ الملفات تُنسخ الملفات إلى مساراتها الأصلية مع الإبلاغ عمّا تعذّرت استعادته.','Old backups are pruned automatically according to the maximum count and maximum age limits set in Settings. You can also delete individual backups manually once you are confident the cleanup was correct. Creating a manual backup from the Backups tab captures the current state of a table or option set you specify.'=>'يتم تقليم النسخ الاحتياطية القديمة تلقائياً وفقاً لحدود الحد الأقصى للعدد والعمر المحددة في Settings. يمكنك أيضاً حذف النسخ الاحتياطية الفردية يدوياً بمجرد التأكد من أن التنظيف كان صحيحاً. إنشاء نسخة احتياطية يدوية من علامة التبويب Backups يلتقط الحالة الراهنة لجدول أو مجموعة خيارات تحددها.','Clean uninstall: by default, deleting the plugin from the Plugins screen removes every trace it created — all settings and transients, scheduled tasks, the object-cache and database drop-ins, the runtime mu-plugin, every backup and scan file, and the WebP/AVIF copies it generated. Your already-optimized images are kept (only the extra next-gen copies and the backups are removed; originals are not restored). You can turn this off in Settings if you plan to reinstall and want to keep your configuration and backups. Note that deactivating the plugin never deletes anything — only deleting it does.'=>'إلغاء تثبيت نظيف: افتراضياً، يؤدي حذف الإضافة من صفحة الإضافات إلى إزالة كل أثر أنشأته — جميع الإعدادات والعناصر المؤقتة، والمهام المجدولة، وإضافات object-cache وقاعدة البيانات (drop-ins)، وإضافة mu-plugin الخاصة بوقت التشغيل، وكل نسخة احتياطية وملف فحص، ونسخ WebP/AVIF التي ولّدتها. تبقى صورك المُحسَّنة بالفعل كما هي (تُزال فقط نسخ الجيل التالي الإضافية والنسخ الاحتياطية؛ ولا تُستعاد الأصول). يمكنك تعطيل ذلك من الإعدادات إذا كنت تنوي إعادة التثبيت وترغب في الاحتفاظ بإعداداتك ونسخك الاحتياطية. لاحظ أن تعطيل الإضافة لا يحذف أي شيء أبداً — الحذف وحده يفعل ذلك.','Quick Profiles are the fastest way to configure WPOptimizing for your site type. Each profile bundles a curated set of cleanup rules together with the appropriate performance settings: Safe, Blog and Membership stick to the basic tasks; WooCommerce adds the store-specific ones (sessions, orphaned variations, Action Scheduler); Agency (maximum) adds duplicate metadata and unused tags as well.'=>'الملفات الشخصية السريعة هي أسرع طريقة لتكوين WPOptimizing لنوع موقعك. يجمع كل ملف شخصي مجموعة منتقاة من قواعد التنظيف جنباً إلى جنب مع إعدادات الأداء المناسبة: تقتصر آمنة ومدونة والعضوية على المهام الأساسية؛ ويضيف WooCommerce المهام الخاصة بالمتجر (الجلسات، والتنويعات اليتيمة، وAction Scheduler)؛ وتضيف وكالة (أقصى حد) أيضاً البيانات الوصفية المكرّرة والوسوم غير المستخدمة.','Applying a profile also configures the Cache tab automatically: the appropriate cache backend is installed, query deduplication is enabled or disabled based on the profile\'s recommendation, and the heartbeat rate is set. You can override any of these from the Cache tab after applying a profile.'=>'تطبيق ملف شخصي يُكوّن أيضاً علامة التبويب Cache تلقائياً: يُثبَّت خادم التخزين المؤقت المناسب، ويُفعَّل أو يُعطَّل إلغاء تكرار الاستعلامات بناءً على توصية الملف الشخصي، وتُعيَّن معدل Heartbeat. يمكنك تجاوز أي من هذه من علامة التبويب Cache بعد تطبيق ملف شخصي.','Backup retention: set a maximum number of backup entries, a maximum age in days and a maximum total size. Entries beyond the count or age limit are pruned automatically; when a new backup would cross the size limit, the action stops instead of filling the disk. The minimum retention is 1 entry and 1 day — WPOptimizing always keeps at least the most recent backup.'=>'الاحتفاظ بالنسخ الاحتياطية: حدد حداً أقصى لعدد إدخالات النسخ الاحتياطي وعمراً أقصى بالأيام وحجماً إجمالياً أقصى. تُقلَّم الإدخالات التي تتجاوز حد العدد أو العمر تلقائياً؛ وعندما تتجاوز نسخة جديدة حد الحجم، يتوقف الإجراء بدلاً من ملء القرص. الاحتفاظ الأدنى هو إدخال واحد ويوم واحد — يحتفظ WPOptimizing دائماً بأحدث نسخة احتياطية على الأقل.','License: enter your license key here to activate Pro features (deletion of attributed records, unlimited scan rows, media deduplication). The key is validated against the wpoptimizing.com API. Internet access is required for license checks; they are rate-limited to once per hour.'=>'الترخيص: أدخل مفتاح ترخيصك هنا لتفعيل ميزات Pro (حذف السجلات المنسوبة، صفوف فحص غير محدودة، إلغاء تكرار الوسائط). يُتحقق من المفتاح مقابل واجهة برمجة تطبيقات wpoptimizing.com. مطلوب الوصول إلى الإنترنت لفحوصات الترخيص؛ محدودة بمرة واحدة في الساعة.','Send a JSON POST to an external URL whenever WPOptimizing finishes a scan, a cleanup, a deletion or a dataset upload. Compatible with Slack, Zapier, n8n and any custom HTTP endpoint, and signed with HMAC-SHA256 when you set a secret.'=>'يرسل طلب JSON POST إلى عنوان URL خارجي في كل مرة ينهي فيها WPOptimizing فحصاً أو تنظيفاً أو حذفاً أو رفع مجموعة بيانات. متوافق مع Slack وZapier وn8n وأي نقطة نهاية HTTP مخصصة، ويُوقَّع بـ HMAC-SHA256 عندما تحدد سراً.','Webhooks let you integrate WPOptimizing events into your existing automation workflows. There is one endpoint, set in Settings › Webhooks, and a POST request goes to it whenever one of the events you selected occurs (with none selected, all of them are sent). The payload is a JSON object with the event, the site URL, the plugin version, a timestamp and the event data.'=>'تتيح لك webhooks دمج أحداث WPOptimizing في سير عمل الأتمتة الحالية لديك. هناك نقطة نهاية واحدة تُضبط في الإعدادات › Webhooks، ويُرسَل إليها طلب POST كلما وقع أحد الأحداث التي اخترتها (وإن لم تختر أياً منها، تُرسَل جميعها). الحمولة كائن JSON يحتوي على الحدث وعنوان URL للموقع وإصدار الإضافة وطابع زمني وبيانات الحدث.','Every request carries an X-WPOptimizing-Event header with the event name. If you set a signing secret (optional), it also carries X-WPOptimizing-Signature: sha256= followed by the HMAC-SHA256 of the raw JSON body keyed with that secret, so your endpoint can confirm the request is genuine and was not altered in transit.'=>'يحمل كل طلب رأس X-WPOptimizing-Event يتضمن اسم الحدث. وإذا حددت سر توقيع (اختياري)، فإنه يحمل أيضاً X-WPOptimizing-Signature: sha256= متبوعاً بقيمة HMAC-SHA256 لنص JSON الخام باستخدام ذلك السر مفتاحاً، حتى تتمكن نقطة النهاية لديك من التأكد من أن الطلب حقيقي ولم يُعدَّل أثناء النقل.','Events: scan_completed, cleanup_completed, items_deleted and dataset_uploaded. items_deleted includes the names or paths of what was deleted (up to 100 per request), so send it only to a system you trust.'=>'الأحداث: scan_completed وcleanup_completed وitems_deleted وdataset_uploaded. يتضمن items_deleted أسماء أو مسارات ما حُذف (حتى 100 لكل طلب)، لذا أرسله فقط إلى نظام تثق به.','WPOptimizing uses a community manifest that maps plugin and theme slugs to their known database tables, options and files. The more sites that contribute their scan results, the more accurate attribution becomes for everyone.'=>'يستخدم WPOptimizing بياناً مجتمعياً يربط معرّفات الإضافات والقوالب بجداول قاعدة بياناتها المعروفة وخياراتها وملفاتها. كلما زاد عدد المواقع التي تُسهم بنتائج فحصها، كلما أصبح النسب أكثر دقةً للجميع.','Attribution accuracy is the core quality metric of WPOptimizing: the more precisely the plugin can say "this option belongs to plugin X", the safer and more useful the cleanup is. The shared dataset is a crowd-sourced manifest that grows with every participating site. When your site uploads its scan results, the new data is merged into the dataset and made available to every participating site on the next update.'=>'دقة الإسناد هي مقياس الجودة الأساسي في WPOptimizing: كلما استطاع الإضافة أن تقول بدقة أكبر «هذا الخيار ينتمي إلى الإضافة X»، كان التنظيف أكثر أماناً وفائدة. مجموعة البيانات المشتركة هي بيان جماعي يتنامى مع كل موقع مشارك. عندما يرفع موقعك نتائج الفحص، تُدمج البيانات الجديدة في مجموعة البيانات وتُتاح لجميع المواقع المشاركة في التحديث التالي.','Dataset uploads never include page URLs, post content, user data, option values or personal information. The upload contains only structural metadata: table names, option key patterns, file path patterns, and the plugin slug they are associated with, plus your site’s domain, which authorises the exchange.'=>'لا تتضمّن تحميلات مجموعة البيانات أبداً عناوين URL للصفحات أو محتوى المنشور أو بيانات المستخدم أو قيم الخيارات أو المعلومات الشخصية. يحتوي التحميل فقط على بيانات وصفية هيكلية: أسماء الجداول، وأنماط مفاتيح الخيارات، وأنماط مسارات الملفات، وslug الإضافة المرتبطة بها، إضافةً إلى نطاق موقعك الذي يأذن بالتبادل.','Languages and custom translations'=>'اللغات والترجمات الخاصة','English plus eight complete translations. If you want to change a string, put your catalogue in wp-content/languages/plugins/ — never inside the plugin folder, where an update would delete it and where it would not be read.'=>'الإنجليزية زائد ثماني ترجمات كاملة. إن أردت تغيير نص، ضع ملف الترجمة في wp-content/languages/plugins/ — وليس داخل مجلد الإضافة أبدًا، فهناك سيحذفه أي تحديث، ولن يُقرأ أصلًا.','The plugin ships English as its source language and eight complete translations: Spanish (es_ES), German (de_DE), French (fr_FR), Italian (it_IT), Portuguese for Portugal (pt_PT), Russian (ru_RU), Arabic (ar) and Chinese Simplified (zh_CN). Portuguese is pt_PT and is not the same as Brazilian Portuguese (pt_BR); a pt_BR site falls back to English until someone contributes that locale.'=>'تأتي الإضافة بالإنجليزية لغةً أصلية وبثماني ترجمات كاملة: الإسبانية (es_ES) والألمانية (de_DE) والفرنسية (fr_FR) والإيطالية (it_IT) والبرتغالية للبرتغال (pt_PT) والروسية (ru_RU) والعربية (ar) والصينية المبسّطة (zh_CN). والبرتغالية هي pt_PT وليست البرتغالية البرازيلية (pt_BR)؛ فموقع pt_BR يبقى بالإنجليزية إلى أن يساهم أحد بتلك اللغة.','Catalogues are shipped in the WordPress 6.5 performance format (.l10n.php), which loads faster than the classic .mo and is the format WordPress prefers. The .pot template ships too, which is what a translation tool needs to start a new locale or to send us a correction.'=>'تُوزَّع ملفات الترجمة بصيغة الأداء في ووردبريس 6.5 (‎.l10n.php)، وهي أسرع تحميلًا من ‎.mo التقليدي وهي التي يفضّلها ووردبريس. ويأتي معها قالب ‎.pot، وهو ما تحتاجه أداة الترجمة لبدء لغة جديدة أو لإرسال تصحيح إلينا.','Where to put your own catalogue:'=>'أين تضع ملف الترجمة الخاص بك:','wp-content/languages/plugins/, named wpoptimizing-<locale>.mo (or .l10n.php). WordPress searches that folder BEFORE the plugin\'s own, so your file wins, and it survives plugin updates — anything inside the plugin folder is replaced on every update.'=>'في wp-content/languages/plugins/ باسم wpoptimizing-<locale>.mo (أو ‎.l10n.php). يبحث ووردبريس في هذا المجلد قبل مجلد الإضافة، فيفوز ملفك، ويبقى بعد التحديثات: فكل ما داخل مجلد الإضافة يُستبدل مع كل تحديث.','The one trap worth knowing:'=>'الفخ الوحيد الذي يجدر معرفته:','do not drop your .mo inside the plugin\'s own languages/ folder. Since WordPress 6.5 the .l10n.php in the SAME folder is preferred over a .mo, so your file would sit there being ignored with no error to tell you. In wp-content/languages/plugins/ there is no .l10n.php of ours to shadow it, which is exactly why that is the right place.'=>'لا تضع ملف ‎.mo داخل مجلد languages/ التابع للإضافة نفسها. فمنذ ووردبريس 6.5 يُفضَّل ملف ‎.l10n.php الموجود في المجلد نفسه على ملف ‎.mo، فيبقى ملفك هناك مُهمَلًا دون أي خطأ ينبّهك. أما في wp-content/languages/plugins/ فلا يوجد ‎.l10n.php من عندنا ليحجبه، ولهذا بالضبط هو المكان الصحيح.','Loco Translate and similar tools already save to that folder by default, so following their defaults is correct. If you improve a translation, send it back and it ships for everyone.'=>'إن Loco Translate والأدوات المشابهة تحفظ في ذلك المجلد افتراضيًا، فاتّباع إعداداتها الافتراضية هو الصحيح. وإن حسّنت ترجمة، أرسلها إلينا لتُوزَّع على الجميع.','How to get the key, step by step'=>'كيفية الحصول على المفتاح، خطوة بخطوة','Sign in to the Google Cloud console with any Google account and create a project (or pick an existing one).'=>'سجّل الدخول إلى وحدة تحكم Google Cloud بأي حساب Google وأنشئ مشروعًا (أو اختر مشروعًا موجودًا).','Open the <a href="%s" target="_blank" rel="noopener noreferrer">PageSpeed Insights API</a> page and press “Enable”.'=>'افتح صفحة <a href="%s" target="_blank" rel="noopener noreferrer">PageSpeed Insights API</a> واضغط على «تفعيل».','Go to <a href="%s" target="_blank" rel="noopener noreferrer">Credentials</a> and choose “Create credentials” → “API key”.'=>'انتقل إلى <a href="%s" target="_blank" rel="noopener noreferrer">بيانات الاعتماد</a> واختر «إنشاء بيانات اعتماد» ← «مفتاح API».','Copy the key, paste it in the field above and save it. Restricting the key to the PageSpeed Insights API is recommended.'=>'انسخ المفتاح والصقه في الحقل أعلاه ثم احفظه. يُنصح بتقييد المفتاح على PageSpeed Insights API فقط.','Official documentation: <a href="%s" target="_blank" rel="noopener noreferrer">Get started with the PageSpeed Insights API</a>.'=>'التوثيق الرسمي: <a href="%s" target="_blank" rel="noopener noreferrer">البدء مع PageSpeed Insights API</a>.','Performance history'=>'سجل الأداء','Where you started versus where you are now, and the change after each scan and cleanup. Snapshots are taken automatically when you scan or clean.'=>'من أين بدأت مقارنةً بوضعك الحالي، والتغيّر بعد كل فحص وتنظيف. تُؤخذ اللقطات تلقائياً عند الفحص أو التنظيف.','No history yet. Run a scan to record the first (baseline) snapshot.'=>'لا يوجد سجل بعد. شغّل فحصاً لتسجيل أول لقطة (خط الأساس).','Baseline pinned at %s.'=>'تم تثبيت خط الأساس عند %s.','Pin a new baseline at the current state? Past snapshots are kept; comparisons will start from now.'=>'تثبيت خط أساس جديد عند الحالة الراهنة؟ يتم الاحتفاظ باللقطات السابقة؛ ستبدأ المقارنات من الآن.','Forever'=>'دائمًا','3 months'=>'3 أشهر','6 months'=>'6 أشهر','1 year'=>'سنة واحدة','Save'=>'حفظ','New performance baseline pinned at the current state.'=>'تم تثبيت خط أساس أداء جديد عند الحالة الراهنة.','from %s'=>'من %s','Timeline'=>'الخط الزمني','Event'=>'الحدث','All events'=>'كل الأحداث','All dates'=>'كل التواريخ','Server TTFB'=>'زمن أول بايت (TTFB) للخادم','Autoload size'=>'حجم التحميل التلقائي','Options'=>'الخيارات','Expired transients'=>'المؤقتات منتهية الصلاحية','Attachments'=>'المرفقات','DB orphans'=>'يتامى قاعدة البيانات','FS orphans'=>'يتامى نظام الملفات','Reclaimable (duplicates)'=>'قابل للاسترداد (مكررات)','Orphan media'=>'وسائط يتيمة','Backups on disk'=>'النسخ الاحتياطية على القرص','Cache hit rate'=>'معدل إصابة الكاش','Queries saved'=>'الاستعلامات الموفَّرة','Baseline'=>'خط الأساس','Before scan'=>'قبل الفحص','After scan'=>'بعد الفحص','After cleanup'=>'بعد التنظيف','%s ms'=>'%s مللي ثانية','The uploads folder now refuses dumps, logs, keys and environment files. The audit was run again to check it.'=>'مجلد الرفع يرفض الآن التفريغات والسجلات والمفاتيح وملفات البيئة. أُعيد تشغيل الفحص للتحقق من ذلك.','The protection rules were removed from the uploads folder.'=>'أُزيلت قواعد الحماية من مجلد الرفع.','The .htaccess file in the uploads folder could not be written. Nothing was changed.'=>'تعذّرت كتابة ملف .htaccess في مجلد الرفع. لم يتغير شيء.','The selected files were deleted. A backup was taken first and is listed under Backups.'=>'حُذفت الملفات المحددة. أُنشئت نسخة احتياطية قبل ذلك وهي مدرجة في النسخ الاحتياطية.','Nothing found.'=>'لم يُعثر على شيء.','Select all'=>'تحديد الكل','Trunk'=>'الجذع','…and %s more'=>'…و%s أخرى','An examination of the uploads folder and the attachment records behind it. It detects, explains and says whose each file is; it only acts on files that should not be downloadable, and only when you ask.'=>'فحص لمجلد الرفع وسجلات المرفقات المرتبطة به. يكتشف ويشرح ويبيّن لمن يعود كل ملف؛ ولا يتصرف إلا في الملفات التي لا ينبغي أن تكون قابلة للتنزيل، وفقط عندما تطلب ذلك.','Run the audit'=>'تشغيل التدقيق','Last run %s ago.'=>'آخر تشغيل قبل %s.','Not run yet. It reads the uploads folder and the database, and checks a few files over HTTP; nothing is modified.'=>'لم يُشغَّل بعد. يقرأ مجلد الرفع وقاعدة البيانات، ويتحقق من بضعة ملفات عبر HTTP؛ ولا يُعدَّل أي شيء.','References are matched by file name, so this errs towards reporting a file as used. It will never call a file unused when it is in use; it may call one used when the name merely appears in some text.'=>'تُطابَق المراجع بالاسم، لذا يميل التقرير إلى اعتبار الملف مستخدمًا. لن يقول أبدًا إن ملفًا غير مستخدم وهو قيد الاستخدام؛ لكنه قد يعتبره مستخدمًا لمجرد ورود اسمه في نص ما.','The folder walk ran out of time, so this is a partial view. Counts below are a floor, not a total.'=>'نفد الوقت أثناء اجتياز المجلد، لذا هذه رؤية جزئية. الأرقام أدناه حد أدنى وليست إجماليًا.','downloadable'=>'قابل للتنزيل','blocked'=>'محجوب','not checked'=>'لم يُفحص','Database dumps, logs, backups and environment files under the uploads folder. Each was requested over HTTP: “downloadable” means the server returned it. This is a security finding, not a housekeeping one.'=>'نسخ قاعدة البيانات والسجلات والنسخ الاحتياطية وملفات البيئة داخل مجلد الرفع. طُلب كل منها عبر HTTP: «قابل للتنزيل» يعني أن الخادم أعاده. هذه نتيجة أمنية لا نتيجة ترتيب.','Reachable'=>'يمكن الوصول إليه','Belongs to'=>'يعود إلى','Delete the selected files? A backup is taken first; if it cannot be made, nothing is deleted. Check first that the plugin they belong to no longer needs them.'=>'حذف الملفات المحددة؟ تُنشأ نسخة احتياطية أولاً؛ وإن تعذّر ذلك لا يُحذف شيء. تحقّق أولاً من أن الإضافة التي تعود إليها لم تعد تحتاجها.','A size owned by an attachment AND derivable, by string manipulation, from another URL in your content — which is how some themes build their srcset. Both work today; move one half and the other breaks, at whichever screen width asks for that size. There is nothing to repair: the fix is not to move these files.'=>'حجم يعود إلى مرفق ويمكن أيضًا اشتقاقه، بمعالجة النصوص، من رابط آخر في محتواك — وهكذا تبني بعض القوالب srcset الخاص بها. كلاهما يعمل اليوم؛ انقل أحد النصفين فيتعطل الآخر، عند عرض الشاشة الذي يطلب ذلك الحجم تحديدًا. لا يوجد ما يُصلح: الحل هو عدم نقل هذه الملفات.','Also derivable from'=>'يمكن اشتقاقه أيضًا من','Referenced from'=>'مُشار إليه من','Dimensions that none of the image sizes this site registers right now would generate, and that no attachment still lists. Compared against the live registry, never against what a name looks like. Those not used anywhere can be deleted here, with a backup first.'=>'أبعاد لن يولّدها أي من أحجام الصور المسجّلة حاليًا في هذا الموقع، ولم يعد أي مرفق يدرجها. تتم المقارنة مع السجل الحالي، لا مع شكل الاسم. ما لا يُستخدم في أي مكان يمكن حذفه هنا، مع نسخة احتياطية مسبقة.','Generated sizes whose name descends from a different original than the attachment they belong to — what a rename leaves behind when the thumbnails are not regenerated. Harmless today; it matters the moment anything moves these files. Regenerating creates the sizes again with the current name; the old files stay on disk and are listed below, to delete once nothing uses them.'=>'أحجام مولّدة ينحدر اسمها من أصل مختلف عن المرفق الذي تنتمي إليه — وهو ما تتركه إعادة التسمية عندما لا تُعاد توليد الصور المصغّرة. غير ضار اليوم؛ ويصبح مهمًا لحظة نقل هذه الملفات. عند إعادة التوليد تُنشأ الأحجام من جديد بالاسم الحالي؛ وتبقى الملفات القديمة على القرص وتُدرج أدناه، لحذفها عندما لا يستخدمها شيء.','Attachment'=>'مرفق','Regenerate the thumbnails of the selected attachments? New sizes are created with the current name and the attachment is updated; the old files are not deleted. Up to 10 attachments per run.'=>'هل تريد إعادة توليد الصور المصغّرة للمرفقات المحددة؟ تُنشأ أحجام جديدة بالاسم الحالي ويُحدَّث المرفق؛ ولا تُحذف الملفات القديمة. حتى 10 مرفقات في كل دفعة.','Regenerate thumbnails'=>'إعادة توليد الصور المصغّرة','The renamed originals themselves (*-mfrh-original*) are cleaned in %s.'=>'تُنظَّف النسخ الأصلية المعاد تسميتها نفسها (*-mfrh-original*) في %s.','Renamed-original backups'=>'نسخ احتياطية لأصول مُعاد تسميتها','Sizes replaced by a regeneration'=>'أحجام استُبدلت بإعادة التوليد','The old sizes of the attachments regenerated above. No attachment lists them any more; those not used anywhere can be deleted, with a backup first.'=>'الأحجام القديمة للمرفقات التي أُعيد توليدها أعلاه. لم يعد أي مرفق يدرجها؛ وما لا يُستخدم في أي مكان يمكن حذفه، مع نسخة احتياطية مسبقة.','One image, two originals'=>'صورة واحدة، أصلان','The same image registered under two extensions, typically what a conversion left behind. Which one your site actually serves depends on the optimiser, so this is reported and never resolved automatically.'=>'الصورة نفسها مسجَّلة بامتدادين، وهو عادةً ما يخلفه التحويل. أيهما يقدّمه موقعك فعليًا يعتمد على أداة التحسين، لذا يُبلَّغ عن هذا ولا يُحل تلقائيًا أبدًا.','Files sitting directly in the uploads folder with no year/month directory. Usually the trace of an old migration, and not a fault in itself. Moving them is what this audit advises against; loose files nothing uses can be deleted, with a backup first.'=>'ملفات موجودة مباشرة في مجلد الرفع دون مجلد سنة/شهر. غالبًا أثر ترحيل قديم، وليست خطأً بحد ذاتها. نقلها هو بالضبط ما يحذّر منه هذا الفحص؛ الملفات المتفرقة التي لا يستخدمها شيء يمكن حذفها، مع نسخة احتياطية مسبقة.','Orphan files'=>'ملفات يتيمة','Orphan thumbnails'=>'صور مصغّرة يتيمة','Other files'=>'ملفات أخرى','Server protection'=>'حماية الخادم','Keep: it stops the folder being listed or run'=>'احتفظ به: يمنع سرد محتوى المجلد أو تنفيذه','In use: Media library (#%d)'=>'مستخدم: مكتبة الوسائط (#%d)','not identified'=>'غير محدد','Media library'=>'مكتبة الوسائط','In use: %s'=>'مستخدم: %s','Delete it in %s'=>'احذفه في %s','Not used: can be deleted'=>'غير مستخدم: يمكن حذفه','Thumbnails regenerated for %1$d attachment(s); %2$d could not be (file missing or not an image). The old sizes are listed under "Sizes replaced by a regeneration".'=>'أُعيد توليد الصور المصغّرة لـ %1$d مرفق؛ وتعذّر ذلك لـ %2$d (الملف مفقود أو ليس صورة). الأحجام القديمة مدرجة في «أحجام استُبدلت بإعادة التوليد».','%s (theme)'=>'%s (قالب)','Protect the uploads folder'=>'حماية مجلد الرفع','Adds a rule to the .htaccess file of the uploads folder so the server refuses database dumps, logs, backups, keys and environment files. Archives (.zip, .tar, .gz) are left out because shops and themes serve them as downloads. The files stay where they are: the plugin that writes them keeps working.'=>'يضيف قاعدة إلى ملف .htaccess في مجلد الرفع كي يرفض الخادم تفريغات قاعدة البيانات والسجلات والنسخ الاحتياطية والمفاتيح وملفات البيئة. تُستثنى الأرشيفات (.zip و.tar و.gz) لأن المتاجر والقوالب تقدّمها كتنزيلات. تبقى الملفات في مكانها: الإضافة التي تكتبها تواصل العمل.','This server runs Nginx, which does not read .htaccess. Add this to the site\'s server block, or ask your host to:'=>'يعمل هذا الخادم بـ Nginx الذي لا يقرأ .htaccess. أضف هذا إلى كتلة server الخاصة بالموقع، أو اطلب ذلك من مزوّد الاستضافة:','Remove the protection'=>'إزالة الحماية','Protect these files'=>'حماية هذه الملفات','Files in the uploads folder with no matching database record (not real attachments) — usually leftovers from uploads, migrations or plugins. Review before deleting.'=>'ملفات في مجلد الرفع بلا سجل مطابق في قاعدة البيانات (وليست مرفقات حقيقية) — عادةً بقايا من عمليات الرفع أو الترحيل أو الإضافات. راجعها قبل الحذف.','Generated thumbnail sizes whose original image is missing or no longer registered. Removing them is normally safe once confirmed.'=>'أحجام صور مصغّرة مُولَّدة فُقدت صورتها الأصلية أو لم تعد مسجّلة. إزالتها آمنة عادةً بعد التأكد.','Files stored in named folders (not date-based), typically data generated by plugins (imports, exports, assets). Review carefully before deleting.'=>'ملفات مخزّنة في مجلدات مُسمّاة (وليست قائمة على التاريخ)، عادةً بيانات تولّدها الإضافات (عمليات استيراد وتصدير وأصول). راجعها بعناية قبل الحذف.','Groups of byte-identical files. The lowest-ID copy is kept and references reassigned to it; the remaining copies can be removed.'=>'مجموعات من ملفات متطابقة على مستوى البايتات. يتم الاحتفاظ بالنسخة ذات أقل معرّف وإعادة إسناد المراجع إليها؛ يمكن إزالة النسخ المتبقية.','Attachments with no detectable reference in content, meta, galleries or parent posts. Heuristic and read-only — confirm each is truly unused before deleting.'=>'مرفقات بلا مرجع قابل للاكتشاف في المحتوى أو البيانات الإضافية أو المعارض أو المقالات الأصلية. اكتشافية وللقراءة فقط — تأكد من أن كلاً منها غير مستخدم فعلاً قبل الحذف.','Showing the first %1$s of %2$s items. Re-run the media analysis to load the full list.'=>'عرض أول %1$s من أصل %2$s عنصر. أعد تشغيل تحليل الوسائط لتحميل القائمة الكاملة.','The largest source images and what would help each one — oversized originals, missing WebP/AVIF copies and heavy files.'=>'أكبر الصور المصدرية وما الذي سيساعد كل واحدة: أصول أكبر من اللازم، ونسخ WebP/AVIF مفقودة، وملفات ثقيلة.','The largest source images and what would help each one — oversized originals, missing WebP/AVIF copies and heavy files. Select the ones you want and optimize them in one go.'=>'أكبر الصور المصدرية وما الذي سيساعد كل واحدة: أصول أكبر من اللازم، ونسخ WebP/AVIF مفقودة، وملفات ثقيلة. حدّد ما تريده وحسّنها دفعةً واحدة.','Heaviest images'=>'أثقل الصور','No heavy images found yet. Open “Image optimization” and run the analysis to populate this list.'=>'لم يُعثر على صور ثقيلة بعد. افتح «تحسين الصور» وشغّل التحليل لملء هذه القائمة.','Bulk optimization of existing images (recompressing originals and generating their WebP/AVIF copies) is not included in this plugin.'=>'التحسين المجمّع للصور الموجودة (إعادة ضغط النسخ الأصلية وإنشاء نسخ WebP/AVIF لها) غير مضمّن في هذه الإضافة.','Optimizing images is a Pro feature — this diagnostic list is free.'=>'تحسين الصور ميزة احترافية (Pro) — أما قائمة التشخيص هذه فمجانية.','Your server cannot process images yet (it needs the GD or Imagick PHP extension), so these are shown for information only.'=>'لا يستطيع خادومك معالجة الصور بعد (يحتاج إلى امتداد GD أو Imagick في PHP)، لذا تُعرض للاطلاع فقط.','Images to act on'=>'صور بحاجة إلى معالجة','Combined weight'=>'الوزن الإجمالي','Search images'=>'البحث عن الصور','Optimize all'=>'تحسين الكل','Recompresses/resizes each original (backup-first, reversible from the Backups tab) and creates the missing WebP/AVIF copies your server supports.'=>'يعيد ضغط/تحجيم كل أصل (مع نسخة احتياطية مسبقة، قابلة للتراجع من تبويب النسخ الاحتياطية) وينشئ نسخ WebP/AVIF المفقودة التي يدعمها خادومك.','Optimize the %d selected image(s)? Originals are backed up first.'=>'هل تريد تحسين %d صورة محددة؟ تُنسخ الأصول احتياطيًا أولًا.','Optimize ALL %d filtered image(s)? Originals are backed up first.'=>'هل تريد تحسين كل الصور المُصفّاة البالغة %d؟ تُنسخ الأصول احتياطيًا أولًا.','%s already serves WebP/AVIF, so the rule was not added.'=>'%s يقدّم WebP/AVIF بالفعل، لذا لم تُضَف القاعدة.','The WebP/AVIF rule was removed from the uploads folder.'=>'أُزيلت قاعدة WebP/AVIF من مجلد الرفع.','Works: asked for a JPEG/PNG the way a browser does, the server answered with its %s copy.'=>'تعمل: عند طلب JPEG/PNG كما يفعل المتصفح، ردّ الخادم بنسخة %s.','The server still answers with the original image. mod_rewrite may be off, or another rule answers first: ask your host, or use the <picture> serving.'=>'ما زال الخادم يردّ بالصورة الأصلية. ربما يكون mod_rewrite معطّلًا أو تردّ قاعدة أخرى أولًا: راجع مزوّد الاستضافة أو استخدم التقديم عبر <picture>.','The test image could not be requested from the server, so nothing could be checked.'=>'تعذّر طلب صورة الاختبار من الخادم، لذا لم يمكن التحقق من أي شيء.','No image has a WebP or AVIF copy yet, so there is nothing to check.'=>'لا توجد بعد أي صورة لها نسخة WebP أو AVIF، لذا لا يوجد ما يُتحقَّق منه.','No image has a WebP or AVIF copy yet. Generate the copies, then check again.'=>'لا توجد بعد أي صورة لها نسخة WebP أو AVIF. أنشئ النسخ ثم تحقّق مجددًا.','A rule in the uploads folder answers each request for a JPEG, PNG or GIF with its AVIF or WebP copy when the browser accepts it. The address does not change, so it also covers backgrounds in CSS files, page builders and images the theme prints, without any PHP. Images without a copy are served as always.'=>'قاعدة في مجلد الرفع تردّ على كل طلب لصورة JPEG أو PNG أو GIF بنسختها AVIF أو WebP عندما يقبلها المتصفح. العنوان لا يتغير، لذا تشمل أيضًا الخلفيات في ملفات CSS ومنشئي الصفحات والصور التي يطبعها القالب، دون أي PHP. الصور التي لا نسخة لها تُقدَّم كالمعتاد.','This server runs Nginx, which does not read .htaccess. Add this to its configuration, or ask your host to:'=>'يعمل هذا الخادم بـ Nginx، الذي لا يقرأ .htaccess. أضف هذا إلى إعداداته أو اطلب ذلك من مزوّد الاستضافة:','%s already serves WebP/AVIF on this site, so this stays off.'=>'%s يقدّم WebP/AVIF على هذا الموقع بالفعل، لذا يبقى هذا معطّلًا.','Remove the rule'=>'إزالة القاعدة','Add the rule and check it'=>'إضافة القاعدة والتحقق منها','The answer carries no "Vary: Accept" header (mod_headers may be off): a shared cache could hand an AVIF to a browser that cannot show it. Ask your host to enable mod_headers.'=>'لا يحمل الرد ترويسة «Vary: Accept» (ربما يكون mod_headers معطّلًا): قد تسلّم ذاكرة تخزين مشتركة صورة AVIF لمتصفح لا يستطيع عرضها. اطلب من مزوّد الاستضافة تفعيل mod_headers.','The images pass through %s. It has to keep one copy per format (Vary: Accept); if your plan does not, remove the rule and keep the <picture> serving, which works behind any CDN.'=>'تمر الصور عبر %s. يجب أن يحتفظ بنسخة لكل صيغة (Vary: Accept)؛ إن لم تفعل خطتك ذلك، أزل القاعدة واحتفظ بالتقديم عبر <picture>، الذي يعمل خلف أي CDN.','Analyze the images in your uploads — total weight, formats, large files and how many lack a WebP/AVIF copy — then recompress originals (backup-first, reversible), generate WebP and AVIF copies, and auto-resize oversized uploads. Serving the next-gen copies on the front-end is built in.'=>'يحلّل الصور في ملفاتك المرفوعة — الحجم الإجمالي والصيغ والملفات الكبيرة وكم منها بلا نسخة WebP/AVIF — ثم يعيد ضغط النسخ الأصلية (نسخة احتياطية أولاً وقابل للعكس)، وينشئ نسخ WebP وAVIF، ويغيّر حجم المرفوعات الكبيرة تلقائيًا. تقديم نسخ الجيل الجديد في الواجهة الأمامية مُضمَّن.','Image settings saved.'=>'تم حفظ إعدادات الصور.','The image analysis runs as part of “Analyze now”. Run it to see weight, formats and savings here'=>'يُجرى تحليل الصور كجزء من «حلّل الآن». شغّله لرؤية الحجم والصيغ والتوفير هنا','or scan images now'=>'أو افحص الصور الآن','Total image weight'=>'الوزن الإجمالي للصور','Large images (≥ 300 KB)'=>'صور كبيرة (≥ 300 كيلوبايت)','Larger than max size'=>'أكبر من الحجم الأقصى','Without WebP/AVIF copy'=>'بدون نسخة WebP/AVIF','Estimated WebP savings'=>'التوفير المقدّر مع WebP','Format'=>'الصيغة','See the heaviest images →'=>'عرض أثقل الصور ←','Generated next-gen copies (created next to each original, served on the front-end):'=>'نسخ الجيل الجديد المُولَّدة (تُنشأ بجوار كل أصل، وتُقدَّم في الواجهة الأمامية):','Copy format'=>'صيغة النسخة','Copies'=>'النسخ','Your server cannot process images yet (it needs the GD or Imagick PHP extension).'=>'لا يستطيع خادمك معالجة الصور بعد (يحتاج إلى امتداد PHP وهو GD أو Imagick).','Optimizing originals and generating WebP/AVIF copies are Pro features — the analysis above is free.'=>'تحسين الأصول وإنشاء نسخ WebP/AVIF ميزتان في Pro — أما التحليل أعلاه فمجاني.','Shrinks your JPEG/PNG originals (and resizes any larger than your max size) without a visible loss of quality. Backup-first and fully reversible with “Restore originals”. Run it before generating copies, so the copies are made from the optimized originals.'=>'يقلّل حجم نسخك الأصلية JPEG/PNG (ويغيّر حجم ما يتجاوز حجمك الأقصى) دون فقدان مرئي للجودة. نسخة احتياطية أولاً وقابل للعكس تمامًا عبر «استعادة النسخ الأصلية». شغّله قبل إنشاء النسخ كي تُنشأ من النسخ الأصلية المُحسَّنة.','Optimize %s image' . "\0" . 'Optimize %s images'=>'تحسين %s صورة' . "\0" . 'تحسين صورة واحدة' . "\0" . 'تحسين صورتين' . "\0" . 'تحسين %s صور' . "\0" . 'تحسين %s صورة' . "\0" . 'تحسين %s صورة','Restore originals'=>'استعادة الأصول','Creates .webp / .avif copies next to each image (originals never change) and serves them automatically on the front-end, with a fallback to the original.'=>'ينشئ نسخ .webp / .avif بجوار كل صورة (لا تتغيّر النسخ الأصلية أبدًا) ويقدّمها تلقائيًا في الواجهة الأمامية مع الرجوع إلى الأصل.','%s is active and already serves WebP/AVIF on the front-end, so WPOptimizing will not — you can still generate copies here.'=>'%s مُفعّل ويقدّم WebP/AVIF بالفعل في الواجهة الأمامية، لذا لن يفعل WPOptimizing ذلك — لا يزال بإمكانك توليد النسخ هنا.','Optimize the originals first: the copies are then created from the lighter, optimized images.'=>'حسّن النسخ الأصلية أولاً: عندئذٍ تُنشأ النسخ من الصور المُحسَّنة الأخف.','Generate %s WebP copy' . "\0" . 'Generate %s WebP copies'=>'إنشاء %s نسخة WebP' . "\0" . 'إنشاء نسخة WebP واحدة' . "\0" . 'إنشاء نسختي WebP' . "\0" . 'إنشاء %s نسخ WebP' . "\0" . 'إنشاء %s نسخة WebP' . "\0" . 'إنشاء %s نسخة WebP','Remove %s WebP copy' . "\0" . 'Remove %s WebP copies'=>'إزالة %s نسخة WebP' . "\0" . 'إزالة نسخة WebP واحدة' . "\0" . 'إزالة نسختي WebP' . "\0" . 'إزالة %s نسخ WebP' . "\0" . 'إزالة %s نسخة WebP' . "\0" . 'إزالة %s نسخة WebP','Generate %s AVIF copy' . "\0" . 'Generate %s AVIF copies'=>'إنشاء %s نسخة AVIF' . "\0" . 'إنشاء نسخة AVIF واحدة' . "\0" . 'إنشاء نسختي AVIF' . "\0" . 'إنشاء %s نسخ AVIF' . "\0" . 'إنشاء %s نسخة AVIF' . "\0" . 'إنشاء %s نسخة AVIF','Remove %s AVIF copy' . "\0" . 'Remove %s AVIF copies'=>'إزالة %s نسخة AVIF' . "\0" . 'إزالة نسخة AVIF واحدة' . "\0" . 'إزالة نسختي AVIF' . "\0" . 'إزالة %s نسخ AVIF' . "\0" . 'إزالة %s نسخة AVIF' . "\0" . 'إزالة %s نسخة AVIF','AVIF needs a newer server (PHP 8.1+ GD with AVIF, or Imagick with libheif). WebP is available.'=>'يتطلّب AVIF خادمًا أحدث (GD في PHP 8.1+ مع AVIF، أو Imagick مع libheif). WebP متاح.','Processed %s…'=>'تمت معالجة %s…','Done. Reloading…'=>'تم. جارٍ إعادة التحميل…','Something went wrong. Please retry.'=>'حدث خطأ ما. حاول مرة أخرى.','For WebP, AVIF and lossy JPEG recompression (40–100). 82 is a good balance; PNG is always lossless.'=>'لإعادة ضغط WebP وAVIF وJPEG بفقدان (40–100). 82 توازن جيّد؛ وPNG دائمًا بلا فقدان.','Quality by format'=>'الجودة حسب الصيغة','WebP quality'=>'جودة WebP','AVIF quality'=>'جودة AVIF','0 uses the conversion quality above. AVIF usually looks the same as WebP at a noticeably lower number, around 60.'=>'القيمة 0 تستخدم جودة التحويل أعلاه. عادةً ما تبدو صيغة AVIF مثل WebP بقيمة أقل بكثير، نحو 60.','Never optimize'=>'لا تُحسَّن أبدًا','One per line, relative to the uploads folder: a folder (everything inside it), a file name, or a pattern with * such as *-print.jpg. These images are never recompressed or converted on upload. Private folders of shops and forms are always left alone.'=>'واحد في كل سطر، نسبةً إلى مجلد الرفع: مجلد (كل ما بداخله)، أو اسم ملف، أو نمط يحتوي *، مثل ‎*-print.jpg. لا يُعاد ضغط هذه الصور ولا تحويلها أبدًا عند الرفع. وتبقى المجلدات الخاصة بالمتاجر والنماذج دون مساس دائمًا.','One per line, relative to the uploads folder: a folder (everything inside it), a file name, or a pattern with * such as *-print.jpg. These images are never recompressed or converted, in bulk or on upload. Private folders of shops and forms are always left alone.'=>'واحد في كل سطر، نسبةً إلى مجلد الرفع: مجلد (كل ما بداخله)، أو اسم ملف، أو نمط يحتوي *، مثل ‎*-print.jpg. لا يُعاد ضغط هذه الصور ولا تحويلها أبدًا، لا دفعةً ولا عند الرفع. وتبقى المجلدات الخاصة بالمتاجر والنماذج دون مساس دائمًا.','Max dimensions (px)'=>'الأبعاد القصوى (بكسل)','Down-size images that exceed these (width × height). 0 on an axis disables it. Applies when recompressing.'=>'يصغّر الصور التي تتجاوز هذه القيم (العرض × الارتفاع). القيمة 0 على أحد المحورين تعطّله. يُطبَّق عند إعادة الضغط.','Image options'=>'خيارات الصور','Lossless mode (do not reduce image quality)'=>'وضع بلا فقدان (عدم خفض جودة الصورة)','Strip metadata (EXIF, comments) for smaller files; the colour profile and orientation are kept'=>'أزل البيانات الوصفية (EXIF والتعليقات) لملفات أصغر؛ يُحتفظ بملف تعريف الألوان والاتجاه','Optimize new uploads: resize oversized images, recompress them and strip their metadata — the full-size original is preserved'=>'تحسين عمليات الرفع الجديدة: تصغير الصور كبيرة الحجم وإعادة ضغطها وإزالة بياناتها الوصفية — ويُحتفَظ بالأصل بحجمه الكامل','Serve WebP/AVIF on the front-end (as <picture> sources, falling back to the original)'=>'تقديم WebP/AVIF في الواجهة الأمامية (كمصادر <picture> مع الرجوع إلى الأصل)','Also backgrounds and theme images: on pages saved by the page cache, inline CSS backgrounds get their WebP/AVIF through image-set() and images outside the content get <picture> sources (the original stays as the fallback)'=>'أيضًا الخلفيات وصور القالب: في الصفحات التي تحفظها ذاكرة الصفحات المؤقتة، تحصل خلفيات CSS المضمّنة على WebP/AVIF عبر image-set()، وتحصل الصور خارج المحتوى على مصادر <picture> (يبقى الأصل احتياطيًا)','Generate a WebP copy on upload — new images get their copy immediately, without waiting for the bulk pass. AVIF stays a bulk action (too slow per upload).'=>'إنشاء نسخة WebP عند الرفع: تحصل الصور الجديدة على نسختها فورًا دون انتظار المعالجة المجمّعة. يبقى AVIF إجراءً مجمّعًا (بطيء جدًا لكل عملية رفع).','Analyzed %s ago.'=>'حُلِّل قبل %s.','Large library: only the first batch was analyzed.'=>'مكتبة كبيرة: حُلِّلت الدفعة الأولى فقط.','Re-scan now'=>'إعادة الفحص','Image sizes'=>'أحجام الصور','Posts showing it'=>'مقالات تعرضه','Stop generating'=>'أوقف التوليد','%d px wide'=>'عرض %d بكسل','%d px high'=>'ارتفاع %d بكسل','cropped'=>'مقصوص','Used by the Media Library'=>'تستخدمه مكتبة الوسائط','Each size is one more file written for every upload. A size switched off is no longer generated for new uploads; existing files stay. The count only sees images placed in post content: a size your theme prints from its templates (product grids, sliders, featured images) shows 0 here and still matters, so switch off only sizes you recognise.'=>'كل حجم ملف إضافي لكل صورة تُرفع. الحجم المعطّل لا يُولَّد بعد الآن للرفوعات الجديدة؛ وتبقى الملفات الموجودة. لا يرى هذا العدّ إلا الصور الموضوعة في المحتوى: الحجم الذي يطبعه قالبك من قوالبه (شبكات المنتجات، العروض المتحركة، الصور البارزة) يظهر هنا 0 ويظل مطلوبًا، فعطّل فقط الأحجام التي تعرفها.','Deleted media is recoverable — file backups available: %s.'=>'الوسائط المحذوفة قابلة للاستعادة — النسخ الاحتياطية للملفات المتاحة: %s.','Restore from Backups'=>'الاستعادة من النسخ الاحتياطية','Files removed from the media sections (unused attachments, duplicates, orphan files and thumbnails) are backed up first and can be restored here. Restoring puts the files back on disk; deleting permanently frees the backup space. This is the same set of copies as the Backups tab.'=>'تُنسخ الملفات المحذوفة من أقسام الوسائط (المرفقات غير المستخدمة، والمكررة، والملفات والصور المصغّرة اليتيمة) احتياطيًا أولًا ويمكن استعادتها هنا. الاستعادة تعيد الملفات إلى القرص؛ والحذف النهائي يحرّر مساحة النسخة الاحتياطية. وهي نفس مجموعة النسخ الموجودة في تبويب النسخ الاحتياطية.','The media trash is empty — nothing has been deleted, or the backups have been pruned.'=>'سلة مهملات الوسائط فارغة — لم يُحذف أي شيء أو تمت إزالة النسخ الاحتياطية.','Finds files in /uploads with no record in the database, orphaned thumbnails, and duplicate media (kept one, reassigned). Free shows everything; deletion is a Pro feature. Media deletions are backed up first and can be restored from the Backups tab.'=>'يعثر على ملفات في ‎/uploads بلا سجل في قاعدة البيانات، وعلى المصغّرات اليتيمة والوسائط المكررة (يُبقي واحدة ويعيد توجيه الإشارات إليها). تعرض النسخة المجانية كل شيء؛ والحذف ميزة Pro. وتُنسخ عمليات حذف الوسائط احتياطيًا قبل تنفيذها ويمكن استعادتها من تبويب النسخ الاحتياطية.','Media & uploads'=>'الوسائط والملفات المرفوعة','Media is analysed automatically as part of “Analyze now”.'=>'تُحلَّل الوسائط تلقائياً كجزء من «تحليل الآن».','Last analyzed: %s'=>'آخر تحليل: %s','Run “Analyze now” to see orphaned and duplicate media here.'=>'شغّل «تحليل الآن» لرؤية الوسائط اليتيمة والمكررة هنا.','Files scanned'=>'الملفات المفحوصة','Duplicate set' . "\0" . 'Duplicate sets'=>'مجموعة مكررة' . "\0" . 'مجموعة مكررة' . "\0" . 'مجموعتان مكررتان' . "\0" . 'مجموعات مكررة' . "\0" . 'مجموعةً مكررةً' . "\0" . 'مجموعة مكررة','Potentially unused'=>'غير مستخدم محتمل','The scan hit its file limit; results are partial.'=>'بلغ الفحص حد الملفات الخاص به؛ النتائج جزئية.','Duplicate detection is partial: %s of the media items that share their size with another one were compared (disk read limit).'=>'اكتشاف التكرارات جزئي: قورن %s من عناصر الوسائط التي يتطابق حجمها مع عنصر آخر (حد القراءة من القرص).','Image optimization views'=>'طرق عرض تحسين الصور','Filter the orphans by kind'=>'تصفية الملفات اليتيمة حسب النوع','Items'=>'العناصر','Total size'=>'الحجم الإجمالي','<strong>Heuristic — verify before deleting.</strong> These attachments have no detectable reference in featured images, post content, post meta (incl. galleries/ACF) or parent posts. But references can live in page builders, theme options, sliders, emails or external systems we can’t see. This list is <strong>read-only</strong>; confirm each is truly unused (e.g. in the Media Library) before removing it.'=>'<strong>اكتشافي — تحقق قبل الحذف.</strong> هذه المرفقات بلا مرجع قابل للاكتشاف في الصور البارزة أو محتوى المقالات أو البيانات الإضافية (بما في ذلك المعارض/ACF) أو المقالات الأصلية. لكن المراجع قد توجد في منشئات الصفحات أو خيارات القالب أو شرائح العرض أو رسائل البريد الإلكتروني أو أنظمة خارجية لا يمكننا رؤيتها. هذه القائمة <strong>للقراءة فقط</strong>؛ تأكد من أن كلاً منها غير مستخدم فعلاً (مثلاً في مكتبة الوسائط) قبل إزالته.','Heads up: these active plugins often reference images dynamically, which this scan cannot see — %s. Be extra careful with images they might use.'=>'تنبيه: غالبًا ما تشير هذه الإضافات النشطة إلى الصور ديناميكيًا، وهو ما لا يستطيع هذا الفحص رؤيته — %s. توخَّ حذرًا إضافيًا مع الصور التي قد تستخدمها.','These plugins keep their own list of unused media: %s. Each list is built with a different heuristic, so they will not agree — an item missing from one is not confirmation that the other is right. Check an item yourself before deleting it, whichever list you are looking at.'=>'تحتفظ هذه الإضافات بقائمتها الخاصة للوسائط غير المستخدمة: %s. كل قائمة مبنية على معيار مختلف، لذا لن تتطابقا — وغياب عنصر من إحداهما ليس تأكيدًا على صحة الأخرى. تحقّق من كل عنصر بنفسك قبل حذفه، أيًّا كانت القائمة التي تنظر إليها.','Detection was bounded on this large site, so some references may have been missed (more items may look unused than really are).'=>'كان الاكتشاف محدوداً في هذا الموقع الكبير، لذا قد تكون بعض المراجع قد فاتت (قد تبدو عناصر أكثر غير مستخدمة مما هي عليه فعلاً).','Media deletions are backed up first and can be restored from the Backups tab.'=>'تُنسخ عمليات حذف الوسائط احتياطيًا قبل تنفيذها ويمكن استعادتها من تبويب النسخ الاحتياطية.','Search files'=>'بحث في الملفات','Mark selected as known'=>'تحديد المحدد كمعروف','Mark all as known'=>'تحديد الكل كمعروف','Mark the %d selected attachment(s) as known? They will stop appearing as unused.'=>'تحديد %d مرفق محدد كمعروف؟ ستتوقف عن الظهور كغير مستخدمة.','Mark ALL %d attachment(s) as known? They will stop appearing as unused.'=>'تحديد كل الـ %d مرفق كمعروف؟ ستتوقف عن الظهور كغير مستخدمة.','Delete all'=>'حذف الكل','A backup is saved to the Backups tab before deletion, and a file that could not be fully backed up is never deleted. Or mark items as known to keep them and hide them from this list.'=>'يتم حفظ نسخة احتياطية في علامة التبويب «النسخ الاحتياطية» قبل الحذف، ولا يُحذف أبدًا ملف تعذّر نسخه احتياطيًا بالكامل. أو حدّد العناصر كمعروفة للاحتفاظ بها وإخفائها من هذه القائمة.','Delete the %d selected attachment(s)? A backup is created first.'=>'حذف المرفقات المحددة البالغ عددها %d؟ يتم إنشاء نسخة احتياطية أولاً.','Delete ALL %d filtered attachment(s)? A backup is created first — and remember this list is heuristic, so verify they are truly unused.'=>'حذف كل المرفقات المُرشَّحة البالغ عددها %d؟ يتم إنشاء نسخة احتياطية أولاً — وتذكّر أن هذه القائمة استدلالية، لذا تأكد من أنها غير مستخدمة فعلاً.','Marking as known keeps these files and hides them from the unused list (reset the known list any time). Deletion is a Pro feature.'=>'التحديد كمعروف يحتفظ بهذه الملفات ويخفيها من قائمة غير المستخدمة (يمكنك إعادة تعيين القائمة في أي وقت). الحذف ميزة Pro.','Clean selected duplicates (keep one)'=>'تنظيف المكررات المحددة (الاحتفاظ بواحدة)','Clean all duplicates'=>'تنظيف جميع المكررات','Kept files and reassignment are permanent; deleted copies are backed up to the Backups tab.'=>'الملفات المُحتفَظ بها وإعادة الإسناد دائمة؛ تُنسخ النسخ المحذوفة احتياطياً إلى علامة تبويب النسخ الاحتياطية.','Clean the %d selected duplicate set(s)? For each, the lowest-ID file is kept, references are reassigned to it, and the rest are deleted (a backup is made first).'=>'تنظيف المجموعات المكررة المحددة وعددها %d؟ في كل مجموعة، يُحتفَظ بالملف ذي أقل معرّف وتُعاد إليه إسناد المراجع، ويُحذف الباقي (مع إنشاء نسخة احتياطية أولاً).','Clean ALL %d filtered duplicate set(s)? For each, the lowest-ID file is kept, references reassigned, and the rest deleted (a backup is made first).'=>'تنظيف جميع المجموعات المكررة المُصفّاة وعددها %d؟ في كل مجموعة، يُحتفَظ بالملف ذي أقل معرّف وتُعاد إسناد المراجع، ويُحذف الباقي (مع إنشاء نسخة احتياطية أولاً).','Delete the %d selected media file(s)? A backup is created first.'=>'حذف ملفات الوسائط المحددة وعددها %d؟ يتم إنشاء نسخة احتياطية أولاً.','Delete ALL %d filtered media file(s)? A backup is created first.'=>'حذف جميع ملفات الوسائط المُصفّاة وعددها %d؟ يتم إنشاء نسخة احتياطية أولاً.','Redundant original copies left by rename plugins such as Media File Renamer (the *-mfrh-original* files), kept as the attachment original_image. The renamed file is already served, so these are safe to remove. Deleting one saves a backup first and clears the leftover original_image reference.'=>'نسخ زائدة من الأصل تتركها إضافات إعادة التسمية مثل Media File Renamer (ملفات *-mfrh-original*)، محفوظة بوصفها original_image للمرفق. الملف المُعاد تسميته يُقدَّم بالفعل، لذا يمكن إزالتها بأمان. عند حذف واحدة، يتم أولًا حفظ نسخة احتياطية وتُنظَّف إشارة original_image المتبقية.','Leftover backups'=>'نسخ احتياطية متبقية','No renamed-original backups were found.'=>'لم يتم العثور على نسخ احتياطية لأصول مُعاد تسميتها.','A copy is saved to the Backups tab before deletion, and the leftover original_image reference is cleared.'=>'تُحفظ نسخة في تبويب النسخ الاحتياطية قبل الحذف، وتُنظَّف إشارة original_image المتبقية.','Delete the %d selected backup(s)? A backup is created first.'=>'حذف النسخ الاحتياطية المحددة البالغ عددها %d؟ يتم إنشاء نسخة احتياطية أولًا.','Delete ALL %d filtered backup(s)? A backup is created first.'=>'حذف كل النسخ الاحتياطية المُرشَّحة البالغ عددها %d؟ يتم إنشاء نسخة احتياطية أولًا.','%s (unknown)'=>'%s (غير معروف)','%1$d unused attachment(s) deleted (backup saved to the Backups tab). %2$d skipped.'=>'تم حذف المرفقات غير المستخدمة وعددها %1$d (تم حفظ النسخة الاحتياطية في علامة تبويب النسخ الاحتياطية). تم تخطي %2$d.','%s attachment is marked as known and hidden from this list.' . "\0" . '%s attachments are marked as known and hidden from this list.'=>'%s مرفق محدد كمعروف ومخفي من هذه القائمة.' . "\0" . 'مرفق واحد محدد كمعروف ومخفي من هذه القائمة.' . "\0" . '%s مرفقان محددان كمعروفين ومخفيان من هذه القائمة.' . "\0" . '%s مرفقات محددة كمعروفة ومخفية من هذه القائمة.' . "\0" . '%s مرفقًا محددًا كمعروف ومخفي من هذه القائمة.' . "\0" . '%s مرفق محدد كمعروف ومخفي من هذه القائمة.','Reset known list'=>'إعادة تعيين قائمة المعروفة','Cleaned %1$d duplicate set(s): %2$d files deleted, %3$d posts and %4$d featured images reassigned.'=>'تم تنظيف %1$d مجموعة مكررة: حُذف %2$d ملف، وأُعيد إسناد %3$d مقالة و%4$d صورة بارزة.','%d duplicate shared the same file, so only its redundant record was removed (the file was kept).' . "\0" . '%d duplicates shared the same file, so only their redundant records were removed (the files were kept).'=>'%d تكرار تشارك الملف نفسه، لذا أُزيلت سجلاتها الزائدة فقط (مع الإبقاء على الملفات).' . "\0" . 'تكرار واحد يشارك الملف نفسه، لذا أُزيل سجله الزائد فقط (مع الإبقاء على الملف).' . "\0" . 'تكراران يشاركان الملف نفسه، لذا أُزيلت سجلاتهما الزائدة فقط (مع الإبقاء على الملفات).' . "\0" . '%d تكرارات تشارك الملف نفسه، لذا أُزيلت سجلاتها الزائدة فقط (مع الإبقاء على الملفات).' . "\0" . '%d تكرارًا تشارك الملف نفسه، لذا أُزيلت سجلاتها الزائدة فقط (مع الإبقاء على الملفات).' . "\0" . '%d تكرار تشارك الملف نفسه، لذا أُزيلت سجلاتها الزائدة فقط (مع الإبقاء على الملفات).','A backup of %d file was saved to the Backups tab.' . "\0" . 'A backup of %d files was saved to the Backups tab.'=>'تم حفظ نسخة احتياطية من %d ملف في علامة التبويب «النسخ الاحتياطية».' . "\0" . 'تم حفظ نسخة احتياطية من ملف واحد في علامة التبويب «النسخ الاحتياطية».' . "\0" . 'تم حفظ نسخة احتياطية من ملفَّين في علامة التبويب «النسخ الاحتياطية».' . "\0" . 'تم حفظ نسخة احتياطية من %d ملفات في علامة التبويب «النسخ الاحتياطية».' . "\0" . 'تم حفظ نسخة احتياطية من %d ملفاً في علامة التبويب «النسخ الاحتياطية».' . "\0" . 'تم حفظ نسخة احتياطية من %d ملف في علامة التبويب «النسخ الاحتياطية».','%d set was skipped because its backup could not be created (nothing was deleted for it).' . "\0" . '%d sets were skipped because their backups could not be created (nothing was deleted for them).'=>'تم تخطي %d مجموعة لأنه تعذّر إنشاء نسختها الاحتياطية (لم يُحذف شيء لأجلها).' . "\0" . 'تم تخطي مجموعة واحدة لأنه تعذّر إنشاء نسختها الاحتياطية (لم يُحذف شيء لأجلها).' . "\0" . 'تم تخطي مجموعتَين لأنه تعذّر إنشاء نسختيهما الاحتياطيتَين (لم يُحذف شيء لأجلهما).' . "\0" . 'تم تخطي %d مجموعات لأنه تعذّر إنشاء نسخها الاحتياطية (لم يُحذف شيء لأجلها).' . "\0" . 'تم تخطي %d مجموعةً لأنه تعذّر إنشاء نسختها الاحتياطية (لم يُحذف شيء لأجلها).' . "\0" . 'تم تخطي %d مجموعة لأنه تعذّر إنشاء نسخها الاحتياطية (لم يُحذف شيء لأجلها).','How the page reaches the visitor: speculative loading, image loading, preload, lazy embeds, resource hints, self-hosted Google Fonts and a CDN. All optional and reversible; none of them caches whole pages.'=>'كيف تصل الصفحة إلى الزائر: التحميل الاستباقي، وتحميل الصور، والتحميل المسبق، والتضمينات المؤجلة، وتلميحات الموارد، وGoogle Fonts المستضافة محليًا، وCDN. كلها اختيارية وقابلة للتراجع؛ ولا يخزّن أي منها صفحات كاملة مؤقتًا.','Save front-end settings'=>'حفظ إعدادات الواجهة الأمامية','What the visitor’s browser downloads and runs: minified copies of your own CSS and JavaScript.'=>'ما ينزّله متصفح الزائر ويشغّله: نسخ مصغّرة من CSS وJavaScript الخاصة بموقعك.','What the visitor’s browser downloads and runs. From least to most intrusive: minify, delay JavaScript, then critical CSS.'=>'ما ينزّله متصفح الزائر ويشغّله. من الأقل إلى الأكثر تدخلًا: التصغير، ثم تأخير JavaScript، ثم CSS الحرج.','Diagnose your server response time (TTFB) and apply the fixes WPOptimizing can do for you in one click. Steps the plugin cannot perform (system cron, PHP/OPcache, hosting) are shown as guidance. Minification is under Speed › Page & browser › CSS & JavaScript.'=>'شخّص زمن استجابة خادمك (TTFB) وطبّق بنقرة واحدة الإصلاحات التي يستطيع WPOptimizing القيام بها نيابةً عنك. أما الخطوات التي لا يستطيع تنفيذها (cron النظام، PHP/OPcache، الاستضافة) فتُعرض كإرشادات. التصغير موجود في السرعة › الصفحة والمتصفح › CSS وJavaScript.','Diagnose your server response time (TTFB) and apply the fixes WPOptimizing can do for you in one click. Steps the plugin cannot perform (system cron, PHP/OPcache, hosting) are shown as guidance. Minify, delay JavaScript and critical CSS are under Speed › Page & browser › CSS & JavaScript.'=>'شخّص زمن استجابة خادمك (TTFB) وطبّق بنقرة واحدة الإصلاحات التي يستطيع WPOptimizing القيام بها نيابةً عنك. أما الخطوات التي لا يستطيع تنفيذها (cron النظام، PHP/OPcache، الاستضافة) فتُعرض كإرشادات. التصغير وتأخير JavaScript وCSS الحرج موجودة في السرعة › الصفحة والمتصفح › CSS وJavaScript.','Server response time'=>'زمن استجابة الخادم','What WordPress spends before it starts sending the page. The levers WPOptimizing can apply come first; the ones that need server access follow as guidance.'=>'الوقت الذي يستغرقه ووردبريس قبل أن يبدأ بإرسال الصفحة. أولًا الإجراءات التي يمكن لـ WPOptimizing تطبيقها، ثم، على سبيل الإرشاد، تلك التي تتطلب الوصول إلى الخادم.','No TTFB measurement yet. Let some front-end traffic flow (or run an analysis) and the server response time will appear here, sampled automatically.'=>'لا يوجد قياس لـ TTFB بعد. اسمح بمرور بعض الزيارات (أو شغّل تحليلاً) وسيظهر زمن استجابة الخادم هنا، مأخوذاً تلقائياً بالعيّنات.','Your server response time is good. Keep the levers below enabled to stay there.'=>'زمن استجابة خادمك جيد. أبقِ المفاتيح أدناه مُفعَّلة للحفاظ على ذلك.','Server TTFB over time'=>'زمن TTFB للخادم عبر الوقت','Server TTFB (daily average)'=>'زمن TTFB للخادم (المتوسط اليومي)','Persistent object cache'=>'ذاكرة كائنات دائمة','Keeps expensive database queries in memory — the single biggest server-TTFB win.'=>'يبقي استعلامات قاعدة البيانات المكلفة في الذاكرة — أكبر تحسين في زمن استجابة الخادم.','Enable now'=>'فعّل الآن','Collapses identical database queries repeated within the same request.'=>'يدمج استعلامات قاعدة البيانات المتطابقة المتكررة ضمن الطلب نفسه.','Autoload weight'=>'حجم autoload','Options loaded on every request: %s (target under 800 KB). Smart Deactivation turns off autoload for options owned by uninstalled plugins.'=>'الخيارات المُحمَّلة في كل طلب: %s (الهدف أقل من 800 كيلوبايت). يوقف «التعطيل الذكي» autoload للخيارات التابعة لإضافات مُزالة.','Options loaded on every request. Smart Deactivation turns off autoload for options owned by uninstalled plugins.'=>'الخيارات المُحمَّلة في كل طلب. يوقف «التعطيل الذكي» autoload للخيارات التابعة لإضافات مُزالة.','Smart Deactivation will turn off autoload for options confidently attributed to plugins that are no longer installed. This is reversible. Continue?'=>'سيوقف «التعطيل الذكي» autoload للخيارات المنسوبة بثقة إلى إضافات لم تعد مثبَّتة. هذا قابل للتراجع. هل تريد المتابعة؟','WordPress Heartbeat'=>'Heartbeat الخاص بووردبريس','The admin Heartbeat fires admin-ajax every minute. Slowing or disabling it lowers PHP/DB load during active sessions.'=>'يُطلق Heartbeat لوحة التحكم طلب admin-ajax كل دقيقة. إبطاؤه أو تعطيله يقلل حِمل PHP/قاعدة البيانات أثناء الجلسات النشطة.','Disabled'=>'معطّل','Slowed'=>'مُبطَّأ','Disable Heartbeat'=>'تعطيل Heartbeat','WP-Cron on visitor requests'=>'WP-Cron عند زيارات المستخدمين','By default WordPress runs scheduled tasks during visits, which can add to TTFB. Define DISABLE_WP_CRON in wp-config.php and add a real system cron that hits wp-cron.php every few minutes. This needs server access, so WPOptimizing does not change it for you.'=>'يُشغّل ووردبريس افتراضياً المهام المجدولة أثناء الزيارات، مما قد يزيد TTFB. عرّف DISABLE_WP_CRON في wp-config.php وأضِف cron حقيقياً على مستوى النظام يستدعي wp-cron.php كل بضع دقائق. يتطلب ذلك وصولاً إلى الخادم، لذا لا يغيّره WPOptimizing نيابةً عنك.','On system cron'=>'على cron النظام','Server & hosting'=>'الخادم والاستضافة','PHP %1$s · OPcache %2$s. If the levers above are all green and TTFB is still high, the remaining time is your server: a modern PHP version, OPcache enabled, enough hosting resources and a light theme matter most. WPOptimizing cannot change these.'=>'PHP %1$s · OPcache %2$s. إذا كانت كل المفاتيح أعلاه خضراء وظل TTFB مرتفعاً، فالزمن المتبقي هو خادمك: إصدار PHP حديث، وتفعيل OPcache، وموارد استضافة كافية، وقالب خفيف هي الأهم. لا يستطيع WPOptimizing تغيير ذلك.','enabled'=>'مُفعَّل','disabled'=>'معطّل','OPcache on'=>'OPcache مُفعَّل','Fetch your Google PageSpeed score and Core Web Vitals. This sends your site URL to Google’s public API and changes nothing on your site.'=>'احصل على درجة Google PageSpeed ومؤشرات Core Web Vitals لموقعك. يرسل هذا رابط موقعك إلى واجهة Google العامة ولا يغيّر أي شيء في موقعك.','Page to test'=>'الصفحة المراد اختبارها','Test mobile'=>'اختبار الجوال','Test desktop'=>'اختبار سطح المكتب','desktop'=>'سطح المكتب','mobile'=>'الجوال','Performance (%s)'=>'الأداء (%s)','LCP'=>'LCP','INP'=>'INP','CLS'=>'CLS','FCP'=>'FCP','TBT'=>'TBT','Speed Index'=>'مؤشر السرعة','Largest element (LCP):'=>'أكبر عنصر (LCP):','It is an image and it is already in your preload list.'=>'إنها صورة وهي موجودة بالفعل في قائمة التحميل المسبق.','It is an image: if it is the same on every page of this kind, add its URL to "Preload key resources" so the browser asks for it first. A featured image is preloaded on its own when that option is on.'=>'إنها صورة: إن كانت هي نفسها في كل صفحات هذا النوع، فأضف عنوانها إلى «التحميل المسبق للموارد الرئيسية» ليطلبها المتصفح أولًا. تُحمَّل الصورة البارزة مسبقًا تلقائيًا عند تفعيل ذلك الخيار.','Field data (real visitors, last 28 days) is included when Google has enough traffic for your site.'=>'تُدرَج بيانات الميدان (زوّار حقيقيون، آخر 28 يوماً) عندما يتوفّر لدى Google زيارات كافية لموقعك.','Last tested %s ago.'=>'آخر اختبار قبل %s.','PageSpeed API key (optional)'=>'مفتاح واجهة PageSpeed (اختياري)','Not required. A free Google API key raises the request quota if you test often.'=>'غير مطلوب. يرفع مفتاح واجهة Google المجاني حصة الطلبات إذا كنت تختبر كثيراً.','Save API key'=>'حفظ مفتاح الواجهة','Database and Redis'=>'قاعدة البيانات وRedis','What MySQL and, if you use it, Redis say about themselves: only what needs fixing, with the setting that fixes it. Most of these are changed by your host.'=>'ما يقوله MySQL و، إن كنت تستخدمه، Redis عن نفسيهما: فقط ما يحتاج إلى إصلاح، مع الإعداد الذي يصلحه. معظم هذه الإعدادات يغيّرها مزوّد الاستضافة.','Nothing to fix'=>'لا شيء لإصلاحه','Important'=>'مهم','Worth a look'=>'يستحق نظرة','Database server'=>'خادم قاعدة البيانات','InnoDB buffer pool'=>'مجمّع ذاكرة InnoDB المؤقت','Your InnoDB data'=>'بيانات InnoDB لديك','Connections used / max'=>'الاتصالات المستخدمة / الحد الأقصى','Redis'=>'Redis','Redis memory'=>'ذاكرة Redis','Redis eviction policy'=>'سياسة الإخلاء في Redis','Redis hit rate'=>'نسبة إصابات Redis','Home page'=>'الصفحة الرئيسية','Latest post'=>'أحدث مقالة','A page'=>'صفحة','Latest product'=>'أحدث منتج','Shop'=>'المتجر','Busiest category'=>'التصنيف الأكثر مقالات','Previous tests'=>'الاختبارات السابقة','Page'=>'الصفحة','Device'=>'الجهاز','Score'=>'النتيجة','Real visitors over time (Chrome UX Report)'=>'الزوار الحقيقيون عبر الزمن (Chrome UX Report)','Values are the 75th percentile of real Chrome visits to the whole site, in 28-day windows. Lower is better.'=>'القيم هي المئين 75 لزيارات Chrome الحقيقية للموقع كله، في نوافذ من 28 يومًا. الأقل أفضل.','Needs the API key below, with the Chrome UX Report API enabled for it in the Google Cloud console.'=>'يحتاج مفتاح API أدناه، مع تفعيل Chrome UX Report API له في وحدة تحكم Google Cloud.','Load real-visitor history'=>'حمّل سجل الزوار الحقيقيين','You do not have permission.'=>'ليست لديك صلاحية.','Real-visitor history loaded.'=>'حُمّل سجل الزوار الحقيقيين.','Get one free at the <a href="%s" target="_blank" rel="noopener noreferrer">Google Cloud console</a> — it takes a couple of minutes and no card is required.'=>'احصل عليه مجانًا من <a href="%s" target="_blank" rel="noopener noreferrer">وحدة تحكم Google Cloud</a> — لا يستغرق الأمر سوى دقائق ولا يتطلب بطاقة.','PageSpeed test failed: %s'=>'فشل اختبار PageSpeed: %s','PageSpeed test completed.'=>'اكتمل اختبار PageSpeed.','Applying an index automatically is a Pro feature.'=>'تطبيق فهرس تلقائياً ميزة احترافية.','That index was not one of the suggestions, so it was not applied.'=>'لم يكن ذلك الفهرس من الاقتراحات، لذلك لم يُطبَّق.','The table or column no longer exists, so the index was not applied.'=>'لم تعد الجدول أو العمود موجوداً، لذلك لم يُطبَّق الفهرس.','That index already exists.'=>'هذا الفهرس موجود بالفعل.','The database cannot build this index without locking the table, and the table is too big to lock safely. Convert it to InnoDB in Tables, or have it created from the command line at a quiet time.'=>'لا تستطيع قاعدة البيانات إنشاء هذا الفهرس دون قفل الجدول، والجدول أكبر من أن يُقفل بأمان. حوّله إلى InnoDB من الجداول، أو اطلب إنشاء الفهرس من سطر الأوامر في وقت هادئ.','The database refused to create the index.'=>'رفضت قاعدة البيانات إنشاء الفهرس.','Index created. You can undo it below.'=>'تم إنشاء الفهرس. يمكنك التراجع عنه أدناه.','That index was not one WPOptimizing created, so it was left alone.'=>'لم يُنشئ WPOptimizing ذلك الفهرس، لذلك تُرك دون تغيير.','The table no longer exists.'=>'لم تعد الجدول موجودة.','The index is still there after removing it. Nothing was changed; try again.'=>'لا يزال الفهرس موجودًا بعد إزالته. لم يتغير شيء؛ حاول مرة أخرى.','The database refused to remove the index. It is still in place, and you can try again below.'=>'رفضت قاعدة البيانات إزالة الفهرس. لا يزال في مكانه، ويمكنك المحاولة مرة أخرى أدناه.','Index removed.'=>'تمت إزالة الفهرس.','PageSpeed API key saved.'=>'تم حفظ مفتاح واجهة PageSpeed.','CSS & JavaScript minification'=>'تصغير CSS وJavaScript','Serves minified copies of your local CSS and JS so they download faster. Safe and free: already-minified, external and excluded files are left untouched, and it never runs alongside another optimizer.'=>'يقدّم نسخاً مصغّرة من ملفات CSS وJS المحلية لتنزيلها بسرعة أكبر. آمن ومجاني: تُترك الملفات المصغّرة مسبقاً والخارجية والمستثناة دون تغيير، ولا يعمل أبداً بجانب أداة تحسين أخرى.','Another asset optimizer is active (%s). WPOptimizing minification stays off to avoid conflicts.'=>'توجد أداة تحسين موارد أخرى نشطة (%s). يبقى تصغير WPOptimizing متوقفاً لتجنّب التعارضات.','Minify CSS'=>'تصغير CSS','Minify JavaScript'=>'تصغير JavaScript','Exclude these handles or URL fragments (one per line)'=>'استثناء هذه المُعرِّفات أو أجزاء الروابط (واحد في كل سطر)','Defer JavaScript (load local scripts after the page renders; jQuery stays eager)'=>'تأجيل JavaScript (تحميل السكربتات المحلية بعد عرض الصفحة؛ يبقى jQuery فورياً)','Do not defer these handles or URL fragments (one per line)'=>'عدم تأجيل هذه المُعرِّفات أو أجزاء الروابط (واحد في كل سطر)','Load CSS asynchronously (non-blocking render; may briefly flash unstyled until you add critical CSS)'=>'تحميل CSS بشكل غير متزامن (لا يحجب العرض؛ قد يظهر وميض قصير بدون تنسيق حتى تضيف CSS الحرِج)','Keep these stylesheets render-blocking (your critical/above-the-fold CSS; one per line)'=>'إبقاء أوراق الأنماط هذه حاجبة للعرض (CSS الحرِج أو الظاهر أولاً؛ واحدة في كل سطر)','Critical CSS (inlined in the head, before the async stylesheets, to remove the flash)'=>'CSS الحرِج (يُضمَّن في الترويسة، قبل أوراق الأنماط غير المتزامنة، لإزالة الوميض)','Paste the above-the-fold CSS generated by your tool of choice. Leave empty to disable.'=>'الصق CSS الظاهر أولاً الذي أنشأته بالأداة التي تفضّلها. اتركه فارغاً لتعطيله.','Save minification settings'=>'حفظ إعدادات التصغير','JavaScript deferral, asynchronous CSS loading and inlined critical CSS are not included in this plugin.'=>'تأجيل JavaScript وتحميل CSS غير المتزامن وCSS الحرِج المُضمَّن غير مضمّنة في هذه الإضافة.','Pro adds JavaScript deferral (scripts load after the page renders), asynchronous CSS loading and inlined critical CSS on top of this free minification.'=>'تضيف Pro تأجيل JavaScript (تُحمَّل السكربتات بعد عرض الصفحة)، وتحميل CSS غير المتزامن، وCSS الحرِج المُضمَّن فوق هذا التصغير المجاني.','Critical CSS per template'=>'CSS حرج لكل قالب','Reads one representative page per template and works out which rules it could possibly use, then inlines that subset so the first paint does not wait for the full stylesheets. The originals keep loading in the background, so anything the extraction missed still arrives.'=>'يقرأ صفحة ممثِّلة عن كل قالب ويستنتج القواعد التي قد تستعملها، ثم يُضمِّن هذه المجموعة الجزئية حتى لا ينتظر الرسم الأول أوراق الأنماط الكاملة. تبقى الأصلية تُحمَّل في الخلفية، فما فات الاستخراجَ يصل رغم ذلك.','Generating critical CSS per template is a Pro feature.'=>'توليد CSS حرج لكل قالب ميزة احترافية.','Inlining critical CSS only pays off with asynchronous CSS switched on above: otherwise the full stylesheets still block the first paint and the inlined copy is simply extra bytes.'=>'لا يفيد تضمين CSS الحرج إلا مع تفعيل CSS غير المتزامن أعلاه: وإلا ظلت الأوراق الكاملة تحجب الرسم الأول وصارت النسخة المضمَّنة بايتات زائدة فحسب.','The theme or the active plugins have changed since this was generated, so the stored CSS no longer matches what the pages load. Generate it again before relying on it.'=>'تغيَّر القالب أو الإضافات المفعَّلة منذ التوليد، فلم يعد CSS المحفوظ مطابقًا لما تحمّله الصفحات. أعد التوليد قبل الاعتماد عليه.','Nothing generated yet. Generating only reads pages and writes files; it changes nothing a visitor sees until you apply it.'=>'لم يُولَّد شيء بعد. التوليد يقرأ صفحات ويكتب ملفات فقط؛ ولا يتغير شيء يراه الزائر حتى تطبّقه.','Never reduce these stylesheets (one handle or URL fragment per line)'=>'لا تُقلَّص أوراق الأنماط هذه أبدًا (معرّف أو جزء رابط في كل سطر)','Their rules are left out of the inlined copy entirely, so they arrive only with the original sheet.'=>'تبقى قواعدها خارج النسخة المضمَّنة تمامًا، فلا تصل إلا مع ورقة الأنماط الأصلية.','Generate'=>'توليد','Apply to the site'=>'تطبيق على الموقع','Stop applying'=>'إيقاف التطبيق','Delete and revert'=>'حذف وتراجع','Any page loaded with %s ignores the inlined CSS, so a layout problem can be attributed or ruled out without changing a setting.'=>'أي صفحة تُحمَّل مع %s تتجاهل CSS المضمَّن، فيمكن عزو مشكلة في التنسيق إليه أو استبعاده دون تغيير أي إعداد.','Template'=>'قالب','Stylesheets'=>'أوراق الأنماط','Original'=>'الأصل','Inlined'=>'مضمَّن','%1$s (%2$s%%)'=>'%1$s (%2$s %%)','Critical CSS is a Pro feature.'=>'CSS الحرج ميزة احترافية.','Critical CSS deleted. The site is serving its stylesheets exactly as before.'=>'حُذف CSS الحرج. يقدّم الموقع أوراق أنماطه تمامًا كما كان.','Critical CSS is now being inlined.'=>'يجري الآن تضمين CSS الحرج.','Critical CSS is stored but no longer inlined.'=>'CSS الحرج محفوظ لكنه لم يعد يُضمَّن.','Generated, with %s template(s) that could not be read. Check the table before applying.'=>'تم التوليد، مع %s قالب/قوالب تعذّرت قراءتها. راجع الجدول قبل التطبيق.','Generated. Nothing has changed for visitors yet — review the sizes and the preview, then apply.'=>'تم التوليد. لم يتغير شيء للزوار بعد — راجع الأحجام والمعاينة ثم طبّق.','Delay JavaScript until the first interaction'=>'تأخير JavaScript حتى أول تفاعل','Holds scripts back until the visitor moves, taps, scrolls or types — the single biggest improvement to responsiveness, because that work leaves the load path entirely. Off by default, and conservative when on.'=>'يحجز السكربتات حتى يحرّك الزائر أو يلمس أو يمرّر أو يكتب — أكبر تحسّن ممكن في الاستجابة، لأن هذا العمل يغادر مسار التحميل بالكامل. معطَّل افتراضيًا، ومتحفظ عند تفعيله.','Another asset optimizer is active (%s). Delaying stays off: two plugins rewriting the same script tags is how a site ends up with scripts that never run.'=>'هناك أداة تحسين موارد أخرى مفعَّلة (%s). يبقى التأخير معطَّلًا: إضافتان تعيدان كتابة الوسوم نفسها هو ما ينتهي بموقع فيه سكربتات لا تعمل أبدًا.','Delaying JavaScript until the first interaction is a Pro feature.'=>'تأخير JavaScript حتى أول تفاعل ميزة احترافية.','What to delay'=>'ما الذي يُؤخَّر','Known third parties only (recommended)'=>'الأطراف الخارجية المعروفة فقط (موصى به)','Analytics, tag managers, pixels, chat widgets and social embeds. Your theme and plugins keep running exactly as they do now, so nothing that renders the page is affected.'=>'التحليلات ومديرو الوسوم والبكسلات وأدوات الدردشة والتضمينات الاجتماعية. يظل قالبك وإضافاتك تعمل تمامًا كما الآن، فلا يتأثر شيء مما يرسم الصفحة.','Every script except the exclusions'=>'كل السكربتات عدا الاستثناءات','Faster, and the option that can break things: a slider, a menu or a cart that needs its script to run before the visitor touches anything will look broken until they do. Test the site before leaving this on.'=>'أسرع، وهو الخيار الذي قد يكسر أشياء: شريط عرض أو قائمة أو سلة تحتاج سكربتها قبل أن يلمس الزائر شيئًا ستبدو معطلة حتى يفعل. اختبر الموقع قبل إبقاء هذا مفعَّلًا.','Run anyway after'=>'شغِّلها على أي حال بعد','seconds'=>'ثانية','The safety timer. Without it a visit that never interacts would never load analytics, and every bounce would go uncounted — which is how a site owner stops trusting their numbers.'=>'مؤقّت الأمان. بدونه لن تُحمَّل التحليلات أبدًا في زيارة بلا تفاعل، ولن يُحتسب أي ارتداد — وهكذا يكفّ صاحب الموقع عن الثقة بأرقامه.','jQuery'=>'jQuery','WooCommerce cart and checkout'=>'سلة WooCommerce والدفع','Elementor'=>'Elementor','Other page builders (Avada, Divi, Bricks, Oxygen, Breakdance)'=>'منشئو صفحات آخرون (Avada وDivi وBricks وOxygen وBreakdance)','Sliders and carousels'=>'العروض المتحركة والدوّارات','Maps'=>'الخرائط','Forms'=>'النماذج','Never delay these kinds of script'=>'لا تؤخّر هذه الأنواع من السكربتات أبدًا','The usual suspects when something stops working after delaying "all scripts": tick the ones your site uses.'=>'المشتبه بهم المعتادون عندما يتوقف شيء عن العمل بعد تأخير «كل السكربتات»: حدّد ما يستخدمه موقعك.','Never delay these (one handle or URL fragment per line)'=>'لا تؤخّر هذه أبدًا (معرّف أو جزء رابط في كل سطر)','Also delay these (one handle or URL fragment per line)'=>'أخّر هذه أيضًا (معرّف أو جزء رابط في كل سطر)','Adds to the recommended profile without switching to the aggressive one.'=>'يوسّع الملف الموصى به دون الانتقال إلى الملف الصارم.','Never delayed, whatever is set above: consent and cookie banners, payment providers and captchas. Delaying a consent banner is a compliance problem, not a speed one, and a delayed payment or captcha script fails silently — the form looks fine and submits nothing.'=>'لا تتأخر أبدًا مهما ضُبط أعلاه: لافتات الموافقة والكوكيز، ومزوّدو الدفع، وأنظمة التحقق. تأخير لافتة الموافقة مشكلة امتثال لا مشكلة سرعة، وسكربت الدفع أو التحقق المؤخَّر يفشل بصمت — يبدو النموذج سليمًا ولا يرسل شيئًا.','To compare both versions of a page, add %s to any URL: that request loads every script immediately, without changing this setting.'=>'لمقارنة نسختَي الصفحة، أضف %s إلى أي رابط: يحمّل ذلك الطلب كل السكربتات فورًا دون تغيير هذا الإعداد.','Save delay settings'=>'حفظ إعدادات التأخير','Delaying JavaScript is a Pro feature.'=>'تأخير JavaScript ميزة احترافية.','Delay settings saved.'=>'حُفظت إعدادات التأخير.','Minification settings saved.'=>'تم حفظ إعدادات التصغير.','Run a one-off, consented test that measures exactly where the server time goes — boot, plugin loading, routing, database and render. It does NOT affect your site in normal operation: nothing runs until you start a test, and it stops on its own after a few requests.'=>'شغّل اختباراً لمرة واحدة وبموافقتك يقيس بدقة أين يُصرف وقت الخادم: الإقلاع، وتحميل الإضافات، والتوجيه، وقاعدة البيانات، والعرض. لا يؤثر على موقعك في التشغيل العادي: لا يعمل أي شيء حتى تبدأ اختباراً، ويتوقف تلقائياً بعد بضع طلبات.','Run diagnostic test'=>'تشغيل اختبار التشخيص','The deep analysis test profiles your requests to pinpoint the exact culprit. The TTFB diagnosis, levers and trend above stay free.'=>'يحلّل اختبارُ التحليل العميق طلباتِك لتحديد المتسبّب بدقة. أما تشخيص TTFB والأدوات والاتجاه أعلاه فتبقى مجانية.','Run profiling test'=>'تشغيل اختبار القياس','Profiles the next few front-end requests, then disarms automatically.'=>'يقيس الطلبات القليلة التالية في الواجهة الأمامية ثم يتعطّل تلقائياً.','Diagnostic report'=>'تقرير التشخيص','The detailed breakdown of your last profiling test: where the server time went, which hooks and plugins cost the most, and what to do about it.'=>'التحليل التفصيلي لآخر اختبار تشخيص: أين ذهب وقت الخادم، وأي الخطافات والإضافات كلّفت الأكثر، وما العمل.','No profiling report yet. Run a diagnostic test from the assistant and it will appear here.'=>'لا يوجد تقرير بعد. شغّل اختبار تشخيص من المساعد وسيظهر هنا.','Back to the assistant'=>'العودة إلى المساعد','Boot — loading PHP, WordPress and plugins'=>'الإقلاع — تحميل PHP وWordPress والإضافات','Plugin startup (init) — plugins set themselves up'=>'بدء تشغيل الإضافات (init) — تُهيّئ الإضافات نفسها','Everything loaded (wp_loaded)'=>'اكتمل التحميل (wp_loaded)','Routing — choosing the page'=>'التوجيه — اختيار الصفحة','Main query — fetching the content'=>'الاستعلام الرئيسي — جلب المحتوى','Render — building and sending the page'=>'العرض — بناء الصفحة وإرسالها','Most of the time is spent just loading WordPress and the active plugins — usually a sign of too many or very heavy plugins.'=>'يُقضى معظم الوقت فقط في تحميل WordPress والإضافات النشطة — وغالباً ما يدل ذلك على كثرة الإضافات أو وجود إضافات ثقيلة جداً.','Most of the time is spent while plugins start up on every page load (the WordPress init step). The list below shows what ran and when — if the biggest entry is named after a plugin, that is the one to look at.'=>'يمضي معظم الوقت بينما تُهيّئ الإضافات نفسها في كل تحميل للصفحة (خطوة init في ووردبريس). تُظهر القائمة أدناه ما جرى تنفيذه ومتى: إن كان أكبر عنصر يحمل اسم إضافة، فهي التي ينبغي النظر فيها.','Most of the time is spent right after everything loaded — see the list below to find which hook is responsible.'=>'يُستهلك معظم الوقت مباشرة بعد اكتمال التحميل — راجع القائمة أدناه لمعرفة الخطاف المسؤول.','Most of the time is spent working out which page this is — permalink rules, redirects and anything hooked into routing.'=>'يذهب معظم الوقت في تحديد أي صفحة هذه: قواعد الروابط الدائمة وعمليات إعادة التوجيه وكل ما يرتبط بالتوجيه.','Most of the time is spent on the query that fetches the content of this page — often slow queries or a plugin filtering them.'=>'يذهب معظم الوقت إلى الاستعلام الذي يجلب محتوى هذه الصفحة — غالبًا استعلامات بطيئة أو إضافة تقوم بتصفيتها.','Most of the time is spent building and sending the page itself — this is the theme and, if you use one, the page builder.'=>'يذهب معظم الوقت في بناء الصفحة نفسها وإرسالها: هذا هو القالب، وأداة بناء الصفحات إن كنت تستخدم واحدة.','Slowest of the last %2$d profiled requests: %1$d ms · captured %3$s ago.'=>'الأبطأ من بين آخر %2$d من الطلبات المُحلَّلة: %1$d مللي ثانية · التُقطت قبل %3$s.','%1$d samples · median %2$d ms · p95 %3$d ms · range %4$d–%5$d ms.'=>'%1$d عيّنات · الوسيط %2$d ms · p95 %3$d ms · المدى %4$d–%5$d ms.','One sample, so there is no spread to judge yet — run the test again to see whether this is typical.'=>'عيّنة واحدة فقط، فلا يوجد تشتّت للحكم عليه بعد — أعد التشغيل لترى إن كان هذا هو المعتاد.','The object cache was COLD for this request: it had to be filled from the database. A warm request is considerably faster.'=>'كانت ذاكرة الكائنات باردة في هذا الطلب: كان لا بد من ملئها من قاعدة البيانات. الطلب مع ذاكرة دافئة أسرع بكثير.','The object cache was warm for this request.'=>'كانت ذاكرة الكائنات دافئة في هذا الطلب.','a visit that runs WP-Cron is much slower than one that does not'=>'الزيارة التي تشغّل WP-Cron أبطأ بكثير من التي لا تشغّله','a request that misses the object cache is much slower than one that hits it'=>'الطلب الذي يخفق في إصابة ذاكرة الكائنات أبطأ بكثير من الطلب الذي يصيبها','This is one real request from the test. The TTFB shown in the Performance assistant above is instead a rolling average of recent visits, so the two numbers differ — front-end TTFB swings request to request (%s).'=>'هذا طلب حقيقي من الاختبار. أما TTFB المعروض أعلاه في مساعد الأداء فهو متوسط متحرك للزيارات الأخيرة، لذا يختلف الرقمان — يتذبذب TTFB للواجهة من طلب لآخر (%s).','Here it is not one plugin: the biggest single step is WordPress itself (%s), which every plugin on the site shares.'=>'لا توجد إضافة مذنبة هنا: أكبر خطوة منفردة هي ووردبريس نفسه (%s)، وتتشاركها كل إضافات الموقع.','Where the time went (top hooks)'=>'أين ذهب الوقت (أهم الخطافات)','first use — warms up after this'=>'أول استخدام — بعدها تبقى محمّلة','fired by %s'=>'يُطلقه %s','These are the actions/filters that consumed the most server time, each with the stage it ran in — they do not all belong to the biggest bar above. A hook named after a plugin (e.g. woocommerce_, elementor/) points straight at that plugin; a slow generic hook means several plugins share the cost.'=>'هذه هي الإجراءات/المرشحات التي استهلكت أكبر قدر من وقت الخادم، كل منها مع المرحلة التي جرى فيها — وهي لا تنتمي كلها إلى أكبر شريط في الأعلى. الخطاف الذي يحمل اسم إضافة (مثل woocommerce_ أو elementor/) يشير إليها مباشرة؛ أما الخطاف العام البطيء فيعني أن عدة إضافات تتقاسم التكلفة.','Database this request'=>'قاعدة البيانات في هذا الطلب','%1$d queries · %2$d ms · %3$d slow (>50 ms)'=>'%1$d استعلام · %2$d مللي ثانية · %3$d بطيء (>50 مللي ثانية)','Most repeated queries by source (plugin/theme):'=>'أكثر الاستعلامات تكراراً حسب المصدر (إضافة/قالب):','Full table scan with no usable index'=>'مسح كامل للجدول دون فهرس قابل للاستخدام','Full table scan'=>'مسح كامل للجدول','Sorting rows without an index (filesort)'=>'فرز الصفوف دون فهرس (filesort)','Building a temporary table'=>'إنشاء جدول مؤقت','Slow queries that may be missing an index'=>'استعلامات بطيئة قد ينقصها فهرس','(~%1$s rows scanned · %2$d ms)'=>'(~%1$s صف تم مسحه · %2$d مللي ثانية)','Suggested index:'=>'الفهرس المقترَح:','Create this index now? On a large table it can take a while and load the database meanwhile. You can remove it afterwards.'=>'هل تريد إنشاء هذا الفهرس الآن؟ في جدول كبير قد يستغرق ذلك وقتًا ويُثقل قاعدة البيانات في أثناء ذلك. يمكنك إزالته لاحقًا.','Apply index'=>'تطبيق الفهرس','These SELECTs scanned a large table without a usable index. Adding the suggested index usually makes them much faster. WPOptimizing only creates one when you press its button and confirm, and you can remove it again below; on a large table it can take a while and load the database meanwhile, so do it at a quiet time. Queries with a compound or range condition are listed without a suggestion because the right index depends on the exact query.'=>'فحصت استعلامات SELECT هذه جدولًا كبيرًا دون فهرس صالح. إضافة الفهرس المقترح تجعلها عادةً أسرع بكثير. لا ينشئ WPOptimizing فهرسًا إلا عندما تضغط زره وتؤكد، ويمكنك إزالته أدناه؛ في جدول كبير قد يستغرق ذلك وقتًا ويُثقل قاعدة البيانات، لذا افعل ذلك في وقت هادئ. تُدرج الاستعلامات ذات الشرط المركّب أو الشرط على نطاق دون اقتراح، لأن الفهرس المناسب يعتمد على الاستعلام بعينه.','Pro can create a suggested index for you with one click (and undo it just as easily).'=>'يمكن للنسخة Pro إنشاء فهرس مقترَح لك بنقرة واحدة (والتراجع عنه بالسهولة نفسها).','Indexes WPOptimizing created'=>'الفهارس التي أنشأها WPOptimizing','on'=>'على','Remove this index?'=>'إزالة هذا الفهرس؟','What to do about it'=>'ما العمل','Nothing stands out: the server response time is healthy. The remaining time is your server/hosting (PHP version, OPcache, resources), which WPOptimizing cannot change.'=>'لا شيء يبرز: زمن استجابة الخادم سليم. الوقت المتبقي يعود إلى خادمك/استضافتك (إصدار PHP، OPcache، الموارد)، وهو ما لا يستطيع WPOptimizing تغييره.','Anything left after these is your server/hosting (PHP version, OPcache, hosting resources, a light theme), which WPOptimizing cannot change.'=>'ما يتبقى بعد ذلك يعود إلى خادمك/استضافتك (إصدار PHP، OPcache، موارد الاستضافة، قالب خفيف)، وهو ما لا يستطيع WPOptimizing تغييره.','cold object cache or a visit that ran WP-Cron'=>'ذاكرة كائنات باردة أو زيارة شغّلت WP-Cron','cold object cache'=>'ذاكرة كائنات باردة','Translation loading (~%d ms)'=>'تحميل الترجمات (~%d مللي ثانية)','Plugins translate their text on every page load. Keep WordPress and your plugins up to date (6.5+ caches translations), and remove language files for locales you do not use.'=>'تترجم الإضافات نصوصها في كل تحميل للصفحة. حافظ على تحديث ووردبريس والإضافات (يخزّن الإصدار 6.5+ الترجمات مؤقتاً) واحذف ملفات اللغات التي لا تستخدمها.','Loading the options table (~%1$d ms this request)'=>'تحميل جدول الخيارات (~%1$d مللي ثانية في هذا الطلب)','Your autoload payload is already healthy (%1$s), so this is a slow one-off request (%2$s), not a size problem. Typical requests are much faster; no action needed.'=>'حِمل التحميل التلقائي لديك سليم بالفعل (%1$s)، لذا فهذا طلب بطيء لمرة واحدة (%2$s)، وليس مشكلة حجم. الطلبات المعتادة أسرع بكثير؛ لا حاجة لأي إجراء.','Loading the options table (~%d ms)'=>'تحميل جدول الخيارات (~%d مللي ثانية)','Too many autoloaded options are read on every request. Trim them from the Autoload tab (Smart Deactivation is reversible).'=>'تُقرأ خيارات autoload كثيرة جداً في كل طلب. قلّصها من تبويب Autoload (التعطيل الذكي قابل للتراجع).','Open Autoload'=>'فتح Autoload','Options that do not exist (~%d ms)'=>'خيارات غير موجودة (~%d ms)','These options are asked for on every request but are not stored, so each lookup returns nothing: %s. This is the plugin that owns them falling back to a default, not a fault of your site — it is worth reporting to its author.'=>'تُطلب هذه الخيارات في كل طلب لكنها غير مخزَّنة، فيعود كل بحث فارغًا: %s. هذه هي الإضافة المالكة لها وهي ترجع إلى قيمة افتراضية، وليس خللًا في موقعك — يستحق إبلاغ مطوّرها.','Your theme %1$s is doing heavy work (~%2$d ms)'=>'سِمتك %1$s تقوم بعمل ثقيل (~%2$d مللي ثانية)','The active theme runs real work on every page load. You cannot deactivate the active theme, but a lighter one would cut this — or review the theme / page-builder options and switch off elements and features you do not use.'=>'تُنفِّذ السِّمة النشطة عملًا حقيقيًا في كل تحميل صفحة. لا يمكنك تعطيل السِّمة النشطة، لكن سِمة أخف ستقلّل ذلك — أو راجع خيارات السِّمة / منشئ الصفحات وأوقف العناصر والميزات التي لا تستخدمها.','%1$s is doing heavy work (~%2$d ms)'=>'‏%1$s يقوم بعمل ثقيل (~%2$d ms)','Your site depends on this one, so switching it off is not an option — but it rarely needs everything it loads. Check its own settings for features you do not use, and stop its CSS and JavaScript loading on the pages that do not need them from the Smart Assets tab.'=>'يعتمد موقعك على هذه، فإيقافها ليس خيارًا — لكنها نادرًا ما تحتاج كل ما تحمّله. راجع إعداداتها بحثًا عن ميزات لا تستخدمها، وأوقف تحميل ملفات CSS وJavaScript الخاصة بها في الصفحات التي لا تحتاجها من تبويب Smart Assets.','Open Smart Assets'=>'فتح Smart Assets','The plugin %1$s is doing heavy work (~%2$d ms)'=>'الإضافة %1$s تقوم بعمل ثقيل (~%2$d مللي ثانية)','This plugin spends real time on every page load. Deactivate it if you no longer need it, or look for a lighter alternative.'=>'تستهلك هذه الإضافة وقتًا حقيقيًا في كل تحميل صفحة. عطّلها إن لم تعد بحاجة إليها، أو ابحث عن بديل أخف.','Database queries (%1$d queries · %2$d ms this request)'=>'استعلامات قاعدة البيانات (%1$d استعلامات · %2$d مللي ثانية في هذا الطلب)','A persistent object cache is already active, so these are uncached queries on this specific request (often a %s outlier). If the query time stays high across requests, the heaviest plugin listed above is the place to look.'=>'توجد بالفعل ذاكرة كائنات دائمة نشطة، لذا فهذه استعلامات غير مخزَّنة لهذا الطلب تحديدًا (غالبًا حالة شاذة بسبب %s). إذا ظل زمن الاستعلامات مرتفعًا في كل الطلبات، فراجع أثقل إضافة في القائمة أعلاه.','Database queries (%1$d queries · %2$d ms)'=>'استعلامات قاعدة البيانات (%1$d استعلام · %2$d مللي ثانية)','A persistent object cache keeps expensive queries in memory and is the single biggest server-TTFB win. Enable it from the Cache tab.'=>'تحتفظ ذاكرة الكائنات الدائمة بالاستعلامات المكلفة في الذاكرة وهي أكبر مكسب لزمن TTFB في الخادم. فعّلها من تبويب الذاكرة المؤقتة.','Open Cache'=>'فتح الذاكرة المؤقتة','One file accounts for most of your CSS and JavaScript: %1$s (%2$s)'=>'ملف واحد يستحوذ على معظم ملفات CSS وJavaScript لديك: %1$s (%2$s)','Your pages ship %s of CSS and JavaScript'=>'ترسل صفحاتك %s من CSS وJavaScript','Measured across the %3$d assets this site enqueues: %1$s of CSS and %2$s of JavaScript. Every visitor downloads this before the page can finish. The biggest win is usually not making the files smaller but not sending them where they are not used — Smart Assets shows which plugin owns each one and lets you unload it per page.'=>'مقيسة عبر %3$d من الموارد التي يضيفها هذا الموقع: %1$s من CSS و%2$s من JavaScript. يُنزّل كل زائر هذا قبل أن تكتمل الصفحة. المكسب الأكبر عادةً ليس تصغير الملفات بل عدم إرسالها حيث لا تُستخدم — يعرض Smart Assets الإضافة المالكة لكل ملف ويتيح إلغاء تحميله لكل صفحة.','%1$d of the %2$d images on your home page have no width and height'=>'‏%1$d من أصل %2$d صورة في صفحتك الرئيسية بلا عرض ولا ارتفاع','Without those two attributes the browser cannot reserve the space, so everything below each image jumps down when it finally arrives. This is what Core Web Vitals measures as layout shift, and it is the single most irritating thing a page can do to a reader. Turn on content image optimization below, and for images printed by the theme rather than by the content, ask its author — or replace them with images from the media library, which carry their size.'=>'بدون هذين الخاصيتين لا يستطيع المتصفح حجز المساحة، فيقفز كل ما تحت الصورة إلى الأسفل عند وصولها أخيرًا. هذا بالضبط ما تقيسه مؤشرات Core Web Vitals بوصفه إزاحةً للتخطيط، وهو أكثر ما يزعج القارئ في أي صفحة. فعِّل أدناه تحسين صور المحتوى، وبالنسبة للصور التي تطبعها القالب لا المحتوى فاسأل مطوّرها — أو استبدلها بصور من مكتبة الوسائط، فهي تحمل أبعادها معها.','%1$d of the %2$d images on your home page load immediately'=>'‏%1$d من أصل %2$d صورة في صفحتك الرئيسية تُحمَّل فورًا','Images the visitor has not scrolled to yet are competing for bandwidth with the ones they can already see, so the visible part of the page finishes later than it needs to. Content image optimization adds the deferral automatically and leaves the first image eager, which is the one that should load first.'=>'الصور التي لم يصل إليها الزائر بعد تزاحم الصور التي يراها فعلًا على عرض النطاق، فيكتمل الجزء المرئي من الصفحة متأخرًا أكثر مما يلزم. يضيف تحسين صور المحتوى التأجيل تلقائيًا ويترك الصورة الأولى بلا تأجيل، وهي التي ينبغي أن تصل أولًا.','%1$d of the %2$d images on your home page offer only one size'=>'‏%1$d من أصل %2$d صورة في صفحتك الرئيسية تقدّم مقاسًا واحدًا فقط','With no list of alternative sizes, a phone downloads the same file a desktop does — often several times larger than its screen can show. Images inserted from the media library get that list from WordPress automatically; ones hard-coded in a template or pasted as raw HTML do not.'=>'بلا قائمة مقاسات بديلة، يُنزِّل الهاتف الملف نفسه الذي يُنزِّله الحاسوب — وغالبًا بأضعاف ما تستطيع شاشته عرضه. الصور المُدرَجة من مكتبة الوسائط تحصل على تلك القائمة من ووردبريس تلقائيًا، أما المكتوبة يدويًا في قالب أو الملصقة بصيغة HTML خام فلا.','Your home page is built from %d HTML elements'=>'صفحتك الرئيسية مبنية من %d عنصر HTML','Past roughly 1,400 elements the browser spends real time on style and layout for every change on the page, and past 2,500 it is the dominant cost — whatever the server does. The usual cause is a page builder nesting rows inside columns inside containers, or a very long archive. Showing fewer items per page, or flattening the sections you build most often, does more here than any server-side setting.'=>'بعد نحو 1400 عنصر يقضي المتصفح وقتًا حقيقيًا في التنسيق والتخطيط مع كل تغيير في الصفحة، وبعد 2500 يصبح ذلك هو التكلفة الغالبة مهما فعل الخادم. السبب المعتاد هو أداة بناء صفحات تُعشِّش الصفوف داخل الأعمدة داخل الحاويات، أو أرشيف طويل جدًا. عرض عناصر أقل في الصفحة، أو تبسيط الأقسام التي تبنيها أكثر من غيرها، يفيد هنا أكثر من أي إعداد على الخادم.','%d elements on your home page carry their own inline styles'=>'‏%d عنصرًا في صفحتك الرئيسية يحمل أنماطه المضمّنة الخاصة','A style attribute cannot be cached, minified or reused between pages: it is re-sent in full with every request. At this volume a builder is writing a stylesheet one element at a time. Check whether it offers a “load CSS as a file” or “combine styles” option — that alone moves the weight into something the browser can cache.'=>'لا يمكن تخزين خاصية style مؤقتًا ولا تصغيرها ولا إعادة استخدامها بين الصفحات: تُرسَل كاملةً مع كل طلب. عند هذا الحجم تكون أداة البناء تكتب ورقة أنماط عنصرًا بعنصر. تحقّق مما إذا كانت تتيح خيار «تحميل CSS كملف» أو «دمج الأنماط» — هذا وحده ينقل الوزن إلى شيء يستطيع المتصفح تخزينه.','Open front-end settings'=>'فتح إعدادات الواجهة الأمامية','%1$d%% of this request went into one thing: %2$s'=>'ذهب %1$d%% من هذا الطلب إلى شيء واحد: %2$s','Everything else on this page was faster than this single step (%s). Whatever is worth improving here, it is that — not the sum of the small things.'=>'كان كل شيء آخر في هذه الصفحة أسرع من هذه الخطوة الواحدة (%s). إن كان هناك ما يستحق التحسين هنا فهو ذلك، لا مجموع الأشياء الصغيرة.','Loading PHP, WordPress and plugins (~%d ms)'=>'تحميل PHP وووردبريس والإضافات (~%d مللي ثانية)','Every active plugin adds boot time. Deactivate the ones you no longer use; a high count here usually means too many plugins.'=>'كل إضافة نشطة تضيف وقت إقلاع. عطّل ما لم تعد تستخدمه؛ العدد المرتفع هنا يعني عادةً إضافات كثيرة جداً.','%1$s %2$d ms'=>'%1$s %2$d ms','the rest %d ms'=>'الباقي %d ms','Made up of: %s.'=>'يتكوّن من: %s.','looking up an option that is not stored — %s'=>'البحث عن خيار غير مخزَّن — %s','loading the options table (autoload)'=>'تحميل جدول الخيارات (autoload)','reading an option'=>'قراءة خيار','database queries'=>'استعلامات قاعدة البيانات','registering blocks'=>'تسجيل الكتل','sanitising/escaping data'=>'تنقية/تهريب البيانات','WordPress itself'=>'ووردبريس نفسه','translation loading — %s'=>'تحميل الترجمات — %s','translation loading'=>'تحميل الترجمات','The deep analysis test is a Pro feature.'=>'اختبار التحليل العميق ميزة Pro.','Could not start the test: the data folder is not writable.'=>'تعذّر بدء الاختبار: مجلد البيانات غير قابل للكتابة.','Profiling test completed — see the breakdown below.'=>'اكتمل اختبار القياس — راجع التفصيل أدناه.','Profiling test armed. Open the public side of your site once, then reload this page to see the breakdown.'=>'تم تجهيز اختبار القياس. افتح الجزء العام من موقعك مرة واحدة، ثم أعد تحميل هذه الصفحة لرؤية التفصيل.','Done'=>'تم','Manual step'=>'خطوة يدوية','Heartbeat disabled.'=>'تم تعطيل Heartbeat.','Heartbeat updated.'=>'تم تحديث Heartbeat.','Stop a plugin from loading where it does nothing — a contact form everywhere but the contact page, a shop plugin on the blog. Its PHP, its queries and its CSS/JS all stay out. Only for visitors: logged-in users, the admin, AJAX, the REST API and cron always get every plugin.'=>'يمنع إضافة من التحميل حيث لا تفعل شيئًا: نموذج اتصال في كل مكان عدا صفحة الاتصال، أو إضافة متجر في المدونة. يبقى PHP الخاص بها واستعلاماتها وCSS/JS خارجًا. للزوار فقط: المستخدمون المسجّلون ولوحة التحكم وAJAX وواجهة REST وcron يحصلون دائمًا على كل الإضافات.','Unloading plugins per URL is a Pro feature.'=>'إيقاف الإضافات حسب الرابط ميزة Pro.','The rules were switched off by themselves: a visit to %1$s with plugins left out ended in a fatal error (%2$s). Review them, test again and save to turn them back on.'=>'توقفت القواعد من تلقاء نفسها: انتهت زيارة إلى %1$s مع استبعاد إضافات بخطأ فادح (%2$s). راجعها واختبرها مجددًا واحفظ لتشغيلها من جديد.','%d rule active' . "\0" . '%d rules active'=>'لا توجد قواعد نشطة (%d)' . "\0" . 'قاعدة واحدة نشطة (%d)' . "\0" . 'قاعدتان نشطتان (%d)' . "\0" . '%d قواعد نشطة' . "\0" . '%d قاعدة نشطة' . "\0" . '%d قاعدة نشطة','No rule is active.'=>'لا توجد قاعدة نشطة.','Load'=>'التحميل','URLs (one per line; * for anything, / for the home page)'=>'الروابط (واحد في كل سطر؛ * لأي شيء، / للصفحة الرئيسية)','Everywhere'=>'في كل مكان','Not on these URLs'=>'ليس في هذه الروابط','Only on these URLs'=>'فقط في هذه الروابط','URLs for %s'=>'روابط %s','Pages to test'=>'صفحات للاختبار','The home page is always tested. Add up to four more, ideally one of each kind the rules touch. Each is loaded twice as a visitor, with every plugin and with the rules, and compared.'=>'تُختبر الصفحة الرئيسية دائمًا. أضف حتى أربع أخرى، ويُفضّل واحدة من كل نوع تمسّه القواعد. تُحمّل كل واحدة مرتين كزائر، مع كل الإضافات ومع القواعد، ثم تُقارن.','Test'=>'اختبار','Test and save'=>'اختبار وحفظ','Switch every rule off'=>'إيقاف كل القواعد','Saving only happens when no tested page breaks. If a visit with plugins left out ever ends in a fatal error, every rule switches itself off. Deactivating WPOptimizing, or define( \'WPOPT_DISABLE\', true ) in wp-config.php, undoes everything at once.'=>'لا يتم الحفظ إلا إذا لم تتعطل أي صفحة مختبرة. إذا انتهت زيارة مع استبعاد إضافات بخطأ فادح، تتوقف كل القواعد من تلقاء نفسها. تعطيل WPOptimizing، أو define( \'WPOPT_DISABLE\', true ) في wp-config.php، يلغي كل شيء دفعة واحدة.','Every rule is off: all plugins load everywhere again. The rules are kept for later.'=>'كل القواعد متوقفة: تعود كل الإضافات للتحميل في كل مكان. تُحفظ القواعد لوقت لاحق.','%1$s is needed by %2$s. Give them all the same rule, or leave %1$s loading everywhere. Nothing was tested or saved.'=>'%2$s تحتاج إلى %1$s. أعطها جميعًا القاعدة نفسها، أو اترك %1$s تُحمّل في كل مكان. لم يُختبر أو يُحفظ أي شيء.','There are no rules: every plugin loads everywhere.'=>'لا توجد قواعد: كل الإضافات تُحمّل في كل مكان.','Not saved: at least one page breaks with these rules. The live rules are unchanged.'=>'لم يُحفظ: صفحة واحدة على الأقل تتعطل بهذه القواعد. القواعد السارية لم تتغير.','Saved and active. The page cache was emptied so visitors get the pages without those plugins.'=>'حُفظ وأصبح نشطًا. أُفرغت ذاكرة الصفحات المؤقتة كي يحصل الزوار على الصفحات دون تلك الإضافات.','The test could not start: the must-use folder (wp-content/mu-plugins) is not writable.'=>'تعذّر بدء الاختبار: لا يمكن الكتابة في مجلد must-use (wp-content/mu-plugins).','The page could not be loaded to compare it.'=>'تعذّر تحميل الصفحة لمقارنتها.','The page answers with an error.'=>'الصفحة تردّ بخطأ.','The page shows a PHP fatal error.'=>'الصفحة تعرض خطأ PHP فادحًا.','The page lost more than half of its HTML: check it looks right.'=>'فقدت الصفحة أكثر من نصف HTML: تحقّق من أنها تبدو سليمة.','Same answer as with every plugin.'=>'الرد نفسه كما مع كل الإضافات.','OK'=>'سليم','Check'=>'للمراجعة','Breaks'=>'تتعطل','Result'=>'النتيجة','Plugins left out'=>'الإضافات المستبعدة','HTML kept'=>'HTML المحفوظ','none'=>'لا شيء','Cleanup Report'=>'تقرير التنظيف','Last analysis:'=>'آخر تحليل:','Records analysed'=>'السجلات المُحلَّلة','Records cleaned'=>'السجلات المُنظَّفة','DB size analysed'=>'حجم قاعدة البيانات المُحلَّل','Orphans found'=>'اليتامى المعثور عليهم','Analysis summary'=>'ملخص التحليل','Pending review'=>'بانتظار المراجعة','Includes both database and filesystem records. Status reflects raw scan results; the live panel applies additional real-time attribution that may reclassify some entries.'=>'يشمل سجلات قاعدة البيانات ونظام الملفات معاً. تعكس الحالة نتائج الفحص الخام؛ تطبّق اللوحة الحية إسناداً إضافياً في الوقت الفعلي قد يعيد تصنيف بعض الإدخالات.','Extension breakdown (top 30 by record count)'=>'تفصيل الإضافات (أعلى 30 حسب عدد السجلات)','Recent cleanup operations'=>'عمليات التنظيف الأخيرة','User'=>'المستخدم','No cleanup operations recorded yet. Run a cleanup to generate history.'=>'لم تُسجَّل أي عمليات تنظيف بعد. شغّل تنظيفاً لإنشاء السجل.','Back to WPOptimizing'=>'العودة إلى WPOptimizing','Configure cleanup options, scheduling, backups, license and integrations. Quick profiles below apply a recommended configuration with one click.'=>'اضبط خيارات التنظيف والجدولة والنسخ الاحتياطية والترخيص والتكاملات. تطبّق ملفات التعريف السريعة أدناه إعدادًا موصى به بنقرة واحدة.','License is Active'=>'الترخيص نشط','License stored — not active'=>'الترخيص مخزّن — غير نشط','For security, the license key is hidden once stored. Deactivate it to enter a new one.'=>'لدواعٍ أمنية، يُخفى مفتاح الترخيص بمجرد تخزينه. ألغِ تفعيله لإدخال مفتاح جديد.','Enter your license key to unlock deletion of attributed records. All other features work without a key.'=>'أدخل مفتاح الترخيص لإلغاء قفل حذف السجلات المنسوبة. تعمل جميع الميزات الأخرى بدون مفتاح.','Expiration date: %s'=>'تاريخ الانتهاء: %s','Deactivate / Change License'=>'إلغاء التفعيل / تغيير الترخيص','Click to activate or deactivate your license key.'=>'انقر لتفعيل أو تعطيل مفتاح الترخيص الخاص بك.','How many backups to keep for each operation type. Older ones are pruned automatically.'=>'عدد النسخ الاحتياطية المحتفظ بها لكل نوع عملية. تُحذف الأقدم تلقائيًا.','Backups older than this many days are deleted automatically.'=>'تُحذف النسخ الاحتياطية الأقدم من هذا العدد من الأيام تلقائيًا.','Every change of your data is backed up first. When the backups would grow past this size, the change (or the cleanup) stops instead of filling the disk. 0 means no limit.'=>'كل تغيير في بياناتك يُنسخ احتياطيًا أولًا. وعندما تتجاوز النسخ الاحتياطية هذا الحجم، يتوقف التغيير (أو التنظيف) بدلًا من ملء القرص. القيمة 0 تعني بلا حد.','Where WPOptimizing sends the periodic report. For agencies managing client sites: route it to the maintainer instead of the site owner. Separate several addresses with commas. Leave empty to use the site admin email. Network alerts go to the network administrator instead.'=>'الوجهة التي يرسل إليها WPOptimizing التقرير الدوري. للوكالات التي تدير مواقع العملاء: وجّهه إلى المسؤول بدلًا من مالك الموقع. افصل بين عدة عناوين بفواصل. اتركه فارغًا لاستخدام بريد مدير الموقع. أما تنبيهات الشبكة فتُرسل إلى مدير الشبكة.','Where WPOptimizing sends license notices and the periodic report. For agencies managing client sites: route them to the maintainer instead of the site owner. Separate several addresses with commas. Leave empty to use the site admin email. Network alerts go to the network administrator instead.'=>'الوجهة التي يرسل إليها WPOptimizing إشعارات الترخيص والتقرير الدوري. للوكالات التي تدير مواقع العملاء: وجّهها إلى المسؤول بدلًا من مالك الموقع. افصل بين عدة عناوين بفواصل. اتركه فارغًا لاستخدام بريد مدير الموقع. أما تنبيهات الشبكة فتُرسل إلى مدير الشبكة.','Send a test now'=>'أرسل اختبارًا الآن','Email a recurring summary to the notification address above: the Health Score and its trend, key database/media metrics, unusual table growth and the activity since the last report. Off by default. The test is sent immediately to check delivery and does not change the schedule.'=>'يرسل ملخّصًا دوريًا إلى عنوان الإشعارات أعلاه: Health Score واتجاهه، والمقاييس الرئيسية لقاعدة البيانات/الوسائط، والنمو غير المعتاد للجداول، والنشاط منذ التقرير السابق. مُعطَّل افتراضيًا. يُرسَل الاختبار فورًا للتحقّق من التسليم ولا يغيّر الجدولة.','Continuously clear expired transients in the background'=>'مسح العناصر العابرة المنتهية باستمرار في الخلفية','Removes expired transients a small batch at a time on normal admin requests, so a site with a leaky transient producer never piles up thousands of dead rows between scans. Pure housekeeping — WordPress regenerates any transient on demand — and it does nothing when a persistent object cache is active. Off by default.'=>'يزيل العناصر العابرة المنتهية على دفعات صغيرة أثناء طلبات الإدارة العادية، بحيث لا يتراكم على موقع فيه مُنتِج عناصر عابرة متسرّب آلافُ الصفوف الميتة بين الفحوصات. صيانة خالصة — إذ يعيد ووردبريس توليد أي عنصر عابر عند الطلب — ولا يفعل شيئًا عندما تكون هناك ذاكرة كائنات دائمة نشطة. مُعطَّل افتراضيًا.','Delete ALL plugin data when the plugin is deleted'=>'حذف كل بيانات الإضافة عند حذف الإضافة','When you delete the plugin from Plugins, remove every trace it created: settings, transients, scheduled tasks, the object-cache and database drop-ins, all backups, scan data and the generated WebP/AVIF copies. Your already-optimized images are kept (only the extra next-gen copies and backups are removed). Leave this on to keep the site clean; turn it off only if you plan to reinstall and want to keep your settings and backups.'=>'عند حذف الإضافة من صفحة الإضافات، يُزال كل أثر أنشأته: الإعدادات والعناصر المؤقتة والمهام المجدولة، وإضافات object-cache وقاعدة البيانات (drop-ins)، وجميع النسخ الاحتياطية وبيانات الفحص ونسخ WebP/AVIF المُولَّدة. تبقى صورك المُحسَّنة بالفعل كما هي (تُزال فقط نسخ الجيل التالي الإضافية والنسخ الاحتياطية). اترك هذا مفعّلاً لإبقاء الموقع نظيفاً؛ ولا تعطّله إلا إذا كنت تنوي إعادة التثبيت وترغب في الاحتفاظ بإعداداتك ونسخك الاحتياطية.','Applies a recommended set of cleanup tasks for your site type. Performance tuning (object cache, query deduplication and Heartbeat) is configured automatically for each profile. You can still fine-tune the options below before saving.'=>'يطبّق مجموعة موصى بها من مهام التنظيف لنوع موقعك. يتم ضبط أداء النظام (ذاكرة التخزين المؤقت للكائنات وإزالة تكرار الاستعلامات و Heartbeat) تلقائيًا لكل ملف تعريف. لا يزال بإمكانك ضبط الخيارات أدناه قبل الحفظ.','Heartbeat: default'=>'Heartbeat: افتراضي','Heartbeat: slow'=>'Heartbeat: بطيء','Heartbeat: off'=>'Heartbeat: معطّل','object cache'=>'ذاكرة التخزين المؤقت للكائنات','query deduplication'=>'إزالة تكرار الاستعلامات','cached comment counts'=>'عدّادات التعليقات المخزّنة مؤقتًا','speculative loading'=>'التحميل الاستباقي','General cleanup options'=>'خيارات التنظيف العام','Delete revisions older than (days)'=>'حذف المراجعات الأقدم من (أيام)','Extra guard: revisions beyond the kept count are only deleted when older than this many days. Set 0 to disable (delete by count only).'=>'حماية إضافية: لا تُحذف المراجعات الزائدة عن العدد المحتفظ به إلا إذا كانت أقدم من هذا العدد من الأيام. اضبطه على 0 للتعطيل (الحذف حسب العدد فقط).','If greater than 0, all auto-drafts except the latest N will be deleted.'=>'إذا كانت القيمة أكبر من 0، فسيتم حذف جميع المسودات التلقائية باستثناء أحدث N منها.','Delete auto-drafts older than (days)'=>'حذف المسودات التلقائية الأقدم من (أيام)','Used when "Auto-drafts to keep" is 0. Set 0 to disable age-based deletion.'=>'يُستخدم عندما تكون "المسودات التلقائية للاحتفاظ بها" 0. اضبط 0 لتعطيل الحذف القائم على العمر.','Posts and comments sent to the trash or marked as spam more recently than this are left alone, so a mistake can still be undone. 0 empties them whatever their age.'=>'لا تُمس المقالات والتعليقات التي نُقلت إلى المهملات أو عُلّمت كرسائل مزعجة منذ مدة أقصر من هذه، كي يبقى التراجع عن الخطأ ممكنًا. 0 يفرغها مهما كان عمرها.','Delete auto-drafts'=>'حذف المسودات التلقائية','Delete trashed posts'=>'حذف المقالات في سلة المهملات','Delete spam comments'=>'حذف التعليقات المزعجة','Delete trashed comments'=>'حذف التعليقات في سلة المهملات','Delete unapproved comments (includes those awaiting moderation, not just spam)'=>'حذف التعليقات غير المعتمدة (يشمل التي تنتظر المراجعة، وليس البريد المزعج فقط)','Delete duplicate metadata (keeps the oldest copy)'=>'حذف البيانات الوصفية المكرّرة (مع الإبقاء على أقدم نسخة)','Delete finished Action Scheduler logs (completed/failed/cancelled, 30+ days)'=>'حذف سجلات Action Scheduler المنتهية (مكتملة/فاشلة/ملغاة، 30+ يومًا)','WooCommerce: delete expired customer sessions'=>'WooCommerce: حذف جلسات العملاء المنتهية','WooCommerce: delete orphaned product variations (their product no longer exists)'=>'WooCommerce: حذف تنويعات المنتج اليتيمة (لم يعد منتجها موجودًا)','Detailed cleanup log'=>'سجل تنظيف مفصل','Generate detailed log'=>'إنشاء سجل مفصل','Summary report is always stored. Enable this to include per-step event lines.'=>'يتم حفظ تقرير الملخص دائمًا. فعّل هذا الخيار لتضمين أسطر الأحداث لكل خطوة.','Tables excluded from optimization'=>'الجداول المستبعدة من التحسين','None'=>'لا شيء','Selected tables will be skipped during optimization.'=>'سيتم تخطي الجداول المحددة أثناء التحسين.','Off (manual only)'=>'معطّل (يدوي فقط)','Daily'=>'يومي','Weekly'=>'أسبوعي','Low-traffic window'=>'نافذة الحركة المنخفضة','Window start hour'=>'ساعة بداية النافذة','Window end hour'=>'ساعة نهاية النافذة','WPOptimizing analyses your site automatically in the background, only during this low-traffic window (site timezone), so the lists stay fresh and you never wait on a manual scan. A manual scan always runs immediately, regardless of this window.'=>'يحلّل WPOptimizing موقعك تلقائيًا في الخلفية، فقط خلال نافذة الحركة المنخفضة هذه (المنطقة الزمنية للموقع)، لتبقى القوائم محدَّثة دون أن تنتظر أبدًا تحليلًا يدويًا. يُنفَّذ التحليل اليدوي دائمًا فورًا بغضّ النظر عن هذه النافذة.','Manual only'=>'يدوي فقط','Hourly'=>'كل ساعة','Twice daily'=>'مرتين يومياً','Monthly'=>'شهرياً','Sunday'=>'الأحد','Monday'=>'الاثنين','Tuesday'=>'الثلاثاء','Wednesday'=>'الأربعاء','Thursday'=>'الخميس','Friday'=>'الجمعة','Saturday'=>'السبت','Start time'=>'وقت البدء','Uses the site timezone.'=>'يستخدم المنطقة الزمنية للموقع.','Day of week'=>'يوم من الأسبوع','Day of month'=>'يوم من الشهر','Maximum 28 to ensure compatibility with all months.'=>'الحد الأقصى 28 لضمان التوافق مع جميع الأشهر.','When enabled, WordPress cron will run the General cleanup automatically.'=>'عند التفعيل، سيشغل Cron في WordPress التنظيف العام تلقائيا.','Trashed posts'=>'المقالات في المهملات','Comments'=>'التعليقات','oEmbed cache'=>'تخزين oEmbed المؤقت','Optimize tables'=>'تحسين الجداول','Every run'=>'كل تشغيل','Optionally run some tasks less often than the main schedule. “Every run” follows the schedule above; “Never” skips the task on automatic runs (manual runs always run every enabled task).'=>'يمكنك اختياريًا تشغيل بعض المهام بوتيرة أقل من الجدولة الرئيسية. «كل تشغيل» يتبع الجدولة أعلاه؛ و«أبدًا» يتخطى المهمة في التشغيلات التلقائية (التشغيلات اليدوية تنفّذ دائمًا كل المهام المفعّلة).','Run the General cleanup automatically once the database grows by more than this many MB since the last cleanup. 0 disables it.'=>'شغّل التنظيف العام تلقائياً بمجرد نمو قاعدة البيانات بأكثر من هذا العدد من الميغابايت منذ آخر تنظيف. القيمة 0 تعطّله.','Speculative loading, image loading, preload, lazy embeds, resource hints, Google Fonts, CDN and Server-Timing are now under Speed › Page & browser, next to minify, delay JavaScript and critical CSS.'=>'أصبح التحميل الاستباقي وتحميل الصور والتحميل المسبق والتضمينات المؤجلة وتلميحات الموارد وGoogle Fonts وCDN وServer-Timing الآن ضمن السرعة › الصفحة والمتصفح، بجانب التصغير وتأخير JavaScript وCSS الحرج.','Open Speed › Page & browser'=>'فتح السرعة › الصفحة والمتصفح','Turn off WordPress features you do not use to trim front-end weight and head/feed noise. Every option is off by default and fully reversible — nothing is deleted.'=>'عطّل ميزات ووردبريس التي لا تستخدمها لتخفيف وزن الواجهة الأمامية وتقليل الضجيج في الترويسة والخلاصات. كل خيار معطَّل افتراضيًا وقابل للتراجع بالكامل — لا يُحذف أي شيء.','Branding'=>'العلامة التجارية','White-label is managed from your account for this license (active brand: %s) and applies automatically to every activation.'=>'تُدار العلامة البيضاء من حسابك لهذا الترخيص (العلامة النشطة: %s) وتُطبَّق تلقائياً على كل تفعيل.','Send a signed JSON POST to an external URL when WPOptimizing finishes a scan, a cleanup, a deletion or a dataset upload (e.g. Slack, Zapier, n8n or your own endpoint).'=>'أرسل طلب JSON POST موقّعاً إلى رابط خارجي عندما ينهي WPOptimizing فحصاً أو تنظيفاً أو حذفاً أو رفع مجموعة بيانات (مثل Slack أو Zapier أو n8n أو نقطة النهاية الخاصة بك).','Leave empty to disable webhooks.'=>'اتركه فارغاً لتعطيل الـ webhooks.','Optional. When set, each request carries an X-WPOptimizing-Signature header (HMAC-SHA256 of the body) so the receiver can verify authenticity.'=>'اختياري. عند تعيينه، يحمل كل طلب ترويسة X-WPOptimizing-Signature ‏(HMAC-SHA256 لجسم الطلب) ليتمكن المستقبِل من التحقق من الأصالة.','Choose which events trigger the webhook. With none selected, all events are sent.'=>'اختر الأحداث التي تُفعّل الـ webhook. إذا لم يُحدَّد أي منها، تُرسَل جميع الأحداث.','Shared attribution dataset'=>'مجموعة بيانات الإسناد المشتركة','WPOptimizing can contribute attribution metadata to a shared dataset that improves accuracy for everyone. Only names (of options, meta keys, tables and files), their sizes and how often they are seen are sent, together with your site’s domain, which authorises the exchange — never option values, post or user content, or any record contents. Sharing is opt-in and reciprocal: while it is off, the plugin keeps working with locally captured attribution but does not exchange data with the shared dataset.'=>'يمكن لـ WPOptimizing المساهمة ببيانات إسناد وصفية في مجموعة بيانات مشتركة تحسّن الدقة للجميع. تُرسَل فقط الأسماء (للخيارات ومفاتيح البيانات الإضافية والجداول والملفات) وأحجامها وعدد مرات ظهورها، مع نطاق موقعك الذي يأذن بالتبادل — ولا تُرسَل أبداً قيم الخيارات أو محتوى المقالات أو المستخدمين أو أي محتوى للسجلات. المشاركة اختيارية وتبادلية: عند إيقافها، تواصل الإضافة العمل بالإسناد المُلتقَط محلياً لكنها لا تتبادل البيانات مع المجموعة المشتركة.','Share attribution metadata to improve and receive the shared dataset.'=>'شارك بيانات إسناد وصفية لتحسين المجموعة المشتركة واستلامها.','You can turn this off at any time.'=>'يمكنك إيقاف ذلك في أي وقت.','See exactly what is shared and what is never sent:'=>'اطّلع بالضبط على ما يُشارَك وما لا يُرسَل أبدًا:','Up to date'=>'محدَّثة','A few days old'=>'عمرها بضعة أيام','Outdated'=>'قديمة','Not downloaded yet'=>'لم تُنزَّل بعد','Knowledge base'=>'قاعدة المعرفة','updated %s ago'=>'حُدِّثت قبل %s','Your local copy of each layer of the shared dataset. They refresh automatically every day; use "Sync dataset now" to update them immediately. A layer that stays on "Not downloaded yet" is not reaching your site — tell us if you see one.'=>'نسختك المحلية من كل طبقة من مجموعة البيانات المشتركة. تُحدَّث تلقائيًا كل يوم؛ استخدم «مزامنة مجموعة البيانات الآن» لتحديثها فورًا. الطبقة التي تظل على «لم تُنزَّل بعد» لا تصل إلى موقعك — أخبرنا إن رأيت واحدة.','Sync now'=>'زامن الآن','Uploads your contributions and refreshes your local copy of the shared dataset now, instead of waiting for the daily schedule. Save any sharing change first.'=>'يرفع مساهماتك ويحدّث الآن نسختك المحلية من مجموعة البيانات المشتركة، بدلاً من انتظار الجدولة اليومية. احفظ أولاً أي تغيير في المشاركة.','Off'=>'إيقاف','Conservative (prefetch on click)'=>'متحفّظ (الجلب المسبق عند النقر)','Eager (prerender on hover)'=>'حثيث (التصيير المسبق عند التمرير)','Uses the browser Speculation Rules API to prefetch or prerender the next page on hover/click, so navigation feels instant. Admin, login, cart/checkout/account and URLs with a query string are excluded automatically.'=>'يستخدم واجهة Speculation Rules في المتصفّح لجلب الصفحة التالية مسبقًا أو تصييرها مسبقًا عند التمرير/النقر، حتى يبدو التصفّح فوريًا. تُستثنى تلقائيًا لوحة الإدارة وتسجيل الدخول وسلة التسوّق/الدفع/الحساب وعناوين URL التي تحتوي على سلسلة استعلام.','Optimize content image loading (prioritize the first image, lazy-load the rest)'=>'تحسين تحميل صور المحتوى (إعطاء الأولوية للصورة الأولى، وتحميل البقية بشكل مؤجّل)','Also outside the content — header, sidebars, footer — on pages saved by the page cache (the first three images stay eager)'=>'وخارج المحتوى أيضًا — الترويسة والأشرطة الجانبية والتذييل — في الصفحات التي تحفظها ذاكرة الصفحات المؤقتة (تُحمَّل الصور الثلاث الأولى فورًا)','Preload the featured image (likely LCP) on posts and pages so it starts downloading sooner'=>'التحميل المسبق للصورة البارزة (LCP المحتمَل) في المقالات والصفحات لتبدأ بالتنزيل مبكراً','Also preload these URLs (one per line): above-the-fold fonts or a hero image'=>'التحميل المسبق أيضاً لهذه الروابط (واحد في كل سطر): خطوط الجزء الظاهر أولاً أو صورة رئيسية','https://example.com/wp-content/themes/x/fonts/brand.woff2'=>'https://example.com/wp-content/themes/x/fonts/brand.woff2','The right type (image, font, style, script) is detected from the file extension; fonts get crossorigin automatically. Only preload what is actually above the fold — preloading too much slows the page down.'=>'يُكتشَف النوع الصحيح (صورة، خط، نمط، سكربت) من امتداد الملف؛ وتحصل الخطوط على crossorigin تلقائياً. حمّل مسبقاً فقط ما هو ظاهر أولاً بالفعل — الإفراط في التحميل المسبق يبطئ الصفحة.','Lazy-load iframes and replace YouTube embeds with a click-to-load thumbnail (loads the heavy player only on click)'=>'تحميل الإطارات المضمّنة (iframes) بشكل مؤجَّل واستبدال فيديوهات YouTube بصورة مصغّرة تُحمَّل عند النقر (لا يُحمَّل المشغّل الثقيل إلا عند النقر)','A YouTube embed pulls in about a megabyte of scripts before the visitor even presses play. The facade shows the video thumbnail and loads the real player (cookie-less youtube-nocookie.com) only when clicked — a big win for LCP and privacy. Stands down when a caching/optimization plugin already handles embeds.'=>'يحمّل فيديو YouTube نحو ميغابايت من السكربتات قبل أن يضغط الزائر زر التشغيل أصلاً. تعرض الواجهة الصورة المصغّرة ولا تُحمِّل المشغّل الحقيقي (youtube-nocookie.com بلا كوكيز) إلا عند النقر — مكسب كبير لـLCP وللخصوصية. وتتوقّف إذا كانت إضافة تخزين مؤقت أو تحسين تدير التضمينات بالفعل.','Send a Server-Timing header (DB queries, object-cache hit rate) for diagnostics'=>'إرسال ترويسة Server-Timing (استعلامات قاعدة البيانات، معدّل إصابات ذاكرة الكائنات المؤقتة) للتشخيص','Add preconnect / dns-prefetch hints for the external origins the page loads (fonts, CDNs), so the browser connects sooner'=>'يضيف تلميحات preconnect / dns-prefetch للأصول الخارجية التي تحمّلها الصفحة (الخطوط، شبكات CDN) كي يتصل المتصفح مبكرًا','Self-host Google Fonts (serve the font CSS and files from this site, so the browser never contacts Google)'=>'استضافة خطوط Google ذاتيًا (تقديم CSS الخطوط وملفاتها من هذا الموقع، بحيث لا يتصل المتصفح بـ Google أبدًا)','Removes the third-party connection to fonts.googleapis.com / fonts.gstatic.com (a common GDPR concern). Save with this on, then use "Localize now" below to download the fonts detected on your site.'=>'يزيل الاتصال بطرف ثالث بـ fonts.googleapis.com / fonts.gstatic.com (مصدر قلق شائع في GDPR). احفظ مع تفعيل هذا الخيار، ثم استخدم «توطين الآن» بالأسفل لتنزيل الخطوط المكتشفة على موقعك.','Serve static files (images, CSS, JS) from a CDN'=>'تقديم الملفات الثابتة (الصور، CSS، JS) من شبكة CDN','Uploads (media library)'=>'ملفات الرفع (مكتبة الوسائط)','wp-content (themes and plugins)'=>'wp-content (القوالب والإضافات)','wp-includes (WordPress core assets)'=>'wp-includes (أصول نواة ووردبريس)','Enter the CDN hostname (no https://). URLs of local static files under the selected folders are rewritten to this host; dynamic PHP endpoints and external URLs are never touched. Point your CDN as a pull zone / origin at this site first, and make sure it serves fonts with the right CORS headers.'=>'أدخل اسم مضيف CDN (بدون https://). تُعاد كتابة عناوين URL للملفات الثابتة المحلية ضمن المجلدات المحددة إلى هذا المضيف؛ ولا تُمسّ أبدًا نقاط النهاية الديناميكية بلغة PHP والعناوين الخارجية. وجّه CDN أولًا كمنطقة سحب / مصدر إلى هذا الموقع، وتأكّد من أنه يقدّم الخطوط بترويسات CORS الصحيحة.','%s is already self-hosting Google Fonts, so WPOptimizing is standing aside to avoid conflicts. Disable it there if you want WPOptimizing to handle fonts instead.'=>'%s يقوم بالفعل باستضافة خطوط Google ذاتيًا، لذا يتنحّى WPOptimizing جانبًا لتجنّب التعارض. عطّله هناك إذا أردت أن يتولّى WPOptimizing إدارة الخطوط بدلًا من ذلك.','No Google Fonts detected yet. Save with self-hosting on, open your site once so the fonts are detected, then return here and click "Localize now".'=>'لم يتم اكتشاف أي خطوط Google بعد. احفظ مع تفعيل الاستضافة الذاتية، وافتح موقعك مرة واحدة حتى تُكتشَف الخطوط، ثم عُد إلى هنا وانقر على «توطين الآن».','%1$d stylesheet(s) localized (%2$d font files); %3$d pending.'=>'تم توطين %1$d من أوراق الأنماط (%2$d من ملفات الخطوط)؛ %3$d قيد الانتظار.','Local'=>'محلي','Localize now'=>'توطين الآن','Remove local fonts'=>'إزالة الخطوط المحلية','WPOptimizing — Downloading Google Fonts'=>'WPOptimizing — جارٍ تنزيل Google Fonts','%1$s of %2$s stylesheets…'=>'%1$s من %2$s من أوراق الأنماط…','Compatibility with other plugins'=>'التوافق مع الإضافات الأخرى','No other performance or optimization plugin was detected, so every WPOptimizing feature is free to run.'=>'لم يُكتشف أي إضافة أداء أو تحسين أخرى، لذا يمكن لجميع وظائف WPOptimizing أن تعمل.','These plugins are active and already provide some of what WPOptimizing does. Where doing it twice would fight, our version is switched off. Tick a row to run ours anyway.'=>'هذه الإضافات مفعّلة وتؤدي بالفعل جزءًا مما يؤديه WPOptimizing. وحيث يسبّب التكرار تعارضًا، تكون نسختنا مُعطّلة. حدّد صفًا لاستخدام نسختنا على أي حال.','These plugins are active and already provide some of what WPOptimizing does. Where doing it twice would fight, our version is switched off — for delaying JavaScript and for critical CSS, doing it twice does not duplicate work, it breaks the page. Tick a row to run ours anyway.'=>'هذه الإضافات مفعّلة وتؤدي بالفعل جزءًا مما يؤديه WPOptimizing. وحيث يسبّب التكرار تعارضًا، تكون نسختنا مُعطّلة — ففي تأخير JavaScript وفي CSS الحَرِج لا يضاعف التكرار العمل بل يكسر الصفحة. حدّد صفًا لاستخدام نسختنا على أي حال.','Also provided by %s. Both run: doing this twice is harmless, so WPOptimizing does not stand down and there is nothing to switch.'=>'توفّره أيضًا %s. كلاهما يعمل: تكرار هذا غير ضار، لذا لا ينسحب WPOptimizing ولا يوجد ما يُبدَّل.','Provided by %s.'=>'يوفّره %s.','WPOptimizing covers everything these plugins are used for, so you can manage it all from one place and deactivate them: %s. Check your settings here first.'=>'يغطي WPOptimizing كل ما تُستخدم من أجله هذه الإضافات، فيمكنك إدارة الأمر كله من مكان واحد وتعطيلها: %s. راجع إعداداتك هنا أولًا.','Settings sections'=>'أقسام الإعدادات','Save changes'=>'حفظ التغييرات','Import / export settings'=>'استيراد / تصدير الإعدادات','Save this site’s configuration to a JSON file and restore it here or on another site — handy to replicate your setup across sites. It includes the settings for cleanup, scheduling, cache, media and images, Smart Assets, backups and attribution. Keys, passwords, the license, webhooks, data-sharing consent and measured runtime state (scan results, baselines, cached sizes) are never included.'=>'احفظ إعدادات هذا الموقع في ملف JSON واستعدها هنا أو في موقع آخر — مفيد لنسخ إعداداتك بين المواقع. يتضمن إعدادات التنظيف والجدولة والتخزين المؤقت والوسائط والصور وSmart Assets والنسخ الاحتياطية والإسناد. لا يتم أبدًا تضمين المفاتيح وكلمات المرور والترخيص وخطافات الويب والموافقة على مشاركة البيانات وحالة التشغيل المقاسة (نتائج الفحص، القيم المرجعية، الأحجام المخزَّنة مؤقتًا).','Export'=>'تصدير','Downloads a JSON file with the current configuration.'=>'ينزّل ملف JSON يحتوي على الإعدادات الحالية.','Import'=>'استيراد','Select a file exported from WPOptimizing. Existing settings are overwritten; unknown keys are ignored.'=>'اختر ملفًا تم تصديره من WPOptimizing. سيتم استبدال الإعدادات الحالية؛ وسيتم تجاهل المفاتيح غير المعروفة.','No file was uploaded, or the upload failed.'=>'لم يتم رفع أي ملف، أو فشل الرفع.','The uploaded file could not be read.'=>'تعذّرت قراءة الملف المرفوع.','The file is too large to be a settings export.'=>'الملف أكبر من أن يكون تصديرًا للإعدادات.','The file is not valid JSON.'=>'الملف ليس JSON صالحًا.','That file was not exported from WPOptimizing.'=>'هذا الملف لم يُصدَّر من WPOptimizing.','The file does not look like a WPOptimizing settings export.'=>'لا يبدو أن الملف عبارة عن تصدير لإعدادات WPOptimizing.','Nothing was imported: the file had no recognized settings.'=>'لم يتم استيراد أي شيء: لم يحتوِ الملف على إعدادات معروفة.','%d settings group imported.' . "\0" . '%d settings groups imported.'=>'تم استيراد %d مجموعة إعدادات.' . "\0" . 'تم استيراد مجموعة إعدادات واحدة.' . "\0" . 'تم استيراد مجموعتي إعدادات.' . "\0" . 'تم استيراد %d مجموعات إعدادات.' . "\0" . 'تم استيراد %d مجموعة إعدادات.' . "\0" . 'تم استيراد %d مجموعة إعدادات.','%d unknown entry was ignored.' . "\0" . '%d unknown entries were ignored.'=>'تم تجاهل %d مدخل غير معروف.' . "\0" . 'تم تجاهل مدخل واحد غير معروف.' . "\0" . 'تم تجاهل مدخلين غير معروفين.' . "\0" . 'تم تجاهل %d مدخلات غير معروفة.' . "\0" . 'تم تجاهل %d مدخلاً غير معروف.' . "\0" . 'تم تجاهل %d مدخل غير معروف.','No assets recorded yet. WPOptimizing samples public page loads in the background (sharing must be enabled); check back after some front-end visits.'=>'لم يتم تسجيل أي موارد بعد. يأخذ WPOptimizing عيّنات من تحميلات الصفحات العامة في الخلفية (يجب تفعيل المشاركة)؛ تحقّق مرة أخرى بعد بعض زيارات الواجهة الأمامية.','Stop loading the ticked assets on the front-end (applies site-wide)'=>'التوقف عن تحميل الموارد المحددة في الواجهة الأمامية (يُطبَّق على الموقع كله)','Only disable assets you recognize, and test your site afterwards. WordPress core and jQuery are protected. Each change is saved and applied immediately, and is fully reversible: untick to restore.'=>'عطّل فقط الموارد التي تعرفها، ثم اختبر موقعك. نواة ووردبريس وjQuery محميّتان. يُحفظ كل تغيير ويُطبَّق فورًا، وهو قابل للتراجع تمامًا: ألغِ التحديد للاستعادة.','Automatically stop loading a plugin or theme\'s assets on pages where it is not used'=>'التوقّف تلقائيًا عن تحميل موارد إضافة أو قالب في الصفحات التي لا يُستخدم فيها','Knowledge-base driven and context-aware: e.g. Contact Form 7 is dropped on pages with no form, WooCommerce off the shop/cart. Conservative (only well-known plugins), core/jQuery always protected, fully reversible. Test your key pages after enabling.'=>'مدفوع بقاعدة المعرفة ومدرك للسياق: مثلًا يُزال Contact Form 7 في الصفحات التي لا تحتوي نموذجًا ويُزال WooCommerce خارج المتجر/سلة الشراء. متحفّظ (الإضافات المعروفة فقط)، والنواة/jQuery محميّة دائمًا، وقابل للعكس بالكامل. اختبر صفحاتك الرئيسية بعد التفعيل.','Suggested by the knowledge base — automatic mode would drop these where they are not used:'=>'مقترَح من قاعدة المعرفة — سيزيلها الوضع التلقائي حيث لا تُستخدَم:','%1$d scripts, %2$d styles'=>'%1$d نصوص برمجية، %2$d أنماط','Quick add:'=>'إضافة سريعة:','Save exceptions'=>'حفظ الاستثناءات','One URL pattern per line. These pages keep every asset — no unloading rule runs on them, whether site-wide or per page. Use * as a wildcard (e.g. /checkout, /cart, */thank-you/*). Matching is by path, so leave out the domain. Ideal to protect the checkout, a landing page or any URL where every script must load.'=>'نمط رابط واحد لكل سطر. تحتفظ هذه الصفحات بجميع الموارد: لا تسري عليها أي قاعدة لإلغاء التحميل، سواء على مستوى الموقع أو لكل صفحة. استخدم * كحرف بدل (مثل /checkout و/cart و*/thank-you/*). تتم المطابقة حسب المسار، لذا احذف النطاق. مثالي لحماية صفحة الدفع أو صفحة هبوط أو أي رابط يجب أن تُحمَّل فيه كل السكربتات.','One URL pattern per line. These pages keep every asset — no manual, automatic or per-page unloading runs on them. Use * as a wildcard (e.g. /checkout, /cart, */thank-you/*). Matching is by path, so leave out the domain. Ideal to protect the checkout, a landing page or any URL where every script must load.'=>'نمط رابط واحد لكل سطر. تحتفظ هذه الصفحات بجميع الموارد: لا يُجرى عليها أي إلغاء تحميل (يدوي أو تلقائي أو لكل صفحة). استخدم * كحرف بدل (مثل /checkout و/cart و*/thank-you/*). تتم المطابقة حسب المسار، لذا احذف النطاق. مثالي لحماية صفحة الدفع أو صفحة هبوط أو أي رابط يجب أن تُحمَّل فيه كل السكربتات.','%d rule(s) belong to an extension that is installed but switched off. They are kept: they will start working again the moment you reactivate it.'=>'%d من القواعد تخص إضافة مثبّتة لكنها معطّلة. يتم الاحتفاظ بها: ستعمل من جديد بمجرد إعادة تفعيلها.','%d rule(s) point at an asset nothing on this site enqueues any more — a renamed handle, or an extension that is gone. They can be removed safely.'=>'%d من القواعد تشير إلى مورد لم يعد أي شيء في هذا الموقع يضيفه — اسم مُعاد تسميته، أو إضافة لم تعد موجودة. يمكن إزالتها بأمان.','Remove the rules that match nothing'=>'إزالة القواعد التي لا تطابق شيئًا','Front page'=>'الصفحة الرئيسية','Posts & pages'=>'المقالات والصفحات','Archives'=>'صفحات الأرشيف','Each unloaded asset is dropped everywhere by default. Narrow a rule to a content type and/or only specific URLs (wildcard *). Leave "Only on URLs" empty to keep it site-wide.'=>'يُزال كل مورد مُلغى تحميله من كل مكان افتراضيًا. ضيّق نطاق القاعدة على نوع محتوى و/أو روابط محددة فقط (حرف بدل *). اترك «في روابط محددة فقط» فارغًا للإبقاء عليها على مستوى الموقع كله.','Asset'=>'المورد','Where'=>'أين','Only on URLs'=>'في روابط محددة فقط','Type: %s'=>'النوع: %s','Pages where this rule applies'=>'الصفحات التي تنطبق عليها هذه القاعدة','Scripts'=>'نصوص برمجية','Styles'=>'أنماط','Search assets'=>'البحث في الموارد','Saved.'=>'تم الحفظ.','Could not save. Try again.'=>'تعذّر الحفظ. أعد المحاولة.','option'=>'خيار','transient'=>'مؤقت','transient (expired)'=>'مؤقت (منتهي)','post type'=>'نوع المقالة','post type content'=>'محتوى نوع المقالة','taxonomy'=>'تصنيف','taxonomy terms'=>'مصطلحات التصنيف','role'=>'دور','capability'=>'صلاحية','table'=>'جدول','post meta'=>'بيانات إضافية للمقالة','user meta'=>'بيانات إضافية للمستخدم','term meta'=>'بيانات إضافية للمصطلح','shortcode'=>'رمز قصير','REST namespace'=>'مساحة اسم REST','widget'=>'ودجة','plugin page'=>'صفحة الإضافة','cron'=>'مؤقت cron','Action Scheduler action'=>'إجراء Action Scheduler','i18n'=>'i18n','post'=>'مقالة','revision'=>'مراجعة','product variation'=>'تنويعة منتج','comment'=>'تعليق','comment meta'=>'بيانات إضافية للتعليق','term relationship'=>'علاقة مصطلح','term taxonomy row'=>'صف تصنيف المصطلح','WooCommerce session'=>'جلسة WooCommerce','autoload flag'=>'علامة التحميل التلقائي','%s (in a folder WordPress does not load)'=>'%s (في مجلد لا يحمّله ووردبريس)','not done from here: the table takes %s, and converting it would take minutes, as much free disk space, and block writes to it meanwhile. Your hosting provider can do it at a quiet time.'=>'لم يُنفَّذ من هنا: يشغل الجدول %s، وتحويله سيستغرق دقائق ومساحة حرة مماثلة على القرص، وسيمنع الكتابة فيه خلال ذلك. يمكن لمزوّد الاستضافة القيام بذلك في وقت هادئ.','conversion rejected by the database'=>'رفضت قاعدة البيانات التحويل','%d table could not be processed' . "\0" . '%d tables could not be processed'=>'تعذّرت معالجة %d جدول' . "\0" . 'تعذّرت معالجة جدول واحد' . "\0" . 'تعذّرت معالجة جدولين' . "\0" . 'تعذّرت معالجة %d جداول' . "\0" . 'تعذّرت معالجة %d جدولًا' . "\0" . 'تعذّرت معالجة %d جدول','(compared with %s)'=>'(مقارنةً بـ %s)','+%1$s (+%2$s%%), %3$s rows added'=>'+%1$s (+%2$s%%)، أُضيفت %3$s صفوف','A table ballooning between scans is often a runaway log, transient/cache table or stuck background job. Review what writes to it before it keeps growing.'=>'الجدول الذي يتضخّم بين الفحوصات غالبًا ما يكون سجلًّا خارجًا عن السيطرة، أو جدول عناصر عابرة/تخزين مؤقت، أو مهمة خلفية عالقة. راجع ما الذي يكتب فيه قبل أن يستمر في النمو.','its owner is not active'=>'مالكها غير مُفعَّل','a large share of the whole database'=>'حصة كبيرة من قاعدة البيانات بأكملها','a very high row count'=>'عدد صفوف مرتفع جدًا','%1$s, %2$s rows — %3$s'=>'%1$s، %2$s صف — %3$s','A table can belong to a plugin that is working perfectly and still be the largest thing in your database — caches, logs and tracking tables are the usual ones. Check the plugin\'s own settings for a retention limit before deleting anything here.'=>'قد ينتمي الجدول إلى إضافة تعمل بشكل ممتاز ومع ذلك يكون أكبر شيء في قاعدة بياناتك: الذاكرة المؤقتة والسجلات وجداول التتبع هي المعتادة. تحقق مما إذا كانت الإضافة نفسها توفّر حدًا للاحتفاظ في إعداداتها قبل حذف أي شيء هنا.','Database tables'=>'جداول قاعدة البيانات','Every table with its engine, row count, size and recoverable overhead. Optimizing reclaims the overhead; it never deletes data. Orphaned custom tables from uninstalled plugins appear in the Orphans tab.'=>'كل جدول مع محركه وعدد صفوفه وحجمه والعبء الزائد القابل للاسترداد. التحسين يستعيد العبء الزائد؛ ولا يحذف البيانات أبدًا. تظهر الجداول المخصصة اليتيمة من الإضافات المُلغى تثبيتها في علامة التبويب «اليتيمة».','Recoverable overhead'=>'زيادة قابلة للاسترداد','MyISAM tables'=>'جداول MyISAM','InnoDB tables also hold %s of internal free space. InnoDB reuses it for new rows, so OPTIMIZE does not hand it back to the operating system — that is normal and not recoverable.'=>'تحتوي جداول InnoDB أيضًا على %s من المساحة الحرة الداخلية. يعيد InnoDB استخدامها للصفوف الجديدة، لذا لا يعيدها OPTIMIZE إلى نظام التشغيل — وهذا أمر طبيعي وغير قابل للاسترداد.','Reclaim %s of overhead now'=>'استرداد %s من الزيادة الآن','Optimizes only the tables with reclaimable overhead. Non-destructive — no data is deleted.'=>'يحسّن فقط الجداول التي بها زيادة قابلة للاسترداد. غير مُدمِّر — لا يتم حذف أي بيانات.','Orphaned only'=>'اليتيمة فقط','All tables'=>'كل الجداول','Search tables'=>'البحث في الجداول','Optimizing reclaims overhead and defragments the table. It does not delete data and is safe to run. On InnoDB tables it rebuilds and re-analyses the table, but the reported free space may not drop because InnoDB reuses that space internally instead of returning it to the operating system — that is normal, not a failure.'=>'تحسين الجدول يستعيد الحِمل الزائد ويلغي تجزئته. لا يحذف أي بيانات وتشغيله آمن. في جداول InnoDB يعيد بناء الجدول وتحليله، لكن المساحة الحرة المعروضة قد لا تنخفض لأن InnoDB يعيد استخدام تلك المساحة داخليًا بدلًا من إعادتها إلى نظام التشغيل — وهذا أمر طبيعي وليس خطأً.','Optimize the %d selected table(s)?'=>'تحسين الجداول المحددة البالغ عددها %d؟','Optimize ALL %d filtered table(s)?'=>'تحسين كل الجداول المُرشَّحة البالغ عددها %d؟','Converting to InnoDB enables row-level locking and crash recovery; it rebuilds the table in place and keeps all data.'=>'يتيح التحويل إلى InnoDB القفل على مستوى الصف والتعافي بعد الأعطال؛ ويعيد بناء الجدول في مكانه مع الحفاظ على جميع البيانات.','Convert all MyISAM'=>'تحويل كل جداول MyISAM','Convert the %d selected table(s) to InnoDB? Only MyISAM tables are changed.'=>'تحويل %d من الجداول المحددة إلى InnoDB؟ تتغير جداول MyISAM فقط.','Convert ALL %d MyISAM table(s) to InnoDB?'=>'تحويل كل الجداول البالغ عددها %d من نوع MyISAM إلى InnoDB؟','You are not allowed to access the WPOptimizing API.'=>'غير مسموح لك بالوصول إلى واجهة برمجة تطبيقات WPOptimizing.','Cleanup engine unavailable.'=>'محرك التنظيف غير متاح.','Media analyzer unavailable.'=>'مُحلّل الوسائط غير متاح.','Scan completed'=>'اكتمل الفحص','Cleanup completed'=>'اكتمل التنظيف','Items deleted'=>'العناصر المحذوفة','Dataset uploaded'=>'تم رفع مجموعة البيانات','Not done: the backups have reached their size limit. Delete old backups under Backups, or raise “Max backup size” in Settings, and try again.'=>'لم يُنفَّذ: بلغت النسخ الاحتياطية حد حجمها. احذف النسخ القديمة من النسخ الاحتياطية، أو ارفع «الحد الأقصى لحجم النسخ الاحتياطية» في الإعدادات، ثم أعد المحاولة.','Not done: a backup could not be created first (check disk space and folder permissions). Please try again.'=>'لم يُنفَّذ: تعذّر إنشاء نسخة احتياطية أولًا (تحقّق من مساحة القرص وأذونات المجلد). يُرجى المحاولة مرة أخرى.','An SEO plugin is active. If it already serves your sitemap, you can turn on the “Disable the WordPress sitemap” core tweak — just confirm its sitemap is enabled first.'=>'هناك إضافة SEO نشطة. إذا كانت توفّر خريطة موقعك بالفعل، فيمكنك تفعيل تحسين «تعطيل خريطة موقع ووردبريس» — لكن تأكّد أولًا من أن خريطة موقعها مُفعّلة.','A caching plugin was detected. WPOptimizing never touches another plugin’s object-cache.php / db.php drop-in, so keep managing page caching from that plugin.'=>'تم اكتشاف إضافة تخزين مؤقت. لا يمسّ WPOptimizing أبدًا ملف object-cache.php / db.php drop-in الخاص بإضافة أخرى، فتابع إدارة تخزين الصفحات المؤقت من تلك الإضافة.','An image-optimization plugin is active. WPOptimizing’s image loading only adds attributes and yields to it, so you can leave image work to that plugin.'=>'هناك إضافة لتحسين الصور نشطة. لا يفعل تحسين تحميل الصور في WPOptimizing سوى إضافة سمات ويُفسح لها المجال، فيمكنك ترك عمل الصور لتلك الإضافة.','Safe'=>'آمنة','Conservative defaults: keeps 5 revisions and removes auto-drafts, trashed posts and comments, spam, expired transients and the oEmbed cache, then optimizes the tables.'=>'إعدادات افتراضية متحفظة: يحتفظ بـ 5 مراجعات ويزيل المسودات التلقائية والمقالات والتعليقات في سلة المهملات والرسائل المزعجة والمؤقتات منتهية الصلاحية وذاكرة oEmbed المؤقتة، ثم يحسّن الجداول.','Blog'=>'مدونة','Like Safe, plus pingbacks/trackbacks; keeps tags and fewer revisions.'=>'مثل «آمن»، بالإضافة إلى التنبيهات الآلية/التتبع الخلفي؛ يحتفظ بالوسوم وعدد أقل من المراجعات.','WooCommerce'=>'WooCommerce','Keeps 5 revisions and product tags; also removes pingbacks and trackbacks, orphan elements, old Action Scheduler logs, expired customer sessions and orphaned variations. Never touches non-expired transients (carts/sessions).'=>'يحتفظ بـ 5 مراجعات ووسوم المنتجات؛ ويزيل أيضاً التنبيهات (pingbacks وtrackbacks) والعناصر اليتيمة وسجلات Action Scheduler القديمة وجلسات العملاء منتهية الصلاحية والتنويعات اليتيمة. لا يمس أبداً المؤقتات غير منتهية الصلاحية (السلال/الجلسات).','Membership'=>'العضوية','Careful preset: keeps moderation queue, pingbacks and member metadata intact.'=>'إعداد مسبق حذر: يُبقي قائمة المراجعة والتنبيهات الآلية وبيانات الأعضاء سليمة.','Agency (maximum)'=>'وكالة (أقصى حد)','Most thorough: also unapproved comments, unused tags and orphaned metadata. Still never deletes non-expired transients.'=>'الأكثر شمولاً: يشمل أيضاً التعليقات غير المعتمدة والوسوم غير المستخدمة والبيانات الوصفية اليتيمة. ومع ذلك لا يحذف أبداً المؤقتات غير منتهية الصلاحية.','No cleanup report available.'=>'لا يتوفر تقرير تنظيف.','You are not allowed to view this report.'=>'غير مسموح لك بعرض هذا التقرير.','Spam & trashed comments'=>'التعليقات المزعجة والتعليقات في سلة المهملات','Records deleted'=>'السجلات المحذوفة','Space freed'=>'المساحة المحررة','Duration'=>'المدة','Deleted by category'=>'المحذوف حسب الفئة','Category'=>'الفئة','Total records deleted'=>'إجمالي السجلات المحذوفة','Size before'=>'الحجم قبل','Size after'=>'الحجم بعد','Generated by %1$s %2$s'=>'تم الإنشاء بواسطة %1$s %2$s','Cleanup skipped: another execution is running.'=>'تم تخطي التنظيف: هناك عملية أخرى قيد التنفيذ.','Retry scheduled due to lock.'=>'تمت جدولة إعادة المحاولة بسبب القفل.','Took over the lock of a previous cleanup that had stopped responding.'=>'تم الاستيلاء على قفل عملية تنظيف سابقة توقفت عن الاستجابة.','Cleanup failed: %s'=>'فشل التنظيف: %s','Retry scheduled after failure.'=>'تمت جدولة إعادة المحاولة بعد الفشل.','Everything deleted was backed up first: %s (listed under Backups).'=>'نُسخ كل ما حُذف احتياطيًا أولًا: %s (يظهر في النسخ الاحتياطية).','Cleanup stopped: the backup folder reached its size limit, so nothing more was deleted. What was already deleted is in the backup listed under Backups.'=>'توقف التنظيف: بلغ مجلد النسخ الاحتياطية حد حجمه، فلم يُحذف أي شيء آخر. وما حُذف بالفعل موجود في النسخة الاحتياطية الظاهرة في النسخ الاحتياطية.','Cleanup stopped: its backup could not be written (check disk space and folder permissions), so nothing more was deleted. What was already deleted is in the backup listed under Backups.'=>'توقف التنظيف: تعذّرت كتابة نسخته الاحتياطية (تحقّق من مساحة القرص وأذونات المجلد)، فلم يُحذف أي شيء آخر. وما حُذف بالفعل موجود في النسخة الاحتياطية الظاهرة في النسخ الاحتياطية.','Execution stopped due to time budget.'=>'توقفت العملية بسبب حد الوقت.','Retry scheduled due to time limit.'=>'تمت جدولة إعادة المحاولة بسبب حد الوقت.','Database size: before %1$s, after %2$s, estimated deleted records %3$s.'=>'حجم قاعدة البيانات: قبل %1$s، بعد %2$s، الحجم التقديري للسجلات المحذوفة %3$s.','General cleanup completed. Revisions: %1$d, Posts: %2$d, Comments: %3$d, Transients: %4$d, Optimized tables: %5$d.'=>'اكتمل التنظيف العام. المراجعات: %1$d، المقالات: %2$d، التعليقات: %3$d، Transients: %4$d، الجداول المحسنة: %5$d.','Revisions cleaned: %d'=>'المراجعات التي تم تنظيفها: %d','Auto-drafts cleaned.'=>'تم تنظيف المسودات التلقائية.','Trashed posts cleaned.'=>'تم تنظيف المنشورات في سلة المهملات.','Comments cleaned.'=>'تم تنظيف التعليقات.','Transients cleaned.'=>'تم تنظيف الـ Transients.','oEmbed cache cleaned.'=>'تم تنظيف ذاكرة oEmbed المؤقتة.','Unused tags cleaned.'=>'تم تنظيف الوسوم غير المستخدمة.','Orphan elements cleaned.'=>'تم تنظيف العناصر اليتيمة.','Duplicate metadata not checked in %1$s: %2$s rows are too many to compare from here.'=>'لم تُفحص البيانات الوصفية المكررة في %1$s: %2$s صف أكثر من أن تُقارن من هنا.','Duplicate metadata in %s: the database stopped the search before it finished; run the cleanup again later.'=>'البيانات الوصفية المكررة في %s: أوقفت قاعدة البيانات البحث قبل اكتماله؛ أعد تشغيل التنظيف لاحقًا.','Duplicate metadata removed: %d'=>'البيانات الوصفية المكرّرة المحذوفة: %d','Action Scheduler: removed %d finished entries.'=>'Action Scheduler: تمت إزالة %d إدخالات منتهية.','WooCommerce: removed %d expired customer sessions.'=>'WooCommerce: تمت إزالة %d جلسة عميل منتهية.','WooCommerce: removed %d orphaned product variations.'=>'WooCommerce: تمت إزالة %d تنويعة منتج يتيمة.','Table optimization finished.'=>'اكتمل تحسين الجداول.','Cloudflare is not configured.'=>'لم يتم إعداد Cloudflare.','Cloudflare answered with HTTP %d.'=>'ردّ Cloudflare بالرمز HTTP %d.','Connect Cloudflare first (zone ID and API token).'=>'اربط Cloudflare أولًا (معرّف المنطقة ورمز API).','Turn on the page cache first: it is what decides, page by page, what Cloudflare may keep.'=>'فعّل ذاكرة الصفحات المؤقتة أولًا: هي التي تقرر، صفحة بصفحة، ما يمكن لـ Cloudflare الاحتفاظ به.','The page cache keeps a separate copy for mobile devices, and the edge would hand one copy to every device. Turn that off first.'=>'تحتفظ ذاكرة الصفحات المؤقتة بنسخة منفصلة للأجهزة المحمولة، والحافة ستعطي نسخة واحدة لكل الأجهزة. أوقف ذلك أولًا.','WordPress lives in a subfolder of this domain, and the rule would also cover what lives beside it.'=>'يوجد ووردبريس في مجلد فرعي من هذا النطاق، وستشمل القاعدة أيضًا ما يوجد بجانبه.','%s also caches the pages and answers before WordPress starts, so the page cache never gets to tell Cloudflare which pages it may keep. Deactivate it first.'=>'يخزّن %s الصفحات أيضًا ويستجيب قبل أن يبدأ ووردبريس، لذا لا يتمكن تخزين الصفحات أبدًا من إخبار Cloudflare بالصفحات التي يمكنه الاحتفاظ بها. عطّله أولًا.','wp-content/advanced-cache.php belongs to another plugin, so the pages are not served by the page cache and it cannot tell Cloudflare which ones it may keep.'=>'الملف wp-content/advanced-cache.php تابع لإضافة أخرى، لذا لا يقدّم تخزين الصفحات هذه الصفحات ولا يمكنه إخبار Cloudflare بأيّها يمكن الاحتفاظ به.','CSS and JavaScript minification'=>'تصغير CSS وJavaScript','Deferred JavaScript'=>'تأجيل تنفيذ JavaScript (defer)','Asynchronous CSS'=>'CSS غير متزامن','Delay JavaScript until interaction'=>'تأخير JavaScript حتى أول تفاعل','Lazy loading of images and embeds'=>'التحميل المؤجَّل للصور والمُضمَّنات','Serving WebP/AVIF copies'=>'تقديم نسخ WebP/AVIF','Image compression'=>'ضغط الصور','Self-hosted Google Fonts'=>'استضافة خطوط Google محليًا','Browser cache headers'=>'ترويسات تخزين المتصفح','Heartbeat control'=>'التحكم في Heartbeat','WP-Cron control'=>'التحكم في WP-Cron','Core tweaks (emojis, embeds, head cleanup)'=>'تعديلات النواة (الإيموجي، المُضمَّنات، تنظيف head)','Unused and orphaned media detection'=>'اكتشاف الوسائط غير المستخدمة واليتيمة','Action Scheduler log cleanup'=>'تنظيف سجلات Action Scheduler','Post revision cleanup'=>'تنظيف مراجعات المقالات','Disable emojis'=>'تعطيل الإيموجي','Removes the emoji detection script, inline styles and DNS prefetch. Modern browsers render emoji natively.'=>'يزيل سكربت اكتشاف الإيموجي والأنماط المضمّنة وجلب DNS المسبق. تعرض المتصفحات الحديثة الإيموجي أصلًا.','Remove WordPress version meta'=>'إزالة وسم إصدار ووردبريس','Removes the generator meta tag that exposes your WordPress version in the page head and feeds.'=>'يزيل وسم generator الذي يكشف إصدار ووردبريس في ترويسة الصفحة والخلاصات.','Remove RSD link'=>'إزالة رابط RSD','Removes the Really Simple Discovery link, used only by some legacy remote-publishing clients.'=>'يزيل رابط Really Simple Discovery، الذي لا تستخدمه سوى بعض عملاء النشر عن بُعد القديمة.','Remove WLW manifest link'=>'إزالة رابط بيان WLW','Removes the Windows Live Writer manifest link, for a long-discontinued desktop editor.'=>'يزيل رابط بيان Windows Live Writer، الخاص بمحرّر سطح مكتب متوقّف منذ زمن.','Remove shortlink tag'=>'إزالة وسم shortlink','Removes the shortlink <link> in the head and its HTTP Link header.'=>'يزيل «<link>» الخاص بـ shortlink في الترويسة وترويسة HTTP Link المرافقة له.','Disable self-pingbacks'=>'تعطيل التنبيهات الذاتية (self-pingbacks)','Stops WordPress from pinging your own site when you link to your own posts.'=>'يمنع ووردبريس من تنبيه موقعك نفسه عندما تربط إلى تدويناتك.','Remove jQuery Migrate'=>'إزالة jQuery Migrate','Drops the jquery-migrate compatibility script on the front end. Disable if an old theme or plugin misbehaves.'=>'يزيل سكربت توافق jquery-migrate في الواجهة الأمامية. عطّله إذا أساء قالب أو إضافة قديمة التصرف.','Remove Dashicons on the front end'=>'إزالة Dashicons من الواجهة الأمامية','Dequeues the Dashicons icon font for logged-out visitors. Kept for logged-in users (admin bar needs it).'=>'يزيل خط أيقونات Dashicons للزوار غير المسجَّلين. ويُبقيه للمستخدمين المسجَّلين (شريط الإدارة يحتاجه).','Disable oEmbed extras'=>'تعطيل إضافات oEmbed','Removes oEmbed discovery links and the wp-embed.min.js script so others cannot embed your posts. Embedding external content still works.'=>'يزيل روابط اكتشاف oEmbed وسكربت wp-embed.min.js كي لا يتمكن الآخرون من تضمين تدويناتك. ويظل تضمين المحتوى الخارجي يعمل.','Disable remote block patterns'=>'تعطيل أنماط الكتل البعيدة','Stops the block editor from fetching the remote pattern directory from WordPress.org.'=>'يمنع محرّر الكتل من جلب دليل الأنماط البعيد من WordPress.org.','Remove REST API head links'=>'إزالة روابط واجهة REST من الترويسة','Removes the REST API discovery <link> and Link header from the front end. The REST API keeps working.'=>'يزيل «<link>» اكتشاف واجهة REST وترويسة Link من الواجهة الأمامية. وتظل واجهة REST تعمل.','Load WooCommerce cart fragments only with a cart'=>'حمّل أجزاء سلة WooCommerce فقط عند وجود سلة','Visitors with an empty cart no longer download the script that refreshes the cart in the header, nor make its request on every page. Adding a product still updates the header.'=>'لم يعد الزوار ذوو السلة الفارغة ينزّلون السكربت الذي يحدّث السلة في الترويسة ولا يرسلون طلبه في كل صفحة. وتبقى إضافة منتج تحدّث الترويسة.','No visible impact — head noise only.'=>'بلا تأثير مرئي — ضجيج الترويسة فقط.','Moderate'=>'معتدلة','May affect a few setups — review each one.'=>'قد تؤثر في بعض الإعدادات — راجع كلًا منها.','Server cache (Nginx)'=>'ذاكرة الخادم المؤقتة (Nginx)','Page cache (WPOptimizing)'=>'ذاكرة تخزين الصفحات (WPOptimizing)','Unidentified cache'=>'ذاكرة تخزين مؤقت غير معروفة','WooCommerce (cart, checkout, account)'=>'WooCommerce (السلة، الدفع، الحساب)','Easy Digital Downloads (checkout, account)'=>'Easy Digital Downloads (الدفع، الحساب)','Courses / LMS (course, lesson, quiz)'=>'الدورات / LMS (دورة، درس، اختبار)','Contact / booking pages'=>'صفحات الاتصال / الحجز','Exclude this content from automatic asset unloading'=>'استثناء هذا المحتوى من الإزالة التلقائية','Don\'t load these assets only on this page:'=>'عدم تحميل هذه الموارد في هذه الصفحة فقط:','No assets recorded yet. Open your site front-end first, then come back.'=>'لم تُسجَّل أي موارد بعد. افتح واجهة موقعك الأمامية أولًا ثم عُد.','WordPress core and jQuery are always protected.'=>'نواة ووردبريس وjQuery محميّة دائمًا.','Play video'=>'تشغيل الفيديو','Enable the persistent object cache — the single biggest server-TTFB win.'=>'فعّل ذاكرة الكائنات الدائمة — أكبر تحسين في زمن استجابة الخادم (TTFB).','Object-cache hit rate is low: check the backend (Redis/Memcached/APCu) is healthy and not being flushed too often.'=>'معدل إصابة ذاكرة الكائنات منخفض: تأكد من أن الخلفية (Redis/Memcached/APCu) سليمة ولا تُفرَّغ كثيراً.','Reduce the autoload weight loaded on every request.'=>'قلّل حجم autoload المُحمَّل في كل طلب.','Move WP-Cron to a real system cron (define DISABLE_WP_CRON) so scheduled tasks do not run during visitor requests.'=>'انقل WP-Cron إلى cron حقيقي على مستوى النظام (عرّف DISABLE_WP_CRON) حتى لا تعمل المهام المجدولة أثناء زيارات المستخدمين.','Database, object cache and autoload are already optimal — the remaining response time is your server/host. Check the PHP version, that OPcache is enabled, the hosting plan resources, and any theme or plugin doing heavy work on every load. WPOptimizing cannot lower this further.'=>'قاعدة البيانات وذاكرة الكائنات وautoload مضبوطة بالفعل على النحو الأمثل — الزمن المتبقي من الاستجابة هو الخادم/الاستضافة لديك. تحقق من إصدار PHP، ومن تفعيل OPcache، ومن موارد خطة الاستضافة، ومن أي قالب أو إضافة تقوم بعمل ثقيل في كل تحميل. لا يستطيع WPOptimizing خفض ذلك أكثر.','Refused to fetch a non-Google font URL.'=>'تم رفض جلب عنوان URL لخط لا يخص Google.','The font request was redirected off Google; refusing the response.'=>'أُعيد توجيه طلب الخط خارج Google؛ يتم رفض الاستجابة.','Not a Google Fonts URL.'=>'ليس عنوان URL لخطوط Google.','The uploads directory is not writable.'=>'مجلد الرفع غير قابل للكتابة.','No font files could be downloaded.'=>'تعذّر تنزيل أي ملف خط.','Could not write the local stylesheet.'=>'تعذّرت كتابة ورقة الأنماط المحلية.','Localized %1$d Google Fonts stylesheet(s) with %2$d font files — they are now served from your site.'=>'تم توطين %1$d من أوراق أنماط Google Fonts مع %2$d من ملفات الخطوط — تُقدَّم الآن من موقعك.','Could not localize the detected Google Fonts. Check that the site can reach fonts.googleapis.com and that the uploads directory is writable.'=>'تعذّر توطين خطوط Google المكتشفة. تحقّق من أن الموقع يمكنه الوصول إلى fonts.googleapis.com وأن مجلد الرفع قابل للكتابة.','No Google Fonts were detected yet. Open your site once with self-hosting enabled, then try again.'=>'لم يتم اكتشاف أي خطوط Google بعد. افتح موقعك مرة واحدة مع تفعيل الاستضافة الذاتية ثم أعد المحاولة.','Object cache (WPOptimizing)'=>'ذاكرة الكائنات المؤقتة (WPOptimizing)','Object cache (host/plugin)'=>'ذاكرة الكائنات المؤقتة (الاستضافة/الإضافة)','Settings for '=>'إعدادات ','Keep all revisions (exclude from WPOptimizing cleanup)'=>'الاحتفاظ بجميع المراجعات (استثناء من تنظيف WPOptimizing)','Fortnightly'=>'كل أسبوعين','Database orphans'=>'يتيمة قاعدة البيانات','File orphans'=>'يتيمة الملفات','%1$s report for %2$s — health %3$d/100'=>'تقرير %1$s لـ %2$s — الصحة %3$d/100','⚠️ Unusual table growth'=>'⚠️ نمو غير معتاد للجداول','These tables grew abnormally between scans — often a runaway log or cache table.'=>'نمت هذه الجداول بشكل غير طبيعي بين الفحوصات — غالبًا سجلّ أو جدول تخزين مؤقت خارج عن السيطرة.','%1$d scans and %2$d cleanups since the last report.'=>'%1$d فحوصات و%2$d عمليات تنظيف منذ التقرير السابق.','Space freed: %s.'=>'المساحة المحرَّرة: %s.','%s vs baseline'=>'%s مقابل الأساس','Key metrics'=>'المقاييس الرئيسية','Sent by %1$s. Change the frequency or turn this off in %2$s.'=>'أُرسل بواسطة %1$s. غيّر التكرار أو عطّل هذا من %2$s.','WPOptimizing → Settings'=>'WPOptimizing ← الإعدادات','%s report'=>'تقرير %s','Open the dashboard'=>'افتح لوحة التحكم','PHP OPcache is switched off'=>'ذاكرة OPcache في PHP معطّلة','Without OPcache, PHP compiles every file of WordPress, your theme and every plugin on every single request. Enabling it is the single largest server-side improvement available, and it is a one-line change your host can make: opcache.enable=1.'=>'بدون OPcache يقوم PHP بترجمة كل ملف من ووردبريس وقالبك وكل إضافة في كل طلب على حدة. تفعيلها هو أكبر تحسين متاح من جهة الخادم، وهو تغيير من سطر واحد يستطيع مزوّد الاستضافة تنفيذه: opcache.enable=1.','OPcache is being rebuilt constantly'=>'يُعاد بناء OPcache باستمرار','The compiled-code cache has started over on several page loads in a row. On this kind of server it lives inside the PHP worker processes, so when the last one is closed for being idle it is thrown away and rebuilt from nothing for the next visitor. More memory will not help. Ask your host to stop PHP workers being recycled while idle — on LiteSpeed that is the external application\'s “Max Idle Time” (set it to -1) and PHP_LSAPI_MAX_REQUESTS.'=>'بدأت ذاكرة الشيفرة المترجمة من الصفر في عدة تحميلات متتالية للصفحة. في هذا النوع من الخوادم تعيش داخل عمليات PHP، فعندما تُغلق آخر عملية بسبب الخمول تُلقى ويُعاد بناؤها من الصفر للزائر التالي. زيادة الذاكرة لن تفيد. اطلب من مزوّد الاستضافة إيقاف إعادة تدوير عمليات PHP أثناء الخمول — في LiteSpeed هو “Max Idle Time” للتطبيق الخارجي (اضبطه على -1) و PHP_LSAPI_MAX_REQUESTS.','OPcache keeps running out of memory'=>'تنفد ذاكرة OPcache مرارًا','OPcache has restarted itself because it filled up, which throws away every compiled file and recompiles them from scratch. This is the one number that says so directly, and the fix is exact: raise opcache.memory_consumption (256M or more on a site with many plugins).'=>'أعادت OPcache تشغيل نفسها لأنها امتلأت، وهذا يتخلص من كل الملفات المترجمة ويعيد ترجمتها من الصفر. هذا هو الرقم الوحيد الذي يقول ذلك مباشرة، والحل دقيق: ارفع opcache.memory_consumption (‏256M أو أكثر في موقع بإضافات كثيرة).','OPcache has run out of file slots'=>'نفدت من OPcache أماكن الملفات','It is not short of memory — it is short of places to put files, so the ones that do not fit are recompiled on every request. Raise opcache.max_accelerated_files above the number of PHP files on the site (30000 or more is normal for WordPress with a page builder and a few dozen plugins).'=>'لا تنقصها الذاكرة، بل تنقصها الأماكن لوضع الملفات، فما لا يتسع يُعاد ترجمته في كل طلب. ارفع opcache.max_accelerated_files فوق عدد ملفات PHP في الموقع (‏30000 أو أكثر أمر طبيعي في ووردبريس مع أداة بناء صفحات وعشرات الإضافات).','OPcache\'s string buffer is full'=>'مخزن السلاسل في OPcache ممتلئ','Repeated strings are shared between compiled files to save memory, and that buffer is full, so the saving stops. Raise opcache.interned_strings_buffer (16 to 32 MB).'=>'تُشارَك السلاسل المتكررة بين الملفات المترجمة لتوفير الذاكرة، وهذا المخزن ممتلئ فتوقّف التوفير. ارفع opcache.interned_strings_buffer (‏من 16 إلى 32 ميغابايت).','OPcache memory is fragmenting'=>'ذاكرة OPcache تتجزأ','A large share of the cache is taken up by versions of files that have since changed. This is normal right after an update and clears itself on the next restart; if it stays high, files are being modified on every request — a plugin writing PHP, or a cache directory inside the site.'=>'تشغل نسخ من ملفات تغيّرت لاحقًا جزءًا كبيرًا من الذاكرة. هذا طبيعي بعد التحديث مباشرة ويُحل عند إعادة التشغيل التالية؛ وإذا بقي مرتفعًا فهناك ملفات تُعدَّل في كل طلب — إضافة تكتب PHP، أو مجلد ذاكرة مؤقتة داخل الموقع.','OPcache is recompiling more than it should'=>'تعيد OPcache الترجمة أكثر مما ينبغي','Nothing is obviously misconfigured — the cache is not full, has not restarted and has been running long enough to judge — so this is worth watching rather than acting on immediately. If it stays low, the usual cause is files changing on disk during normal traffic.'=>'لا يوجد خطأ واضح في الإعداد — الذاكرة ليست ممتلئة ولم تُعد التشغيل وتعمل منذ وقت كافٍ للحكم عليها — لذا هذا للمراقبة لا للتصرف فورًا. إذا بقي منخفضًا فالسبب المعتاد ملفات تتغير على القرص أثناء حركة المرور العادية.','The Chrome UX Report history needs a Google API key.'=>'يحتاج سجل Chrome UX Report إلى مفتاح Google API.','Google has no Chrome UX Report data for this site yet: it needs enough real visits from Chrome.'=>'لا تملك Google بعدُ بيانات Chrome UX Report لهذا الموقع: يلزم عدد كافٍ من الزيارات الحقيقية عبر Chrome.','The Chrome UX Report API returned HTTP %d.'=>'أعادت واجهة Chrome UX Report API الرمز HTTP %d.','No URL to test.'=>'لا يوجد رابط لاختباره.','PageSpeed Insights returned HTTP %d.'=>'أعاد PageSpeed Insights رمز HTTP %d.','PageSpeed Insights returned an unreadable response.'=>'أعاد PageSpeed Insights رداً غير قابل للقراءة.','Shared library: %s'=>'مكتبة مشتركة: %s','Manual: you attributed this item by hand. A human assertion outranks every automatic one.'=>'يدوي: أنت من أسند هذا العنصر بنفسك. وتقديرُ الإنسان مُقدَّمٌ على أي مصدر آلي.','Sure: captured live on this site at the moment the item was registered, by a plugin whose own namespace the item belongs to.'=>'مؤكد: رُصد مباشرةً على هذا الموقع لحظةَ تسجيل العنصر، وبواسطة إضافة ينتمي العنصر إلى نطاق أسمائها.','Likely: recorded by comparing what your site registered before and after activating the extension.'=>'مرجّح: سُجّل بمقارنة ما كان موقعك قد سجّله قبل تنشيط الإضافة وبعده.','Possible: found by reading the extension\'s own code, or confirmed by several sites in the shared dataset. Not verified while running.'=>'محتمل: وُجد بقراءة شفرة الإضافة نفسها، أو أكّدته عدة مواقع في مجموعة البيانات المشتركة. لم يُتحقق منه أثناء التشغيل.','Doubtful: one claim only, and the item does not belong to the claimant\'s namespace — or few sites have reported it. Review before deleting.'=>'مشكوك فيه: مطالبة واحدة فقط، والعنصر خارج نطاق أسماء من يطالب به، أو أبلغت عنه مواقع قليلة. راجعه قبل الحذف.','Estimated: inferred from a prefix or slug pattern. An educated guess, not evidence.'=>'تقديري: استُنتج من سابقة أو من نمط في الاسم اللطيف. تخمين مبني على أساس، لا دليل.','Undetermined: no owner found. Never delete without reviewing it yourself.'=>'غير محدد: لم يُعرف المالك. لا تحذفه أبدًا قبل أن تراجعه بنفسك.','Database attribution'=>'نسبة قاعدة البيانات','File attribution'=>'نسبة الملفات','Known extensions'=>'الإضافات المعروفة','Runtime evidence'=>'أدلة وقت التشغيل','Asset owners'=>'مالكو الموارد','Unload rules'=>'قواعد إلغاء التحميل','WordPress core inventory'=>'جرد نواة ووردبريس','this site shares nothing, so it receives nothing'=>'هذا الموقع لا يشارك شيئًا، لذلك لا يستقبل شيئًا','this layer has no entry in the download map (a bug: please report it)'=>'هذه الطبقة ليست في خريطة التنزيل (هذا خلل: أبلِغنا به)','the server could not be reached'=>'تعذّر الوصول إلى الخادم','the server sent an empty file'=>'أرسل الخادم ملفًا فارغًا','the server sent a web page instead of data'=>'أرسل الخادم صفحة وِب بدلًا من البيانات','the file could not be written to disk'=>'تعذّر كتابة الملف على القرص','the server has not built this layer yet (HTTP 404)'=>'لم يُنشئ الخادم هذه الطبقة بعد (HTTP 404)','the server answered HTTP %d'=>'أجاب الخادم بـ HTTP %d','it downloaded and then disappeared — something is deleting it after the download'=>'جرى تنزيلها ثم اختفت: شيء ما يحذفها بعد التنزيل','manual'=>'يدوي','activation'=>'تفعيل','plugin change'=>'تغيير إضافة','theme change'=>'تغيير قالب','upgrade'=>'ترقية','after cleanup'=>'بعد التنظيف','API'=>'API','network'=>'الشبكة','Preparing scan…'=>'جارٍ تحضير الفحص…','Scanning plugin code…'=>'جارٍ فحص كود الإضافة…','Scanning must-use plugin code…'=>'جارٍ فحص كود إضافة must-use…','Scanning theme code…'=>'جارٍ فحص كود القالب…','Analysing database records…'=>'جارٍ تحليل سجلات قاعدة البيانات…','Listing empty database records…'=>'يجري سرد سجلات قاعدة البيانات الفارغة…','Skipping file-orphan detection (too heavy on this server)…'=>'تم تخطّي كشف الملفات اليتيمة (ثقيل جدًا على هذا الخادم)…','Detecting orphaned files…'=>'جارٍ اكتشاف الملفات اليتيمة…','Analysing media & uploads…'=>'جارٍ تحليل الوسائط والملفات المرفوعة…','Analysis complete.'=>'اكتمل التحليل.','Media analysis complete.'=>'اكتمل تحليل الوسائط.','Indexing the media library… %1$s / %2$s'=>'جارٍ فهرسة مكتبة الوسائط… %1$s / %2$s','Scanning uploads… %s files'=>'جارٍ فحص الملفات المرفوعة… %s ملف','Comparing duplicate images…'=>'جارٍ مقارنة الصور المكررة…','Checking for unused attachments…'=>'جارٍ التحقق من المرفقات غير المستخدمة…','Looking for where each attachment is used… step %1$d of %2$d'=>'جارٍ البحث عن مكان استخدام كل مرفق… الخطوة %1$d من %2$d','Blog index'=>'فهرس المدونة','Single: %s'=>'مفرد: %s','Archive: %s'=>'أرشيف: %s','Archive: taxonomy'=>'أرشيف: تصنيف','The page could not be fetched.'=>'تعذّر جلب الصفحة.','The page links no local stylesheets.'=>'الصفحة لا تربط أي ورقة أنماط محلية.','No stylesheet could be read.'=>'تعذّرت قراءة أي ورقة أنماط.','The generated file could not be written.'=>'تعذّرت كتابة الملف المولَّد.','Redis is almost full (%1$s of %2$s)'=>'Redis ممتلئ تقريبًا (%1$s من %2$s)','When it fills up it starts throwing away keys or refusing writes. Raise maxmemory, or ask your host for a bigger Redis.'=>'عندما يمتلئ يبدأ بالتخلص من المفاتيح أو رفض الكتابة. ارفع maxmemory أو اطلب من مزوّد الاستضافة Redis أكبر.','Redis is set to refuse writes when it fills up'=>'Redis مضبوط على رفض الكتابة عندما يمتلئ','With maxmemory-policy noeviction, a full Redis rejects every write and WordPress quietly works without its cache. For a cache, allkeys-lru is the right policy.'=>'مع maxmemory-policy noeviction يرفض Redis الممتلئ كل كتابة ويعمل ووردبريس بصمت دون ذاكرته المؤقتة. للذاكرة المؤقتة، السياسة الصحيحة هي allkeys-lru.','Redis throws away about %d keys an hour to make room'=>'يتخلص Redis من نحو %d مفتاح في الساعة لإفساح المجال','Every evicted key is a query that runs again. More memory for Redis makes the cache keep what it already computed.'=>'كل مفتاح يُخلى هو استعلام يُنفَّذ من جديد. ذاكرة أكبر لـ Redis تجعل الذاكرة المؤقتة تحتفظ بما حسبته من قبل.','Only %d%% of Redis lookups are hits'=>'%d%% فقط من عمليات البحث في Redis إصابات','Something is flushing the cache often or keys expire too soon. Check for plugins that flush the whole cache on every save, and that Redis has enough memory.'=>'شيء ما يفرّغ الذاكرة المؤقتة كثيرًا أو تنتهي صلاحية المفاتيح مبكرًا. ابحث عن إضافات تفرّغ الذاكرة المؤقتة كلها عند كل حفظ، وتأكد من أن لدى Redis ذاكرة كافية.','Redis has refused %d connections'=>'رفض Redis %d اتصالًا','It hit maxclients: on those requests the site ran without a cache. Raise maxclients or ask your host.'=>'بلغ maxclients: في تلك الطلبات عمل الموقع دون ذاكرة مؤقتة. ارفع maxclients أو راجع مزوّد الاستضافة.','Redis memory is fragmented (%s×)'=>'ذاكرة Redis مجزّأة (%s×)','It holds more memory than its data needs. activedefrag yes, or a restart in a quiet hour, gives it back.'=>'يشغل ذاكرة أكثر مما تحتاجه بياناته. activedefrag yes، أو إعادة تشغيل في ساعة هادئة، يعيدها.','The InnoDB buffer pool (%1$s) is smaller than your data (%2$s)'=>'مجمّع ذاكرة InnoDB المؤقت (%1$s) أصغر من بياناتك (%2$s)','MySQL cannot keep the tables in memory and reads them from disk. Raise innodb_buffer_pool_size to at least the size of your data, or ask your host.'=>'لا يستطيع MySQL إبقاء الجداول في الذاكرة فيقرأها من القرص. ارفع innodb_buffer_pool_size إلى حجم بياناتك على الأقل، أو راجع مزوّد الاستضافة.','%d%% of MySQL temporary tables go to disk'=>'%d%% من جداول MySQL المؤقتة تذهب إلى القرص','Sorting and grouping that does not fit in memory is written to disk. Raise tmp_table_size and max_heap_table_size together.'=>'عمليات الفرز والتجميع التي لا تتسع لها الذاكرة تُكتب على القرص. ارفع tmp_table_size وmax_heap_table_size معًا.','MySQL has used %1$d of its %2$d connections'=>'استخدم MySQL %1$d من أصل %2$d اتصالًا','At the limit, new visits get "Error establishing a database connection". Raise max_connections or find what holds connections open.'=>'عند الحد يحصل الزوار الجدد على «خطأ في إنشاء اتصال بقاعدة البيانات». ارفع max_connections أو اعثر على ما يُبقي الاتصالات مفتوحة.','MySQL opens about %d tables an hour'=>'يفتح MySQL نحو %d جدول في الساعة','Its table cache is too small for the number of tables, so it keeps closing and reopening them. Raise table_open_cache.'=>'ذاكرة الجداول المؤقتة لديه صغيرة جدًا بالنسبة لعدد الجداول، فيظل يغلقها ويعيد فتحها. ارفع table_open_cache.','Your database server (%s) is out of support'=>'خادم قاعدة البيانات لديك (%s) لم يعد مدعومًا','It no longer receives security fixes and is slower than current versions. Ask your host to move you to MySQL 8 or MariaDB 10.6 or later.'=>'لم يعد يتلقى إصلاحات أمنية وهو أبطأ من الإصدارات الحالية. اطلب من مزوّد الاستضافة نقلك إلى MySQL 8 أو MariaDB 10.6 أو أحدث.','Your license key is invalid!'=>'مفتاح الترخيص غير صالح!','The API key is invalid.'=>'مفتاح API غير صالح.','That license key is already in use!'=>'هذا مفتاح الترخيص مستخدم بالفعل!','The license key is already inactive.'=>'مفتاح الترخيص غير نشط بالفعل.','Your license key has expired!'=>'انتهت صلاحية مفتاح الترخيص!','Invalid parameters for the license request.'=>'معلمات غير صالحة لطلب الترخيص.','That license key was activated on another website!'=>'تم تفعيل مفتاح الترخيص هذا على موقع آخر!','Missing or invalid site identifier for the license.'=>'معرّف الموقع للترخيص مفقود أو غير صالح.','An error has occurred, please retry!'=>'حدث خطأ، يرجى المحاولة مرة أخرى!','%s: License Key Expired'=>'%s: انتهت صلاحية مفتاح الترخيص','Your license key has expired and has been deactivated!'=>'انتهت صلاحية مفتاح الترخيص وتم تعطيله!','Please enter and activate your license key if you want to use this plugin!'=>'يرجى إدخال وتفعيل مفتاح الترخيص إذا كنت تريد استخدام هذا الإضافة!','%s: License Expiring Soon'=>'%s: مفتاح الترخيص سينتهي قريباً','Your license key will expire in %d days.'=>'سينتهي مفتاح الترخيص الخاص بك خلال %d يومًا.','Please renew your license to avoid service interruption.'=>'يرجى تجديد الترخيص لتجنب انقطاع الخدمة.','Open license settings'=>'فتح إعدادات الترخيص','Sent by WPOptimizing.'=>'أُرسل بواسطة WPOptimizing.','WPOptimizing — performance & cleanup'=>'WPOptimizing — الأداء والتنظيف','Run a full analysis of code, files and database'=>'تشغيل تحليل كامل للشيفرة والملفات وقاعدة البيانات','Run general cleanup'=>'تشغيل التنظيف العام','Run the general database cleanup with your saved settings'=>'تشغيل التنظيف العام لقاعدة البيانات بإعداداتك المحفوظة','Flush all caches'=>'إفراغ كل ذاكرات التخزين المؤقت','Flush the object cache and any detected host/plugin page cache'=>'يُفرّغ ذاكرة الكائنات المؤقتة وأي ذاكرة تخزين صفحات للاستضافة/الإضافة مكتشفة','Go to dashboard'=>'الذهاب إلى لوحة التحكم','Working…'=>'جارٍ العمل…','Cache flushed ✓'=>'تم إفراغ التخزين المؤقت ✓','Cleanup done ✓'=>'اكتمل التنظيف ✓','Run a general cleanup now with your saved settings?'=>'هل تريد تشغيل تنظيف عام الآن بإعداداتك المحفوظة؟','Once Weekly'=>'مرة واحدة أسبوعيا','Once Monthly'=>'مرة واحدة في الشهر','Read more in the documentation'=>'اقرأ المزيد في الوثائق','Smart Assets needs an active Pro license.'=>'يحتاج Smart Assets إلى ترخيص Pro فعّال.','This plugin deletes one item at a time, backing it up first. Pro deletes as many as you select, or all of them at once.'=>'يحذف هذا الإضافة عنصرًا واحدًا في كل مرة بعد نسخه احتياطيًا. أما Pro فيحذف كل ما تحدده، أو الجميع دفعة واحدة.','This plugin deletes one item at a time. Select just one; Pro deletes as many as you select.'=>'يحذف هذا الإضافة عنصرًا واحدًا في كل مرة. حدّد عنصرًا واحدًا فقط؛ أما Pro فيحذف كل ما تحدده.','This plugin uninstalls one extension at a time: if you tick several, only the first is uninstalled. Pro uninstalls every one you select.'=>'يُلغي هذا الإضافة تثبيت امتداد واحد في كل مرة: إذا حددت عدة امتدادات، يُلغى تثبيت الأول فقط. أما Pro فيلغي تثبيت كل ما تحدده.','Smart Assets, which stops the CSS and JavaScript a page does not need, is not included in this plugin.'=>'لا يتضمن هذا الإضافة Smart Assets، الذي يوقف ملفات CSS وJavaScript التي لا تحتاجها الصفحة.','The library audit is not included in this plugin.'=>'لا يتضمن هذا الإضافة تدقيق مكتبة الوسائط.','deletes the record you ticked, after a backup: this plugin deletes one at a time. The notice that follows offers Undo for one day.'=>'يحذف السجل الذي حدّدته بعد نسخه احتياطيًا: يحذف هذا الإضافة سجلًا واحدًا في كل مرة. ويعرض الإشعار التالي «تراجع» لمدة يوم واحد.','Webhooks are not included in this plugin.'=>'لا يتضمن هذا الإضافة Webhooks.','WPOptimizing — Network'=>'WPOptimizing — الشبكة','The network dashboard (every site at a glance, network-wide profiles and scans, CSV export and email alerts) is part of Pro and needs an active license.'=>'لوحة الشبكة (جميع المواقع في لمحة، والملفات الشخصية والتحليلات على مستوى الشبكة، والتصدير إلى CSV، وتنبيهات البريد) جزء من Pro وتحتاج إلى ترخيص فعّال.','See Pro'=>'اطّلع على Pro','See where the time goes and fix it: object cache, CSS and JavaScript, images and delivery, each one switched on separately.'=>'اكتشف أين يضيع الوقت وأصلحه: التخزين المؤقت للكائنات، وCSS وJavaScript، والصور، والتحميل والتسليم، وكل منها يُفعَّل على حدة.','Scale down oversized uploads.'=>'تصغير المرفوعات الكبيرة جدًا.','Uploads above the max size are scaled down; the full-size original is preserved.'=>'تُصغَّر المرفوعات التي تتجاوز الحجم الأقصى، مع الحفاظ على الأصل بالحجم الكامل.','Max size'=>'الحجم الأقصى','0 on an axis disables resizing.'=>'القيمة 0 على أحد المحورين تعطّل تغيير الحجم.','Pro also caches your pages at Cloudflare\'s edge, for anonymous visitors, with a Cache Rule it checks before leaving on.'=>'يخزّن Pro صفحاتك مؤقتًا أيضًا على حافة Cloudflare للزوار المجهولين، بقاعدة تخزين يتحقق منها قبل إبقائها مفعّلة.','Caching the pages at Cloudflare needs an active Pro license.'=>'يحتاج تخزين الصفحات مؤقتًا في Cloudflare إلى ترخيص Pro فعّال.','The page cache needs an active Pro license.'=>'تحتاج ذاكرة تخزين الصفحات إلى ترخيص Pro فعّال.','Speed up the admin and the front end with a persistent object cache and per-request query deduplication — safe and reversible.'=>'سرّع لوحة التحكم والواجهة الأمامية بذاكرة كائنات دائمة وإزالة تكرار الاستعلامات لكل طلب — آمن وقابل للتراجع.','WPOptimizing detects your host or plugin page cache and purges it automatically after a cleanup (and from the toolbar “Flush all caches”), so visitors never see stale content.'=>'يكتشف WPOptimizing ذاكرة تخزين الصفحات الخاصة باستضافتك أو إضافتك ويُفرّغها تلقائيًا بعد التنظيف (ومن زر «إفراغ كل ذاكرات التخزين المؤقت» في شريط الأدوات)، حتى لا يرى الزوار محتوى قديمًا أبدًا.','A page cache serves a static HTML copy of each page to anonymous visitors, so most requests never boot WordPress.'=>'تقدّم ذاكرة تخزين الصفحات نسخة HTML ثابتة من كل صفحة للزوّار المجهولين، فلا تُشغّل معظم الطلبات ووردبريس إطلاقًا.','A page cache, with background preload and page caching at Cloudflare\'s edge, is not included in this plugin.'=>'لا يتضمن هذا الإضافة ذاكرة تخزين الصفحات ولا تحميلها المسبق في الخلفية ولا تخزين الصفحات على حافة Cloudflare.','The page cache, its background preload and page caching at Cloudflare\'s edge are part of Pro and need an active license.'=>'ذاكرة تخزين الصفحات وتحميلها المسبق في الخلفية وتخزين الصفحات على حافة Cloudflare جزء من Pro وتحتاج إلى ترخيص فعّال.','CSS and JavaScript minification (opt-in, off by default): under Speed › Page & browser › Minification WPOptimizing can serve minified copies of your own local CSS and JS, stripping comments and whitespace so they download faster. It is deliberately conservative: files that are already minified, hosted on another domain, or listed in your exclusions are left untouched; the minified copies live in wp-content/uploads/wpopt-assets/ and are rebuilt automatically when the source changes or a cache is flushed. A test mode lets administrators preview the result before exposing it to visitors, and it refuses to run alongside another asset optimizer (Autoptimize, WP Rocket, Perfmatters, LiteSpeed) to avoid double-processing.'=>'تصغير CSS وJavaScript (اختياري، معطّل افتراضياً): من السرعة › الصفحة والمتصفح › التصغير، يمكن لـWPOptimizing تقديم نسخ مصغّرة من ملفات CSS وJS المحلية الخاصة بك، مع إزالة التعليقات والمسافات لتنزيلها بسرعة أكبر. وهو محافظ عن قصد: تُترك الملفات المصغّرة مسبقاً أو المستضافة على نطاق آخر أو المدرجة في استثناءاتك دون تغيير؛ وتوجد النسخ المصغّرة في wp-content/uploads/wpopt-assets/ ويُعاد إنشاؤها تلقائياً عند تغيّر المصدر أو إفراغ إحدى الذاكرات. ويتيح وضع الاختبار للمسؤولين معاينة النتيجة قبل عرضها على الزوّار، وهو يرفض العمل بجانب أداة تحسين موارد أخرى (Autoptimize، WP Rocket، Perfmatters، LiteSpeed) لتجنّب المعالجة المزدوجة.','Optional speed features for the public site, configured in Speed › Page & browser: speculative loading (prefetch/prerender the next page), content image loading optimization, resource hints and a Server-Timing diagnostic header. All opt-in and reversible; none cache full HTML pages.'=>'ميزات سرعة اختيارية للموقع العام، تُضبط في السرعة › الصفحة والمتصفح: التحميل التخميني (الجلب المسبق/العرض المسبق للصفحة التالية)، وتحسين تحميل صور المحتوى، وتلميحات الموارد، وترويسة Server-Timing تشخيصية. جميعها اختيارية وقابلة للعكس؛ ولا تخزّن أي منها صفحات HTML كاملة في الذاكرة المؤقتة.','Settings: Max dimensions set separate width and height limits (0 on an axis disables it). Scale down oversized uploads applies them to new uploads through WordPress\' native handling, which keeps the full-size original.'=>'الإعدادات: تحدّد الأبعاد القصوى حدّي العرض والارتفاع بشكل منفصل (القيمة 0 على أحد المحورين تعطّله). ويطبّقها «تصغير المرفوعات الكبيرة جدًا» على المرفوعات الجديدة عبر المعالجة الأصلية في ووردبريس، التي تحتفظ بالأصل بالحجم الكامل.','Removes database clutter: post revisions, auto-drafts, trashed posts, spam comments, and expired transients. Runs from a single button. A detailed log is saved after every run.'=>'يزيل الفوضى من قاعدة البيانات: مراجعات المنشورات، والمسودات التلقائية، والمنشورات المحذوفة، وتعليقات السبام، والمؤقتات المنتهية الصلاحية. يعمل بنقرة واحدة. يُحفظ سجل تفصيلي بعد كل تشغيل.','Every batch the cleanup deletes is backed up first, into one Backups entry per run. If that backup cannot be written, the run stops with the status “Stopped: backup failed” and deletes nothing more. Table optimization changes no data and needs no backup.'=>'تُنسخ كل دفعة يحذفها التنظيف احتياطيًا أولًا، في مُدخل واحد ضمن النسخ الاحتياطية لكل تشغيل. وإذا تعذّرت كتابة تلك النسخة، يتوقف التشغيل بالحالة «متوقف: فشل النسخ الاحتياطي» ولا يحذف شيئًا آخر. أما تحسين الجداول فلا يغيّر أي بيانات ولا يحتاج إلى نسخة احتياطية.','Scans your uploads for files with no database attachment record, orphaned thumbnail sizes and potentially unused attachments, and counts the exact-content duplicates.'=>'يفحص ملفات التحميل الخاصة بك بحثاً عن الملفات التي لا يوجد لها سجل مرفق في قاعدة البيانات، وأحجام الصور المصغرة المتروكة، والمرفقات التي قد لا تكون مستخدمة، ويحصي الملفات المكررة ذات المحتوى المتطابق.','Every change WPOptimizing makes to your data is backed up first: deletions (orphans, empty rows, media and the general cleanup) and changes (autoload flags, scheduled tasks, .htaccess and wp-config.php edits). Backups are grouped by operation so you can find and restore exactly what a specific action changed. Manual backups can also be created at any time.'=>'كل تغيير يجريه WPOptimizing على بياناتك يُنسخ احتياطيًا أولًا: عمليات الحذف (اليتيم، والصفوف الفارغة، والوسائط، والتنظيف العام) والتعديلات (علامات التحميل التلقائي، والمهام المجدولة، وتعديلات .htaccess وwp-config.php). وتُجمَّع النسخ حسب العملية، فتجد وتستعيد بالضبط ما غيّره إجراء بعينه. ويمكن أيضًا إنشاء نسخ يدوية في أي وقت.','Uploads larger than this (width × height) are scaled down when they are uploaded; the full-size original is kept. 0 on an axis disables it.'=>'تُصغَّر المرفوعات الأكبر من هذه القيم (العرض × الارتفاع) عند رفعها، مع الاحتفاظ بالأصل بالحجم الكامل. القيمة 0 على أحد المحورين تعطّله.','Scale down oversized uploads to the max dimensions — the full-size original is preserved'=>'تصغير المرفوعات الكبيرة جدًا إلى الأبعاد القصوى — ويُحتفَظ بالأصل بحجمه الكامل','The media library audit (stranded and competing files, leftover sizes, downloadable dumps and logs, and the uploads protection) is not included in this plugin.'=>'لا يتضمن هذا الإضافة تدقيق مكتبة الوسائط (الملفات المتروكة والمتعارضة، والأحجام المتبقية، والتفريغات والسجلات القابلة للتنزيل، وحماية مجلد uploads).','The media library audit is part of Pro and needs an active license.'=>'تدقيق مكتبة الوسائط جزء من Pro ويحتاج إلى ترخيص فعّال.','Listing duplicate images and merging them (one copy kept, its references reassigned) is not included in this plugin.'=>'لا يتضمن هذا الإضافة عرض الصور المكررة ودمجها (الاحتفاظ بنسخة واحدة وإعادة تعيين مراجعها).','How the page reaches the visitor: speculative loading, image loading, resource hints and a Server-Timing diagnostic. All optional and reversible; none of them cache whole pages.'=>'كيف تصل الصفحة إلى الزائر: التحميل التخميني، وتحميل الصور، وتلميحات الموارد، وتشخيص Server-Timing. كلها اختيارية وقابلة للعكس، ولا يخزّن أي منها صفحات كاملة.','Scheduled cleanup (hourly to monthly, with a frequency per task) and automatic cleanup when the database grows are not included in this plugin. Run the cleanup from General cleanup whenever you need it.'=>'لا يتضمن هذا الإضافة التنظيف المجدول (من كل ساعة إلى شهري، بتكرار لكل مهمة) ولا التنظيف التلقائي عند نمو قاعدة البيانات. شغّل التنظيف من «التنظيف العام» متى احتجت إليه.','Scheduled cleanup and automatic cleanup when the database grows are part of Pro and need an active license. Your schedule is kept and comes back with the license.'=>'التنظيف المجدول والتنظيف التلقائي عند نمو قاعدة البيانات جزء من Pro ويحتاجان إلى ترخيص فعّال. يُحتفظ بجدولك ويعود مع الترخيص.','Webhooks are part of Pro and need an active license. The endpoint you saved is kept.'=>'Webhooks جزء من Pro وتحتاج إلى ترخيص فعّال. يُحتفظ بنقطة النهاية التي حفظتها.','Preloading key resources, lazy YouTube embeds, self-hosted Google Fonts and CDN rewriting are not included in this plugin.'=>'لا يتضمن هذا الإضافة التحميل المسبق للموارد الأساسية، ولا تأجيل تضمينات YouTube، ولا خطوط Google المستضافة ذاتيًا، ولا إعادة الكتابة إلى CDN.','Preloading key resources, lazy YouTube embeds, self-hosted Google Fonts and CDN rewriting are part of Pro and need an active license.'=>'التحميل المسبق للموارد الأساسية وتأجيل تضمينات YouTube وخطوط Google المستضافة ذاتيًا وإعادة الكتابة إلى CDN جزء من Pro وتحتاج إلى ترخيص فعّال.','More delivery options'=>'خيارات تسليم أخرى','Smart Assets stops the CSS and JavaScript a page does not need — site-wide, on chosen URLs or on a single page — with a test mode that applies it to administrators first.'=>'يوقف Smart Assets ملفات CSS وJavaScript التي لا تحتاجها الصفحة — على الموقع كله، أو على عناوين URL تختارها، أو على صفحة واحدة — مع وضع اختبار يطبّقه على المسؤولين أولًا.','Smart Assets is not included in this plugin.'=>'لا يتضمن هذا الإضافة Smart Assets.','Smart Assets is part of Pro and needs an active license.'=>'Smart Assets جزء من Pro ويحتاج إلى ترخيص فعّال.','The CSS and JavaScript actually loaded on your public pages. You can stop specific assets from loading, on the whole site or only where you choose, and let the knowledge base unload them automatically where they are not needed.'=>'ملفات CSS وJavaScript التي تُحمَّل فعليًا على صفحاتك العامة. يمكنك إيقاف تحميل موارد محددة، على الموقع كله أو حيث تختار فقط، وترك قاعدة المعرفة تزيلها تلقائيًا حيث لا حاجة إليها.','The WPOptimizing API needs an active Pro license.'=>'تحتاج واجهة WPOptimizing البرمجية إلى ترخيص Pro فعّال.','The WPOptimizing commands need an active Pro license.'=>'تحتاج أوامر WPOptimizing إلى ترخيص Pro فعّال.','Import / export: download the whole configuration as a JSON file and restore it here or on another site — handy to replicate your setup across a fleet. The export covers the settings for cleanup, cache, media and images, backups and attribution. For safety it never includes keys, passwords, the data-sharing consent, branding or measured runtime state (scan results, baselines, cached sizes), so importing onto another site only carries configuration. On import, existing settings are overwritten and any unrecognized keys are ignored.'=>'استيراد / تصدير: نزّل التهيئة بالكامل كملف JSON واستعدها هنا أو في موقع آخر — مفيد لنسخ إعداداتك عبر مجموعة من المواقع. يشمل التصدير إعدادات التنظيف، والتخزين المؤقت، والوسائط والصور، والنسخ الاحتياطية، والإسناد. لأسباب أمنية لا يتضمن أبدًا المفاتيح أو كلمات المرور أو الموافقة على مشاركة البيانات أو العلامة التجارية أو حالة التشغيل المقاسة (نتائج الفحص، القيم المرجعية، الأحجام المخزَّنة مؤقتًا)، لذا فإن الاستيراد إلى موقع آخر ينقل التهيئة فقط. عند الاستيراد، يتم استبدال الإعدادات الحالية وتجاهل أي مفاتيح غير معروفة.','Every media deletion is backed up first, so it is reversible: WPOptimizing copies each file before removing anything. If you ever need to undo a deletion, the Media tab shows how many file backups are available and links straight to the Backups tab, where you restore a whole operation in one click. Nothing is deleted that was not fully backed up.'=>'يُنسَخ كل حذف للوسائط احتياطيًا أولًا، لذا فهو قابل للتراجع: ينسخ WPOptimizing كل ملف قبل إزالة أي شيء. وإذا احتجت يومًا إلى التراجع عن حذف، يعرض تبويب «الوسائط» عدد النسخ الاحتياطية للملفات المتاحة ويربط مباشرةً بتبويب «النسخ الاحتياطية»، حيث تستعيد عملية كاملة بنقرة واحدة. ولا يُحذف أي شيء لم يُنسَخ احتياطيًا بالكامل.','Image optimization (front-end WebP/AVIF serving, scaling down oversized uploads and the analysis of the library) has its own sub-section, documented separately under Image optimization.'=>'لتحسين الصور (تقديم WebP/AVIF في الواجهة الأمامية، وتصغير المرفوعات الكبيرة جدًا، وتحليل المكتبة) قسم فرعي خاص به، موثَّق على حدة ضمن «تحسين الصور».','Media has six entries: Orphans (with a filter for orphan files, orphan thumbnails and other files), Duplicate sets, Unused attachments, Image optimization (Summary and Heaviest images), Trash and Library audit. Merging duplicates and the library audit are not included in this plugin: their entries only say so.'=>'تحتوي الوسائط على ستة إدخالات: اليتيمة (مع عامل تصفية للملفات اليتيمة والصور المصغّرة اليتيمة والملفات الأخرى)، ومجموعات المكررات، والمرفقات غير المستخدمة، وتحسين الصور (الملخص وأثقل الصور)، وسلة المهملات، وفحص المكتبة. لا يتضمن هذا الإضافة دمج المكررات ولا فحص المكتبة: يكتفي إدخالاهما بالإشارة إلى ذلك.','Finds files in /uploads with no record in the database, orphaned thumbnails and unused attachments, and counts the duplicate media. Media deletions are backed up first and can be restored from the Backups tab.'=>'يعثر على ملفات في ‎/uploads بلا سجل في قاعدة البيانات، وعلى المصغّرات اليتيمة والمرفقات غير المستخدمة، ويُحصي الوسائط المكررة. وتُنسخ عمليات حذف الوسائط احتياطيًا قبل تنفيذها ويمكن استعادتها من تبويب النسخ الاحتياطية.','Configure cleanup options and backups. Quick profiles below apply a recommended configuration with one click.'=>'اضبط خيارات التنظيف والنسخ الاحتياطية. تطبّق ملفات التعريف السريعة أدناه إعدادًا موصى به بنقرة واحدة.','Speculative loading, image loading, resource hints and Server-Timing are now under Speed › Page & browser, next to minify.'=>'أصبح التحميل الاستباقي وتحميل الصور وتلميحات الموارد وServer-Timing الآن ضمن السرعة › الصفحة والمتصفح، بجانب التصغير.','Save this site’s configuration to a JSON file and restore it here or on another site — handy to replicate your setup across sites. It includes the settings for cleanup, cache, media and images, backups and attribution. Keys, passwords, data-sharing consent and measured runtime state (scan results, baselines, cached sizes) are never included.'=>'احفظ إعدادات هذا الموقع في ملف JSON واستعدها هنا أو في موقع آخر — مفيد لنسخ إعداداتك بين المواقع. يتضمن إعدادات التنظيف والتخزين المؤقت والوسائط والصور والنسخ الاحتياطية والإسناد. لا يتم أبدًا تضمين المفاتيح وكلمات المرور والموافقة على مشاركة البيانات وحالة التشغيل المقاسة (نتائج الفحص، القيم المرجعية، الأحجام المخزَّنة مؤقتًا).','All the WPO your WordPress needs in a single plugin, with the only cleanup that knows who owns each leftover before you delete anything.'=>'كل ما يحتاجه ووردبريس الخاص بك من WPO في إضافة واحدة، مع التنظيف الوحيد الذي يعرف لمن تعود كل بقية قبل أن تحذف أي شيء.','WPOptimizing'=>'WPOptimizing','Analyze the images in your uploads — total weight, formats, large files and how many lack a WebP/AVIF copy. Oversized new uploads are scaled down as they arrive, and serving the next-gen copies on the front-end is built in.'=>'يحلّل الصور في ملفاتك المرفوعة: الحجم الإجمالي والصيغ والملفات الكبيرة وكم منها بلا نسخة WebP/AVIF. وتُصغَّر المرفوعات الجديدة الكبيرة جدًا فور وصولها، وتقديم نسخ الجيل الجديد في الواجهة الأمامية مُضمَّن.','Files removed from the media sections (unused attachments, orphan files and thumbnails) are backed up first and can be restored here. Restoring puts the files back on disk; deleting permanently frees the backup space. This is the same set of copies as the Backups tab.'=>'تُنسخ الملفات المحذوفة من أقسام الوسائط (المرفقات غير المستخدمة، والملفات والصور المصغّرة اليتيمة) احتياطيًا أولًا ويمكن استعادتها هنا. الاستعادة تعيد الملفات إلى القرص؛ والحذف النهائي يحرّر مساحة النسخة الاحتياطية. وهي نفس مجموعة النسخ الموجودة في تبويب النسخ الاحتياطية.','Deleting records and uninstalling extensions requires an active license. Without one you can scan, review, deactivate, run general cleanup and create backups.'=>'يتطلب حذف السجلات وإلغاء تثبيت الإضافات ترخيصاً نشطاً. بدونه يمكنك الفحص والمراجعة وإلغاء التفعيل وتشغيل التنظيف العام وإنشاء النسخ الاحتياطية.','<strong>Without a license:</strong> showing %1$s of %2$s records found.'=>'<strong>بدون ترخيص:</strong> عرض %1$s من %2$s سجلًّا موجودًا.','<strong>Without a license:</strong> all %s records found are shown. Deleting them needs an active license.'=>'<strong>بدون ترخيص:</strong> تُعرض كل السجلات التي عُثر عليها (%s). حذفها يحتاج إلى ترخيص فعّال.','Without a license'=>'بدون ترخيص','Without a license you can analyse and review your site and run the general cleanup. Activate your license to delete what the analysis attributes and to use the other Pro features.'=>'بدون ترخيص يمكنك تحليل موقعك ومراجعته وتشغيل التنظيف العام. فعّل ترخيصك لحذف ما ينسبه التحليل واستخدام ميزات Pro الأخرى.','The license has not been verified for over a week, so Pro features are off until the store can be reached again. The rest keeps working: scanning and review are unaffected.'=>'لم يتم التحقق من الترخيص منذ أكثر من أسبوع، لذلك أُوقفت ميزات Pro حتى يتسنى الوصول إلى المتجر مجددًا. يواصل الباقي العمل: الفحص والمراجعة لا يتأثران.','Your license has expired. The plugin keeps working without it — activate a license to enable deletion and the other Pro features.'=>'انتهت صلاحية ترخيصك. تواصل الإضافة العمل بدونه — فعّل ترخيصاً لتمكين الحذف وميزات Pro الأخرى.','Activate your license to unlock the Pro features (deleting attributed records, automatic asset unloading and uninstalling extensions). You can also do this later in Settings — without a license the plugin already scans, reviews, cleans and backs up.'=>'فعّل ترخيصك لفتح ميزات Pro (حذف السجلات المنسوبة، والتفريغ التلقائي للموارد، وإلغاء تثبيت الإضافات). يمكنك أيضًا فعل ذلك لاحقًا في الإعدادات: بدون ترخيص تفحص الإضافة وتراجع وتنظّف وتنشئ نسخًا احتياطية بالفعل.','Enter your key and click Activate. No key yet? Continue — everything here works without a license, and you can add it anytime.'=>'أدخل مفتاحك وانقر على «تفعيل». ليس لديك مفتاح بعد؟ تابع: كل شيء هنا يعمل بدون ترخيص، ويمكنك إضافته في أي وقت.','Without a license you can see your autoload weight and every option. <a href="%s" target="_blank" rel="noopener">Get a license</a> to disable the ones slowing your site down and run Smart Deactivation.'=>'بدون ترخيص ترى وزن autoload وكل الخيارات. <a href="%s" target="_blank" rel="noopener">احصل على ترخيص</a> لتعطيل ما يُبطئ موقعك وتشغيل التعطيل الذكي.','The "Heaviest images" view of Image optimization turns the aggregate numbers into a concrete, per-image to-do list: a table with a thumbnail, dimensions, weight, a plain-language tag of what would help each image (Oversized, No WebP, No AVIF — only ever suggesting formats your server can actually create) and an estimated saving, with search, a format filter and pagination. Tick the images you want and click "Optimize selected" to recompress/resize them (backup-first) and generate their missing WebP/AVIF copies in one pass; "Optimize all" does the whole filtered list. Without a license the table is read-only. On very large libraries the scan is time-bounded, so the list shows the worst offenders it reached.'=>'يحوّل عرض «أثقل الصور» في تحسين الصور الأرقام الإجمالية إلى قائمة مهام ملموسة لكل صورة: جدول يضم صورة مصغّرة والأبعاد والوزن ووسمًا بلغة واضحة لما سيساعد كل صورة (أكبر من اللازم، بدون WebP، بدون AVIF — مع اقتراح الصيغ التي يستطيع خادومك إنشاءها فقط) وتوفيرًا تقديريًا، مع بحث وتصفية حسب الصيغة وترقيم صفحات. حدّد الصور التي تريدها واضغط «تحسين المحدد» لإعادة ضغطها/تحجيمها (مع نسخة احتياطية مسبقة) وإنشاء نسخ WebP/AVIF المفقودة دفعةً واحدة؛ ويعالج «تحسين الكل» القائمة المُصفّاة بأكملها. بدون ترخيص يكون الجدول للقراءة فقط. في المكتبات الكبيرة جدًا يكون الفحص محدودًا زمنيًا، لذا تعرض القائمة أسوأ الحالات التي بلغها.','File deletion needs an active license; without one you can review all findings without risk. Always run a full site backup before bulk-deleting media files.'=>'يحتاج حذف الملفات إلى ترخيص فعّال؛ وبدونه يمكنك مراجعة جميع النتائج دون مخاطر. قم دائماً بعمل نسخة احتياطية كاملة للموقع قبل الحذف الجماعي لملفات الوسائط.','Deleting files requires an active license.'=>'يتطلب حذف الملفات ترخيصاً فعّالاً.','Without a license you can see the full media analysis. <a href="%s" target="_blank" rel="noopener">Get a license</a> to delete orphaned and duplicate images (with an automatic backup).'=>'بدون ترخيص ترى تحليل الوسائط الكامل. <a href="%s" target="_blank" rel="noopener">احصل على ترخيص</a> لحذف الصور اليتيمة والمكررة (مع نسخة احتياطية تلقائية).','Without a license the leftovers are only listed. <a href="%s" target="_blank" rel="noopener">Get a license</a> to delete them (with an automatic backup).'=>'بدون ترخيص تُعرض المتبقيات فقط. <a href="%s" target="_blank" rel="noopener">احصل على ترخيص</a> لحذفها (مع نسخة احتياطية تلقائية).','%d suggestion accepted. The records were re-evaluated.' . "\0" . '%d suggestions accepted. The records were re-evaluated.'=>'عدد الاقتراحات المقبولة: %d. أُعيد تقييم السجلات.' . "\0" . 'عدد الاقتراحات المقبولة: %d. أُعيد تقييم السجلات.' . "\0" . 'عدد الاقتراحات المقبولة: %d. أُعيد تقييم السجلات.' . "\0" . 'عدد الاقتراحات المقبولة: %d. أُعيد تقييم السجلات.' . "\0" . 'عدد الاقتراحات المقبولة: %d. أُعيد تقييم السجلات.' . "\0" . 'عدد الاقتراحات المقبولة: %d. أُعيد تقييم السجلات.','Accept all sure suggestions (%d)'=>'قبول كل الاقتراحات المؤكدة (%d)','Library'=>'مكتبة','Extension names'=>'أسماء الإضافات','Action Scheduler entries are backed up. Their log rows (trace lines such as «action started») are deleted without a backup, and so is any other log row older than %d days.'=>'تُنسخ إدخالات Action Scheduler احتياطيًا. أما صفوف سجلها (رسائل التتبع مثل «action started») فتُحذف دون نسخة احتياطية، وكذلك أي صف سجل آخر أقدم من %d يومًا.','Action Scheduler: %s log rows deleted without a backup.'=>'Action Scheduler: حُذف %s من صفوف السجل دون نسخة احتياطية.','The cleanup continues by itself in the background in about a minute, until it is done.'=>'يستأنف التنظيف من تلقاء نفسه في الخلفية بعد دقيقة تقريبًا حتى ينتهي.','The cleanup reached its time limit and continues by itself in the background until it is done. You can leave this page.'=>'بلغ التنظيف حده الزمني ويستمر من تلقاء نفسه في الخلفية حتى ينتهي. يمكنك مغادرة هذه الصفحة.','The cleanup reached its time limit and is continuing by itself in the background since %2$s (passes so far: %1$s). You can leave this page, or follow it here until it is done.'=>'بلغ التنظيف حده الزمني ويستمر من تلقاء نفسه في الخلفية منذ %2$s (الدورات حتى الآن: %1$s). يمكنك مغادرة هذه الصفحة أو متابعته هنا حتى ينتهي.','Action Scheduler entries removed'=>'إدخالات Action Scheduler المحذوفة','Action Scheduler log rows removed (no backup)'=>'صفوف سجل Action Scheduler المحذوفة (دون نسخة احتياطية)','Continue now'=>'المتابعة الآن','Removed %s rows so far…'=>'حُذف %s صفًا حتى الآن…','Waiting for the background pass to finish…'=>'بانتظار انتهاء الدورة الجارية في الخلفية…','%s: AUTO_INCREMENT restored.'=>'%s: أُعيد AUTO_INCREMENT.','%1$s was not changed: %2$s.'=>'لم يُغيَّر %1$s: %2$s.','WordPress tables without AUTO_INCREMENT'=>'جداول ووردبريس بلا AUTO_INCREMENT','Their id column no longer numbers new rows by itself, usually after a migration that copied the tables without their attributes. New rows go in with id 0 and the next one collides: saving, updating plugins or creating users and terms fails with errors that do not point here.'=>'لم يعد عمود المعرّف فيها يرقّم الصفوف الجديدة تلقائيًا، وعادةً ما يحدث ذلك بعد ترحيل نسخ الجداول دون خصائصها. تدخل الصفوف الجديدة بالمعرّف 0 ويتعارض الصف التالي معها: فيفشل الحفظ وتحديث الإضافات وإنشاء المستخدمين والتصنيفات بأخطاء لا تشير إلى هنا.','— it has also lost its primary key, so it may hold duplicate ids. Fix it with your host or a developer, from a backup; it is not changed from here.'=>'— فقد أيضًا مفتاحه الأساسي، لذا قد يحتوي على معرّفات مكررة. أصلحه عبر الاستضافة أو مطوّر انطلاقًا من نسخة احتياطية؛ لا يُعدَّل من هنا.','— it has a row with %s 0, and other tables and plugins point at that id. Moving it to another id would break those links, so it is not done automatically: give that row a new id, update what refers to it, and come back.'=>'— فيه صف قيمة %s فيه 0، وتشير إليه جداول وإضافات أخرى. نقله إلى معرّف آخر سيكسر تلك الروابط، لذا لا يتم تلقائيًا: امنح هذا الصف معرّفًا جديدًا، وحدّث ما يشير إليه، ثم عُد إلى هنا.','— the table takes %s, and the change rebuilds it and blocks writes to it meanwhile, so it is not done from here. Your hosting provider can do it at a quiet time.'=>'— يشغل الجدول %s، والتغيير يعيد بناءه ويمنع الكتابة فيه خلال ذلك، لذا لا يُنفَّذ من هنا. يمكن لمزوّد الاستضافة القيام بذلك في وقت هادئ.','The table is rebuilt and writes to it wait until it finishes, usually a few seconds. Continue?'=>'يُعاد بناء الجدول وتنتظر عمليات الكتابة حتى ينتهي، عادةً بضع ثوانٍ. هل تريد المتابعة؟','Fix'=>'إصلاح','Its row with id 0 moves to the next free id first; nothing refers to it.'=>'يُنقل أولًا صفّه ذو المعرّف 0 إلى أول معرّف متاح؛ لا شيء يشير إليه.','the table no longer needs it, or is not a WordPress table of this site'=>'لم يعد الجدول بحاجة إلى ذلك أو ليس جدول ووردبريس لهذا الموقع','it cannot be fixed from here; follow the instructions in the notice'=>'لا يمكن إصلاحه من هنا؛ اتبع التعليمات في الإشعار','the database accepted the change but the column still has no AUTO_INCREMENT'=>'قبلت قاعدة البيانات التغيير، لكن العمود ما زال بلا AUTO_INCREMENT','rejected by the database'=>'رفضته قاعدة البيانات','the server stopped the rebuild before it finished; the table was left as it was'=>'أوقف الخادم إعادة البناء قبل انتهائها؛ بقي الجدول كما كان','the table no longer exists'=>'لم يعد الجدول موجودًا','nothing worth recovering any more; skipped'=>'لم يعد فيه ما يستحق الاسترداد؛ تم تخطيه','only InnoDB tables are rebuilt in the background, because others would be locked meanwhile'=>'لا يُعاد بناء إلا جداول InnoDB في الخلفية، لأن غيرها سيُقفل خلال ذلك','%1$d large table had almost no free space to recover and was skipped: %2$s.' . "\0" . '%1$d large tables had almost no free space to recover and were skipped: %2$s.'=>'%1$d جدول كبير كاد لا يحتوي مساحة فارغة للاسترداد وتم تخطيه: %2$s.' . "\0" . 'جدول كبير واحد (%1$d) كاد لا يحتوي مساحة فارغة للاسترداد وتم تخطيه: %2$s.' . "\0" . 'جدولان كبيران (%1$d) كادا لا يحتويان مساحة فارغة للاسترداد وتم تخطيهما: %2$s.' . "\0" . '%1$d جداول كبيرة كادت لا تحتوي مساحة فارغة للاسترداد وتم تخطيها: %2$s.' . "\0" . '%1$d جدولًا كبيرًا كاد لا يحتوي مساحة فارغة للاسترداد وتم تخطيه: %2$s.' . "\0" . '%1$d جدول كبير كاد لا يحتوي مساحة فارغة للاسترداد وتم تخطيه: %2$s.','%1$d large table will be rebuilt in the background, one at a time and without stopping the site: %2$s. You can leave this page.' . "\0" . '%1$d large tables will be rebuilt in the background, one at a time and without stopping the site: %2$s. You can leave this page.'=>'سيُعاد بناء %1$d جدول كبير في الخلفية، واحدًا تلو الآخر ودون إيقاف الموقع: %2$s. يمكنك مغادرة هذه الصفحة.' . "\0" . 'سيُعاد بناء جدول كبير واحد (%1$d) في الخلفية، دون إيقاف الموقع: %2$s. يمكنك مغادرة هذه الصفحة.' . "\0" . 'سيُعاد بناء جدولين كبيرين (%1$d) في الخلفية، واحدًا تلو الآخر ودون إيقاف الموقع: %2$s. يمكنك مغادرة هذه الصفحة.' . "\0" . 'سيُعاد بناء %1$d جداول كبيرة في الخلفية، واحدًا تلو الآخر ودون إيقاف الموقع: %2$s. يمكنك مغادرة هذه الصفحة.' . "\0" . 'سيُعاد بناء %1$d جدولًا كبيرًا في الخلفية، واحدًا تلو الآخر ودون إيقاف الموقع: %2$s. يمكنك مغادرة هذه الصفحة.' . "\0" . 'سيُعاد بناء %1$d جدول كبير في الخلفية، واحدًا تلو الآخر ودون إيقاف الموقع: %2$s. يمكنك مغادرة هذه الصفحة.','%1$s is being rebuilt in the background (started %2$s ago). The site keeps working meanwhile.'=>'يُعاد بناء %1$s في الخلفية (بدأ منذ %2$s). يستمر الموقع في العمل خلال ذلك.','Waiting to be rebuilt: %s.'=>'بانتظار إعادة البناء: %s.','%1$s was not rebuilt: %2$s.'=>'لم يُعَد بناء %1$s: %2$s.','%1$s rebuilt: %2$s recovered.'=>'أُعيد بناء %1$s: استُرد %2$s.','Large tables rebuilt in the background'=>'جداول كبيرة أُعيد بناؤها في الخلفية','A page cache you no longer use left things behind'=>'تركت ذاكرة تخزين مؤقت للصفحات لم تعد تستخدمها بقايا خلفها','Rules from %s in .htaccess, which keep serving old pages before WordPress runs.'=>'قواعد من %s في ملف .htaccess، لا تزال تقدّم صفحات قديمة قبل أن يعمل ووردبريس.','wp-content/advanced-cache.php from %s, which is no longer active but still loads on every visit.'=>'الملف wp-content/advanced-cache.php من %s، الذي لم يعد نشطًا لكنه لا يزال يُحمَّل في كل زيارة.','wp-content/advanced-cache.php from a plugin that is no longer active, which still loads on every visit.'=>'الملف wp-content/advanced-cache.php من إضافة لم تعد نشطة، ولا يزال يُحمَّل في كل زيارة.','A second WP_CACHE line in wp-config.php, which makes PHP warn on every visit.'=>'سطر WP_CACHE ثانٍ في wp-config.php، يجعل PHP يُظهر تحذيرًا في كل زيارة.','Each file is copied to Backups before it is changed, so this can be undone.'=>'يُنسخ كل ملف إلى النسخ الاحتياطية قبل تغييره، لذا يمكن التراجع عن ذلك.','Remove what was left behind'=>'إزالة البقايا','You do not have permission to change these files.'=>'ليست لديك صلاحية تغيير هذه الملفات.','Removed what the old page cache left behind. The previous files are in Backups.'=>'تمت إزالة بقايا ذاكرة التخزين المؤقت للصفحات السابقة. الملفات السابقة موجودة في النسخ الاحتياطية.','Some of it could not be removed: the file is not writable or could not be backed up first, so it was left as it was.'=>'تعذّرت إزالة جزء منها: الملف غير قابل للكتابة أو تعذّر نسخه احتياطيًا أولًا، لذا تُرك كما كان.','Your hosting already keeps a copy of every page (%s), and WPOptimizing cannot clear it. A second page cache would leave visitors seeing old pages after each change, so it was not enabled. The object cache and the other speed-ups still work alongside it.'=>'تحتفظ استضافتك بالفعل بنسخة من كل صفحة (%s)، ولا يستطيع WPOptimizing مسحها. ذاكرة تخزين مؤقت ثانية للصفحات ستجعل الزوار يرون صفحات قديمة بعد كل تغيير، لذلك لم تُفعَّل. تستمر ذاكرة التخزين المؤقت للكائنات وتحسينات السرعة الأخرى في العمل إلى جانبها.','%s replaced WPOptimizing\'s page cache file, so pages are now cached by it. WPOptimizing\'s page cache has been switched off so the two do not get in each other\'s way.'=>'استبدلت %s ملف ذاكرة التخزين المؤقت للصفحات الخاص بـ WPOptimizing، لذا أصبحت هي التي تخزّن الصفحات الآن. تم إيقاف ذاكرة التخزين المؤقت للصفحات في WPOptimizing حتى لا تتعارضا.','%1$s: these patterns use regular expressions, which WPOptimizing does not read, so they were not imported. Add them again as plain text: %2$s'=>'%1$s: تستخدم هذه الأنماط تعابير نمطية لا يقرؤها WPOptimizing، لذلك لم تُستورد. أضفها مرة أخرى كنص عادي: %2$s','Page lifetime: the other plugin kept pages for longer than 12 hours (or for ever). Forms and «add to cart» buttons stop working on pages that old, so it was set to 10 hours.'=>'مدة صلاحية الصفحات: كانت الإضافة الأخرى تحتفظ بالصفحات أكثر من 12 ساعة (أو إلى الأبد). تتوقف النماذج وأزرار «أضف إلى السلة» عن العمل في الصفحات بهذا القِدم، لذلك ضُبطت على 10 ساعات.','Cache lifespan'=>'مدة صلاحية التخزين المؤقت','Never cache URL(s)'=>'عدم تخزين عناوين URL مؤقتًا أبدًا','Never cache cookies'=>'عدم التخزين المؤقت أبدًا مع ملفات تعريف الارتباط هذه','Cache query string(s)'=>'تخزين سلاسل الاستعلام مؤقتًا','Separate cache files for mobile devices'=>'ملفات تخزين مؤقت منفصلة للأجهزة المحمولة','Activate preloading'=>'تفعيل التحميل المسبق','Enable caching for logged-in WordPress users: WPOptimizing never serves cached pages to logged-in users.'=>'تفعيل التخزين المؤقت للمستخدمين المسجّلين: لا يقدّم WPOptimizing أبدًا صفحات مخزنة مؤقتًا للمستخدمين المسجّلين.','Never cache user agent(s): not imported; WPOptimizing keeps its own fixed list.'=>'عدم التخزين المؤقت أبدًا لوكلاء المستخدم هؤلاء: لم يُستورد؛ يحتفظ WPOptimizing بقائمته الثابتة الخاصة.','Always purge URL(s): not imported; WPOptimizing purges the pages a change affects on its own.'=>'تفريغ عناوين URL هذه دائمًا: لم يُستورد؛ يفرّغ WPOptimizing بنفسه الصفحات التي يؤثر فيها كل تغيير.','Minify CSS files'=>'تصغير ملفات CSS','Minify JavaScript files'=>'تصغير ملفات JavaScript','Excluded CSS and JavaScript files'=>'ملفات CSS وJavaScript المستثناة','Load JavaScript deferred'=>'تحميل JavaScript مؤجَّلًا','Excluded JavaScript files (deferred)'=>'ملفات JavaScript المستثناة (مؤجَّلة)','Load CSS asynchronously'=>'تحميل CSS بشكل غير متزامن','Fallback critical CSS'=>'CSS حرج احتياطي','Delay JavaScript execution'=>'تأخير تنفيذ JavaScript','Excluded JavaScript files (delayed)'=>'ملفات JavaScript المستثناة (مؤخَّرة)','Combine JavaScript files: not imported. Combining files makes HTTP/2 sites slower and breaks scripts, so WPOptimizing does not do it.'=>'دمج ملفات JavaScript: لم يُستورد. يُبطئ دمج الملفات المواقع التي تعمل بـ HTTP/2 ويعطّل السكربتات، لذلك لا يقوم به WPOptimizing.','Remove Unused CSS: WP Rocket\'s own online service, not imported. WPOptimizing generates critical CSS on your server instead.'=>'إزالة CSS غير المستخدم: خدمة إلكترونية خاصة بـ WP Rocket، لم تُستورد. يُنشئ WPOptimizing بدلًا من ذلك CSS الحرج على خادمك.','LazyLoad for images and iframes'=>'التحميل الكسول للصور وإطارات iframe','Replace YouTube iframe with preview image'=>'استبدال إطار YouTube بصورة معاينة','Self-host Google Fonts'=>'استضافة خطوط Google ذاتيًا','Preload fonts'=>'التحميل المسبق للخطوط','Prefetch DNS requests'=>'الجلب المسبق لطلبات DNS','Prefetch DNS requests: WPOptimizing finds the hosts to connect to early on its own, so the list itself was not copied.'=>'الجلب المسبق لطلبات DNS: يحدد WPOptimizing بنفسه الخوادم التي يتصل بها مبكرًا، لذلك لم تُنسخ القائمة.','Excluded images or iframes (LazyLoad): not imported.'=>'الصور أو إطارات iframe المستثناة (التحميل الكسول): لم تُستورد.','Disable WordPress emoji'=>'تعطيل رموز WordPress التعبيرية','Enable Content Delivery Network'=>'تفعيل شبكة توصيل المحتوى (CDN)','CDN CNAME(s)'=>'أسماء CNAME لشبكة CDN','CDN CNAME(s): WPOptimizing uses one CDN host, so only the first one was imported.'=>'أسماء CNAME لشبكة CDN: يستخدم WPOptimizing خادم CDN واحدًا، لذلك استُورد الأول فقط.','Auto drafts'=>'المسودات التلقائية','Spam comments'=>'تعليقات مزعجة','Trashed comments'=>'التعليقات في سلة المهملات','All transients'=>'جميع البيانات المؤقتة','Revisions: WP Rocket deletes all of them; WPOptimizing keeps the last two of each post, which you can change in General cleanup.'=>'المراجعات: يحذفها WP Rocket كلها؛ يحتفظ WPOptimizing بآخر مراجعتين لكل مقالة، ويمكنك تغيير ذلك في التنظيف العام.','Schedule automatic cleanup'=>'جدولة التنظيف التلقائي','Control Heartbeat'=>'التحكم في Heartbeat','Cloudflare: WP Rocket uses your account\'s Global API Key, which WPOptimizing does not copy. Connect Cloudflare in Cache › Cloudflare with an API token.'=>'Cloudflare: يستخدم WP Rocket مفتاح Global API Key الخاص بحسابك، ولا ينسخه WPOptimizing. اربط Cloudflare من التخزين المؤقت › Cloudflare باستخدام رمز API.','Varnish: switch on its purge in Cache › Browser & server once WPOptimizing has checked that Varnish is in front of the site.'=>'Varnish: فعّل التفريغ من التخزين المؤقت › المتصفح والخادم بعد أن يتحقق WPOptimizing من أن Varnish يقع أمام الموقع.','Import from another plugin'=>'الاستيراد من إضافة أخرى','Moving from another cache or performance plugin? WPOptimizing reads the settings it left on this site, even if it is deactivated, and brings over what has an equivalent here. Passwords, licence and API keys are never copied, and nothing that changes files (the page cache, the object cache) is switched on by an import.'=>'هل تنتقل من إضافة أخرى للتخزين المؤقت أو الأداء؟ يقرأ WPOptimizing الإعدادات التي تركتها على هذا الموقع، حتى لو كانت معطّلة، وينقل ما له مقابل هنا. لا تُنسخ أبدًا كلمات المرور ولا التراخيص ولا مفاتيح API، ولا يفعّل الاستيراد أي شيء يغيّر الملفات (التخزين المؤقت للصفحات أو للكائنات).','On'=>'مفعّل','No settings from another cache or performance plugin were found on this site.'=>'لم يُعثر على هذا الموقع على إعدادات إضافة أخرى للتخزين المؤقت أو الأداء.','Its settings have nothing WPOptimizing can bring over.'=>'لا تحتوي إعداداته على أي شيء يمكن لـ WPOptimizing نقله.','Import from %s'=>'الاستيراد من %s','Undo the import from %1$s (%2$s)'=>'التراجع عن الاستيراد من %1$s (%2$s)','The settings are back to how they were before the import.'=>'عادت الإعدادات إلى ما كانت عليه قبل الاستيراد.','There is no import to undo.'=>'لا يوجد استيراد للتراجع عنه.','That plugin cannot be imported from.'=>'لا يمكن الاستيراد من هذه الإضافة.','Nothing was imported: none of its settings could be brought over.'=>'لم يُستورد أي شيء: تعذّر نقل أي من إعداداته.','Settings imported from %s. Check the pages they belong to, and switch the page cache or the object cache on yourself when the other plugin is deactivated. You can undo the import below.'=>'استُوردت الإعدادات من %s. راجع الشاشات التي تنتمي إليها، وفعّل بنفسك التخزين المؤقت للصفحات أو للكائنات بعد تعطيل الإضافة الأخرى. يمكنك التراجع عن الاستيراد أدناه.','%d setting would be imported' . "\0" . '%d settings would be imported'=>'لن يُستورد أي إعداد (%d)' . "\0" . 'سيُستورد إعداد واحد (%d)' . "\0" . 'سيُستورد إعدادان (%d)' . "\0" . 'ستُستورد %d إعدادات' . "\0" . 'سيُستورد %d إعدادًا' . "\0" . 'سيُستورد %d إعداد','Purge this page'=>'تفريغ هذه الصفحة','Delete the cached copy of this page here, at Cloudflare and in Varnish'=>'يحذف النسخة المخزنة مؤقتًا من هذه الصفحة هنا وفي Cloudflare وVarnish','Also ignore these tracking parameters (the page is cached as if they were not there)'=>'تجاهل معلمات التتبع هذه أيضًا (تُخزَّن الصفحة مؤقتًا كأنها غير موجودة)','parameter name, e.g. ref'=>'اسم المعلمة، مثل ref','Never cache for these browsers or bots'=>'عدم استخدام التخزين المؤقت أبدًا لهذه المتصفحات أو الروبوتات','part of the user agent, e.g. Lighthouse'=>'جزء من وكيل المستخدم، مثل Lighthouse','Serve without PHP'=>'التقديم دون PHP','The web server answers from the cached file directly, without starting PHP: faster pages and far more visitors at once on the same server. Only pages that need nothing from PHP are served this way (no separate mobile copy, currency, query string or security headers sent from PHP); the rest keep going through PHP as now.'=>'يجيب خادم الويب مباشرةً من الملف المخزّن مؤقتًا دون تشغيل PHP: صفحات أسرع وعدد أكبر بكثير من الزوار في الوقت نفسه على الخادم نفسه. لا تُقدَّم بهذه الطريقة إلا الصفحات التي لا تحتاج إلى شيء من PHP (من دون نسخة منفصلة للجوال أو عملة أو سلسلة استعلام أو ترويسات أمان يرسلها PHP)؛ وتستمر بقية الصفحات بالمرور عبر PHP كما الآن.','Serve cached pages straight from the web server (adds rules to .htaccess, backed up first)'=>'تقديم الصفحات المخزنة مؤقتًا مباشرةً من خادم الويب (يضيف قواعد إلى .htaccess مع نسخة احتياطية مسبقة)','This server does not read .htaccess (it is probably Nginx), so WordPress cannot add the rules itself. Whoever manages the server can add these lines to the site\'s configuration:'=>'لا يقرأ هذا الخادم ملف .htaccess (غالبًا هو Nginx)، لذا لا يستطيع ووردبريس إضافة القواعد بنفسه. يمكن لمن يدير الخادم إضافة هذه الأسطر إلى إعدادات الموقع:','Never cache user agent(s)'=>'عدم التخزين المؤقت أبدًا لوكلاء المستخدم هؤلاء','URLs to exclude from caching'=>'عناوين URL المستثناة من التخزين المؤقت','Cookies which, if present, will prevent caching'=>'ملفات تعريف الارتباط التي تمنع التخزين المؤقت عند وجودها','Generate separate files for mobile devices'=>'إنشاء ملفات منفصلة للأجهزة المحمولة','Automatically preload content after it is purged'=>'التحميل المسبق للمحتوى تلقائيًا بعد مسحه','%s: WPOptimizing never serves cached pages to logged-in users.'=>'%s: لا يقدّم WPOptimizing أبدًا صفحات مخزنة مؤقتًا للمستخدمين المسجلين دخولهم.','Serve cached pages to logged in users'=>'تقديم الصفحات المخزنة مؤقتًا للمستخدمين المسجلين','List of browser agent strings which, if detected, will prevent caching'=>'قائمة سلاسل وكيل المتصفح التي تمنع التخزين المؤقت عند اكتشافها','Ignore these query variables when caching'=>'تجاهل متغيرات الاستعلام هذه عند التخزين المؤقت','%s: not imported.'=>'%s: لم يُستورد.','Conditional tags to exclude from caching'=>'الوسوم الشرطية المستثناة من التخزين المؤقت','Cache Specific URLs Only'=>'تخزين عناوين URL محددة فقط مؤقتًا','Cloudflare: the credentials %s keeps are not copied. Connect Cloudflare in Cache › Cloudflare with an API token.'=>'Cloudflare: لا تُنسخ بيانات الاعتماد التي يحتفظ بها %s. اربط Cloudflare من التخزين المؤقت › Cloudflare باستخدام رمز API.','Enable minification of CSS files'=>'تفعيل تصغير ملفات CSS','Enable minification of JavaScript files'=>'تفعيل تصغير ملفات JavaScript','Exclude JavaScript from processing'=>'استثناء JavaScript من المعالجة','Defer all the JavaScript files'=>'تأجيل جميع ملفات JavaScript','%s: WPOptimizing defers every script except the ones you exclude, not a chosen few, so this list was not imported.'=>'%s: يؤجّل WPOptimizing كل السكربتات باستثناء ما تستثنيه، وليس بعضها المختار، لذا لم تُستورد هذه القائمة.','Asynchronously load selected JavaScript files'=>'تحميل ملفات JavaScript المحددة بشكل غير متزامن','Load all CSS files asynchronously'=>'تحميل جميع ملفات CSS بشكل غير متزامن','Fallback CSS'=>'CSS احتياطي','Delay JS'=>'تأخير JS','Remove default WordPress and TinyMCE icons'=>'إزالة أيقونات WordPress وTinyMCE الافتراضية','Host Google Fonts locally'=>'استضافة خطوط Google محليًا','Preconnect Headers'=>'ترويسات الاتصال المسبق','%s: WPOptimizing finds the hosts to connect to early on its own, so the list itself was not copied.'=>'%s: يحدّد WPOptimizing بنفسه الخوادم التي يتصل بها مبكرًا، لذلك لم تُنسخ القائمة نفسها.','Enable merging of CSS files'=>'تفعيل دمج ملفات CSS','Enable merging of JavaScript files'=>'تفعيل دمج ملفات JavaScript','%s: not imported. Combining files makes HTTP/2 sites slower and breaks scripts, so WPOptimizing does not do it.'=>'%s: لم يُستورد. دمج الملفات يبطئ المواقع التي تعمل بـ HTTP/2 ويعطّل السكربتات، لذلك لا يفعله WPOptimizing.','%s: not imported; WPOptimizing does not minify HTML.'=>'%s: لم يُستورد؛ لا يصغّر WPOptimizing شيفرة HTML.','Process HTML'=>'معالجة HTML','%s: not imported. WPOptimizing generates critical CSS on your server instead.'=>'%s: لم يُستورد. يولّد WPOptimizing بدلًا من ذلك CSS الحرج على خادمك.','Enable removal of unused rules from CSS files (Experimental)'=>'تفعيل إزالة القواعد غير المستخدمة من ملفات CSS (تجريبي)','%s: not imported. It only applied to the files the other plugin optimized, while WPOptimizing\'s CDN rewrites every static file; set it up yourself if your CDN serves them all.'=>'%s: لم يُستورد. كان يُطبَّق فقط على الملفات التي حسّنتها الإضافة الأخرى، بينما تعيد شبكة CDN في WPOptimizing كتابة كل الملفات الثابتة؛ اضبطها بنفسك إن كانت شبكتك تقدّمها كلها.','Your CDN domain'=>'نطاق CDN الخاص بك','Lazy-load images'=>'التحميل الكسول للصور','Replace YouTube iframe with thumbnail image'=>'استبدال إطار YouTube بصورة مصغّرة','Skip image classes'=>'فئات الصور المتجاوزة','Clean all auto-draft posts'=>'تنظيف كل المسودات التلقائية','Clean all trashed posts'=>'تنظيف كل المقالات المحذوفة إلى سلة المهملات','Remove spam and trashed comments'=>'إزالة التعليقات المزعجة والمحذوفة','Remove pingbacks'=>'إزالة الإشعارات (Pingbacks)','Remove trackbacks'=>'إزالة التعقيبات (Trackbacks)','Remove expired transient options'=>'إزالة الخيارات المؤقتة المنتهية','Clean post metadata'=>'تنظيف بيانات تعريف المقالات','Revisions: %s deletes all of them; WPOptimizing keeps the last two of each post, which you can change in General cleanup.'=>'المراجعات: يحذفها %s كلها؛ يحتفظ WPOptimizing بآخر مراجعتين لكل مقالة، ويمكنك تغيير ذلك في التنظيف العام.','Enable scheduled clean-up and optimization'=>'تفعيل التنظيف والتحسين المجدولين','%s: WPOptimizing has no fortnightly schedule, so it was set to weekly.'=>'%s: لا يملك WPOptimizing جدولة كل أسبوعين، لذا ضُبطت على أسبوعية.','Select schedule type (default is Weekly)'=>'اختر نوع الجدولة (الافتراضي أسبوعي)','%s: not imported. Set the minimum age of what is cleaned in General cleanup.'=>'%s: لم يُستورد. اضبط الحد الأدنى لعمر ما يُنظَّف في التنظيف العام.','Keep last X weeks data'=>'الاحتفاظ ببيانات آخر X أسابيع','Cache Lifespan'=>'مدة صلاحية التخزين المؤقت','Gzip Compression'=>'ضغط Gzip','Separate Mobile Cache'=>'تخزين مؤقت منفصل للجوال','Cache Preload'=>'التحميل المسبق للتخزين المؤقت','Never Cache URLs'=>'عناوين URL التي لا تُخزَّن مؤقتًا أبدًا','Rejected Cookies'=>'ملفات تعريف الارتباط المرفوضة','Rejected User Agents'=>'وكلاء المستخدم المرفوضون','Ignored Query Strings'=>'سلاسل الاستعلام المتجاهلة','Cache Query Strings'=>'تخزين سلاسل الاستعلام مؤقتًا','Logged-in User Cache'=>'التخزين المؤقت للمستخدمين المسجلين','Rejected Referrers'=>'المُحيلون المرفوضون','Vary Cookies'=>'ملفات تعريف الارتباط المتغيرة','Purge Additional Pages'=>'مسح صفحات إضافية','Object Cache: not imported. Set up the object cache in WPOptimizing once Powered Cache is deactivated, because both use the same drop-in file.'=>'التخزين المؤقت للكائنات: لم يُستورد. اضبطه في WPOptimizing بعد تعطيل Powered Cache، لأن كليهما يستخدم ملف drop-in نفسه.','Excluded CSS Files'=>'ملفات CSS المستثناة','Excluded JavaScript Files'=>'ملفات JavaScript المستثناة','Defer JavaScript'=>'تأجيل JavaScript','Defer JavaScript Exclusions'=>'استثناءات تأجيل JavaScript','Delay JavaScript Exclusions'=>'استثناءات تأخير JavaScript','Delay Timeout'=>'مهلة التأخير','Fallback Critical CSS'=>'CSS حرج احتياطي','Combine CSS'=>'دمج CSS','Combine JavaScript'=>'دمج JavaScript','Minify HTML'=>'تصغير HTML','Remove Unused CSS'=>'إزالة CSS غير المستخدم','Lazy Load'=>'التحميل الكسول','YouTube Embeds'=>'تضمينات YouTube','Lazy Load Exclusions'=>'استثناءات التحميل الكسول','Emoji Scripts'=>'سكربتات الرموز التعبيرية','WordPress Embeds'=>'تضمينات WordPress','Preload Fonts'=>'التحميل المسبق للخطوط','Preconnect'=>'الاتصال المسبق','DNS Prefetch'=>'الجلب المسبق لـ DNS','CDN Delivery'=>'التسليم عبر CDN','CDN Hostnames'=>'أسماء مضيفي CDN','CDN Hostnames: WPOptimizing uses one CDN host for every static file, so only the first one was imported, without its zone or excluded files.'=>'أسماء مضيفي CDN: يستخدم WPOptimizing مضيف CDN واحدًا لكل الملفات الثابتة، لذا استُورد الأول فقط، دون منطقته أو ملفاته المستثناة.','Auto Drafts'=>'المسودات التلقائية','Trashed Posts'=>'المقالات في سلة المهملات','Spam Comments'=>'التعليقات المزعجة','Trashed Comments'=>'التعليقات في سلة المهملات','Expired Transients'=>'المؤقتات المنتهية','All Transients'=>'كل المؤقتات','Optimize Tables'=>'تحسين الجداول','Database Cleanup Frequency'=>'تكرار تنظيف قاعدة البيانات','Heartbeat Control'=>'التحكم في Heartbeat','Clear cache at set intervals'=>'مسح التخزين المؤقت على فترات محددة','Serve compressed cached files'=>'تقديم ملفات التخزين المؤقت المضغوطة','Preload cache'=>'التحميل المسبق للتخزين المؤقت','Exclude URL strings'=>'استثناء سلاسل URL','Exclude cookies'=>'استثناء ملفات تعريف الارتباط','Exclude user agent'=>'استثناء وكيل المستخدم','Cache for logged-in users'=>'التخزين المؤقت للمستخدمين المسجلين','Cache URL queries'=>'تخزين عناوين URL ذات الاستعلامات مؤقتًا','Cache 404 requests'=>'تخزين طلبات 404 مؤقتًا','Compress assets'=>'ضغط الموارد','Combine & Compress'=>'الدمج والضغط','Defer'=>'تأجيل','Delay JavaScript exclusions'=>'استثناءات تأخير JavaScript','Delay JavaScript post type exclusions'=>'استثناءات تأخير JavaScript حسب نوع المحتوى','Delay JavaScript URL exclusions'=>'استثناءات تأخير JavaScript حسب URL','Delay JavaScript plugin and theme exclusions'=>'استثناءات تأخير JavaScript للإضافات والقوالب','Delay JavaScript ad and tracker exclusions'=>'استثناءات تأخير JavaScript للإعلانات وأدوات التتبع','%s: generated by an online service, not imported. WPOptimizing generates critical CSS on your server instead.'=>'%s: تولّده خدمة عبر الإنترنت، ولم يُستورد. يولّد WPOptimizing بدلًا من ذلك CSS الحرج على خادمك.','Font Optimization'=>'تحسين الخطوط','Remove default emoji files'=>'إزالة ملفات الرموز التعبيرية الافتراضية','Disable WooCommerce cart fragments'=>'تعطيل أجزاء سلة WooCommerce','Disable WooCommerce cart fragments: Hummingbird removed them by type of page; WPOptimizing loads them only for visitors with something in the cart.'=>'تعطيل أجزاء سلة WooCommerce: كان Hummingbird يزيلها حسب نوع الصفحة؛ ويحمّلها WPOptimizing فقط للزوار الذين في سلتهم شيء.','DNS prefetch'=>'الجلب المسبق لـ DNS','%s: not imported. Removing the version from file URLs does not make pages faster and can serve outdated files after an update.'=>'%s: لم يُستورد. إزالة الإصدار من عناوين الملفات لا تسرّع الصفحات وقد تقدّم ملفات قديمة بعد التحديث.','Remove URL query strings'=>'إزالة سلاسل الاستعلام من عناوين URL','%s: Hummingbird limits how many revisions WordPress keeps; WPOptimizing cleans old ones instead, keeping the last two of each post, which you can change in General cleanup.'=>'%s: يحدّ Hummingbird عدد المراجعات التي يحتفظ بها WordPress؛ أما WPOptimizing فينظّف القديمة مع الاحتفاظ بآخر مراجعتين لكل مقالة، ويمكنك تغيير ذلك في التنظيف العام.','Gravatar Caching'=>'التخزين المؤقت لـ Gravatar','%s: WPMU DEV\'s own CDN, not imported.'=>'%s: شبكة CDN الخاصة بـ WPMU DEV، لم تُستورد.','Optimize JavaScript Code?'=>'تحسين شيفرة JavaScript؟','Aggregate JS-files?'=>'تجميع ملفات JS؟','Do not aggregate but defer?'=>'عدم التجميع مع التأجيل؟','Exclude scripts from Autoptimize:'=>'استثناء السكربتات من Autoptimize:','Optimize CSS Code?'=>'تحسين شيفرة CSS؟','Aggregate CSS-files?'=>'تجميع ملفات CSS؟','Eliminate render-blocking CSS?'=>'إزالة CSS المعيق للعرض؟','Inline all CSS?'=>'تضمين كل CSS داخل الصفحة؟','Exclude CSS from Autoptimize:'=>'استثناء CSS من Autoptimize:','Optimize HTML Code?'=>'تحسين شيفرة HTML؟','CDN Base URL'=>'عنوان URL الأساسي لـ CDN','Remove emojis'=>'إزالة الرموز التعبيرية','Preload specific requests (advanced users)'=>'التحميل المسبق لطلبات محددة (للمستخدمين المتقدمين)','Preconnect to 3rd party domains (advanced users)'=>'الاتصال المسبق بنطاقات خارجية (للمستخدمين المتقدمين)','Google Fonts: not imported. Autoptimize removed or combined them; WPOptimizing can host them on your server instead (Self-host Google Fonts), which you can switch on yourself.'=>'Google Fonts: لم يُستورد. كان Autoptimize يزيلها أو يدمجها؛ ويمكن لـ WPOptimizing استضافتها على خادمك بدلًا من ذلك (استضافة خطوط Google ذاتيًا)، ويمكنك تفعيل ذلك بنفسك.','Remove query strings from static resources'=>'إزالة سلاسل الاستعلام من الموارد الثابتة','Async Javascript-files (advanced users)'=>'ملفات JavaScript غير المتزامنة (للمستخدمين المتقدمين)','Remove WordPress block CSS'=>'إزالة CSS مكونات WordPress','Lazy-load images?'=>'التحميل الكسول للصور؟','Lazy-load exclusions'=>'استثناءات التحميل الكسول','Image optimization & CDN: ShortPixel\'s online service, not imported. WPOptimizing optimizes images on your server.'=>'تحسين الصور وCDN: خدمة ShortPixel عبر الإنترنت، لم تُستورد. يحسّن WPOptimizing الصور على خادمك.','%1$s: these patterns use wildcards or regular expressions in the middle, which WPOptimizing does not read, so they were not imported. Add them again as plain text: %2$s'=>'%1$s: تحتوي هذه الأنماط على أحرف بدل أو تعابير نمطية في وسطها لا يقرؤها WPOptimizing، لذلك لم تُستورد. أضفها مرة أخرى كنص عادي: %2$s','Dynamic Caching: this is SiteGround\'s own server cache and only works on their hosting, so it was not turned into WPOptimizing\'s page cache. If the site is hosted at SiteGround, keep it on in their Site Tools.'=>'Dynamic Caching: هذه ذاكرة التخزين المؤقت الخاصة بخادم SiteGround ولا تعمل إلا على استضافتها، لذلك لم تُحوَّل إلى ذاكرة تخزين الصفحات في WPOptimizing. إذا كان الموقع مستضافًا لدى SiteGround، فأبقِها مفعّلة في Site Tools لديهم.','Memcached: it runs on SiteGround\'s own Memcached service, so it was not turned into WPOptimizing\'s object cache. If the site is hosted at SiteGround, keep it on in their Site Tools.'=>'Memcached: يعمل على خدمة Memcached الخاصة بـ SiteGround، لذلك لم يُحوَّل إلى تخزين الكائنات المؤقت في WPOptimizing. إذا كان الموقع مستضافًا لدى SiteGround، فأبقِه مفعّلًا في Site Tools لديهم.','%s: the import does not switch on WPOptimizing\'s page cache. Deactivate the other plugin first, then switch it on in Cache › Page cache.'=>'%s: الاستيراد لا يفعّل ذاكرة تخزين الصفحات في WPOptimizing. عطّل الإضافة الأخرى أولًا، ثم فعّلها من التخزين المؤقت › ذاكرة تخزين الصفحات.','File-Based Caching'=>'التخزين المؤقت المعتمد على الملفات','Scheduled cache cleanup'=>'تنظيف ذاكرة التخزين المؤقت المجدول','Browser-Specific Caching'=>'تخزين مؤقت خاص بكل متصفح','Preheat Cache'=>'تسخين ذاكرة التخزين المؤقت مسبقًا','Exclude URLs from Caching'=>'استثناء عناوين URL من التخزين المؤقت','%s: not imported; WPOptimizing never serves cached pages to logged-in users.'=>'%s: لم يُستورد؛ لا يقدّم WPOptimizing أبدًا صفحات مخزنة مؤقتًا للمستخدمين المسجّلين.','Logged-in Users Cache'=>'تخزين مؤقت للمستخدمين المسجّلين','%s: not imported. Switch on the browser cache and compression in Cache › Browser & server once the other plugin is deactivated, because deactivating it can remove those rules from .htaccess.'=>'%s: لم يُستورد. فعّل ذاكرة التخزين المؤقت للمتصفح والضغط من التخزين المؤقت › المتصفح والخادم بعد تعطيل الإضافة الأخرى، لأن تعطيلها قد يزيل تلك القواعد من .htaccess.','GZIP Compression, Browser Caching'=>'ضغط GZIP، التخزين المؤقت للمتصفح','Minify CSS Files'=>'تصغير ملفات CSS','Minify JavaScript Files'=>'تصغير ملفات JavaScript','Exclude from CSS and JavaScript Minification'=>'استثناء من تصغير CSS وJavaScript','Defer Render-blocking JS'=>'تأجيل JS المعيق للعرض','Exclude from Loading JS Files Asynchronously'=>'استثناء من تحميل ملفات JS بشكل غير متزامن','Combine CSS Files'=>'دمج ملفات CSS','Combine JavaScript Files'=>'دمج ملفات JavaScript','Minify the HTML Output'=>'تصغير مخرجات HTML','Remove Query Strings From Static Resources'=>'إزالة سلاسل الاستعلام من الموارد الثابتة','Exclude Post Types'=>'استثناء أنواع المحتوى','Disable Emojis'=>'تعطيل الرموز التعبيرية','Lazy Load Media'=>'التحميل الكسول للوسائط','%s: not imported; WPOptimizing\'s lazy loading has no exclusion list.'=>'%s: لم يُستورد؛ لا توجد قائمة استثناءات للتحميل الكسول في WPOptimizing.','Exclude from Lazy Load'=>'استثناء من التحميل الكسول','Generate WebP Copies of New Images'=>'إنشاء نسخ WebP من الصور الجديدة','Maximum Image Width'=>'أقصى عرض للصورة','Web Fonts Optimization'=>'تحسين خطوط الويب','Fonts Preloading'=>'التحميل المسبق للخطوط','DNS Pre-fetch for External Domains'=>'الجلب المسبق لـ DNS للنطاقات الخارجية','Scheduled Database Maintenance'=>'صيانة قاعدة البيانات المجدولة','%s: the other plugin deletes every revision; WPOptimizing keeps the last ones of each post, as set in General cleanup.'=>'%s: تحذف الإضافة الأخرى كل المراجعات؛ أما WPOptimizing فيحتفظ بآخرها لكل مقالة، حسب ما هو محدد في التنظيف العام.','Delete all page and post revisions'=>'حذف كل مراجعات الصفحات والمقالات','WordPress Heartbeat Optimization'=>'تحسين Heartbeat في ووردبريس','%s: the other plugin sets the Heartbeat for each area; WPOptimizing has one setting for the whole site and always keeps it running in the editor, where it saves drafts. Check that the result suits you.'=>'%s: تضبط الإضافة الأخرى Heartbeat لكل منطقة؛ أما WPOptimizing فله إعداد واحد للموقع كله ويبقيه يعمل دائمًا في المحرر حيث يحفظ المسودات. تحقّق من أن النتيجة تناسبك.','No equivalent in WPOptimizing, not imported: %s.'=>'لا مقابل له في WPOptimizing، لم يُستورد: %s.','Disable Dashicons'=>'تعطيل Dashicons','Disable Embeds'=>'تعطيل التضمينات','Remove RSD Link'=>'إزالة رابط RSD','Hide WP Version'=>'إخفاء إصدار ووردبريس','Remove Shortlink'=>'إزالة الرابط المختصر','Disable Self Pingbacks'=>'تعطيل التنبيهات الذاتية','Remove REST API Links'=>'إزالة روابط REST API','Disable Cart Fragmentation'=>'تعطيل أجزاء سلة التسوق','Disable XML-RPC'=>'تعطيل XML-RPC','Disable RSS Feeds'=>'تعطيل خلاصات RSS','Remove RSS Feed Links'=>'إزالة روابط خلاصات RSS','Disable REST API'=>'تعطيل REST API','Disable Google Maps'=>'تعطيل خرائط Google','Disable Password Meter'=>'تعطيل مقياس كلمة المرور','Disable Comments'=>'تعطيل التعليقات','Remove Comment URLs'=>'إزالة عناوين URL من التعليقات','Add Blank Favicon'=>'إضافة أيقونة موقع فارغة','Remove Global Styles'=>'إزالة الأنماط العامة','Separate Block Styles'=>'فصل أنماط المكوّنات','Autosave Interval'=>'فاصل الحفظ التلقائي','Custom Login URL'=>'رابط تسجيل دخول مخصص','Disable Scripts'=>'تعطيل السكربتات','Disable Status Meta Box'=>'تعطيل صندوق الحالة','Disable Widgets'=>'تعطيل الودجات','Heartbeat Frequency'=>'تردد Heartbeat','Limit Post Revisions'=>'تحديد عدد المراجعات','%s: the other plugin stops WordPress from keeping more revisions; WPOptimizing deletes the extra ones each time General cleanup runs.'=>'%s: تمنع الإضافة الأخرى ووردبريس من الاحتفاظ بمزيد من المراجعات؛ أما WPOptimizing فيحذف الزائد منها في كل تشغيل للتنظيف العام.','Defer Javascript'=>'تأجيل JavaScript','Excluded from Deferral'=>'مستثنى من التأجيل','Delay Behavior'=>'سلوك التأخير','Delayed Scripts'=>'السكربتات المؤخَّرة','Excluded from Delay'=>'مستثنى من التأخير','%s: imported with «Test mode: apply only for logged-in administrators» on, because delaying every script can break menus, sliders and carts. Check your key pages, then switch test mode off in Delay JavaScript.'=>'%s: استُورد مع تفعيل «وضع الاختبار: التطبيق على المسؤولين المسجّلين فقط»، لأن تأخير كل السكربتات قد يعطّل القوائم وعروض الشرائح وسلال التسوق. تحقّق من صفحاتك الأساسية، ثم عطّل وضع الاختبار من تأخير JavaScript.','Delay All Scripts'=>'تأخير كل السكربتات','Excluded from Minification'=>'مستثنى من التصغير','%s: not imported. WPOptimizing generates critical CSS on your server instead of removing unused CSS.'=>'%s: لم يُستورد. يولّد WPOptimizing ملف CSS الحرج على خادمك بدلًا من إزالة CSS غير المستخدم.','Add Header Code, Add Body Code, Add Footer Code: code snippets are not imported. If you still need them, move them to your theme or to a code snippets plugin before deactivating Perfmatters.'=>'إضافة شيفرة في الترويسة والجسم والتذييل: لا تُستورد مقتطفات الشيفرة. إذا كنت لا تزال تحتاجها، فانقلها إلى قالبك أو إلى إضافة لمقتطفات الشيفرة قبل تعطيل Perfmatters.','Speculative Loading'=>'التحميل الاستباقي','Enable Instant Page'=>'تفعيل Instant Page','Preconnect, DNS Prefetch'=>'الاتصال المسبق، الجلب المسبق لـ DNS','Lazy Loading: Images, iFrames and Videos'=>'التحميل الكسول: الصور وiframe والفيديو','YouTube Preview Thumbnails'=>'صور معاينة مصغّرة لـ YouTube','Exclude from Lazy Loading'=>'استثناء من التحميل الكسول','Background Images'=>'صور الخلفية','Add Image Dimensions'=>'إضافة أبعاد الصور','Lazy Load Elements'=>'التحميل الكسول للعناصر','Local Google Fonts'=>'خطوط Google محليًا','Enable CDN Rewrite'=>'تفعيل إعادة الكتابة إلى CDN','CDN URL'=>'رابط CDN','Included Directories'=>'المجلدات المضمّنة','Enable Local Analytics'=>'تفعيل التحليلات المحلية','Post Auto-Drafts'=>'المسودات التلقائية','Scheduled Optimization'=>'التحسين المجدول','Post Revisions'=>'المراجعات','Script Manager: its rules are not imported. Use Smart Assets in WPOptimizing to unload files page by page; it tells you which plugin each file belongs to.'=>'Script Manager: لا تُستورد قواعده. استخدم الموارد الذكية في WPOptimizing لإلغاء تحميل الملفات صفحةً بصفحة؛ فهي تخبرك بالإضافة التي ينتمي إليها كل ملف.','Auto-refresh Cache'=>'تحديث ذاكرة التخزين المؤقت تلقائيًا','Separate Mobile Cache & Optimizations'=>'ذاكرة تخزين وتحسينات منفصلة للجوال','Exclude Pages from Cache'=>'استثناء صفحات من التخزين المؤقت','Bypass Cache for Cookies'=>'تجاوز التخزين المؤقت حسب ملفات تعريف الارتباط','Query Strings to Cache'=>'سلاسل الاستعلام المخزنة مؤقتًا','Cache for Logged-in Users by Role'=>'تخزين مؤقت للمستخدمين المسجّلين حسب الدور','Preload Links on Hover'=>'تحميل الروابط مسبقًا عند التمرير','Minify CSS and JavaScript'=>'تصغير CSS وJavaScript','Delay All JavaScript'=>'تأخير كل JavaScript','Delay Specific Scripts on Interaction'=>'تأخير سكربتات محددة حتى التفاعل','Lazy Load Images, Videos, and Iframes'=>'التحميل الكسول للصور والفيديو وiframe','Lightweight YouTube Previews'=>'معاينات YouTube خفيفة','Image optimization: FlyingPress compresses images on its own servers, so it was not imported. WPOptimizing converts images to WebP and AVIF on your server; set it up in Media.'=>'تحسين الصور: يضغط FlyingPress الصور على خوادمه الخاصة، لذلك لم يُستورد. يحوّل WPOptimizing الصور إلى WebP وAVIF على خادمك؛ اضبط ذلك من الوسائط.','Lazy Render Elements'=>'العرض الكسول للعناصر','Properly size images'=>'تحجيم الصور بشكل صحيح','Self-host Gravatar Images'=>'استضافة صور Gravatar محليًا','Self-host third-party CSS and JavaScript'=>'استضافة CSS وJavaScript الخارجية محليًا','Disable Block Editor CSS'=>'تعطيل CSS محرر المكوّنات','Disable RSS Feed'=>'تعطيل خلاصة RSS','Remove Dashicons'=>'إزالة Dashicons','Disable jQuery Migrate'=>'تعطيل jQuery Migrate','Disable oEmbeds'=>'تعطيل oEmbeds','Throttle Heartbeat API'=>'تقليل وتيرة Heartbeat API','Enable CDN'=>'تفعيل CDN','FlyingCDN: FlyingPress\'s own paid CDN, not imported. If you keep it, enter its address as the CDN host in WPOptimizing.'=>'FlyingCDN: شبكة CDN المدفوعة الخاصة بـ FlyingPress، لم تُستورد. إذا أبقيت عليها، فأدخل عنوانها كمضيف CDN في WPOptimizing.','%s: the other plugin connects with your Cloudflare account\'s Global API Key, which WPOptimizing does not copy. Connect Cloudflare in Cache › Cloudflare with an API token.'=>'%s: تتصل الإضافة الأخرى بمفتاح Global API Key لحسابك في Cloudflare، ولا ينسخه WPOptimizing. اربط Cloudflare من التخزين المؤقت › Cloudflare باستخدام رمز API.','Automatic Cleaning'=>'التنظيف التلقائي','Delete Post Revisions'=>'حذف مراجعات المقالات','%s: not switched on by the import. Deactivate the other plugin first, then switch it on in Cache › Object cache.'=>'%s: لا يفعّله الاستيراد. عطّل الإضافة الأخرى أولًا، ثم فعّله من التخزين المؤقت › تخزين الكائنات المؤقت.','Object Cache'=>'تخزين الكائنات المؤقت','Cache System'=>'نظام التخزين المؤقت','Purge Cache After'=>'مسح ذاكرة التخزين المؤقت بعد','Mobile Cache'=>'ذاكرة تخزين الجوال','Never Cache URL(s)'=>'عدم تخزين عناوين URL هذه مؤقتًا أبدًا','Cache Logged-in Users'=>'التخزين المؤقت للمستخدمين المسجّلين','Cache Warmup'=>'تسخين ذاكرة التخزين المؤقت','Cache Warmup: WPOptimizing warms up the home page and your latest content on its own, so the list of URLs was not copied.'=>'تسخين ذاكرة التخزين المؤقت: يسخّن WPOptimizing بنفسه الصفحة الرئيسية وأحدث محتواك، لذلك لم تُنسخ قائمة عناوين URL.','Gzip Compression, Browser Cache'=>'ضغط Gzip، ذاكرة التخزين المؤقت للمتصفح','CSS Minify'=>'تصغير CSS','JS Minify'=>'تصغير JS','Exclude CSS, Exclude JS'=>'استثناء CSS، استثناء JS','Combine JS'=>'دمج JS','JS Files With Deferred Loading: Breeze defers only the files you list, while WPOptimizing defers every script except the ones you exclude, so it was not switched on. Try «Load JavaScript deferred» in WPOptimizing and check the site.'=>'ملفات JS ذات التحميل المؤجَّل: يؤجّل Breeze الملفات التي تحددها فقط، بينما يؤجّل WPOptimizing كل السكربتات ما عدا المستثناة، لذلك لم يُفعَّل. جرّب «تحميل JavaScript مؤجَّلًا» في WPOptimizing وتحقّق من الموقع.','HTML Minify'=>'تصغير HTML','Move JS Files to Footer'=>'نقل ملفات JS إلى التذييل','Font remain visible during load'=>'إبقاء النص ظاهرًا أثناء تحميل الخطوط','Delay JS Inline Scripts'=>'تأخير السكربتات المضمّنة','List of scripts not to delay'=>'قائمة السكربتات التي لا تُؤخَّر','Lazy Load Images'=>'التحميل الكسول للصور','Preload Webfont'=>'التحميل المسبق لخطوط الويب','Preload Links'=>'التحميل المسبق للروابط','Prefetch of DNS Request'=>'الجلب المسبق لطلبات DNS','Host Files Locally'=>'استضافة الملفات محليًا','Host Files Locally: Gravatars'=>'استضافة الملفات محليًا: Gravatar','Disable Emoji'=>'تعطيل الرموز التعبيرية','Activate CDN'=>'تفعيل CDN','CDN CNAME'=>'CNAME لشبكة CDN','CDN Content'=>'محتوى CDN','This site runs on a LiteSpeed web server, which serves LiteSpeed Cache\'s page cache before WordPress even loads. Its page cache settings were not imported: keep using it, or switch it off before you turn on the WPOptimizing page cache.'=>'يعمل هذا الموقع على خادم ويب LiteSpeed، الذي يقدّم التخزين المؤقت للصفحات الخاص بـ LiteSpeed Cache قبل أن يُحمَّل WordPress أصلًا. لم تُستورد إعدادات التخزين المؤقت للصفحات الخاصة به: استمر في استخدامه، أو عطّله قبل تفعيل التخزين المؤقت للصفحات في WPOptimizing.','Default Public Cache TTL'=>'مدة TTL الافتراضية للتخزين المؤقت العام','Do Not Cache URIs'=>'عدم تخزين عناوين URI مؤقتًا','Do Not Cache Cookies'=>'عدم التخزين المؤقت مع ملفات تعريف الارتباط','Cache Mobile'=>'التخزين المؤقت للجوال','Crawler'=>'الزاحف','Do Not Cache User Agents'=>'عدم التخزين المؤقت لوكلاء المستخدم','Drop Query String'=>'إسقاط سلسلة الاستعلام','%s: not imported; WPOptimizing has no equivalent.'=>'%s: لم يُستورد؛ لا يوجد مقابل له في WPOptimizing.','Guest Mode'=>'وضع الضيف','CSS Excludes / JS Excludes'=>'استثناءات CSS / استثناءات JS','Load JS Deferred'=>'تحميل JS مؤجلًا','JS Deferred / Delayed Excludes'=>'استثناءات JS المؤجل / المتأخر','JS Delayed Includes'=>'تضمينات JS المتأخر','Load CSS Asynchronously'=>'تحميل CSS بشكل غير متزامن','Critical CSS Rules'=>'قواعد CSS الحرجة','Load CSS Asynchronously: LiteSpeed Cache gets its critical CSS from QUIC.cloud, which is not imported. Generate the critical CSS in WPOptimizing before relying on this setting, or pages will flash unstyled.'=>'تحميل CSS بشكل غير متزامن: يحصل LiteSpeed Cache على CSS الحرج من QUIC.cloud، وهذا لا يُستورد. أنشئ CSS الحرج في WPOptimizing قبل الاعتماد على هذا الإعداد، وإلا ستظهر الصفحات للحظة بلا تنسيق.','CSS Combine'=>'دمج CSS','JS Combine'=>'دمج JS','%s: not imported; WPOptimizing does not minify HTML. Compression already removes most of what minifying would save.'=>'%s: لم يُستورد؛ لا يصغّر WPOptimizing ملفات HTML. يزيل الضغط بالفعل معظم ما كان التصغير سيوفّره.','%s: not imported; it is an online service of the other plugin. WPOptimizing generates critical CSS on your own server instead.'=>'%s: لم يُستورد؛ إنها خدمة عبر الإنترنت تابعة للإضافة الأخرى. يُنشئ WPOptimizing بدلًا من ذلك CSS الحرج على خادمك.','Generate UCSS'=>'إنشاء UCSS','Lazy Load Iframes'=>'التحميل الكسول لإطارات iframe','%s: not imported; WPOptimizing has no exclusion list for lazy loading.'=>'%s: لم يُستورد؛ لا توجد في WPOptimizing قائمة استثناءات للتحميل الكسول.','Lazy Load Image Excludes'=>'استثناءات التحميل الكسول للصور','Next-Gen Image Format'=>'تنسيق الصور من الجيل التالي','Remove WordPress Emoji'=>'إزالة رموز WordPress التعبيرية','Load Google Fonts Asynchronously'=>'تحميل خطوط Google بشكل غير متزامن','%s: WPOptimizing does not load Google Fonts asynchronously; it serves them from your own server instead, which is faster and sends nothing to Google.'=>'%s: لا يحمّل WPOptimizing خطوط Google بشكل غير متزامن؛ بل يقدّمها من خادمك، وهذا أسرع ولا يرسل شيئًا إلى Google.','Remove Google Fonts'=>'إزالة خطوط Google','DNS Prefetch / DNS Preconnect'=>'الجلب المسبق لـ DNS / الاتصال المسبق','Instant Click'=>'النقر الفوري','Use CDN Mapping'=>'استخدام تعيين CDN','Original Directories'=>'المجلدات الأصلية','%s: WPOptimizing uses one CDN host, so only the first one was imported.'=>'%s: يستخدم WPOptimizing خادم CDN واحدًا، لذلك استُورد الأول فقط.','%s: the other plugin connects to Cloudflare with your account\'s credentials, which WPOptimizing does not copy. Connect Cloudflare in Cache › Cloudflare with an API token.'=>'%s: تتصل الإضافة الأخرى بـ Cloudflare باستخدام بيانات اعتماد حسابك، ولا ينسخها WPOptimizing. اربط Cloudflare من التخزين المؤقت › Cloudflare باستخدام رمز API.','Cloudflare API'=>'واجهة Cloudflare البرمجية','Revisions Max Number'=>'الحد الأقصى لعدد المراجعات','Revisions Max Age'=>'الحد الأقصى لعمر المراجعات','%s: the other plugin set the Heartbeat separately for each place; WPOptimizing uses one value for the whole site, so the strictest one was kept.'=>'%s: كانت الإضافة الأخرى تضبط Heartbeat لكل موضع على حدة؛ يستخدم WPOptimizing قيمة واحدة للموقع كله، لذلك احتُفظ بالأكثر صرامة.','Host'=>'المضيف','Port'=>'المنفذ','Redis Database ID'=>'معرّف قاعدة بيانات Redis','%s: the connection was imported, but not switched on and without any password. If the server needs one, type it again in Cache › Object cache.'=>'%s: استُورد الاتصال، لكن دون تفعيله ودون أي كلمة مرور. إذا كان الخادم يحتاج إلى واحدة، فاكتبها مجددًا في التخزين المؤقت › تخزين الكائنات المؤقت.','Maximum lifetime of cache objects'=>'أقصى مدة صلاحية لكائنات التخزين المؤقت','Never cache the following pages'=>'عدم تخزين الصفحات التالية مؤقتًا أبدًا','Rejected cookies'=>'ملفات تعريف الارتباط المرفوضة','Rejected user agents'=>'وكلاء المستخدم المرفوضون','Accepted query strings'=>'سلاسل الاستعلام المقبولة','User Agent Groups'=>'مجموعات وكلاء المستخدم','User Agent Groups: WPOptimizing keeps one separate copy for all mobile devices, without groups, themes or redirects of its own.'=>'مجموعات وكلاء المستخدم: يحتفظ WPOptimizing بنسخة منفصلة واحدة لجميع الأجهزة المحمولة، دون مجموعات أو قوالب أو عمليات إعادة توجيه خاصة.','Automatically prime the page cache'=>'تهيئة التخزين المؤقت للصفحات تلقائيًا','Don\'t cache pages for logged in users'=>'عدم تخزين الصفحات مؤقتًا للمستخدمين المسجلين','Page Cache Method: W3 Total Cache kept pages in memory (Memcached, Redis or APC); WPOptimizing keeps them on disk.'=>'طريقة التخزين المؤقت للصفحات: كان W3 Total Cache يحتفظ بالصفحات في الذاكرة (Memcached أو Redis أو APC)؛ أما WPOptimizing فيحتفظ بها على القرص.','Minify › CSS'=>'التصغير › CSS','Minify › JS'=>'التصغير › JS','Never minify the following JS / CSS files'=>'عدم تصغير ملفات JS / CSS التالية أبدًا','Embed type'=>'نوع التضمين','%s: WPOptimizing defers every script except the ones you exclude, wherever it sits in the page. Check the exclusions after importing.'=>'%s: يؤجّل WPOptimizing جميع السكربتات باستثناء ما تستبعده، أينما كانت في الصفحة. راجع الاستثناءات بعد الاستيراد.','Minify › JS › Combine only'=>'التصغير › JS › الدمج فقط','Minify › HTML & XML'=>'التصغير › HTML وXML','Delay Scripts and Preload Requests: they are W3 Total Cache Pro features and this site has no Pro licence, so they were not acting and were not imported.'=>'تأخير السكربتات والتحميل المسبق للطلبات: هاتان ميزتان في W3 Total Cache Pro، وهذا الموقع ليس لديه ترخيص Pro، لذلك لم تكونا تعملان ولم تُستوردا.','Delay Scripts'=>'تأخير السكربتات','Delay Scripts › Timeout'=>'تأخير السكربتات › مهلة الانتظار','Preload Requests'=>'التحميل المسبق للطلبات','DNS Prefetch / Preconnect'=>'الجلب المسبق لـ DNS / الاتصال المسبق','Disable wp-embed script'=>'تعطيل سكربت wp-embed','Disable jquery-migrate on the front-end'=>'تعطيل jquery-migrate في الواجهة الأمامية','CDN'=>'CDN','CDN host name'=>'اسم مضيف CDN','CDN: W3 Total Cache uploads your files to the CDN; WPOptimizing only points file addresses at a CDN host. Set the host in WPOptimizing\'s CDN settings.'=>'CDN: يرفع W3 Total Cache ملفاتك إلى شبكة CDN؛ أما WPOptimizing فيوجّه عناوين الملفات إلى مضيف CDN فقط. حدّد المضيف في إعدادات CDN في WPOptimizing.','Object Cache: W3 Total Cache kept it in files on disk, which WPOptimizing does not offer. Choose Redis, Memcached or APCu in Cache › Object cache if the server has one.'=>'تخزين الكائنات المؤقت: كان W3 Total Cache يحتفظ به في ملفات على القرص، وهذا ما لا يوفره WPOptimizing. اختر Redis أو Memcached أو APCu من التخزين المؤقت › تخزين الكائنات المؤقت إن كان أحدها متاحًا على الخادم.','Database Cache'=>'التخزين المؤقت لقاعدة البيانات','Cache Timeout'=>'مهلة انتهاء التخزين المؤقت','Rejected URL Strings'=>'سلاسل عناوين URL المرفوضة','Tracking Parameters'=>'معلمات التتبع','Compress pages so they’re served more quickly to visitors.'=>'ضغط الصفحات لتقديمها للزوار بسرعة أكبر.','Mobile device support'=>'دعم الأجهزة المحمولة','Preload mode'=>'وضع التحميل المسبق','Enable caching for all visitors.'=>'تفعيل التخزين المؤقت لجميع الزوار.','Disable caching for visitors who have a cookie set in their browser: WPOptimizing does cache visitors with ordinary cookies, and skips only logged-in users and the cookies you list.'=>'تعطيل التخزين المؤقت للزوار الذين لديهم ملف تعريف ارتباط في المتصفح: يخزّن WPOptimizing مؤقتًا الزوار ذوي ملفات تعريف الارتباط العادية، ويستثني فقط المستخدمين المسجلين وملفات تعريف الارتباط التي تحددها.','Do not cache the following page types (%s): not imported; WPOptimizing cannot leave out whole page types. Add their addresses to the URLs that are never cached if you need to.'=>'عدم تخزين أنواع الصفحات التالية مؤقتًا (%s): لم يُستورد؛ لا يستطيع WPOptimizing استبعاد أنواع صفحات كاملة. أضف عناوينها إلى عناوين URL التي لا تُخزَّن مؤقتًا أبدًا إن احتجت إلى ذلك.','Cache Delivery Method «Expert»: WP Super Cache serves pages straight from rules in .htaccess. After deactivating it, check that the block between «BEGIN WPSuperCache» and «END WPSuperCache» is gone, or visitors will keep getting its old pages.'=>'طريقة تقديم التخزين المؤقت «خبير»: يقدّم WP Super Cache الصفحات مباشرة من قواعد في ملف ‎.htaccess. بعد تعطيله، تحقّق من اختفاء الكتلة بين «BEGIN WPSuperCache» و«END WPSuperCache»، وإلا سيستمر الزوار في تلقي صفحاته القديمة.','Enable CDN Support'=>'تفعيل دعم CDN','Off-site URL'=>'عنوان URL خارجي','Include directories'=>'المجلدات المضمّنة','Additional CNAMES'=>'سجلات CNAME إضافية','Timeout Rules: a rule for some pages only, or at a fixed time of day, was not imported. WPOptimizing has one lifetime for every page.'=>'قواعد انتهاء الصلاحية: لم تُستورد قاعدة تخص بعض الصفحات فقط أو وقتًا محددًا من اليوم. لدى WPOptimizing مدة صلاحية واحدة لكل الصفحات.','Timeout Rules'=>'قواعد انتهاء الصلاحية','Mobile'=>'الجوال','Mobile: WP Fastest Cache did not cache pages for phones at all; WPOptimizing caches them, in a copy of their own.'=>'الجوال: لم يكن WP Fastest Cache يخزّن الصفحات مؤقتًا للهواتف إطلاقًا؛ أما WPOptimizing فيخزّنها في نسخة خاصة بها.','Logged-in Users'=>'المستخدمون المسجلون','Gzip'=>'Gzip','Widget Cache'=>'التخزين المؤقت للودجات','Exclude Pages'=>'استثناء الصفحات','Exclude Cookies'=>'استثناء ملفات تعريف الارتباط','Exclude User-Agents'=>'استثناء وكلاء المستخدم','Exclude CSS / Exclude JS'=>'استثناء CSS / استثناء JS','Exclude Pages (Google Analytics, Google Ads, Facebook and Yandex click IDs): not imported on purpose. WPOptimizing ignores those parameters and serves the cached page, which is faster and does not affect tracking.'=>'استثناء الصفحات (معرّفات النقر في Google Analytics وGoogle Ads وFacebook وYandex): لم يُستورد عمدًا. يتجاهل WPOptimizing هذه المعلمات ويقدّم الصفحة المخزنة مؤقتًا، وهذا أسرع ولا يؤثر في التتبع.','Exclude Pages (home page, categories, tags, posts, pages, archives, attachments): not imported; WPOptimizing cannot leave out whole page types. Add their addresses to the URLs that are never cached if you need to.'=>'استثناء الصفحات (الصفحة الرئيسية، التصنيفات، الوسوم، المقالات، الصفحات، الأرشيفات، المرفقات): لم يُستورد؛ لا يستطيع WPOptimizing استبعاد أنواع صفحات كاملة. أضف عناوينها إلى عناوين URL التي لا تُخزَّن مؤقتًا أبدًا إن احتجت إلى ذلك.','Minify Css'=>'تصغير CSS','Minify Js'=>'تصغير JS','Render Blocking Js'=>'JS الذي يحجب العرض','Delay Js'=>'تأخير JS','%s: they need WP Fastest Cache Premium, which is not installed here, so they were not acting and were not imported.'=>'%s: تتطلب WP Fastest Cache Premium، وهو غير مثبّت هنا، لذلك لم تكن تعمل ولم تُستورد.','Lazy Load Exclude Sources'=>'التحميل الكسول › استثناء المصادر','Render Blocking Js › CSS: not imported. If you want it, switch on «Load CSS asynchronously» in WPOptimizing once its critical CSS is generated.'=>'JS الذي يحجب العرض › CSS: لم يُستورد. إن أردته، فعّل «تحميل CSS بشكل غير متزامن» في WPOptimizing بعد إنشاء CSS الحرج الخاص به.','Combine Css'=>'دمج CSS','Combine Js'=>'دمج JS','Combine Js Plus'=>'دمج JS Plus','CDN Url'=>'عنوان URL لشبكة CDN','CDN: the file types and keywords that chose which files go to the CDN were not imported; WPOptimizing sends the uploads, theme, plugin and WordPress files.'=>'CDN: لم تُستورد أنواع الملفات والكلمات المفتاحية التي كانت تحدد الملفات المرسلة إلى CDN؛ يرسل WPOptimizing الملفات المرفوعة وملفات القالب والإضافات وWordPress.','Database Cleanup › Auto Cleanup'=>'تنظيف قاعدة البيانات › التنظيف التلقائي','Database Cleanup: WP Fastest Cache deleted every revision and every transient. WPOptimizing keeps the last two revisions of each post and deletes only expired transients; you can change both in General cleanup.'=>'تنظيف قاعدة البيانات: كان WP Fastest Cache يحذف كل المراجعات وكل الـ transients. يحتفظ WPOptimizing بآخر مراجعتين لكل مقالة ويحذف الـ transients المنتهية الصلاحية فقط؛ ويمكنك تغيير الأمرين في التنظيف العام.','The web server did not answer from the cache, so pages keep being served through PHP. Check that the rules are in place and that the site can reach itself.'=>'لم يستجب خادم الويب من ذاكرة التخزين المؤقت، لذا ستستمر الصفحات في التقديم عبر PHP. تحقق من وجود القواعد ومن قدرة الموقع على الاتصال بنفسه.','These lines are in the server\'s configuration: serve cached pages straight from the web server'=>'هذه الأسطر موجودة في إعدادات الخادم: قدّم الصفحات المخزنة مؤقتًا مباشرةً من خادم الويب','Only the scripts in my list'=>'البرامج النصية الموجودة في قائمتي فقط','Nothing is delayed except the scripts you list in "Also delay these" below. Useful to keep the list you used with another plugin.'=>'لا يُؤخَّر شيء سوى البرامج النصية التي تضعها أدناه في «أخّر هذه أيضًا». مفيد للاحتفاظ بالقائمة التي كنت تستخدمها مع إضافة أخرى.','The page cache settings changed and the lines in the server\'s configuration no longer match them, so pages are served through PHP again. Replace them with these and tick the box below.'=>'تغيّرت إعدادات ذاكرة التخزين المؤقت للصفحات ولم تعد الأسطر في إعدادات الخادم مطابقة لها، لذا تُقدَّم الصفحات عبر PHP من جديد. استبدلها بهذه وحدّد المربع أدناه.','%1$s: not switched on. The other plugin sent only some files to %2$s (by folder, file type or exclusion list), and WPOptimizing\'s CDN cannot be limited that way. If that host can serve every static file of the site, set it up in WPOptimizing\'s CDN settings.'=>'%1$s: لم يُفعَّل. كانت الإضافة الأخرى ترسل بعض الملفات فقط إلى %2$s (حسب المجلد أو نوع الملف أو قائمة الاستثناءات)، ولا يمكن تقييد شبكة CDN في WPOptimizing بهذه الطريقة. إذا كان هذا المضيف قادرًا على تقديم جميع الملفات الثابتة للموقع، فاضبطه في إعدادات CDN في WPOptimizing.','Page types'=>'أنواع الصفحات','Pages of the kinds ticked here are never cached. Saving empties the whole cache, so copies already stored stop being served at once.'=>'لا تُخزَّن الصفحات من الأنواع المحددة هنا مؤقتًا أبدًا. عند الحفظ تُفرَّغ ذاكرة التخزين المؤقت بالكامل، فتتوقف النسخ المخزنة مسبقًا عن التقديم فورًا.','Posts page (the blog listing, when it is not the front page)'=>'صفحة المقالات (قائمة المدونة، عندما لا تكون الصفحة الرئيسية)','Archives: categories, tags, authors, dates, custom taxonomies and content type listings'=>'الأرشيفات: التصنيفات والوسوم والكتّاب والتواريخ والتصنيفات المخصصة وقوائم أنواع المحتوى','Second and later pages of any listing'=>'الصفحة الثانية وما بعدها من أي قائمة','Never cache single pages of these content types'=>'لا تخزّن مؤقتًا أبدًا الصفحات المفردة لأنواع المحتوى هذه','HTML minification'=>'تصغير HTML','Removes ordinary HTML comments, spaces at the end of lines and repeated empty lines from the cached copy. The spaces between tags, attributes, scripts, styles and preformatted text are never touched, and the page is stored as it was if anything looks unusual.'=>'يزيل من النسخة المخزنة مؤقتًا تعليقات HTML العادية والمسافات في نهاية الأسطر والأسطر الفارغة المتكررة. لا تُمَس أبدًا المسافات بين الوسوم ولا السمات ولا البرامج النصية ولا الأنماط ولا النص المنسق مسبقًا، وتُحفَظ الصفحة كما هي إذا بدا أي شيء غير مألوف.','Minify the HTML of cached pages'=>'تصغير HTML للصفحات المخزنة مؤقتًا','Keep HTML comments containing'=>'الإبقاء على تعليقات HTML التي تحتوي على','part of the comment, e.g. ko foreach'=>'جزء من التعليق، مثل ko foreach','Conditional comments, comments starting with <code>&lt;!--!</code> and anything between <code>&lt;!--noptimize--&gt;</code> and <code>&lt;!--/noptimize--&gt;</code> are always kept. One entry per line.'=>'تُحفَظ دائمًا التعليقات الشرطية والتعليقات التي تبدأ بـ <code>&lt;!--!</code> وكل ما بين <code>&lt;!--noptimize--&gt;</code> و<code>&lt;!--/noptimize--&gt;</code>. إدخال واحد في كل سطر.','Heartbeat by area'=>'Heartbeat حسب المنطقة','How often the browser calls admin-ajax.php in each area. In the editor it is autosave and the edit lock, so it can be slowed (up to 120 seconds, before locks expire) but not switched off.'=>'عدد المرات التي يستدعي فيها المتصفح admin-ajax.php في كل منطقة. في المحرر يتولى الحفظ التلقائي وقفل التحرير، لذا يمكن إبطاؤه (حتى 120 ثانية، قبل أن تنتهي صلاحية الأقفال) لكن لا يمكن إيقافه.','Admin screens'=>'شاشات لوحة التحكم','Editor (posts, pages and Site Editor)'=>'المحرر (المقالات والصفحات ومحرّر الموقع)','Front end (logged-in users)'=>'الواجهة الأمامية (المستخدمون المسجّلون)','Every %d seconds'=>'كل %d ثانية','Also outside the content — header, sidebars, footer — on pages saved by the page cache'=>'خارج المحتوى أيضًا — الترويسة والأشرطة الجانبية والتذييل — في الصفحات التي تحفظها ذاكرة تخزين الصفحات','Give the first image of the content high fetch priority (the likely LCP image); it is never lazy-loaded'=>'منح أول صورة في المحتوى أولوية جلب عالية (صورة LCP المحتملة)؛ ولا تُحمَّل أبدًا بشكل مؤجّل','Images never lazy-loaded at the top of the page'=>'الصور التي لا تُحمَّل أبدًا بشكل مؤجّل في أعلى الصفحة','Automatic (the first image of the content; the first three of the whole page)'=>'تلقائي (الصورة الأولى في المحتوى؛ أول ثلاث صور في الصفحة كلها)','Never lazy-load images whose class or file name contains (one per line)'=>'عدم تحميل الصور بشكل مؤجّل أبدًا إذا احتوت فئتها أو اسم ملفها على (واحد في كل سطر)','A fixed number counts the images of the whole page from the top, header included. Images with the <code>skip-lazy</code> or <code>no-lazy</code> class, or the <code>data-skip-lazy</code> or <code>data-no-lazy</code> attribute, are never lazy-loaded either; an image already marked <code>loading="lazy"</code> keeps it and is not given priority.'=>'يَعُدّ الرقم الثابت صور الصفحة كلها من الأعلى، بما فيها الترويسة. كما أن الصور ذات الفئة <code>skip-lazy</code> أو <code>no-lazy</code>، أو السمة <code>data-skip-lazy</code> أو <code>data-no-lazy</code>، لا تُحمَّل أبدًا بشكل مؤجّل؛ والصورة التي تحمل <code>loading="lazy"</code> مسبقًا تحتفظ به ولا تُمنح الأولوية.','%s: one area could not be copied as it was. WPOptimizing never switches the Heartbeat off in the editor, where it autosaves drafts and keeps the edit lock, and keeps intervals between 15 seconds and 120 (editor) or 300 (elsewhere); the nearest of those was set. Check Performance › Server.'=>'%s: تعذّر نسخ إحدى المناطق كما هي. لا يوقف WPOptimizing أبدًا Heartbeat في المحرر، حيث يحفظ المسودات تلقائيًا ويحافظ على قفل التحرير، ويُبقي الفواصل الزمنية بين 15 ثانية و120 (المحرر) أو 300 (باقي المناطق)؛ وقد ضُبطت أقرب قيمة منها. راجع الأداء › الخادم.','%1$s: WPOptimizing excludes images by a part of their class or file name; these entries name another attribute and were not imported: %2$s'=>'%1$s: يستثني WPOptimizing الصور بجزء من فئتها أو اسم ملفها؛ وهذه الإدخالات تشير إلى سمة أخرى ولم تُستورد: %2$s','%s: not imported; WPOptimizing excludes an image by its own class or file name, not by the element around it. Add the images\' class or file name to its lazy-load exclusions.'=>'%s: لم يُستورد؛ يستثني WPOptimizing الصورة بفئتها أو اسم ملفها هي، لا بالعنصر المحيط بها. أضف فئة الصور أو اسم ملفها إلى استثناءات التحميل المؤجّل فيه.','Exclude Leading Images'=>'Exclude Leading Images','Exclude by Parent Selector'=>'Exclude by Parent Selector','%s: the excluded images are not deferred, but they no longer all get high fetch priority; WPOptimizing gives it only to the likely LCP image.'=>'%s: لا تُحمَّل الصور المستثناة بشكل مؤجّل، لكنها لم تعد كلها تحصل على أولوية جلب عالية؛ إذ يمنحها WPOptimizing لصورة LCP المحتملة فقط.','Media Exclusions'=>'Media Exclusions','%s: not imported; WPOptimizing excludes images by their own class or file name only.'=>'%s: لم يُستورد؛ يستثني WPOptimizing الصور بفئتها أو اسم ملفها فقط.','Excluded images or iframes'=>'Excluded images or iframes','Lazy Load Image Class Name Excludes'=>'Lazy Load Image Class Name Excludes','Lazy Load Image Parent Class Name Excludes'=>'Lazy Load Image Parent Class Name Excludes','Lazy Load URI Excludes'=>'Lazy Load URI Excludes','Hit diagnostics'=>'تشخيص الإصابات','Counts how each request was answered and, when a page was not served from the cache, why. Off by default: while it is on, every request PHP handles adds one byte to a counter file.'=>'يحصي كيف أُجيب عن كل طلب، وعندما لا تُقدَّم الصفحة من ذاكرة التخزين المؤقت، يحصي السبب. معطّل افتراضيًا: ما دام مفعّلًا، يضيف كل طلب يعالجه PHP بايتًا واحدًا إلى ملف عدّاد.','Count cache hits and the reasons for misses'=>'إحصاء إصابات ذاكرة التخزين المؤقت وأسباب الإخفاقات','Hits seen by PHP: pages the web server sends without PHP and pages served by a CDN never reach these counters, so the real share of hits is higher. The share is hits, stale copies and 304 answers over the requests a page cache can answer: the preload\'s own visits, logged-in users, the admin, files that are not pages and methods other than GET are counted apart.'=>'إصابات يراها PHP: الصفحات التي يرسلها خادم الويب دون PHP والصفحات التي تقدّمها CDN لا تصل أبدًا إلى هذه العدّادات، لذا فالنسبة الحقيقية للإصابات أعلى. النسبة هي الإصابات والنسخ المنتهية الصلاحية وردود 304 مقسومةً على الطلبات التي يمكن لذاكرة تخزين الصفحات الرد عليها: تُحتسب على حدة زيارات التحميل المسبق نفسه، والمستخدمون المسجّلون، ولوحة الإدارة، والملفات التي ليست صفحات، والطرق غير GET.','No requests counted yet.'=>'لم تُحتسب أي طلبات بعد.','Hit rate, last 24 hours'=>'نسبة الإصابة، آخر 24 ساعة','Hit rate, last 7 days'=>'نسبة الإصابة، آخر 7 أيام','Outcome'=>'النتيجة','Last 24 hours'=>'آخر 24 ساعة','Last 7 days'=>'آخر 7 أيام','Paths that miss most (estimate)'=>'المسارات الأكثر إخفاقًا (تقدير)','Estimated from one miss in every 20, so small numbers are rough. Only the path is recorded, never the query string.'=>'تقدير مبني على إخفاق واحد من كل 20، لذا فالأرقام الصغيرة تقريبية. يُسجَّل المسار فقط، ولا تُسجَّل معاملات الاستعلام أبدًا.','Path'=>'المسار','Estimated misses'=>'الإخفاقات المقدّرة','Served from the cache (HIT)'=>'قُدِّمت من ذاكرة التخزين المؤقت (HIT)','Served an expired copy while it was rebuilt (STALE)'=>'قُدِّمت نسخة منتهية الصلاحية أثناء إعادة بنائها (STALE)','Browser copy still valid (304)'=>'نسخة المتصفح لا تزال صالحة (304)','Rendered and stored (MISS)'=>'أُنشئت وخُزِّنت (MISS)','HEAD request with no copy yet'=>'طلب HEAD دون نسخة بعد','Preload visits (not part of the share)'=>'زيارات التحميل المسبق (لا تدخل في النسبة)','Not cached: method other than GET or HEAD'=>'لم تُخزَّن مؤقتًا: طريقة غير GET أو HEAD','Not cached: logged-in user'=>'لم تُخزَّن مؤقتًا: مستخدم مسجّل','Not cached: cookie that prevents caching (cart, password, commenter or your own list)'=>'لم تُخزَّن مؤقتًا: ملف تعريف ارتباط يمنع التخزين المؤقت (السلة أو كلمة المرور أو المعلِّق أو قائمتك الخاصة)','Not cached: excluded browser or bot'=>'لم تُخزَّن مؤقتًا: متصفح أو روبوت مستثنى','Not cached: dynamic file (wp-cron.php, admin-ajax.php, sitemaps…)'=>'لم تُخزَّن مؤقتًا: ملف ديناميكي (wp-cron.php وadmin-ajax.php وخرائط الموقع…)','Not cached: excluded URL (feeds, REST API or your own list)'=>'لم تُخزَّن مؤقتًا: عنوان URL مستثنى (الخلاصات أو REST API أو قائمتك الخاصة)','Not cached: query string not allowed'=>'لم تُخزَّن مؤقتًا: معاملات استعلام غير مسموح بها','Not cached: host name this site does not answer to'=>'لم تُخزَّن مؤقتًا: اسم مضيف لا يستجيب له هذا الموقع','Not cached: currency or country cookie with an unknown value'=>'لم تُخزَّن مؤقتًا: ملف تعريف ارتباط للعملة أو البلد بقيمة غير معروفة','Not cached: the page was sent in pieces before it ended'=>'لم تُخزَّن مؤقتًا: أُرسلت الصفحة على أجزاء قبل اكتمالها','Not cached: admin screen'=>'لم تُخزَّن مؤقتًا: شاشة الإدارة','Not cached: page not found'=>'لم تُخزَّن مؤقتًا: الصفحة غير موجودة','Not cached: search results'=>'لم تُخزَّن مؤقتًا: نتائج البحث','Not cached: feed'=>'لم تُخزَّن مؤقتًا: خلاصة','Not cached: the page asked not to be cached (DONOTCACHEPAGE)'=>'لم تُخزَّن مؤقتًا: طلبت الصفحة عدم تخزينها مؤقتًا (DONOTCACHEPAGE)','Not cached: excluded page'=>'لم تُخزَّن مؤقتًا: صفحة مستثناة','Not cached: excluded page type'=>'لم تُخزَّن مؤقتًا: نوع صفحة مستثنى','Not cached: the response sets a cookie'=>'لم تُخزَّن مؤقتًا: الاستجابة تعيّن ملف تعريف ارتباط','Not cached: the response forbids shared caches (private or no-store)'=>'لم تُخزَّن مؤقتًا: الاستجابة تمنع ذاكرات التخزين المشتركة (private أو no-store)','Not cached: HTTP status other than 200'=>'لم تُخزَّن مؤقتًا: حالة HTTP غير 200','Not cached: not a complete HTML page'=>'لم تُخزَّن مؤقتًا: ليست صفحة HTML كاملة','Not cached: the settings changed while the page was rendered'=>'لم تُخزَّن مؤقتًا: تغيّرت الإعدادات أثناء إنشاء الصفحة','Not cached: too many currency copies of the same URL'=>'لم تُخزَّن مؤقتًا: نسخ كثيرة جدًا حسب العملة لعنوان URL نفسه','Not cached: other reason'=>'لم تُخزَّن مؤقتًا: سبب آخر','Pages found in the sitemap'=>'الصفحات الموجودة في خريطة الموقع','Pages that could not be preloaded'=>'الصفحات التي تعذّر تحميلها مسبقًا','%1$s (HTTP %2$s)'=>'%1$s (HTTP %2$s)','Also preload the pages listed in the site\'s sitemap'=>'حمّل مسبقًا أيضًا الصفحات المدرجة في خريطة الموقع','%s request' . "\0" . '%s requests'=>'%s طلب' . "\0" . '%s طلب' . "\0" . '%s طلبان' . "\0" . '%s طلبات' . "\0" . '%s طلبًا' . "\0" . '%s طلب','The web server did not answer from the cache, so pages keep being served through PHP. Check that the rules are in place, that Apache has mod_headers (it is needed to tell browsers not to keep the pages) and that the site can reach itself.'=>'لم يستجب خادم الويب من ذاكرة التخزين المؤقت، لذا ستستمر الصفحات في التقديم عبر PHP. تحقق من وجود القواعد، ومن توفّر mod_headers في Apache (وهو لازم لإخبار المتصفحات بعدم الاحتفاظ بالصفحات)، ومن قدرة الموقع على الاتصال بنفسه.','The web server answers from the cached file directly, without starting PHP: faster pages and far more visitors at once on the same server. Only pages that need nothing from PHP are served this way (no currency, query string or security headers sent from PHP; phones get their own copy when it is on); the rest keep going through PHP as now.'=>'يستجيب خادم الويب مباشرةً من الملف المخزّن مؤقتًا دون تشغيل PHP: صفحات أسرع وعدد أكبر بكثير من الزوار في الوقت نفسه على الخادم ذاته. لا تُقدَّم بهذه الطريقة إلا الصفحات التي لا تحتاج شيئًا من PHP (بلا عملة أو معاملات استعلام أو ترويسات أمان يرسلها PHP؛ وتحصل الهواتف على نسختها الخاصة عند تفعيلها)؛ أما البقية فتستمر في المرور عبر PHP كما هي الآن.','Not cached: the page was purged while it was rendered'=>'لم تُخزَّن مؤقتًا: أُفرغت الصفحة أثناء إنشائها','WP-Cron is running late: a scheduled task has been waiting for more than 10 minutes. WP-Cron depends on visits that reach WordPress, and most visits are now answered from the cache. Set a system cron that calls wp-cron.php every minute.'=>'WP-Cron متأخر: هناك مهمة مجدولة تنتظر منذ أكثر من 10 دقائق. يعتمد WP-Cron على الزيارات التي تصل إلى ووردبريس، ومعظم الزيارات تُجاب الآن من ذاكرة التخزين المؤقت. اضبط مهمة cron في النظام تستدعي wp-cron.php كل دقيقة.','Hosting cache'=>'ذاكرة التخزين المؤقت للاستضافة','WPOptimizing purges your host’s page cache when content changes and when the whole site does (theme, menus, updates, “Flush all caches”), even with its own page cache off. Hosts that can only empty everything are emptied only for site-wide changes.'=>'يُفرغ WPOptimizing ذاكرة التخزين المؤقت للصفحات لدى استضافتك عند تغيّر المحتوى وعند تغيّر الموقع كله (القالب، القوائم، التحديثات، «إفراغ جميع ذواكر التخزين المؤقت»)، حتى مع إيقاف ذاكرته المؤقتة للصفحات. أما الاستضافات التي لا تستطيع إلا إفراغ كل شيء فلا تُفرَغ إلا عند التغييرات التي تشمل الموقع كله.','Page lifetime'=>'مدة صلاحية الصفحات','How long a cached page is served before it is built again. Forms, «add to cart» and many buttons carry WordPress security tokens that stop working after 12 to 24 hours, so pages are never kept longer than 12 hours: older copies would show forms and buttons that fail. Saving empties the cache.'=>'المدة التي تُقدَّم فيها الصفحة المخزنة مؤقتًا قبل إعادة بنائها. تحمل النماذج وزر «أضف إلى السلة» وأزرار كثيرة أخرى رموز أمان WordPress التي تتوقف عن العمل بعد 12 إلى 24 ساعة، لذلك لا تُحفظ الصفحات أبدًا أكثر من 12 ساعة: فالنسخ الأقدم ستعرض نماذج وأزرارًا لا تعمل. عند الحفظ تُفرَّغ ذاكرة التخزين المؤقت.','Rebuild cached pages after'=>'إعادة بناء الصفحات المخزنة مؤقتًا بعد','%d hour' . "\0" . '%d hours'=>'%d ساعة' . "\0" . '%d ساعة' . "\0" . '%d ساعتان' . "\0" . '%d ساعات' . "\0" . '%d ساعة' . "\0" . '%d ساعة','Code on this site changes it through the %1$s filter: pages are kept for %2$s hours (0 means they never expire).'=>'تغيّر شيفرة في هذا الموقع هذه القيمة عبر المرشّح %1$s: تُحفظ الصفحات لمدة %2$s ساعة (0 يعني أنها لا تنتهي صلاحيتها أبدًا).','Compression'=>'الضغط','A compressed copy of each page is stored next to the normal one and sent to every browser that accepts it: smaller pages, sent faster, at no cost per visit. Turn it off only if the server already compresses pages on its own and something looks wrong.'=>'تُخزَّن نسخة مضغوطة من كل صفحة بجانب النسخة العادية وتُرسل إلى كل متصفح يقبلها: صفحات أصغر تصل أسرع، دون أي تكلفة في كل زيارة. لا تعطّلها إلا إذا كان الخادم يضغط الصفحات بنفسه وبدا لك أن شيئًا لا يعمل كما ينبغي.','Store compressed copies (gzip)'=>'تخزين نسخ مضغوطة (gzip)','Purge also these pages'=>'تفريغ هذه الصفحات أيضًا','Pages purged every time any page is purged, for example a page that lists the latest posts or products in a way WPOptimizing cannot see. They go to Cloudflare, Varnish and the hosting\'s cache too, also with the page cache off. One per line: a path or a full address of this site.'=>'صفحات تُفرَّغ في كل مرة تُفرَّغ فيها أي صفحة، مثل صفحة تعرض أحدث المقالات أو المنتجات بطريقة لا يستطيع WPOptimizing رصدها. وتُفرَّغ أيضًا في Cloudflare وVarnish وذاكرة التخزين المؤقت لدى الاستضافة، حتى مع تعطيل ذاكرة التخزين المؤقت للصفحات. واحدة في كل سطر: مسار أو عنوان كامل من هذا الموقع.','Purge also these URLs every time any page is purged'=>'تفريغ عناوين URL هذه أيضًا في كل مرة تُفرَّغ فيها أي صفحة','e.g. /latest-news/'=>'مثال: /latest-news/','Page cache settings saved, except these addresses to purge too, which are not pages of this site: %s'=>'حُفظت إعدادات ذاكرة التخزين المؤقت للصفحات، باستثناء عناوين التفريغ الإضافية هذه لأنها ليست صفحات من هذا الموقع: %s','Page lifetime: WPOptimizing keeps pages for whole hours, from 1 to 12, so the other plugin\'s %2$d minutes became %1$d hour.' . "\0" . 'Page lifetime: WPOptimizing keeps pages for whole hours, from 1 to 12, so the other plugin\'s %2$d minutes became %1$d hours.'=>'مدة صلاحية الصفحات: يحتفظ WPOptimizing بالصفحات بساعات كاملة، من 1 إلى 12، لذلك أصبحت الدقائق (%2$d) لدى الإضافة الأخرى %1$d ساعة.' . "\0" . 'مدة صلاحية الصفحات: يحتفظ WPOptimizing بالصفحات بساعات كاملة، من 1 إلى 12، لذلك أصبحت الدقائق (%2$d) لدى الإضافة الأخرى %1$d ساعة.' . "\0" . 'مدة صلاحية الصفحات: يحتفظ WPOptimizing بالصفحات بساعات كاملة، من 1 إلى 12، لذلك أصبحت الدقائق (%2$d) لدى الإضافة الأخرى %1$d ساعتين.' . "\0" . 'مدة صلاحية الصفحات: يحتفظ WPOptimizing بالصفحات بساعات كاملة، من 1 إلى 12، لذلك أصبحت الدقائق (%2$d) لدى الإضافة الأخرى %1$d ساعات.' . "\0" . 'مدة صلاحية الصفحات: يحتفظ WPOptimizing بالصفحات بساعات كاملة، من 1 إلى 12، لذلك أصبحت الدقائق (%2$d) لدى الإضافة الأخرى %1$d ساعة.' . "\0" . 'مدة صلاحية الصفحات: يحتفظ WPOptimizing بالصفحات بساعات كاملة، من 1 إلى 12، لذلك أصبحت الدقائق (%2$d) لدى الإضافة الأخرى %1$d ساعة.','Always Purge URL(s)'=>'تفريغ عناوين URL هذه دائمًا','Always Purge URL(s): these entries are patterns (or not pages of this site), which WPOptimizing does not purge, so they were not imported. Add the pages they meant one by one: %s'=>'تفريغ عناوين URL هذه دائمًا: هذه الإدخالات أنماط (أو ليست صفحات من هذا الموقع)، ولا يفرّغها WPOptimizing، لذلك لم تُستورد. أضف الصفحات المقصودة واحدة تلو الأخرى: %s','Also store Brotli copies (about 10–15% smaller than gzip)'=>'احفظ أيضًا نسخًا بضغط Brotli (أصغر من gzip بنحو 10–15%)','Sent to browsers that accept Brotli. Serving them without PHP on Nginx needs its brotli module.'=>'تُرسَل إلى المتصفحات التي تقبل Brotli. لتقديمها دون PHP على Nginx تحتاج إلى وحدة brotli الخاصة به.','The web server cannot write to %s: no page is stored there until they belong to its user again.'=>'لا يستطيع خادم الويب الكتابة في %s: لن تُحفَظ أي صفحة هناك حتى تعود ملكيتها إلى مستخدمه.','Preload hints (experimental)'=>'تلميحات التحميل المسبق (تجريبي)','Each cached page is stored with up to three preload hints: its main image and up to two stylesheets from its head, so the browser can start downloading them before it reads the page. Cloudflare can turn them into 103 Early Hints if you switch Early Hints on there; other servers just send them with the page. Pages the web server sends without PHP go without them.'=>'تُحفَظ كل صفحة مخزنة مؤقتًا مع ما يصل إلى ثلاثة تلميحات للتحميل المسبق: صورتها الرئيسية وما يصل إلى ورقتي أنماط من ترويستها، حتى يبدأ المتصفح تنزيلها قبل قراءة الصفحة. يمكن لـ Cloudflare تحويلها إلى 103 Early Hints إذا فعّلت Early Hints هناك؛ أما الخوادم الأخرى فترسلها مع الصفحة فحسب. الصفحات التي يرسلها خادم الويب دون PHP تُرسَل بدونها.','Send preload hints for the main image and stylesheets of cached pages'=>'إرسال تلميحات التحميل المسبق للصورة الرئيسية وأوراق الأنماط في الصفحات المخزنة مؤقتًا','The page cache is not available for this site: its address cannot be used to name its cache files.'=>'ذاكرة التخزين المؤقت للصفحات غير متاحة لهذا الموقع: لا يمكن استخدام عنوانه لتسمية ملفات التخزين المؤقت الخاصة به.','Not available on a multisite network yet: every site shares the same server rules, and each site has its own exclusions. Pages are served through PHP, from the cache.'=>'غير متاح بعد في شبكة المواقع المتعددة: تتشارك جميع المواقع قواعد الخادم نفسها، ولكل موقع استثناءاته الخاصة. تُقدَّم الصفحات عبر PHP من ذاكرة التخزين المؤقت.','HTML at Cloudflare\'s edge is not available on a multisite network yet: its sites can share a Cloudflare zone, and one rule would cover them all.'=>'HTML على حافة Cloudflare غير متاح بعد في شبكة المواقع المتعددة: يمكن لمواقعها مشاركة منطقة Cloudflare واحدة، وستغطيها جميعًا قاعدة واحدة.','WordPress security tokens on this site are only guaranteed for %s hours, less than pages are kept: forms and buttons on older pages may fail. Choose a shorter lifetime.'=>'رموز الأمان في ووردبريس على هذا الموقع مضمونة لمدة %s ساعة فقط، وهي أقل من مدة الاحتفاظ بالصفحات: قد تفشل النماذج والأزرار في الصفحات الأقدم. اختر مدة أقصر.','Visits from campaigns (utm_*, gclid, fbclid and the other parameters the page cache ignores) are served from the edge too: a Transform Rule takes those parameters off before Cloudflare looks for the page, only when they are the only ones. Analytics still sees them, because it reads the address in the browser. For this the token needs Zone › Transform Rules › Edit; without it, the edge works as before.'=>'تُقدَّم الزيارات القادمة من الحملات (utm_* وgclid وfbclid وسائر المعاملات التي تتجاهلها ذاكرة التخزين المؤقت للصفحات) من الحافة أيضًا: تزيل قاعدة Transform Rule هذه المعاملات قبل أن تبحث Cloudflare عن الصفحة، فقط عندما تكون هي الوحيدة. تظل أدوات التحليل تراها لأنها تقرأ العنوان في المتصفح. يحتاج الرمز لذلك إلى Zone › Transform Rules › Edit؛ ومن دونه تعمل الحافة كما كانت.','Visits with campaign parameters are served from the edge too.'=>'تُقدَّم الزيارات التي تحمل معاملات الحملات من الحافة أيضًا.','Campaign parameters are taken off at the edge, but a visit with one was not served from the edge yet. That is normal while it fills.'=>'تُزال معاملات الحملات عند الحافة، لكن زيارة تحمل أحدها لم تُقدَّم من الحافة بعد. هذا طبيعي أثناء امتلائها.','Visits with campaign parameters still reach your server: Cloudflare refused the Transform Rule (%s). Add Zone › Transform Rules › Edit to the token and press «Check now».'=>'لا تزال الزيارات التي تحمل معاملات الحملات تصل إلى خادمك: رفضت Cloudflare قاعدة Transform Rule (%s). أضف Zone › Transform Rules › Edit إلى الرمز واضغط «افحص الآن».','Never on the front end'=>'ليس في الواجهة الأمامية أبدًا','Stop a plugin from loading where it does nothing — a contact form everywhere but the contact page, a shop plugin on the blog, an editor plugin (Classic Editor, Advanced Editor Tools) on every page with "Never on the front end". Its PHP, its queries and its CSS/JS all stay out. Only for visitors: logged-in users, the admin, AJAX, the REST API and cron always get every plugin.'=>'يمنع إضافة من التحميل حيث لا تفعل شيئًا: نموذج اتصال في كل مكان عدا صفحة الاتصال، أو إضافة متجر في المدونة، أو إضافة محرر (Classic Editor وAdvanced Editor Tools) في كل الصفحات مع «أبدًا في الواجهة الأمامية». يبقى PHP الخاص بها واستعلاماتها وCSS/JS خارجًا. للزوار فقط: المستخدمون المسجّلون ولوحة التحكم وAJAX وواجهة REST وcron يحصلون دائمًا على كل الإضافات.','Load CSS asynchronously (non-blocking render; only on pages that have critical CSS, so they never paint unstyled)'=>'تحميل CSS بشكل غير متزامن (لا يعيق العرض؛ فقط في الصفحات التي لديها CSS حرج، فلا تظهر أبدًا بلا أنماط)','The generated critical CSS files are no longer on the disk, so nothing is being inlined and asynchronous CSS stays off. Generate it again.'=>'لم تعد ملفات CSS الحرج المُنشأة موجودة على القرص، لذا لا يُضمَّن شيء ويبقى CSS غير المتزامن متوقفًا. أنشئه من جديد.','Pages keep being served through PHP, from the cache, as before.'=>'تبقى الصفحات تُقدَّم عبر PHP من ذاكرة التخزين المؤقت كما في السابق.','The web server does not have the mod_headers module enabled, and it is needed to tell browsers not to keep the pages. In cPanel: Software › EasyApache 4 › Apache Modules › mod_headers. In Plesk: Tools & Settings › Apache Web Server › headers. Or ask your host: «Please enable the Apache module mod_headers for my site».'=>'لا يحتوي خادم الويب على الوحدة mod_headers مفعّلة، وهي لازمة لإخبار المتصفحات بعدم الاحتفاظ بالصفحات. في cPanel: Software › EasyApache 4 › Apache Modules › mod_headers. في Plesk: الأدوات والإعدادات › خادم الويب Apache › headers. أو اطلب من الاستضافة: «يرجى تفعيل وحدة Apache mod_headers لموقعي».','The web server refuses to read the cache folder (wp-content/cache/wpopt-page): a rule in the server\'s configuration or a security plugin closes it. Ask your host to allow reading the .html files in that folder.'=>'يرفض خادم الويب قراءة مجلد ذاكرة التخزين المؤقت (wp-content/cache/wpopt-page): تغلقه قاعدة في إعدادات الخادم أو إضافة أمان. اطلب من الاستضافة السماح بقراءة ملفات .html في هذا المجلد.','The site could not reach itself to check the rules (a firewall, a security plugin or the hosting blocks it). Ask your host to allow the site to make requests to its own address.'=>'تعذّر على الموقع الاتصال بنفسه للتحقق من القواعد (يمنعه جدار حماية أو إضافة أمان أو الاستضافة). اطلب من الاستضافة السماح للموقع بإرسال طلبات إلى عنوانه.','The web server is not applying the rules added to .htaccess (the hosting may not allow .htaccess overrides, or another rule answers first). Ask your host whether .htaccess rewrite rules are allowed for the site.'=>'لا يطبّق خادم الويب القواعد المضافة إلى .htaccess (ربما لا تسمح الاستضافة بملفات .htaccess أو تجيب قاعدة أخرى أولًا). اسأل الاستضافة إن كان الموقع يستطيع استخدام قواعد إعادة الكتابة في .htaccess.','Too many sites of this network serve their pages without PHP: the shared .htaccess would grow too long. This site keeps being served through PHP, from the cache.'=>'عدد كبير جدًا من مواقع هذه الشبكة يقدّم صفحاته دون PHP: سيصبح ملف ‎.htaccess المشترك طويلًا جدًا. يستمر تقديم هذا الموقع عبر PHP من ذاكرة التخزين المؤقت.','On a multisite network this is only available with Apache or LiteSpeed. Pages keep being served through PHP, from the cache.'=>'في شبكة متعددة المواقع لا يتوفر هذا إلا مع Apache أو LiteSpeed. يستمر تقديم الصفحات عبر PHP من ذاكرة التخزين المؤقت.','On a multisite network this is only available with Apache or LiteSpeed. Pages are served through PHP, from the cache.'=>'في شبكة متعددة المواقع لا يتوفر هذا إلا مع Apache أو LiteSpeed. تُقدَّم الصفحات عبر PHP من ذاكرة التخزين المؤقت.','On: the web server serves this site\'s cached pages. Only a network administrator can switch it off, because the rules are in the .htaccess shared by every site of the network.'=>'مفعّل: يقدّم خادم الويب الصفحات المخزنة لهذا الموقع. لا يمكن إيقافه إلا لمسؤول الشبكة، لأن القواعد موجودة في ملف ‎.htaccess المشترك بين جميع مواقع الشبكة.','Off. Only a network administrator can switch it on, because the rules go into the .htaccess shared by every site of the network.'=>'متوقف. لا يمكن تفعيله إلا لمسؤول الشبكة، لأن القواعد تُكتب في ملف ‎.htaccess المشترك بين جميع مواقع الشبكة.','The .htaccess is shared by every site of the network: each site that switches this on gets its own block of rules, for its own address and with its own exclusions.'=>'ملف ‎.htaccess مشترك بين جميع مواقع الشبكة: كل موقع يفعّل هذا يحصل على كتلة قواعد خاصة به، لعنوانه ومع استثناءاته الخاصة.','This site runs on a LiteSpeed web server, which serves LiteSpeed Cache\'s page cache before WordPress even loads. Its page cache settings were imported, but the WPOptimizing page cache stays off: switch LiteSpeed Cache\'s page cache off before you turn it on.'=>'يعمل هذا الموقع على خادم ويب LiteSpeed، الذي يقدّم ذاكرة الصفحات المؤقتة لـ LiteSpeed Cache حتى قبل تحميل WordPress. تم استيراد إعدادات ذاكرة الصفحات المؤقتة الخاصة به، لكن ذاكرة الصفحات المؤقتة في WPOptimizing تبقى متوقفة: أوقف ذاكرة الصفحات المؤقتة في LiteSpeed Cache قبل تفعيلها.','Load CSS Asynchronously: LiteSpeed Cache gets its critical CSS from QUIC.cloud, which is not imported. WPOptimizing only loads CSS asynchronously on pages that have their own critical CSS, so generate it in WPOptimizing for this setting to take effect.'=>'تحميل CSS بشكل غير متزامن: يحصل LiteSpeed Cache على CSS الحرج من QUIC.cloud، وهو لا يُستورد. لا يحمّل WPOptimizing ملفات CSS بشكل غير متزامن إلا في الصفحات التي لها CSS حرج خاص بها، لذا أنشئه في WPOptimizing ليصبح هذا الإعداد فعّالًا.','The web server answers from the cached file directly, without starting PHP: faster pages and far more visitors at once on the same server. Only pages that need nothing else from PHP are served this way (no currency or query string; security headers sent from PHP go with them when every page sends the same; phones get their own copy when it is on); the rest keep going through PHP as now.'=>'يرد خادم الويب مباشرةً بالملف المخزن دون تشغيل PHP: صفحات أسرع وعدد أكبر بكثير من الزوار في الوقت نفسه على الخادم ذاته. لا تُقدَّم بهذه الطريقة إلا الصفحات التي لا تحتاج إلى أي شيء آخر من PHP (بلا عملة ولا معاملات في العنوان؛ وتُرسل معها ترويسات الأمان التي يرسلها PHP عندما ترسل جميع الصفحات الترويسات نفسها؛ وللهواتف نسختها الخاصة إن كانت مفعّلة)؛ ويستمر الباقي عبر PHP كما هو الآن.','Defer jQuery too (the inline code that uses it runs right after it; only with «Defer JavaScript» on)'=>'تأجيل jQuery أيضًا (يُنفَّذ الكود المضمّن الذي يستخدمه بعده مباشرةً؛ فقط مع تفعيل «تأجيل JavaScript»)','jQuery is in the list of scripts not to defer, so it stays eager. Remove it from that list for this setting to take effect.'=>'jQuery موجود في قائمة السكربتات التي لا تُؤجَّل، لذا يبقى محمَّلًا فورًا. أزله من تلك القائمة ليصبح هذا الإعداد فعّالًا.','Also cache these REST API routes, for visitors who are not logged in (only routes whose answer is the same for everybody)'=>'تخزين مسارات REST API هذه أيضًا مؤقتًا للزوار غير المسجلين (فقط المسارات التي تكون إجابتها واحدة للجميع)','route after /wp-json/, e.g. my-plugin/v1/settings'=>'المسار بعد ‎/wp-json/‎، مثل my-plugin/v1/settings','%s has been deactivated (not deleted): its page cache no longer serves your pages. Switch on the WPOptimizing page cache in Speed › Cache; an import never switches it on by itself.'=>'تم إلغاء تفعيل %s (ولم يُحذف): لم تعد ذاكرة الصفحات المؤقتة الخاصة به تقدّم صفحاتك. فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.','LiteSpeed Cache cleans up after itself when it is deactivated: its rules in .htaccess, its object-cache.php and the WP_CACHE line in wp-config.php (WPOptimizing writes its own back if its page cache is installed). On a network it only does so when no other site still has it active.'=>'ينظّف LiteSpeed Cache ما يخصّه عند إلغاء تفعيله: قواعده في ‎.htaccess وملف object-cache.php الخاص به وسطر WP_CACHE في wp-config.php (ويعيد WPOptimizing كتابة سطره إن كانت ذاكرة الصفحات المؤقتة لديه مثبّتة). وفي الشبكة لا يفعل ذلك إلا عندما لا يبقى مفعّلًا في أي موقع آخر.','Settings imported from %s. You can undo the import in Settings.'=>'تم استيراد الإعدادات من %s. يمكنك التراجع عن الاستيراد من الإعدادات.','%s was not deactivated: only a network administrator can do it, because it is active for the whole network.'=>'لم يتم إلغاء تفعيل %s: لا يستطيع ذلك إلا مسؤول الشبكة، لأنه مفعّل على الشبكة كلها.','Import your current settings'=>'استورد إعداداتك الحالية','Another cache or performance plugin left its settings on this site. WPOptimizing can bring over what has an equivalent here, so you do not have to set it up again. The import is applied when the analysis starts, after the choices of the next steps, so what you bring over wins over their defaults. Passwords and API keys are never copied, the page cache and the object cache are never switched on by an import, and you can undo it in Settings.'=>'ترك إضافة أخرى للذاكرة المؤقتة أو الأداء إعداداتها على هذا الموقع. يستطيع WPOptimizing جلب ما له مقابل هنا، كي لا تضطر إلى إعداده من جديد. يُطبَّق الاستيراد عند بدء التحليل، بعد اختيارات الخطوات التالية، لذا يتقدّم ما تجلبه على قيمها الافتراضية. لا تُنسخ كلمات المرور ومفاتيح API أبدًا، ولا يفعّل الاستيراد أبدًا ذاكرة الصفحات أو ذاكرة الكائنات المؤقتة، ويمكنك التراجع عنه من الإعدادات.','Deactivate %s on the whole network after importing (it is not deleted)'=>'إلغاء تفعيل %s على الشبكة كلها بعد الاستيراد (لا يُحذف)','Deactivate %s after importing (it is not deleted)'=>'إلغاء تفعيل %s بعد الاستيراد (لا يُحذف)','%s is active for the whole network: only a network administrator can deactivate it.'=>'%s مفعّل على الشبكة كلها: لا يستطيع إلغاء تفعيله إلا مسؤول الشبكة.','Do not import anything'=>'عدم استيراد أي شيء','Import the settings another cache or performance plugin left on each chosen site (after the profile, so they win over it; undo it in each site\'s Settings)'=>'استيراد الإعدادات التي تركتها إضافة أخرى للذاكرة المؤقتة أو الأداء في كل موقع مختار (بعد الملف الشخصي، فتتقدّم عليه؛ ويمكن التراجع عنها من إعدادات كل موقع)','Then deactivate that plugin (not deleted): on its site, or on the whole network when it is network-active'=>'ثم إلغاء تفعيل تلك الإضافة (دون حذفها): في موقعها، أو على الشبكة كلها إن كانت مفعّلة على مستوى الشبكة','Settings of another cache plugin imported on %d site; you can undo it in that site\'s Settings.' . "\0" . 'Settings of another cache plugin imported on %d sites; you can undo it in each site\'s Settings.'=>'تم استيراد إعدادات إضافة ذاكرة مؤقتة أخرى في %d موقع؛ يمكنك التراجع عنها من إعدادات كل موقع.' . "\0" . 'تم استيراد إعدادات إضافة ذاكرة مؤقتة أخرى في %d موقع؛ يمكنك التراجع عنها من إعدادات كل موقع.' . "\0" . 'تم استيراد إعدادات إضافة ذاكرة مؤقتة أخرى في %d موقع؛ يمكنك التراجع عنها من إعدادات كل موقع.' . "\0" . 'تم استيراد إعدادات إضافة ذاكرة مؤقتة أخرى في %d موقع؛ يمكنك التراجع عنها من إعدادات كل موقع.' . "\0" . 'تم استيراد إعدادات إضافة ذاكرة مؤقتة أخرى في %d موقع؛ يمكنك التراجع عنها من إعدادات كل موقع.' . "\0" . 'تم استيراد إعدادات إضافة ذاكرة مؤقتة أخرى في %d موقع؛ يمكنك التراجع عنها من إعدادات كل موقع.','%d plugin deactivated (not deleted): its page cache no longer serves pages, so switch on the WPOptimizing page cache in each site\'s Speed › Cache; an import never switches it on by itself.' . "\0" . '%d plugins deactivated (not deleted): their page cache no longer serves pages, so switch on the WPOptimizing page cache in each site\'s Speed › Cache; an import never switches it on by itself.'=>'تم إلغاء تفعيل %d إضافة (دون حذفها): لم تعد ذاكرة الصفحات المؤقتة تقدّم الصفحات، لذا فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة في كل موقع؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.' . "\0" . 'تم إلغاء تفعيل %d إضافة (دون حذفها): لم تعد ذاكرة الصفحات المؤقتة تقدّم الصفحات، لذا فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة في كل موقع؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.' . "\0" . 'تم إلغاء تفعيل %d إضافة (دون حذفها): لم تعد ذاكرة الصفحات المؤقتة تقدّم الصفحات، لذا فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة في كل موقع؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.' . "\0" . 'تم إلغاء تفعيل %d إضافة (دون حذفها): لم تعد ذاكرة الصفحات المؤقتة تقدّم الصفحات، لذا فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة في كل موقع؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.' . "\0" . 'تم إلغاء تفعيل %d إضافة (دون حذفها): لم تعد ذاكرة الصفحات المؤقتة تقدّم الصفحات، لذا فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة في كل موقع؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.' . "\0" . 'تم إلغاء تفعيل %d إضافة (دون حذفها): لم تعد ذاكرة الصفحات المؤقتة تقدّم الصفحات، لذا فعّل ذاكرة الصفحات المؤقتة في WPOptimizing من السرعة › الذاكرة المؤقتة في كل موقع؛ فالاستيراد لا يفعّلها أبدًا من تلقاء نفسه.','Also cache llms.txt, robots.txt, the XML sitemaps and Markdown copies generated by WordPress or a plugin (only kept when the answer is text or XML and the same for everybody, and purged with any content change)'=>'تخزين llms.txt وrobots.txt وخرائط موقع XML ونسخ Markdown التي يولّدها WordPress أو إضافة مؤقتًا أيضًا (تُحفظ فقط إذا كان الرد نصًا أو XML وهو نفسه للجميع، وتُمسح مع أي تغيير في المحتوى)','Also cache these text files generated by WordPress (only kept when the answer is text or XML and the same for everybody)'=>'تخزين ملفات النص هذه التي يولّدها WordPress مؤقتًا أيضًا (تُحفظ فقط إذا كان الرد نصًا أو XML وهو نفسه للجميع)','file name from the site\'s address, * for any characters, e.g. ai.txt'=>'اسم الملف من عنوان الموقع، * لأي أحرف، مثل ai.txt','Analytics never receives cookie consent'=>'لا يتلقى Analytics أبدًا الموافقة على ملفات تعريف الارتباط','%2$s only learns that visitors accepted cookies in %1$s through the WP Consent API plugin, which is not installed: Google receives every visit as without consent and they do not appear in Realtime.'=>'لا يعرف %2$s أن الزوار قبلوا ملفات تعريف الارتباط في %1$s إلا عبر إضافة WP Consent API، وهي غير مثبتة: تتلقى Google كل زيارة على أنها بدون موافقة ولا تظهر في الوقت الفعلي.','Install WP Consent API'=>'تثبيت WP Consent API','The design has changed: the critical CSS will be regenerated on its own in a few minutes, and the cached pages emptied.'=>'تغيّر التصميم: سيُعاد إنشاء CSS الحرج تلقائيًا خلال بضع دقائق وستُفرغ الصفحات المخزنة مؤقتًا.','Once applied, it is regenerated on its own when the theme, its options, the Customizer, the global styles, the theme builder\'s layouts or the pages it was generated from change.'=>'بعد تطبيقه، يُعاد إنشاؤه تلقائيًا عند تغيّر القالب أو خياراته أو أداة التخصيص أو الأنماط العامة أو تخطيطات منشئ القالب أو الصفحات التي أُنشئ منها.','Last done %s ago.'=>'آخر مرة منذ %s.','The zone ID belongs to %s, not to this site.'=>'معرّف المنطقة يخص %s وليس هذا الموقع.','That zone ID belongs to %1$s, not to %2$s. Nothing will be purged until you enter the zone ID of this domain.'=>'معرّف المنطقة هذا يخص %1$s وليس %2$s. لن يُمسح أي شيء حتى تُدخل معرّف المنطقة لهذا النطاق.','The zone ID belongs to %s, not to this site, so nothing of this site is being purged. Enter the zone ID of this domain.'=>'معرّف المنطقة يخص %s وليس هذا الموقع، لذلك لا يُمسح أي شيء من هذا الموقع. أدخل معرّف المنطقة لهذا النطاق.','This zone ID is also saved on %s. A Cloudflare zone is one domain, so one of the sites is purging the other\'s cache and not its own: check the zone ID on each.'=>'معرّف المنطقة هذا محفوظ أيضًا في %s. منطقة Cloudflare نطاق واحد، لذا أحد الموقعين يمسح ذاكرة الآخر وليس ذاكرته: تحقق من معرّف المنطقة في كل منهما.','In %s'=>'في %s','In the other plugin'=>'في الإضافة الأخرى','In WPOptimizing'=>'في WPOptimizing','%d px'=>'%d بكسل','%d second' . "\0" . '%d seconds'=>'%d ثانية' . "\0" . '%d ثانية' . "\0" . 'ثانيتان' . "\0" . '%d ثوانٍ' . "\0" . '%d ثانية' . "\0" . '%d ثانية','Clean all post revisions'=>'تنظيف جميع مراجعات المقالات','Regenerate critical CSS'=>'إعادة إنشاء CSS الحرج','Regenerate the critical CSS of every template in the background, then purge the page cache'=>'يعيد إنشاء CSS الحرج لكل القوالب في الخلفية، ثم يفرغ ذاكرة الصفحات المؤقتة','Regenerating in the background ✓'=>'تجري إعادة الإنشاء في الخلفية ✓','Regenerate the critical CSS of every template now? The current one stays in use until the new one is ready.'=>'إعادة إنشاء CSS الحرج لكل القوالب الآن؟ يبقى الحالي قيد الاستخدام حتى يصبح الجديد جاهزًا.','The critical CSS is being regenerated in the background; the cached pages will be emptied when it is ready.'=>'تجري إعادة إنشاء CSS الحرج في الخلفية؛ ستُفرَّغ الصفحات المخزنة مؤقتًا عندما يصبح جاهزًا.','To regenerate it without any change, use “Regenerate critical CSS” in the WPOptimizing toolbar menu.'=>'لإعادة إنشائه دون أي تغيير، استخدم «إعادة إنشاء CSS الحرج» في قائمة WPOptimizing في شريط الأدوات.','Not cached: the page was cut short (the visitor left, the time limit or a fatal error)'=>'لم تُخزَّن مؤقتًا: انقطعت الصفحة في منتصفها (غادر الزائر أو انتهت المهلة أو حدث خطأ فادح)','For campaign visits (utm_*, gclid…) to be served from there too, a third line:'=>'لكي تُقدَّم زيارات الحملات (utm_*، gclid…) من هناك أيضًا، سطر ثالث:','Transform Rules'=>'Transform Rules','The page cache is not available on a multisite network.'=>'ذاكرة التخزين المؤقت للصفحات غير متاحة في شبكة مواقع متعددة.','On a multisite network the page cache is part of Pro and needs an active license.'=>'في شبكة المواقع المتعددة، تُعد ذاكرة التخزين المؤقت للصفحات جزءًا من Pro وتحتاج إلى ترخيص نشط.','Preloading, serving pages without PHP, Brotli copies, HTML minification, hit diagnostics, caching text files and REST routes, and page caching at Cloudflare\'s edge are not included in this plugin.'=>'التحميل المسبق، وتقديم الصفحات دون PHP، ونسخ Brotli، وتصغير HTML، وتشخيص الإصابات، وتخزين الملفات النصية ومسارات REST مؤقتًا، وتخزين الصفحات مؤقتًا على حافة Cloudflare غير مضمّنة في هذه الإضافة.','Pro adds preloading, serving pages without PHP, Brotli copies, HTML minification, hit diagnostics, caching text files and REST routes, and page caching at Cloudflare\'s edge.'=>'يضيف Pro التحميل المسبق، وتقديم الصفحات دون PHP، ونسخ Brotli، وتصغير HTML، وتشخيص الإصابات، وتخزين الملفات النصية ومسارات REST مؤقتًا، وتخزين الصفحات مؤقتًا على حافة Cloudflare.','%s: not imported, this edition of WPOptimizing does not have it.'=>'%s: لم يُستورد، فهذا الإصدار من WPOptimizing لا يتضمنه.','serves a static copy of each page to anonymous visitors, for 10 hours by default (from 1 to 12), and clears what changes. Logged-in users, carts, checkout and the admin are never cached. Enabling it writes wp-content/advanced-cache.php and adds WP_CACHE to wp-config.php. It stays off while another page cache is active, and it is not available on a multisite network.'=>'يقدّم للزوار المجهولين نسخة ثابتة من كل صفحة، لمدة 10 ساعات افتراضيًا (من 1 إلى 12)، ويمسح ما يتغيّر. لا يُخزَّن مؤقتًا أبدًا المستخدمون المسجَّلون ولا السلال ولا الدفع ولا لوحة الإدارة. يؤدي تفعيله إلى كتابة wp-content/advanced-cache.php وإضافة WP_CACHE إلى wp-config.php. يبقى معطّلًا ما دامت ذاكرة تخزين صفحات أخرى نشطة، وهو غير متاح في شبكة متعددة المواقع.','serves a static copy of each page to anonymous visitors, for 10 hours by default (from 1 to 12), and clears what changes. Logged-in users, carts, checkout and the admin are never cached. Enabling it writes wp-content/advanced-cache.php and adds WP_CACHE to wp-config.php. It stays off while another page cache is active; on a multisite network, a network administrator turns it on site by site.'=>'يقدّم للزوار المجهولين نسخة ثابتة من كل صفحة، لمدة 10 ساعات افتراضيًا (من 1 إلى 12)، ويمسح ما يتغيّر. لا يُخزَّن مؤقتًا أبدًا المستخدمون المسجَّلون ولا السلال ولا الدفع ولا لوحة الإدارة. يؤدي تفعيله إلى كتابة wp-content/advanced-cache.php وإضافة WP_CACHE إلى wp-config.php. يبقى معطّلًا ما دامت ذاكرة تخزين صفحات أخرى نشطة؛ وفي شبكة متعددة المواقع يفعّله مدير الشبكة موقعًا بموقع.']];
